ClinicalChunks.register("data/templates-093.js",[{"id":"templates-e9e32f085b7276658178","key":"v1-c9ccc21dfe2a3058|templates-e9e32f085b7276658178","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肾上腺危象","category":"临床急症","raw":{"name":"肾上腺危象","category":"临床急症","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】低血压至休克、乏力、恶心呕吐、厌食、腹痛；发热或低体温；低血糖表现（出汗、心慌、意识改变）；原发者皮肤黏膜色素沉着。。\n【待人工确认·本机素材无此段原文】","现病史":"危急识别：Addison病或继发性肾上腺皮质功能不全患者，在感染（最常见）、手术创伤、停用激素等应激下出现低血压休克（对升压药反应差）、低钠血症、高钾血症。临床意义：致命并发症，延迟治疗死亡率极高；停用激素是最常见可避免诱因；疑诊即抢救，勿等生化结果。\n常见表现：低血压至休克、乏力、恶心呕吐、厌食、腹痛；发热或低体温；低血糖表现（出汗、心慌、意识改变）；原发者皮肤黏膜色素沉着。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"低血压/休克、皮肤黏膜色素沉着（掌纹、乳晕、口腔黏膜）、脱水貌、发热或低体温、心动过速；可腹痛压痛。","辅助检查":"检查计划：患者存在基础肾上腺疾病或长期激素使用史，此次在感染、手术创伤、停用激素等应激下出现低血压至休克、乏力、恶心呕吐、腹痛，入院即刻完善电解质检查以排除低钠、高钾血症，此为肾上腺危象的生化三联之一，并指导补钠、降钾治疗；完善血糖检查以排除低血糖，低血糖常与皮质醇不足并存，须即刻纠正；完善肾功能检查以了解肾灌注与有无急性肾损伤，指导补液复苏；完善血气分析检查以明确有无代谢性酸中毒及组织灌注不足程度；疑诊即抢救、勿等生化结果，同时完善血皮质醇、尿游离皮质醇及ACTH检查以明确肾上腺皮质功能不全，皮质醇低而ACTH高提示原发性，ACTH低提示继发性，用于定位诊断；条件允许时完善快速ACTH兴奋试验以明确肾上腺皮质储备功能；高钾可致严重心律失常，急诊完善心电图检查以排除高钾所致传导阻滞等改变；发热或低体温提示感染这一最常见诱因，完善血培养、尿培养及胸片检查以排查感染诱因；危重患者完善凝血功能与D-二聚体检查以评估有无凝血紊乱。\n\n（检查清单）\n电解质（低钠、高钾）、血糖、肾功能、血气；血/尿皮质醇、ACTH；心电图（高钾改变）；血/尿培养、胸片。","初步诊断":"临床诊断：基础病+应激诱因+低血压/休克即应疑诊并立即治疗。生化三联：低钠、高钾、低血糖；皮质醇低、ACTH高提示原发；条件允许行快速ACTH兴奋试验，并排查感染等诱因。\n1. 肾上腺危象（ICD-10：E27.2）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n氢化可的松100mg静注首剂→100mg静注q6–8h；0.9%氯化钠快速补液：首1小时1000ml，第2–3小时再1000ml，首日总量2000–3000ml；低血糖加5%GS，重度者50%GS 20–40ml静注。量按说明书/指南调整。\n\n【药物治疗·口服】\n稳定后过渡：第2天氢化可的松50mg静注q6–8h，第3天起每日减约50%，至口服维持量20–30mg/d分次（早2/3、午后1/3）；血压/血钠仍低者加氟氢可的松0.05–0.1mg/d口服。剂量按说明书/指南调整。\n\n【治疗】\n①立即激素替代：氢化可的松100mg静注（缓慢推注）→100mg静注q6–8h，首日总量300–400mg；②0.9%氯化钠快速补液，首日2000–3000ml；③低血糖予50%GS 20–40ml静注，高钾按规范处理；④稳定24–48h后阶梯减量过渡口服；⑤治诱因：感染→血/尿培养+胸片+广谱抗生素；出血/创伤→止血、手术评估；停激素→重审方案。剂量按说明书/指南调整。\n\n【处理要点】\n心电血压监护，纠正休克与电解质紊乱；稳定后评估HPA轴功能，制定长期替代及应激剂量方案；宣教随身携带急救卡/医疗警示手环。\n\n【护理】\n休克护理：平卧、保暖、持续心电血压监测；按序执行激素—补液—补糖；记录出入量防过负荷；宣教识别前驱症状、随身急救卡/警示手环、应激剂量原则（发热<39℃激素加倍，手术创伤予50–100mg/d或住院），禁擅自停药。\n\n【饮食】\n急性期呕吐明显者暂禁食补液；稳定后高盐、均衡饮食并保证水分；原发者避免低盐饮食；血糖不稳者规律进餐防低血糖。\n\n【注意事项】\n勿等生化结果；对升压药反应差的休克须想到本病；首日大剂量氢化可的松已具盐皮质作用，氟氢可的松按血压/血钠加用；低血糖补糖同时必须给激素；警惕Waterhouse-Friderichsen综合征。\n\n【急诊/急救】\n氢化可的松100mg静注→100mg静注q6–8h；同步0.9%氯化钠快速扩容（首小时1000ml）；重度低血糖50%GS 20–40ml静注。","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"E27.2","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2778,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"88b279083c4bc50e68734a3dd7c22ae41a7f4084547af3d51e3eee94a38f954b","pinyin":"shenshangxianweixiang","initials":"ssxwx","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","E27.2",30]]},{"id":"templates-ec48c7129d3be6129cd5","key":"v1-c9ccc21dfe2a3058|templates-ec48c7129d3be6129cd5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肾性高钾血症","category":"临床急症","raw":{"name":"肾性高钾血症","category":"临床急症","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】乏力、肢端与口周麻木、肌肉无力、腱反射减弱、心动过缓或传导阻滞，严重者心脏骤停；部分患者可无症状。。\n【待人工确认·本机素材无此段原文】","现病史":"危急阈值：血钾≥6.5mmol/L（慢性肾病/终末期肾病可放宽至≥6.0mmol/L）需紧急处理。临床意义：肾衰竭排钾能力下降，叠加ACEI/ARB、螺内酯等药物与代谢性酸中毒作用，高钾顽固、易反复、药物反应差，可致恶性心律失常甚至猝死。\n常见表现：乏力、肢端与口周麻木、肌肉无力、腱反射减弱、心动过缓或传导阻滞，严重者心脏骤停；部分患者可无症状。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"心率心律、肌力、腱反射、呼吸节律（酸中毒代偿表现）。","辅助检查":"检查计划：患者存在慢性肾脏病、肾功能下降，此次出现乏力、肢端与口周麻木、肌肉无力、腱反射减弱及心动过缓等表现，入院即刻完善血钾检查以明确高钾程度，血钾≥6.0～6.5mmol/L需紧急处理，并动态复查血钾以评估降钾治疗疗效；完善肾功能（BUN/Cr）检查以明确肾衰竭程度及有无急性加重，急性肾损伤所致高钾往往进展迅速，是启动透析的重要依据；完善血气分析检查以明确有无代谢性酸中毒，酸中毒可加重钾向细胞外转移，并指导补碱治疗；完善血糖检查以排除高血糖所致血钾假性升高及糖尿病相关代谢紊乱；患者在使用ACEI/ARB、螺内酯等药物，需结合肾功能调整用药，完善尿常规及尿量监测以评估肾排钾能力；高钾可致T波高尖、PR间期延长、QRS增宽乃至正弦波，急诊完善心电图检查以排除高钾所致恶性心律失常；必要时完善血常规、心肌损伤标志物检查以排除感染及心肌损伤等诱因，并每4～6小时复查血钾与心电图直至血钾降至安全范围。\n\n（检查清单）\n血钾、肾功能（BUN/Cr）、血气分析、血糖、心电图。","初步诊断":"血钾≥6.0-6.5mmol/L结合肾功能、血气判断；心电图见T波高尖、PR间期延长、QRS增宽、P波低平乃至正弦波为高危表现。\n1. 肾性高钾血症（ICD-10：E87.5（高钾血症））","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n10%葡萄糖酸钙10ml缓慢IV（肾衰患者易高钙，钙剂用量宜偏小）；促钾内移：短效胰岛素10U+50%葡萄糖50ml IV，肾衰患者低血糖风险高，需监测。\n\n【药物治疗·口服】\n环硅酸锆钠（SZC）10g tid，肾性高钾尤其适用，不影响肾功能，可长期口服维持。\n\n【治疗】\n三步法：钙剂稳定心肌膜→促钾内移（胰岛素+葡萄糖、沙丁胺醇雾化，后者不影响肾功能可联合）→促排出：呋塞米100-200mg IV（有残余肾功能者）或SZC 10g tid，必要时血液透析。紧急透析指征：血钾≥7.0mmol/L或药物治疗无效。\n\n【处理要点】\n持续心电监护直至血钾降至安全范围；透析后血钾1-2h内可下降1-2mmol/L，透析后4-6h易反跳需复查血钾；监测血糖至少12h；复查心电图。\n\n【护理】\n持续心电监护；规范复查血钾与血糖；观察静脉钙剂外渗；宣教避免高钾食物。\n\n【饮食】\n低钾饮食：避免香蕉、橙子、土豆、菌菇等高钾食物及含钾低钠盐。\n\n【注意事项】\n肾性高钾对药物治疗反应较差，反复发作者常需维持性透析或长期口服SZC控制。\n\n【急诊/急救】\n血钾≥7.0mmol/L、或伴明显心电图异常而药物无效者，立即安排紧急血液透析。","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"E87.5（高钾血症）","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2779,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"73a71502db1451fb67f52db54cbb01dd819dc8528fb97fd9258c761871f2ff2a","pinyin":"shenxinggaojiaxuezheng","initials":"sxgjxz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","E87.5（高钾血症）",30]]},{"id":"templates-e5ceeef50fc5cbac5fdd","key":"v1-c9ccc21dfe2a3058|templates-e5ceeef50fc5cbac5fdd","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肾输尿管结石症","category":"临床急症","raw":{"name":"肾输尿管结石症","category":"临床急症","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】典型：突发腰部或腹部绞痛，向腹股沟、会阴及大腿内侧放射，阵发加重，伴恶心呕吐。、伴随：肉眼或镜下血尿、尿频尿急。、危险信号：发热寒战、少尿或无尿、持续剧痛不缓解、血压下降（梗阻合并感染）。。\n【待人工确认·本机素材无此段原文】","现病史":"定义：泌尿系统最常见病症，病因与遗传、代谢、环境及泌尿自身病变有关，可致绞痛、血尿与梗阻，反复发作者需病因治疗。\n夜班目标：迅速解痉镇痛，评估有无梗阻与感染，判断是否需要急诊减压或手术。\n常见表现：典型：突发腰部或腹部绞痛，向腹股沟、会阴及大腿内侧放射，阵发加重，伴恶心呕吐。、伴随：肉眼或镜下血尿、尿频尿急。、危险信号：发热寒战、少尿或无尿、持续剧痛不缓解、血压下降（梗阻合并感染）。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"腹部与腰部：肾区叩击痛、输尿管走行区压痛，有无腹膜刺激征。\n全身：体温、心率、血压、脱水程度。\n泌尿：膀胱区叩诊（尿潴留），必要时直肠指检。","辅助检查":"检查计划：患者突发腰部或腹部绞痛并向腹股沟、会阴及大腿内侧放射，伴恶心呕吐、肉眼或镜下血尿、尿频尿急，急诊完善尿常规检查以明确有无红细胞（血尿）并排除泌尿系感染；完善泌尿系超声检查以明确有无结石、输尿管扩张及肾积水，是判断梗阻程度的首选影像；因本次需解痉镇痛并需排除感染，完善血常规检查以排除感染所致白细胞升高；完善肾功能与电解质检查以评估梗阻所致肾功能损害及呕吐所致电解质紊乱，指导补液；患者既往可有痛风、饮水少、高温作业等代谢因素，完善血尿酸检查以了解代谢性结石的病因；拟行体外碎石或输尿管镜取石者，完善凝血功能检查以排除凝血障碍所致出血风险；必要时完善泌尿系CT平扫检查以明确结石部位、大小及有无梗阻，其敏感度高于腹部平片，亦可鉴别急性阑尾炎、胆囊炎、胰腺炎、异位妊娠、卵巢囊肿蒂扭转及腹主动脉瘤等急腹症；患者发热寒战、血压下降时，完善尿培养、血培养检查以明确有无梗阻合并感染（脓毒症）；病情危重时完善血气与乳酸检查以评估组织灌注与感染严重程度。\n\n（检查清单）\n必查：尿常规（红细胞）、泌尿系超声、血常规、肾功能与电解质、血尿酸、凝血功能。\n按需：泌尿系CT平扫或腹部平片、尿培养、血培养、血气与乳酸。","初步诊断":"病史：既往结石史、饮水少、高温作业、痛风、泌尿系畸形或感染；反复发作者查代谢因素。\n线索：绞痛加血尿，影像示结石、输尿管扩张或肾积水。\n鉴别：急性阑尾炎、胆囊炎、胰腺炎、异位妊娠、卵巢囊肿蒂扭转、腹主动脉瘤。\n1. 肾输尿管结石症（ICD-10：N20.1）","鉴别诊断":"1. 鉴别：急性阑尾炎、胆囊炎、胰腺炎、异位妊娠、卵巢囊肿蒂扭转、腹主动脉瘤","处理方案":"【药物治疗·输液】\n解痉镇痛：戊乙奎醚0.3~0.5mg 静推 每8小时1次；双氯芬酸钠75mg 肌注 立即（24小时≤150mg）。\n重度疼痛：氢吗啡酮0.5~1mg 静推 每4小时1次，呼吸<12次/分时停用并备纳洛酮。\n抗感染：非复杂性用头孢呋辛1.5g 静滴 每8小时1次；复杂性加甲硝唑0.5g 每12小时1次；青霉素过敏用磷霉素氨丁三醇3g口服单次加左氧氟沙星0.5g 静滴 每日1次。\n\n【药物治疗·口服】\n排石与解痉：坦索罗辛缓释胶囊0.4mg 口服 每晚1次；间苯三酚片80mg 口服 每8小时1次。\n代谢调节：枸橼酸钾颗粒1包 口服 每日4次（目标尿pH6.5~7.0）；别嘌醇片0.1g 口服 每日1次。\n复发性高钙尿症：氢氯噻嗪25mg 口服 每日1次。\n\n【治疗】\n首要：充分解痉镇痛，评估生命体征与有无感染性梗阻。\n其次：按结石大小与位置分层——输尿管结石<5mm用坦索罗辛0.4mg 每晚1次加跳跃运动；5~10mm行体外冲击波碎石或输尿管镜钬激光碎石；肾结石>2cm行经皮肾镜取石术。\n随后：合并脓毒症或持续梗阻者发病48小时内急诊干预；术前三维CT重建定位，坦索罗辛术前3天启用；留置双J管者口服坦索罗辛至拔管后1周。\n\n【处理要点】\n复评：每2~4小时评估疼痛评分与尿量，观察尿色与排石情况。\n术后：感染性结石尿培养转阴后继续抗生素1周；尿酸或胱氨酸结石长期枸橼酸钾维持尿pH。\n收治：发热、梗阻、孤立肾或肾功能不全者收入院。\n\n【护理】\n体位：舒适体位，绞痛时协助屈膝侧卧，鼓励适度活动助排石。\n监测：疼痛评分、尿量、尿色及有无结石排出。\n记录：液体入量与尿量，用药时间与效果。\n安全：绞痛与使用镇痛药后防跌倒，术后固定引流管路。\n\n【注意事项】\n以本院规范为准：镇痛解痉药物、排石治疗与手术指征按本院常规执行。\n禁用/慎用：青光眼与前列腺增生者慎用戊乙奎醚等抗胆碱药；肾功能不全者慎用非甾体抗炎药。\n提醒：止痛成功不等于可离院，需确认无梗阻与感染。\n\n【急诊/急救】\n立即升级：体温>38.5℃伴寒战、肾区叩痛加重、无尿或少尿、收缩压<90mmHg、孤立肾或双侧梗阻 → 急诊减压引流并抗感染。\n提示：感染性梗阻可在数小时内进展为脓毒症，不能等待自行排石。","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「肾输尿管结石症」原文）"},"icd10_diagnosis":"N20.1","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2780,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"600fad1607b02ccb4467f5d7ccc0427a779140d8cfb2a60e36d09f7492de2ec1","pinyin":"shenshuniaoguanjieshizheng","initials":"ssngjsz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","N20.1",30]]},{"id":"templates-7b04b283ea73a6c5a70f","key":"v1-c9ccc21dfe2a3058|templates-7b04b283ea73a6c5a70f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肿瘤急症","category":"临床急症","raw":{"name":"肿瘤急症","category":"临床急症","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】上腔静脉综合征：面颈部与上肢肿胀、颈静脉怒张、胸壁静脉曲张、呼吸困难、头晕头痛、声音嘶哑（平卧加重）、脊髓压迫：持续性背痛（夜间与平卧加重）、肢体麻木无力、感觉平面、大小便功能障碍（尿潴留/失禁）、颅内高压：晨起头痛、喷射性呕吐、视物模糊、意识改变、癫痫发作、瞳孔不等大、高钙血症：恶心呕吐、便秘、多尿多饮、乏力嗜睡、意识障碍、心律失常（'结石、骨痛、腹痛、精神症状'）、共性：症状进展迅速（数小时至数天），需紧急评估与干预。\n【待人工确认·本机素材无此段原文】","现病史":"肿瘤急症需立即识别与处理，常见包括：上腔静脉综合征（SVCS，纵隔肿瘤压迫致面颈上肢肿胀与呼吸困难）、脊髓压迫（硬膜外转移致背痛、肢体无力与大小便障碍）、颅内高压（脑转移致头痛呕吐与意识改变）、高钙血症（骨转移或PTHrP分泌）与肿瘤溶解综合征（已单列）。及时识别与紧急处理可避免不可逆神经损伤与死亡。\n常见表现：上腔静脉综合征：面颈部与上肢肿胀、颈静脉怒张、胸壁静脉曲张、呼吸困难、头晕头痛、声音嘶哑（平卧加重）、脊髓压迫：持续性背痛（夜间与平卧加重）、肢体麻木无力、感觉平面、大小便功能障碍（尿潴留/失禁）、颅内高压：晨起头痛、喷射性呕吐、视物模糊、意识改变、癫痫发作、瞳孔不等大、高钙血症：恶心呕吐、便秘、多尿多饮、乏力嗜睡、意识障碍、心律失常（'结石、骨痛、腹痛、精神症状'）、共性：症状进展迅速（数小时至数天），需紧急评估与干预。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：血压、心率、呼吸频率与形态、血氧（气道受压与循环评估）、体温\n上腔静脉综合征体征：面颈部与上肢肿胀、颈静脉怒张、胸壁静脉曲张、口唇发绀、声嘶\n神经系统：意识（GCS）、肌力分级、感觉平面、腱反射、病理反射、括约肌功能（直肠指检评估张力）\n脊柱：棘突压痛与叩击痛、脊柱畸形、活动受限（脊髓压迫定位）\n眼底与颅神经：视乳头水肿、瞳孔、眼球运动（颅内高压与颅神经受累）\n高钙相关：脱水征、心律失常（心率与心律）、意识状态、肌肉无力与腱反射减弱\n肿瘤体征：浅表淋巴结肿大、原发灶相关体征（肺部体征、腹块）、骨转移局部压痛","辅助检查":"1. 血钙（含离子钙+白蛋白校正）+PTH+PTHrP+碱性磷酸酶+25-羟维生素D：高钙血症诊断与病因鉴别\n2. 电解质（钠、钾、钙）+肾功能+尿量：补液与利尿治疗监测（每4～6小时，高钙/颅压增高时）\n3. 全脊柱MRI增强（脊髓压迫首选）：明确压迫节段、程度与有无多发转移（症状出现后24小时内完成）\n4. 头颅增强CT/MRI（颅内高压）：脑转移灶、水肿范围与脑疝征象\n5. 胸部增强CT（上腔静脉综合征）：阻塞部位、纵隔肿块与血管受压情况（必要时上腔静脉造影）\n6. 血常规+凝血功能+肝肾功能+血气分析：综合评估与治疗准备\n7. 肿瘤标志物+病理活检：明确原发肿瘤类型（指导针对性治疗）","初步诊断":"1. 上腔静脉综合征：胸部增强CT（明确阻塞部位与病因）、上腔静脉造影（必要时）、胸部X线（纵隔增宽）\n2. 脊髓压迫：全脊柱MRI增强（首选，明确压迫节段与程度，患者出现症状后24小时内完成）；脊柱X线/CT（骨破坏）\n3. 颅内高压：头颅增强CT/MRI（脑转移、水肿、脑疝征象）、眼底检查（视乳头水肿）\n4. 高钙血症：血钙（含离子钙+白蛋白校正）、PTH、PTHrP、碱性磷酸酶、25-羟维生素D、肾功能与电解质\n5. 肿瘤相关评估：原发肿瘤类型与分期、肿瘤标志物、必要时活检（明确病理以指导治疗）\n6. 血常规+凝血功能+电解质+肾功能+血气分析：综合评估与治疗监测\n7. 神经系统评估：肌力分级、感觉平面、反射与括约肌功能（脊髓压迫需每1～2小时评估并记录）\n1. 肿瘤急症（ICD-10：C80.0）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 肿瘤急症抢救用药，须立即处理并多学科协作！\n\n方案1（上腔静脉综合征，减轻水肿与压迫）：\n 用法：地塞米松 10～20mg 静推后 4～6mg q6h（减轻纵隔水肿）；呋塞米 20～40mg 静推（减轻水负荷）；0.9%氯化钠 静滴（谨慎补液，上肢输液受限应下肢或中心静脉置管）；吸氧\n\n方案2（脊髓压迫，保护神经功能）：\n 用法：地塞米松 10mg 静推后 4mg q6h（立即开始，减轻脊髓水肿）；甘露醇 125ml 静滴 q8～12h（必要时）；0.9%氯化钠 静滴维持灌注；尽快放疗或手术减压\n\n方案3（颅内高压）：\n 用法：20%甘露醇 125～250ml 静滴 q6～8h（快速静滴）；地塞米松 10mg 静推 q6h（脑转移水肿）；3%氯化钠 100～150ml 静滴（难治性颅压增高）；必要时急诊放疗或手术\n\n方案4（高钙血症）：\n 用法：0.9%氯化钠 1000～2000ml 静滴（快速补液，首24小时3～4L）；呋塞米 20～40mg 静推 q6～12h（补液后利尿）；唑来膦酸 4mg + 0.9%氯化钠 100ml 静滴（>15分钟）或 帕米膦酸二钠 60～90mg 静滴；降钙素 4IU/kg 皮下注射 q12h（快速起效，短期）；必要时血液透析\n\n📌 肿瘤急症处理需多学科（肿瘤科、放疗科、神经外科、骨科、ICU）协作；激素用于减轻水肿但不能替代抗肿瘤治疗。\n\n【药物治疗·口服】\n⚠️ 急症稳定后的口服用药与支持：\n\n药物1（激素减量，按医嘱逐渐减停）：\n 用法：地塞米松 4mg q6h → 逐渐减量（防颅压/水肿反跳，不可骤停）；同时护胃（艾司奥美拉唑 20mg qd）\n\n药物2（镇痛，脊髓压迫/骨转移疼痛）：\n 用法：吗啡缓释片 10～30mg q12h（按疼痛滴定）+ 即释吗啡 5～10mg 必要时；或羟考酮缓释片 10mg q12h；同时预防便秘（乳果糖 15ml bid）\n\n药物3（骨转移骨保护）：\n 用法：唑来膦酸 4mg 静滴 每3～4周 或 地舒单抗 120mg 皮下注射 每4周；碳酸钙D3 600mg qd + 维生素D 800IU/日\n\n药物4（抗癫痫与对症）：\n 用法：左乙拉西坦 500mg bid（脑转移伴癫痫）；乳果糖 15ml bid（阿片类致便秘）\n\n📌 激素减量需缓慢（数周），突然停药可致脑水肿反跳；骨保护药物使用前需口腔检查（预防颌骨坏死）。\n\n【治疗】\n上腔静脉综合征：抬高床头、吸氧、激素+利尿减轻水肿；紧急放疗（放疗敏感肿瘤如小细胞肺癌、淋巴瘤）或化疗；血管内支架置入（快速缓解，尤其放疗不敏感者）；抗凝（合并血栓时）\n脊髓压迫：立即激素+尽快放疗（放疗敏感肿瘤）或手术减压固定（脊柱不稳、单发压迫、病理不明或放疗无效者）；理想治疗窗口为症状出现后24～48小时内\n颅内高压：激素+甘露醇/高渗盐水降颅压；全脑放疗（多发脑转移）或立体定向放疗（寡转移）；手术切除（单发大病灶、颅压危象）；抗癫痫治疗\n高钙血症：大量补液+利尿+双膦酸盐（±降钙素），控制原发病（化疗/激素治疗），避免制动与噻嗪类利尿剂\n抗肿瘤治疗：明确病理后尽快启动针对性治疗（化疗/靶向/免疫/放疗），是根本解决肿瘤急症的手段\n支持治疗与并发症防治：镇痛（阿片类按三阶梯）、抗凝（VTE风险）、营养支持、感染防治、心理支持\n多学科协作：肿瘤科、放疗科、神经外科、骨科、ICU与影像科共同决策（多数急症需急诊放疗或手术）\n随访与宣教：告知患者与家属急症预警症状（背痛、肢体无力、大小便障碍、气促、意识改变）并立即就诊\n\n【处理要点】\n紧急评估与分诊：评估生命体征、神经功能（肌力、感觉、括约肌）与气道安全，急症优先处理（脊髓压迫与颅压危象不可延误）\n神经功能监测（脊髓压迫/脑转移）：每1～2小时评估肌力、感觉平面与大小便功能并记录，恶化立即报告（决定手术/放疗时机）\n激素与降颅压执行：按医嘱准时给药，观察疗效（症状缓解）与不良反应（血糖升高、消化道出血、感染、失眠），监测血糖与电解质\n补液与电解质管理：高钙血症大量补液并记录出入量；颅压增高者限制液体；监测血钠、血钙、肾功能与尿量\n气道与呼吸管理：上腔静脉综合征者抬高床头、吸氧、避免上肢输液（选下肢或中心静脉），观察呼吸困难与声音嘶哑（气道受压）\n疼痛与症状管理：按三阶梯镇痛并预防便秘，评估疼痛评分；观察大小便功能与皮肤完整性（截瘫风险者防压疮）\n放疗/手术前准备与宣教：快速完成定位、备血与术前准备；向患者家属解释治疗紧迫性与风险并完成知情同意\n\n【护理】\n急症监测与报告：评估生命体征与神经功能（肌力、感觉、括约肌）每1～2小时并记录，恶化立即报告（脊髓压迫与颅压危象预警）\n激素与脱水用药护理：按医嘱准时给药，观察疗效与不良反应（血糖、血压、消化道出血、感染），监测血糖与电解质\n体位与呼吸护理：上腔静脉综合征者抬高床头、吸氧、避免上肢输液（选下肢或中心静脉）；颅内高压者床头抬高15～30°\n出入量与电解质监测：准确记录24小时出入量与尿量，高钙血症者补液充足、颅压增高者限制液体，监测血钠与血钙\n疼痛与舒适护理：按三阶梯镇痛并预防便秘，评估疼痛评分；截瘫/活动障碍者每2小时轴线翻身防压疮，保持皮肤清洁干燥\n心理与家属沟通：急症病情危重，及时沟通病情与治疗紧迫性，安抚情绪并配合完成知情同意与治疗转运\n\n【饮食】\n高钙血症：充足饮水（每日2000～3000ml，心肾功能允许下）、低钙饮食（避免大量牛奶与钙剂）、限制钠盐\n颅内高压：按医嘱限制液体入量，避免大量饮水；低盐饮食\n脊髓压迫/卧床患者：高纤维饮食与充足水分（防便秘，避免用力排便）、高蛋白饮食防压疮与肌肉萎缩\n激素治疗期间：低盐低糖饮食、控制体重、补充钙与维生素D（预防骨质疏松）、保护胃黏膜\n总体原则：高蛋白、高热量、易消化，少量多餐；必要时口服营养补充剂或肠内营养支持\n\n【注意事项】\n肿瘤急症的共同特点是进展快、可致不可逆损伤或死亡，需在数小时内识别与处理\n脊髓压迫患者24小时内明确诊断并治疗（激素+放疗或手术），延迟治疗常致永久性截瘫与大小便功能障碍\n激素是减轻水肿的重要手段但不能替代抗肿瘤治疗；激素减量需缓慢（防水肿反跳）\n高钙血症处理首要是补液（禁用噻嗪类利尿剂与制动），双膦酸盐为一线降钙药物（需监测肾功能与血钙）\n脑转移患者抗癫痫药仅用于有发作者（预防性用药不推荐）；激素与抗癫痫药有相互作用需注意\n\n【急诊/急救】\n脊髓压迫（背痛+肢体无力+大小便障碍）→ 立即激素+全脊柱MRI，24小时内放疗或手术减压\n上腔静脉综合征伴呼吸困难、意识改变或气道受压 → 抬高床头、吸氧、激素+利尿，紧急放疗或支架置入\n颅内高压伴意识恶化、瞳孔不等大（脑疝）→ 立即甘露醇/高渗盐水+激素，急诊放疗或手术减压\n高钙危象（血钙>3.5mmol/L伴意识障碍或心律失常）→ 立即大量补液+利尿+双膦酸盐，必要时透析\n癫痫持续状态（脑转移患者）→ 立即静推地西泮/咪达唑仑+抗癫痫药负荷量，保护气道","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"C80.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2781,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ba272bb3f0cf56295298275b142f57d25fc69d3174cedb3d9ea4129fc331d458","pinyin":"zhongliujizheng","initials":"zljz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","C80.0",30]]},{"id":"templates-33b211aa13cf1fae866c","key":"v1-c9ccc21dfe2a3058|templates-33b211aa13cf1fae866c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肿瘤溶解综合征","category":"临床急症","raw":{"name":"肿瘤溶解综合征","category":"临床急症","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】恶心呕吐、乏力；少尿/无尿提示急性肾损伤；肌肉痉挛、手足麻木、抽搐（低钙）；心悸、晕厥提示高钾心律失常；癫痫、意识改变见于严重电解质紊乱。。\n【待人工确认·本机素材无此段原文】","现病史":"危急阈值：Cairo-Bishop分级≥2级（实验室TLS：尿酸↑、K⁺↑、PO₄³⁻↑、Ca²⁺↓；临床TLS：Cr↑、心律失常/猝死、癫痫）。临床意义：TLS是肿瘤治疗中大量细胞溶解释放细胞内成分（尿酸、K⁺、PO₄³⁻）入血的代谢急症，高发于急性白血病（尤其ALL）、Burkitt淋巴瘤等；严重者可致急性肾损伤（尿酸结晶+磷酸钙沉积）、高钾心律失常甚至猝死。\n常见表现：恶心呕吐、乏力；少尿/无尿提示急性肾损伤；肌肉痉挛、手足麻木、抽搐（低钙）；心悸、晕厥提示高钾心律失常；癫痫、意识改变见于严重电解质紊乱。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"神志、皮肤弹性与脱水表现、心率心律、水肿；低钙体征（Chvostek征、Trousseau征）；记录尿量。","辅助检查":"血尿酸、K⁺、Ca²⁺、PO₄³⁻、肌酐、LDH、血常规动态监测（q6h）；血气分析；持续心电监护观察高钾心电图改变。","初步诊断":"高危条件：高增殖、高肿瘤负荷、化疗高度敏感的肿瘤。化疗启动后查血尿酸↑、K⁺↑、PO₄³⁻↑、Ca²⁺↓、LDH显著升高、肌酐↑，按Cairo-Bishop标准分级；据风险分层（低/中/高/极高危）决定预防强度；治疗前评估基线肾功能与尿酸。\n1. 肿瘤溶解综合征（ICD-10：E88.8）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n强化水化3L/m²/d或200-300ml/h（平衡液或0.45%NaCl），监测出入量、维持足够尿量以冲刷尿酸与磷酸盐；心肾功能不全者调整补液速度，尿量充足时可加利尿剂维持尿量。\n\n【药物治疗·口服】\n别嘌醇300mg/m²/d口服用于预防（对已升高的尿酸作用慢）；高磷血症予磷酸盐结合剂随餐口服：碳酸镧750mg tid或司维拉姆800mg tid。\n\n【治疗】\n降尿酸：已出现高尿酸或中/高危TLS首选拉布立酶（雷布立酶）0.2mg/kg IV qd，1-2小时内降至正常（G6PD缺乏者禁用，用前筛查）；高钾（见心内科章）：静脉钙剂+胰岛素葡萄糖+利尿等，必要时透析；低钙：无症状不处理（防磷酸钙沉积加重），有症状予葡萄糖酸钙；严重肾损伤（Cr↑、少尿、药物无效）→血液透析。\n\n【处理要点】\n化疗前后q6h监测血常规、尿酸、K⁺、Ca²⁺、PO₄³⁻、Cr、LDH，高危者持续3-7天；记录出入量维持尿量；据风险分层决定预防强度（水化、别嘌醇或拉布立酶）。\n\n【护理】\n心电监护并观察心律失常；准确记录24小时出入量、维持尿量；静脉补液执行与巡视（防液体过负荷）；宣教低钾饮食；观察抽搐、手足麻木与神志变化。\n\n【饮食】\n限钾饮食（少食香蕉、柑橘、土豆、绿叶菜等富钾食物）；限磷饮食（少食乳制品、坚果、加工食品）；治疗期以静脉补液为主。\n\n【注意事项】\n拉布立酶禁用于G6PD缺乏者（可致溶血），用药前必须筛查；别嘌醇对已升高的尿酸作用缓慢，已确诊高尿酸时优先拉布立酶；无症状低钙不补钙，以免磷酸钙沉积加重肾损伤。\n\n【急诊/急救】\n高钾致恶性心律失常（心电图T波高尖、QRS增宽、室速/室颤）：立即静脉钙剂+胰岛素葡萄糖等紧急降钾并持续心电监护，转ICU；少尿性急性肾衰经药物治疗无效→紧急血液透析。","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"E88.8","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2782,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bbcf794ffc5c4ee069eaaceb8aeb82b1940afa4aa0b5af86926f262ff9a33eb7","pinyin":"zhongliurongjiezonghezheng","initials":"zlrjzhz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","E88.8",30]]},{"id":"templates-cbc2e295272ca1b7715a","key":"v1-c9ccc21dfe2a3058|templates-cbc2e295272ca1b7715a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脑与蛛网膜下腔出血","category":"临床急症","raw":{"name":"脑与蛛网膜下腔出血","category":"临床急症","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】脑出血：突发头痛呕吐、意识障碍、一侧肢体无力、言语障碍、血压显著升高。、蛛网膜下腔出血：突发剧烈头痛（雷击样）、颈项强直、呕吐、畏光，可伴短暂意识丧失。、分层依据：血肿量≤30mL 为小量，30~60mL 为中等量，>60mL 或脑干、小脑出血为大量。、危险信号：意识进行性下降、瞳孔不等大、抽搐、呼吸不规则、再出血表现。。\n【待人工确认·本机素材无此段原文】","现病史":"定义：非外伤性脑血管破裂后脑实质出血性卒中，最常见病因是高血压与脑小动脉硬化。脑出血形成血肿后易引起脑水肿、脑组织受压移位、软化与坏死，可因脑疝致死；蛛网膜下腔出血系脑表面血管破裂，血液流入蛛网膜与软脑膜间的蛛网膜下腔。治疗目的是减少脑损伤范围、改善循环、控制脑水肿与降低颅内压。\n夜班目标：按血肿量分层控制血压、降颅压、止血与脑保护，掌握手术与脑室外引流指征，防止再出血与脑疝。\n常见表现：脑出血：突发头痛呕吐、意识障碍、一侧肢体无力、言语障碍、血压显著升高。、蛛网膜下腔出血：突发剧烈头痛（雷击样）、颈项强直、呕吐、畏光，可伴短暂意识丧失。、分层依据：血肿量≤30mL 为小量，30~60mL 为中等量，>60mL 或脑干、小脑出血为大量。、危险信号：意识进行性下降、瞳孔不等大、抽搐、呼吸不规则、再出血表现。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"神经系统：意识水平（格拉斯哥昏迷评分）、瞳孔大小与光反应、脑膜刺激征、肢体肌力、病理反射。\n循环与呼吸：血压、心率、呼吸节律、SpO2，注意库欣反应。\n其他：体温、眼底（有无视乳头水肿与玻璃体膜下出血）、外伤痕迹、颈项强直程度。","辅助检查":"必查：头颅 CT（急诊首选）、血糖、血常规、凝血功能、肾功能、电解质、心电图。\n按需：CT 血管成像或数字减影血管造影、腰椎穿刺（CT 阴性而高度怀疑蛛网膜下腔出血）、血型与交叉配血、心肌损伤标志物。\n复评：动态复查头颅 CT 评估血肿与脑水肿；体温目标≤37.5℃，超过时予对乙酰氨基酚 650mg 每 6 小时 1 次。","初步诊断":"病史：起病形式与时间、既往高血压、动脉瘤或家族史、抗凝抗血小板药物使用、外伤史、吸烟与饮酒。\n诱因：情绪激动、用力排便、剧烈活动、血压骤升。\n影像评估：CT 点征出现于出血 6 小时内，提示血肿可能扩大；24 小时复查 CT 血管成像排除继发动静脉畸形；蛛网膜下腔出血以数字减影血管造影为金标准。\n凝血管理：华法林相关出血予凝血酶原复合物 25~50U/kg 加维生素 K 10mg。\n1. 脑与蛛网膜下腔出血（ICD-10：I61.9）","鉴别诊断":"1. 24 小时复查 CT 血管成像排除继发动静脉畸形","处理方案":"【药物治疗·输液】\n血压控制（小量出血首选尼卡地平）：尼卡地平 10mg 加 5% 葡萄糖 40mL 泵入，从 10mL/h 起始（心率超过 100 次/分需减量）；次选乌拉地尔，先静推 6.25mL（5 分钟推完），再泵入 3~5mL/h，血压稳定后降至 3mL/h，每小时降幅≤15%。\n中等量出血：心率正常或偏慢首选尼卡地平；心率>100 次/分者改用拉贝洛尔，先 20mg 静推 2 分钟，继以 200mg 加 0.9% 氯化钠 50mL 泵入 15~60mL/h。\n颅内压管理：甘露醇 0.5~1.0g/kg 静滴每 6~8 小时 1 次（维持血浆渗透压 300~320mOsm/L），中等量加呋塞米 10mg 静推；估算肾小球滤过率<30mL/min 者改用 3% 氯化钠 100mL 静滴每 6 小时 1 次。\n大量或脑干、小脑出血：3% 氯化钠 100mL 静滴每 4 小时 1 次，目标颅内压<20mmHg；镇静与脑保护予丙泊酚 50mg 泵入 6~18mL/h。\n抗纤溶止血：氨甲环酸 1g 静滴超过 10 分钟，继以 1g 泵入 2mL/h 持续 24 小时；仅用于活动性出血且动脉瘤未处理者，介入或术后 24 小时停用。\n\n【药物治疗·口服】\n急性期多卧床、常伴呕吐与意识障碍，一般禁食禁口服，药物经静脉或胃管给予。\n意识清楚、吞咽安全者：尼莫地平片 60mg 口服每 4 小时 1 次（蛛网膜下腔出血静脉治疗第 13 天提前 12 小时开始口服，维持 14 天）；脑积水者乙酰唑胺片 250mg 口服每日 3 次；癫痫防治予左乙拉西坦 0.5g 口服每日 2 次。\n恢复期二级预防：阿托伐他汀钙片 20mg 口服每晚 1 次（低密度脂蛋白胆固醇目标<1.4mmol/L）；氯吡格雷片 75mg 口服每日 1 次。\n限制：意识不清或吞咽障碍者经胃管给药，不口服。\n\n【治疗】\n首要：保持气道通畅与呼吸循环稳定，快速头颅 CT 确诊；立即评估血肿量分层处理，控制血压（每小时降幅≤15%）与颅内压。\n其次：停用抗凝与抗血小板药物并按规范拮抗（华法林相关出血予凝血酶原复合物 25~50U/kg 加维生素 K 10mg）；抽搐者止抽，纠正电解质紊乱。\n随后：大量出血或脑干、小脑出血者评估手术（去骨瓣减压）；小脑出血>3cm 或脑干受压、脑室积血或急性脑积水者立即行脑室外引流，初始放液速度≤10mL/h；蛛网膜下腔出血者预防脑血管痉挛（尼莫地平注射液 50mL 泵入 2.5~5mL/h 维持 14 天；不耐受者用法舒地尔 30mg 静滴每日 3 次）。\n最后：动脉瘤未闭锁期予抗纤溶止血（氨甲环酸总疗程≤72 小时，与介入或手术间隔>4 小时），尽早请神经外科评估夹闭或栓塞。\n\n【处理要点】\n复评：每 15~30 分钟评估意识、瞳孔与生命体征，稳定后每小时记录；动态复查头颅 CT。\n观察：意识与瞳孔变化、血压、头痛程度、抽搐、尿量与电解质、有无再出血与脑血管痉挛表现。\n随访：每日复查电解质与肾功能，监测凝血功能。\n收治：全部患者收入神经外科或监护病房；动脉瘤性出血应尽早干预。\n\n【护理】\n体位：床头抬高 15~30 度，头偏向一侧防误吸；绝对卧床，避免用力与频繁搬动。\n监测：意识、瞳孔、血压、呼吸与 SpO2，注意癫痫发作与再出血；记录脑室外引流量与性状。\n记录：意识与瞳孔变化、血压曲线、甘露醇与高渗盐水使用与尿量、出入量、体温。\n安全：安静避光、减少刺激，避免用力排便与剧烈咳嗽，加床栏防坠床。\n\n【注意事项】\n以本院规范为准：降压目标与药物选择、脱水剂与高渗盐水剂量、抗纤溶方案与手术指征按本院常规执行。\n禁用：急性期不用抗血小板与抗凝药物；氨甲环酸不用于动脉瘤已处理者，总疗程≤72 小时；甘露醇在估算肾小球滤过率<30mL/min 时改用高渗盐水；血压每小时降幅≤15%。\n提醒：突发雷击样头痛即使 CT 阴性，也需按规范进一步排查动脉瘤。\n\n【急诊/急救】\n立即升级：意识下降、瞳孔不等大、呼吸不规则、血压>180/110mmHg、剧烈头痛再发、抽搐、SpO2<92% → 立即复查 CT、降颅压并呼叫上级。\n疑再出血或脑疝：紧急神经外科会诊并准备手术。\n提示：甘露醇使用期间监测肾功能与血浆渗透压；氨甲环酸仅用于活动性出血且总疗程≤72 小时。","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「脑与蛛网膜下腔出血」原文）"},"icd10_diagnosis":"I61.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2783,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b353a4b6ebddcc80dd1b3e78fed504ed8c1a85293870b4cff444fdf253251dfc","pinyin":"naoyuzhuwangmoxiaqiangchuxie","initials":"nyzwmxqcx","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","I61.9",30]]},{"id":"templates-35b37020951e49cd2592","key":"v1-c9ccc21dfe2a3058|templates-35b37020951e49cd2592","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脑血栓与脑栓塞","category":"临床急症","raw":{"name":"脑血栓与脑栓塞","category":"临床急症","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】典型：突发一侧肢体无力或麻木、口角歪斜、言语含糊或失语、视物模糊、行走不稳、意识障碍。、脑栓塞特点：起病更急骤，多在活动中发病，可伴心房颤动、瓣膜病等栓子来源。、危险信号：意识迅速恶化、呼吸不规则、抽搐、呕吐、血压极高或极低。、时间要素：发病时间是决定治疗方案的关键，须记录最后正常时间。。\n【待人工确认·本机素材无此段原文】","现病史":"定义：因脑缺血导致的脑卒中。脑血栓指在脑动脉粥样硬化基础上形成血栓致管腔狭窄或闭塞；脑栓塞指颅外栓子经血液循环堵塞脑血管，常见于瓣膜性心脏病、冠心病与心房颤动。两者均导致脑血管血流受阻与组织梗死。急性期治疗在于尽快遏制缺血面积扩展、减少梗死范围、改善半暗带循环、控制脑水肿。\n夜班目标：发病 4.5 小时内评估静脉溶栓，3 小时内获益更显著；按时间窗分层考虑机械取栓，并管理血压与血糖。\n常见表现：典型：突发一侧肢体无力或麻木、口角歪斜、言语含糊或失语、视物模糊、行走不稳、意识障碍。、脑栓塞特点：起病更急骤，多在活动中发病，可伴心房颤动、瓣膜病等栓子来源。、危险信号：意识迅速恶化、呼吸不规则、抽搐、呕吐、血压极高或极低。、时间要素：发病时间是决定治疗方案的关键，须记录最后正常时间。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"神经系统：意识水平、瞳孔、面瘫、肢体肌力与肌张力、病理反射、共济失调、言语与视野。\n循环：心率与心律（判断房颤）、血压、双侧颈动脉杂音、外周动脉搏动。\n其他：体温、SpO2、头部有无外伤、皮肤有无栓塞表现。","辅助检查":"必查：头颅 CT（急诊首选，排除出血）、床旁血糖、血常规、凝血功能、肾功能、电解质、心电图。\n按需：头颅磁共振与血管成像、颈部血管超声、心脏超声、血脂、糖化血红蛋白、心肌损伤标志物。\n复评：溶栓后 24 小时内监测神经功能与出血征象；血糖目标 7.8~10.0mmol/L。","初步诊断":"病史：起病时间与症状演变、既往房颤、高血压、糖尿病、血脂异常、吸烟与既往卒中史。\n诱因：心房颤动、瓣膜性心脏病、冠心病、近期心肌梗死、颈动脉狭窄、脱水与久坐。\n鉴别：脑出血、蛛网膜下腔出血、低血糖、癫痫后麻痹、偏头痛先兆、颅内占位。\n时间窗分层：≤3 小时优先静脉溶栓；3~24 小时经多模影像评估后行机械取栓；>24 小时启动脑保护与抗血小板治疗。\n1. 脑血栓与脑栓塞（ICD-10：I63.9）","鉴别诊断":"1. 鉴别：脑出血、蛛网膜下腔出血、低血糖、癫痫后麻痹、偏头痛先兆、颅内占位","处理方案":"【药物治疗·输液】\n静脉溶栓（发病≤4.5 小时）：阿替普酶 0.9mg/kg（最大 90mg），总量的 10% 加 0.9% 氯化钠 10mL 静推 1 分钟，剩余 90% 加 0.9% 氯化钠 50mL 静脉泵入 1 小时；禁忌证为近期手术或创伤、活动性出血、血压>180/110mmHg、血小板<10 万/mm³。\n溶栓替代：尿激酶 150 万U 加 0.9% 氯化钠 100mL 静滴 30 分钟，发病 6 小时内使用并需签署知情同意。\n脑水肿控制：甘露醇 125mL 静滴 20 分钟内完成每 6~8 小时 1 次；或呋塞米 40mg 静推加 20% 人血白蛋白 50mL 静滴协同降颅压。\n血压与血糖：尼莫地平注射液 50mL 泵入 2.5~10mL/h，目标血压下降 10%~15%（避光使用并监测肝功能）；溶栓或取栓后血压维持<180/105mmHg，非溶栓患者急性期允许≤220/120mmHg；胰岛素持续静脉泵入 0.1U/kg/h。\n\n【药物治疗·口服】\n神经保护与微循环改善：依达拉奉 30mg 加 0.9% 氯化钠 100mL 静滴每日 2 次连用 14 天；丁苯酞氯化钠注射液 25mg 静滴每日 2 次，14 天后改丁苯酞软胶囊 0.2g 口服每日 4 次。\n抗血小板（溶栓 24 小时后启动）：阿司匹林肠溶片 100mg 每日 1 次（负荷 300mg）加氯吡格雷片 75mg 每日 1 次（负荷 300mg），持续 21 天后改为单药维持。\n二级预防：阿托伐他汀钙片 20mg 口服每晚 1 次（低密度脂蛋白胆固醇目标<1.8mmol/L）加依折麦布片 10mg 每日 1 次；甲钴胺片 0.5mg 每日 3 次。\n房颤相关脑栓塞抗凝：梗死体积小者 3 天、大面积梗死者 14 天后启动；利伐沙班片 10mg 口服每日 1 次，或达比加群酯胶囊 150mg 每日 2 次。\n限制：急性期吞咽功能评估前禁食禁口服，吞咽障碍者经胃管给药。\n\n【治疗】\n首要：识别卒中并记录最后正常时间，10 分钟内完成血糖与头颅 CT，排除出血后评估溶栓与取栓。\n其次：按时间窗分层干预。≤3 小时优先阿替普酶静脉溶栓；3~24 小时经多模影像评估后行机械取栓；>24 小时启动脑保护与抗血小板治疗。\n随后：管理血压、血糖、体温与氧合，保持气道通畅；控制脑水肿，防治并发症。\n最后：明确病因（心源性、大动脉粥样硬化、小血管病），启动二级预防与康复评估；颈动脉狭窄>70% 的症状性病变可考虑支架，烟雾病或低灌注梗死可考虑颅内外搭桥。\n\n【处理要点】\n复评：溶栓后 24 小时内按卒中单元规范加密监测神经功能与血压，注意神经功能恶化。\n观察：意识与肌力变化、血压、心律、血糖、吞咽功能、有无出血与颅内压增高。\n随访：隔日复查电解质与血肌酐；监测血脂与肝功能。\n收治：全部急性缺血性卒中患者收入卒中单元或神经内科监护病房，评估取栓者转导管室。\n\n【护理】\n体位：平卧或床头抬高 15~30 度，意识不清者侧卧防误吸，避免颈部过度屈曲。\n监测：神经功能与生命体征，溶栓后按规范加密观察，注意穿刺点与皮肤黏膜出血。\n记录：发病与到院时间、溶栓时间节点、神经功能评分变化、用药与血压记录。\n安全：禁食至吞咽评估完成，床栏保护，防坠床与压疮。\n\n【注意事项】\n以本院规范为准：溶栓与取栓适应证、血压管理目标、抗栓启动时机与抗凝时间按本院常规执行。\n禁用：溶栓禁忌者（近期手术或创伤、活动性出血、血压>180/110mmHg、血小板<10 万/mm³）不得溶栓；溶栓后 24 小时内禁用抗血小板与抗凝药物；急性期不盲目快速降压与大量补液。\n提醒：时间窗分层管理是关键；尼莫地平需避光使用并监测肝功能。\n\n【急诊/急救】\n立即升级：神经功能进行性恶化、意识下降、瞳孔不等大、呕吐伴血压升高、抽搐、SpO2<92% → 立即复查头颅 CT 并呼叫上级。\n溶栓后突发头痛呕吐意识改变：按症状性颅内出血处理并复查头颅 CT。\n提示：溶栓前必须排除近期手术或创伤、活动性出血、血压>180/110mmHg与血小板<10 万/mm³；溶栓后 24 小时内禁用抗血小板与抗凝药物。","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「脑血栓与脑栓塞」原文）"},"icd10_diagnosis":"I63.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2784,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a7b3051b56afa0f1db277449ae1a87db19c6ff7809b078c1974c227226621190","pinyin":"naoxueshuanyunaoshuanse","initials":"nxsynss","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","I63.9",30]]},{"id":"templates-86f9d6d094419b97b586","key":"v1-c9ccc21dfe2a3058|templates-86f9d6d094419b97b586","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"酒精中毒性精神障碍","category":"临床急症","raw":{"name":"酒精中毒性精神障碍","category":"临床急症","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】急性中毒：兴奋多语、面色潮红、步态不稳、共济失调，继而昏睡甚至昏迷，可伴呼吸抑制。、戒断与慢性中毒：手抖、出汗、心慌、焦虑、失眠，进一步出现震颤、谵妄、幻觉与妄想，认知障碍与人格改变。、危险信号：高热、大汗、抽搐、意识波动、血压升高、共济失调、眼球运动异常。、特殊提示：停饮后 6~24 小时出现戒断表现，48~96 小时易出现震颤谵妄；补充葡萄糖前必须先补维生素 B1。。\n【待人工确认·本机素材无此段原文】","现病史":"定义：由饮酒导致的精神障碍，常合并相应躯体症状与体征。既可发生在一次大量饮酒之后，也可因长期饮酒形成依赖后出现停饮症状。急性中毒可相继出现兴奋、共济失调、昏睡甚至昏迷；慢性中毒的精神症状包括震颤、谵妄、幻觉与妄想，部分病例发生中毒性脑病。治疗需按躁狂或抑郁状态选配药物，彻底戒酒是治愈关键。\n夜班目标：生命支持与解毒（纳洛酮）、补充 B 族维生素、控制戒断与谵妄，保证环境安全，防止自伤与他伤。\n常见表现：急性中毒：兴奋多语、面色潮红、步态不稳、共济失调，继而昏睡甚至昏迷，可伴呼吸抑制。、戒断与慢性中毒：手抖、出汗、心慌、焦虑、失眠，进一步出现震颤、谵妄、幻觉与妄想，认知障碍与人格改变。、危险信号：高热、大汗、抽搐、意识波动、血压升高、共济失调、眼球运动异常。、特殊提示：停饮后 6~24 小时出现戒断表现，48~96 小时易出现震颤谵妄；补充葡萄糖前必须先补维生素 B1。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"意识与认知：意识水平与波动、定向力、注意力、幻觉内容与形式。\n神经系统：震颤、共济失调、眼球运动与眼震、瞳孔、病理反射、肌力。\n其他：体温、血压、心率、皮肤与巩膜黄染、脱水征、外伤痕迹。","辅助检查":"检查计划：患者有长期大量饮酒史，此次出现兴奋多语、步态不稳、共济失调、昏睡甚至昏迷，或停饮后手抖、出汗、心慌、焦虑并出现震颤、谵妄、幻觉，入院即刻完善床旁血糖检查以排除低血糖所致意识障碍，其表现与醉酒极易混淆；长期饮酒常伴镁、磷缺乏，完善电解质（钾、镁、磷）检查以排除电解质紊乱所致心律失常及谵妄，并指导补充治疗；完善肝功能、肾功能检查以评估酒精性肝损伤及药物代谢能力，指导镇静药物剂量；完善血常规及凝血功能检查以排除感染、消化道出血及肝病所致凝血障碍；完善血气分析检查以排除代谢性酸中毒及呼吸抑制所致低氧；酒精可致心肌损伤，完善心肌损伤标志物检查以排除酒精性心肌损伤；患者有外伤或意识状态与饮酒史不符，急诊完善头颅CT检查以排除颅内出血及颅脑外伤；完善血氨检查以鉴别肝性脑病，完善血乙醇浓度测定以明确中毒程度；发热者完善感染指标与血培养检查以排除感染这一常见戒断诱因；完善心电图检查以排除心律失常；长期饮酒进食减少者完善B族维生素水平检查以排除维生素B1缺乏所致Wernicke脑病，补充葡萄糖前须先补维生素B1；治疗期间每周复查血镁、磷及转氨酶1次，动态评估营养与肝功能恢复情况。\n\n（检查清单）\n必查：床旁血糖、电解质（钾、镁、磷）、肝肾功能、血常规、凝血功能、血气、心肌损伤标志物。\n按需：头颅 CT（外伤或意识与饮酒史不符）、血氨、乙醇血浓度、感染指标与血培养、心电图、B 族维生素水平。\n复评：生化指标（血镁、磷、转氨酶）每周复查 1 次。","初步诊断":"病史：饮酒年限、每日饮酒量、末次饮酒时间、既往戒断或谵妄发作史、有无外伤与合并用药。\n诱因：突然停酒、感染、外伤、手术、进食减少、肝病。\n鉴别：肝性脑病、低血糖、颅内感染、脑出血、药物中毒、精神分裂症、甲状腺危象。\n风险评估：可用戒断评估量表（如 PAWSS）评估戒断风险，指导镇静药剂量。\n1. 酒精中毒性精神障碍（ICD-10：F10.5）","鉴别诊断":"1. 鉴别：肝性脑病、低血糖、颅内感染、脑出血、药物中毒、精神分裂症、甲状腺危象","处理方案":"【药物治疗·输液】\n解毒与生命支持：纳洛酮 0.4~0.8mg 加 10% 葡萄糖 20mL 缓慢静推 5 分钟，继以纳洛酮 2mg 加 10% 葡萄糖 500mL 静滴 0.1mg/kg/h 维持；需心电监护，警惕反跳性戒断反应。\n维生素替代：维生素 B1 注射液 200mg 肌注每日 2 次（首剂），继以 100mg 肌注每日 1 次维持 5 天；或复合维生素 B 注射液 2 支加 0.9% 氯化钠 250mL 静滴每日 1 次。\n代谢调节：普通胰岛素 8U 加 50% 葡萄糖 40mL 静推>5 分钟，继以普通胰岛素 12U 加 10% 葡萄糖 500mL 静滴，血糖维持 7~10mmol/L。\n癫痫或严重激越：劳拉西泮 2~4mg 缓慢静推（每 15 分钟重复，极量 20mg/24h）；难治性抽搐首选地西泮直肠凝胶 10~20mg 纳肛。\n\n【药物治疗·口服】\n戒断综合征：症状控制后劳拉西泮片 1~2mg 口服每 6 小时 1 次并逐渐递减，每 3 天减量 25%。\n严重激越：奥氮平片 5~10mg 舌下含服每 8 小时 1 次（仅限严重激越时使用）。\n抗渴求（需戒酒≥7 天启动）：阿坎酸片 666mg 口服每日 3 次（餐时），或纳曲酮长效注射剂 380mg 肌注每月 1 次。\n慢性脑病与认知改善：美金刚片 5mg 口服每日 1 次起始，每周递增 5mg，目标 20mg 每日 1 次；维生素 B1 片 100mg 口服每日 3 次（持续 4 周）。\n限制：意识模糊、幻觉明显或不配合者不口服。\n\n【治疗】\n首要：评估意识、生命体征与外伤，安静环境、专人看护，防止自伤与他伤；清理口鼻分泌物、吸氧，必要时气管插管。\n其次：解毒与维生素替代同步进行——纳洛酮加 B 族维生素冲击疗法，纠正低血糖、脱水与电解质紊乱，注意补镁、补磷。\n随后：控制戒断与谵妄。苯二氮䓬类为一线，劳拉西泮阶梯式递减（每 3 天减量 25%），严重激越时短期加奥氮平；幻觉与妄想明显者由精神科按病情选配药物。\n最后：慢性期予阿坎酸加纳曲酮双靶点抗渴求，配合神经修复与心理干预，彻底戒酒。\n\n【处理要点】\n复评：戒断期每 1~2 小时评估意识、震颤与生命体征，按量表评分调整镇静药剂量。\n观察：体温、心率、血压、意识波动、抽搐、幻觉、尿量与电解质。\n随访：每周复查血镁、磷与转氨酶；监测血糖（胰岛素-葡萄糖疗法期间）。\n收治：震颤谵妄、抽搐、意识障碍、合并外伤或感染、无法口服者收入院或监护病房。\n\n【护理】\n体位：安静单间、光线柔和，卧床并加床栏；呕吐时侧卧防误吸。\n监测：意识、体温、心率、血压、SpO2、震颤与幻觉变化。\n记录：镇静药给药时间与剂量、戒断评分、出入量与电解质、血糖。\n安全：清除危险物品，专人陪护；约束具按本院规范使用并记录，防止自伤与他伤。\n\n【注意事项】\n以本院规范为准：苯二氮䓬类剂量调整、抗精神病药使用指征、约束与转诊流程按本院常规执行。\n禁用：不主张单用抗精神病药控制戒断（可能降低抽搐阈值）；补充葡萄糖前必须先给维生素 B1；奥氮平仅限严重激越时短期使用。\n提醒：震颤谵妄属急症，死亡率高，不可只给镇静药观察；抗渴求药物需在戒酒≥7 天后启动。\n\n【急诊/急救】\n立即升级：体温>38.5℃、心率>120 次/分、抽搐、意识明显波动或昏迷、收缩压>180mmHg、SpO2<92% → 转监护病房并呼叫上级。\n疑颅内出血或感染：急查头颅 CT与腰椎穿刺。\n提示：补充葡萄糖前必须先给维生素 B1；纳洛酮使用期间警惕反跳性戒断反应。","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「酒精中毒性精神障碍」原文）"},"icd10_diagnosis":"F10.5","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2785,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0bb56d9b5b0b6381d2dfbb3b6ca103bb5dff8bf65dfb6fa9c4338ae10ab88bc4","pinyin":"jiujingzhongduxingjingshenzhangai","initials":"jjzdxjsza","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","F10.5",30]]},{"id":"templates-9152045d9d089e9c7e85","key":"v1-c9ccc21dfe2a3058|templates-9152045d9d089e9c7e85","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"重度血小板减少症","category":"临床急症","raw":{"name":"重度血小板减少症","category":"临床急症","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】皮肤瘀点瘀斑、牙龈出血、鼻出血、口腔血疱；血便/血尿提示消化道或泌尿道出血；突发剧烈头痛、呕吐、意识改变提示颅内出血（最危急）。。\n【待人工确认·本机素材无此段原文】","现病史":"危急阈值：血小板(PLT)≤20×10⁹/L，最常见于重症免疫性血小板减少症(ITP)与化疗后骨髓抑制。临床意义：PLT<50×10⁹/L外伤/手术出血风险增加；<20×10⁹/L可自发皮肤黏膜出血；<10×10⁹/L内脏及颅内出血风险显著升高，需预防性输注血小板。\n常见表现：皮肤瘀点瘀斑、牙龈出血、鼻出血、口腔血疱；血便/血尿提示消化道或泌尿道出血；突发剧烈头痛、呕吐、意识改变提示颅内出血（最危急）。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮肤瘀点瘀斑、口腔黏膜血疱、牙龈渗血、眼底出血、鼻腔出血；疑颅内出血者查神志、瞳孔与神经系统体征。","辅助检查":"检查计划：患者出现皮肤瘀点瘀斑、牙龈出血、鼻出血、口腔血疱，血常规示血小板≤20×10⁹/L，入院即刻复查血常规并完善外周血涂片检查以复核血小板计数，排除EDTA依赖性假性血小板减少；完善凝血功能检查并检测D-二聚体、纤维蛋白原以排除弥散性血管内凝血（DIC）所致消耗性血小板减少；疑免疫性血小板减少症（ITP）者，完善血小板抗体检查以明确诊断并指导糖皮质激素及丙种球蛋白治疗；疑血栓性血小板减少性紫癜（TTP）者，出现溶血表现时完善LDH、破碎红细胞及ADAMTS13检查以明确微血管病性溶血，该病需紧急血浆置换；疑肝素诱导的血小板减少症（HIT）者，有肝素暴露史时完善PF4抗体检查以明确诊断并立即停用肝素；完善肝功能、肾功能检查以评估肝脏合成功能与药物代谢，为用药安全提供依据；患者有血便或血尿提示消化道、泌尿道出血，完善尿常规、粪便隐血检查以明确出血部位；疑再生障碍性贫血或白血病者，病情允许时完善骨髓穿刺及骨髓活检检查以明确造血系统病因；突发剧烈头痛、呕吐、意识改变提示颅内出血，急诊完善头颅CT检查以排除颅内出血这一最危急并发症。\n\n（检查清单）\n血常规+血涂片、凝血功能、血小板抗体、肝肾功能；疑DIC查D-二聚体/纤维蛋白原；疑TTP查LDH、破碎红细胞、ADAMTS13；疑HIT查PF4抗体。","初步诊断":"血常规示PLT≤20×10⁹/L并经外周血涂片复核（排除EDTA依赖性假性减少）。评估出血迹象（皮肤黏膜、眼底、消化道、泌尿道、中枢）。病因鉴别：ITP（血小板相关抗体）、TTP（ADAMTS13、破碎红细胞、LDH）、HIT（肝素暴露史+PF4抗体）、再障/白血病（骨髓检查）。\n1. 重度血小板减少症（ICD-10：D69.6）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n输血指征：①活动性出血→输注血小板1-2个治疗量（成人1个治疗量约提升PLT 20-30×10⁹/L）；②PLT<10×10⁹/L无出血→预防性输注，尤其合并发热/感染/抗凝时；③PLT<50×10⁹/L需侵入性操作→操作前输注；④ITP血小板被快速破坏、输注疗效差，仅用于致命性出血。\n\n【药物治疗·口服】\nITP：地塞米松40mg/d口服×4天或泼尼松1mg/kg/d；化疗后骨髓抑制：艾曲泊帕、阿伐曲泊帕等口服TPO-RA；禁服阿司匹林等抗血小板药与抗凝药。\n\n【治疗】\n病因治疗：ITP→糖皮质激素+IVIG 1g/kg（急救/术前）；TTP→血浆置换+激素；HIT→停肝素、换比伐卢定或阿加曲班；再障→免疫抑制或移植评估；化疗后骨髓抑制→TPO-RA（罗米司亭/艾曲泊帕/阿伐曲泊帕）。严重出血可加抗纤溶药氨甲环酸1g IV q8h，尿路出血禁用（血凝块可致梗阻）。\n\n【处理要点】\n严密观察皮肤黏膜、眼底、消化道、泌尿道及中枢出血迹象；输注后复查血小板评价疗效；避免肌内注射、硬毛牙刷、牙龈刺激及不必要有创操作；使用抗纤溶药者监测血栓风险。\n\n【护理】\n急性期卧床休息、减少活动防碰撞跌倒；用软毛牙刷或纱布清洁口腔；观察并记录大小便颜色、痰液及呕吐物有无血性；静脉穿刺后按压5-10分钟以上；避免肌注与灌肠。\n\n【饮食】\n温凉软食，避免过热、坚硬、粗糙及带骨刺食物，防止划伤消化道黏膜。\n\n【注意事项】\nITP输注血小板疗效短暂，仅限致命性出血时使用；PLT<10×10⁹/L合并发热/感染/抗凝是预防性输注的强化指征；氨甲环酸禁用于尿路出血。\n\n【急诊/急救】\n颅内或内脏大出血：紧急输注血小板（可多单位）、大剂量糖皮质激素冲击、IVIG 1g/kg，必要时重组人凝血因子Ⅶa，请血液科会诊并转ICU；同步头颅CT明确颅内出血。","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"D69.6","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2786,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a35087bdd2c2dc42251e14028c56d9bea3a00390d43cc6683de7560224010c3f","pinyin":"zhongduxuexiaobanjianshaozheng","initials":"zdxxbjsz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","D69.6",30]]},{"id":"templates-c6d407743a5be45a586c","key":"v1-c9ccc21dfe2a3058|templates-c6d407743a5be45a586c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"重度贫血","category":"临床急症","raw":{"name":"重度贫血","category":"临床急症","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】头晕、乏力、面色苍白、活动后心悸气促、胸痛；体位性低血压、心率增快提示血容量不足或缺氧失代偿；心衰者可现端坐呼吸、下肢水肿；溶血性者有黄疸、酱油色尿。。\n【待人工确认·本机素材无此段原文】","现病史":"危急阈值：血红蛋白(Hb)≤60g/L；活动性出血时可放宽至Hb<70-80g/L即需输血。临床意义：严重贫血致组织供氧不足、代偿性心输出量增加，可诱发心肌缺血与心力衰竭（原有心脏病者尤甚）；慢性贫血耐受性较好，而急性失血/溶血致Hb骤降者耐受差，需积极干预。\n常见表现：头晕、乏力、面色苍白、活动后心悸气促、胸痛；体位性低血压、心率增快提示血容量不足或缺氧失代偿；心衰者可现端坐呼吸、下肢水肿；溶血性者有黄疸、酱油色尿。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮肤黏膜苍白、心率增快、血压下降或体位性低血压；心衰时肺底湿啰音、颈静脉充盈、下肢水肿；溶血性者巩膜皮肤黄染、脾大。","辅助检查":"血常规+网织红细胞计数、外周血涂片；铁蛋白、叶酸、维生素B12；LDH、胆红素、结合珠蛋白、Coombs试验；肝肾功能；心电图评估心肌缺血。","初步诊断":"血常规示Hb≤60g/L即达危急值。评估血流动力学与缺氧症状（胸痛、气促、头晕、体位性低血压、心衰征象）。病因筛查：急性失血→急诊内镜/影像学定位出血灶；溶血→Coombs试验、LDH、胆红素、结合珠蛋白；骨髓造血障碍→骨髓穿刺/活检；营养缺乏→铁蛋白、叶酸、维生素B12。无症状且Hb<50g/L者个体化评估：年轻无基础病可观察，老年/心脏病者放宽输血指征。\n1. 重度贫血（ICD-10：D64.9）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n有症状或急性失血：输注ABO同型+交叉配血悬浮红细胞2-4U；急性失血可加压快速输注，慢性贫血缓慢输注（每次1U、>2h）；心衰患者每次输注1U，输注中监测心肺体征，必要时同时给予呋塞米利尿减轻容量负荷。\n\n【药物治疗·口服】\n按病因补充：缺铁性贫血予铁剂，巨幼细胞贫血予叶酸、维生素B12；慢性肾病/慢性病贫血在医生指导下评估EPO等促红素治疗（非急症首选）。\n\n【治疗】\n核心为病因治疗：急性失血→止血（急诊内镜、介入或手术）；自身免疫性溶血→糖皮质激素等免疫抑制；骨髓衰竭→促造血治疗或成分支持。输血期间监测输血反应（发热、过敏、溶血、循环超负荷TACO）。\n\n【处理要点】\n监测生命体征、血氧、尿量；心衰者控制输液速度并记录出入量；定期复查血常规评估Hb动态；输血前后严格核对血型及交叉配血结果；观察有无输血反应并及时处理。\n\n【护理】\n卧床休息、减少耗氧与活动；防跌倒坠床；心衰者控制输液速度、准确记录出入量；注意保暖；观察输血过程反应。\n\n【饮食】\n高蛋白、富含铁、叶酸与维生素B12饮食（瘦肉、动物肝脏、绿叶蔬菜）；溶血急性期清淡易消化。\n\n【注意事项】\n慢性贫血患者对较低Hb耐受性较好，不必一律按阈值输血；急性Hb骤降者即使数值略高也可明显不耐受，需放宽输血指征、个体化决策。\n\n【急诊/急救】\n输血反应（尤其急性溶血反应、TACO）一旦发生立即停止输注、换用生理盐水维持通路，溶血反应查血尿游离血红蛋白、复查血型与交叉配血，TACO予利尿、减慢输液；失血性休克者在配血完成前先以晶体液复苏并启用O型或同型红细胞紧急抢救。","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"D64.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2787,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4ff9b5a6af6a1cd2e7b6c74a6046f5e043a823ab0b82093eb5b4e1144da54885","pinyin":"zhongdupinxue","initials":"zdpx","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","D64.9",30]]},{"id":"templates-0712908fc822790b826f","key":"v1-c9ccc21dfe2a3058|templates-0712908fc822790b826f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"银杏中毒","category":"临床急症","raw":{"name":"银杏中毒","category":"临床急症","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】消化道症状（最先出现）：恶心、呕吐、腹痛、腹泻。、神经系统症状：头晕、头痛、烦躁不安，轻微刺激即可诱发抽搐，继而嗜睡、昏迷；少数出现四肢无力与迟缓型瘫痪。、严重中毒体征：发绀、瞳孔散大、对光反应迟钝或消失，可发生急性肺水肿、心力衰竭与猝死。。\n【待人工确认·本机素材无此段原文】","现病史":"定义：银杏（白果）的有害成分为白果酸，主要毒性作用是损害神经系统，表现为先兴奋后抑制及神经末梢功能障碍；直接接触可强烈刺激皮肤与黏膜。摄食中毒先出现消化道症状，继而出现神经系统症状，严重者可发生急性肺水肿与猝死。\n夜班目标：2小时内完成活性炭吸附与全胃肠灌洗，控制惊厥、保护脑与心肌，重症评估血液净化。\n常见表现：消化道症状（最先出现）：恶心、呕吐、腹痛、腹泻。、神经系统症状：头晕、头痛、烦躁不安，轻微刺激即可诱发抽搐，继而嗜睡、昏迷；少数出现四肢无力与迟缓型瘫痪。、严重中毒体征：发绀、瞳孔散大、对光反应迟钝或消失，可发生急性肺水肿、心力衰竭与猝死。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"神经：意识水平、瞳孔大小与对光反应、抽搐形式、肌力与病理反射。\n呼吸与循环：呼吸频率与节律、SpO2<90%即危重、肺部啰音（警惕肺水肿）、心率与心律、血压。\n其他：皮肤与黏膜有无刺激表现与皮疹，腹部压痛与肠鸣音。","辅助检查":"检查计划：患者有明确白果（银杏）食用史，出现恶心呕吐、腹痛腹泻等消化道症状，继而头晕头痛、烦躁不安、抽搐、嗜睡甚至昏迷，入院即刻完善血常规检查以排除感染及血液系统受累；完善肝功能、肾功能检查以评估毒物代谢与排泄能力，并为血液净化治疗提供依据；完善电解质检查以排除呕吐所致低钾、低钠等电解质紊乱，指导补液；完善血糖检查以排除低血糖所致抽搐与意识障碍；患者发绀、急性肺水肿时，完善血气分析检查以明确有无低氧血症及酸碱失衡，指导氧疗与呼吸支持；严重中毒可致心力衰竭与猝死，完善心电图检查以排除心律失常及心肌损害；完善血清银杏酸浓度测定以明确中毒程度，其＞50μg/L提示需强化血液净化；白果酸可损害心肌，完善心肌酶与肌钙蛋白检查以排除心肌损伤，72小时CK＞5000U/L或肌钙蛋白I＞1.0ng/mL提示心肌受累；完善肌酐检查以评估肾功能及血液净化指征（＞3mg/dL），完善乳酸检查以评估组织灌注（＞5mmol/L提示灌注不足）；患者有抽搐、昏迷等神经系统症状，急诊完善头颅影像（CT或MRI）与脑电图检查以明确中毒性脑病并排除颅内感染、出血等其他病因；必要时完善毒物筛查以排除其他植物或药物中毒，并需与癫痫、中枢神经系统感染、食物过敏相鉴别。\n\n（检查清单）\n必查：血常规、肝肾功能、电解质、血糖、血气分析、心电图。\n按需：血清银杏酸（>50μg/L提示需强化血液净化）、心肌酶与肌钙蛋白（72小时CK>5000U/L或肌钙蛋白I>1.0ng/mL提示心肌损伤）、肌酐（>3mg/dL）与乳酸（>5mmol/L）、头颅影像与脑电图、毒物筛查。","初步诊断":"1. 食用史（关键）：白果数量、生熟、是否连胚芽食用、进食时间，是否儿童共食；摄入未熟银杏>20颗为全胃肠灌洗指征。\n2. 潜伏期与剂量：多在小儿空腹大量食用后起病，量与生熟程度决定病情轻重。\n3. 实验室与影像方向：血银杏酸浓度、心肌酶与肌钙蛋白、肝肾功能、头颅影像与脑电图。\n4. 鉴别：其他植物或药物中毒、中枢神经系统感染、低血糖、癫痫、食物过敏。\n1. 银杏中毒（ICD-10：T62.2）","鉴别诊断":"1. 4. 鉴别：其他植物或药物中毒、中枢神经系统感染、低血糖、癫痫、食物过敏","处理方案":"【药物治疗·输液】\n抗惊厥序贯：咪达唑仑0.2mg/kg静推，接苯巴比妥15mg/kg静推负荷，维持1~3mg/kg/h。\n糖皮质激素：甲泼尼龙80mg加入0.9%氯化钠100mL静滴每8小时1次×3天。\n血液净化：DFPP置换2倍血浆体积、白蛋白浓度5%、间隔12小时×3次；CVVHDF指征为肌酐>3mg/dL或乳酸>5mmol/L，超滤率35mL/kg/h。\n\n【药物治疗·口服】\n清醒且就诊早者：活性炭50g＋甘露醇100mL口服，每2小时1次×3次（活性炭吸附优于高锰酸钾）。\n昏迷者经鼻胃管注入，不可经口给药。\n导泻禁用硫酸镁（加重电解质紊乱），改用聚乙二醇电解质溶液4L口服全胃肠灌洗，持续至排出液无银杏残渣。\n\n【治疗】\n首要：评估气道、呼吸与循环，抽搐者优先止抽并吸氧，建立静脉通路。\n其次：2小时内完成毒物清除——活性炭吸附加甘露醇导泻，必要时全胃肠灌洗；洗胃时取头低足高位15°减少误吸，活性炭需与食物或药物间隔2小时。\n随后：脑保护、激素抗炎、器官支持；混合型中毒尽早血液净化，其中中毒6小时内启动血液灌流可提升存活率。\n\n【处理要点】\n监测：24小时血银杏酸>50μg/L需强化血液净化；72小时CK>5000U/L或肌钙蛋白I>1.0ng/mL提示心肌损伤，应加强监护。\n留观：症状缓解后仍需留观至少24小时，警惕迟发抽搐、肺水肿与心律失常。\n宣教：白果必须充分煮熟并去胚芽，成人不宜过量，学龄前儿童尽量不食用。\n\n【护理】\n气道：侧卧位、头偏一侧，抽搐时保护头颈与肢体，勿强行按压或塞入硬物。\n监测：意识、瞳孔、呼吸、SpO2、心率与心律，记录抽搐持续时间和次数、尿量。\n安全：加床栏防坠床；洗胃与灌洗期间注意保暖与误吸防护。\n\n【注意事项】\n以本院规范为准：活性炭与甘露醇用法、全胃肠灌洗指征、DFPP与CVVHDF参数请按本院流程执行。\n禁用与避免：导泻禁用硫酸镁；昏迷者不可经口给药；抽搐时不可强行撬牙或按压肢体。\n提醒：集体食用者应同时排查，儿童需留观至症状完全消失。\n\n【急诊/急救】\n立即升级：持续或反复抽搐、呼吸<8次/分、SpO2<90%、意识进行性加深、急性肺水肿（粉红色泡沫痰、双肺湿啰音）、误吸、血压下降 → 立即呼叫上级、气管插管并转ICU。\n血液净化指征：肌酐>3mg/dL或乳酸>5mmol/L，或血清银杏酸明显升高。","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「银杏中毒」原文）"},"icd10_diagnosis":"T62.2","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2788,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"70b3dcf5c0e4cdd534593757c097bb534cd9d99a869aac757e90e5448c2d008e","pinyin":"yinxingzhongdu","initials":"yxzd","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T62.2",30]]},{"id":"templates-aeec44273f0901a7c071","key":"v1-c9ccc21dfe2a3058|templates-aeec44273f0901a7c071","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"靶向与免疫治疗常见不良反应","category":"临床急症","raw":{"name":"靶向与免疫治疗常见不良反应","category":"临床急症","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】靶向治疗：痤疮样皮疹（EGFR抑制剂）、腹泻、甲沟炎、口腔黏膜炎、高血压与蛋白尿（抗血管生成）、手足综合征、乏力、间质性肺炎：干咳、活动后气促、血氧下降（EGFR-TKI、ALK抑制剂、免疫治疗均可致，属严重不良反应）、免疫相关皮肤毒性：皮疹、瘙痒、白癜风样脱色、大疱性皮炎、免疫相关结肠炎：腹泻（可为血性）、腹痛、黏液便，重者腹泻>7次/日、免疫相关肝炎：乏力、食欲减退、转氨酶升高、黄疸、免疫相关内分泌毒性：甲状腺功能减退（乏力、畏寒、水肿）、垂体炎（头痛、乏力、低血压）、1型糖尿病（多饮多尿）、免疫相关肺炎：干咳、气促、发热，影像见磨玻璃影、免疫相关心肌炎（少见但致命）：胸闷、心悸、气促、心律失常。\n【待人工确认·本机素材无此段原文】","现病史":"靶向治疗（抗EGFR、抗HER2、抗血管生成、小分子TKI等）与免疫检查点抑制剂（PD-1/PD-L1/CTLA-4抑制剂）不良反应机制与化疗不同：靶向药多有皮疹、腹泻、高血压、蛋白尿、手足综合征、间质性肺炎；免疫治疗则可致免疫相关不良反应（irAE），累及皮肤、结肠、肝、肺、甲状腺、垂体等，重者可致命。\n常见表现：靶向治疗：痤疮样皮疹（EGFR抑制剂）、腹泻、甲沟炎、口腔黏膜炎、高血压与蛋白尿（抗血管生成）、手足综合征、乏力、间质性肺炎：干咳、活动后气促、血氧下降（EGFR-TKI、ALK抑制剂、免疫治疗均可致，属严重不良反应）、免疫相关皮肤毒性：皮疹、瘙痒、白癜风样脱色、大疱性皮炎、免疫相关结肠炎：腹泻（可为血性）、腹痛、黏液便，重者腹泻>7次/日、免疫相关肝炎：乏力、食欲减退、转氨酶升高、黄疸、免疫相关内分泌毒性：甲状腺功能减退（乏力、畏寒、水肿）、垂体炎（头痛、乏力、低血压）、1型糖尿病（多饮多尿）、免疫相关肺炎：干咳、气促、发热，影像见磨玻璃影、免疫相关心肌炎（少见但致命）：胸闷、心悸、气促、心律失常。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温（感染/免疫性发热）、血压（抗血管生成药致高血压）、呼吸与血氧（肺炎）\n皮肤黏膜：皮疹范围与分级（体表面积）、瘙痒、甲沟炎、黏膜糜烂（口腔、眼、生殖器）、色素脱色\n呼吸系统：呼吸频率、双肺呼吸音、湿啰音、喘鸣（肺炎/间质性肺炎）\n消化系统：腹部压痛、肠鸣音（结肠炎可亢进）、有无腹膜炎体征、肛周情况\n内分泌：甲状腺肿大与质地、体重变化、皮肤干燥与水肿（甲减）、有无脱水与多尿（糖尿病）\n心脏：心率、心律、心音、颈静脉（心肌炎、心衰）\n神经系统：意识、肌力、感觉（免疫相关神经毒性、垂体炎致头痛）\n眼部：结膜炎、眼睑水肿、视力变化（免疫相关眼毒性）","辅助检查":"1. 肝功能（ALT/AST/胆红素）+肾功能：每2～4周复查（免疫相关肝炎、靶向药肝毒性）\n2. 甲状腺功能（TSH、FT3、FT4）+皮质醇+ACTH：免疫治疗前基线及每4～6周复查（内分泌毒性）\n3. 血糖+糖化血红蛋白+尿酮：免疫治疗相关1型糖尿病筛查（出现多饮多尿时急查）\n4. 血常规+CRP+PCT：感染与免疫性炎症鉴别，骨髓抑制评估\n5. 肌钙蛋白+BNP+心电图+心脏超声：胸闷心悸时紧急评估（心肌炎）\n6. 胸部高分辨CT：免疫治疗前基线，出现咳嗽气促时紧急复查（肺炎）\n7. 尿蛋白定量/尿常规：抗血管生成药物相关肾毒性监测（每周期）\n8. 病原学检查（痰培养、G试验、GM试验、结核筛查）：免疫治疗前与疑感染时，排除感染后诊断irAE","初步诊断":"1. 用药前基线：血常规、肝肾功能、甲状腺功能（TSH/FT3/FT4）、血糖、心电图、胸部CT（免疫治疗前必查）\n2. 治疗中监测：每2～4周复查肝肾功能、甲状腺功能、血糖；每6～12周复查胸部CT\n3. irAE分级（CTCAE）：1级（无症状/轻微）、2级（中度症状，影响日常活动）、3级（严重，需住院/激素治疗）、4级（危及生命）\n4. 免疫相关结肠炎：腹泻次数、便血、腹膜炎体征；必要时肠镜+活检\n5. 免疫相关肺炎：胸部高分辨CT（磨玻璃影、机化性肺炎）、血氧、必要时支气管镜肺泡灌洗\n6. 心肌炎筛查：肌钙蛋白、BNP、心电图、心脏超声（出现胸闷心悸时紧急检查）\n7. 靶向药相关：EGFR-TKI皮疹分级、血压监测（抗血管生成药每日测血压）、尿蛋白定量\n1. 靶向与免疫治疗常见不良反应（ICD-10：Y43.3）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 按不良反应类型与分级选择，切勿全部同时使用！\n\n方案1（免疫相关不良反应，2级及以上，糖皮质激素为首选）：\n 用法：甲泼尼龙 1～2mg/kg/日 静滴（或等效泼尼松口服）；3～4级：甲泼尼龙 1g/日 静滴×3～5天（冲击治疗）后逐渐减量（减量过程需≥4～6周）\n\n方案2（免疫相关结肠炎，激素无效时）：\n 用法：英夫利西单抗 5mg/kg 静滴（单次，2周后可重复）\n\n方案3（过敏反应，单抗类输注反应）：\n 用法：立即停输；肾上腺素 0.3～0.5mg 肌注；地塞米松 10mg 静推；苯海拉明 20mg 肌注；补液吸氧\n\n方案4（靶向药相关皮肤毒性/支持）：\n 用法：0.9%氯化钠 静滴（补液）；葡萄糖酸钙+维生素C 静滴（辅助）；抗生素（继发感染时）\n\n📌 免疫治疗相关不良反应处理核心是『早识别、早停免疫药物、及时足量激素』；激素减量需缓慢（≥4周），过快减量可致复发。\n\n【药物治疗·口服】\n⚠️ 按不良反应类型选择，同类只选一种：\n\n药物1（免疫相关不良反应口服激素，轻症或减量期）：\n 用法：泼尼松 0.5～1mg/kg/日（晨起顿服，逐渐减量，不可骤停）\n\n药物2（皮疹/皮肤毒性）：\n 用法：多西环素 0.1g bid（EGFR-TKI痤疮样皮疹）；氢化可的松乳膏 外用 bid；米诺环素 0.1g bid（二选一）\n\n药物3（免疫相关甲状腺功能减退）：\n 用法：左甲状腺素钠 25～50μg qd 起（晨起空腹，按TSH调整）\n\n药物4（腹泻，免疫相关结肠炎1级）：\n 用法：洛哌丁胺 2mg tid（症状控制后减量）；蒙脱石散 3g tid；益生菌\n\n药物5（靶向药相关腹泻/手足综合征）：\n 用法：洛哌丁胺（腹泻）；维生素B6 100mg tid + 尿素软膏外用（手足综合征）\n\n📌 免疫相关不良反应≥2级应暂停免疫治疗并口服/静脉激素；1级可在密切监测下继续治疗。\n\n【治疗】\n免疫相关不良反应（irAE）总原则：1级密切监测可继续治疗；2级暂停免疫药物并口服激素（泼尼松0.5～1mg/kg/日）；3级停用免疫药物并静脉激素（甲泼尼龙1～2mg/kg/日）；4级永久停用并大剂量激素冲击±其他免疫抑制\n免疫相关结肠炎：激素+必要时英夫利西单抗；警惕肠穿孔（剧烈腹痛、腹膜炎体征需急诊）\n免疫相关肺炎：停免疫药+激素；3～4级需住院、吸氧、必要时机械通气；激素减量需≥6周\n免疫相关肝炎：停免疫药+激素；严重者加用吗替麦考酚酯（不用英夫利西单抗，可能致肝毒性）\n免疫相关内分泌毒性：甲状腺功能减退予左甲状腺素替代（多数需长期）；垂体炎予激素替代；1型糖尿病予胰岛素治疗\n免疫相关心肌炎：立即停免疫药、大剂量激素冲击、心内科协作（必要时加用抗胸腺细胞球蛋白/英夫利西单抗），病死率高\n靶向药不良反应处理：皮疹（保湿+抗生素软膏+多西环素，重者减量或短期激素）、腹泻（洛哌丁胺，重者停用）、高血压（ACEI/ARB降压）、蛋白尿（减量或停用）、间质性肺炎（立即停药+激素）\n多学科协作：皮疹/皮肤科、结肠炎/消化科、肝炎/肝病科、肺炎/呼吸科、内分泌毒性/内分泌科、心肌炎/心内科\n\n【处理要点】\n基线评估与记录：免疫治疗前完成血常规、肝肾功能、甲功、血糖、心电图、胸部CT，作为对比基线\n定期监测：每2～4周复查肝肾功能、甲功、血糖；每6～12周胸部CT；出现症状随时检查\n症状日记：指导患者记录皮疹、腹泻次数、大便性状、咳嗽气促、乏力与体重变化，复诊时提供\n激素使用护理：遵医嘱足量起始、缓慢减量（≥4～6周），观察激素不良反应（高血糖、高血压、感染、骨质疏松、失眠）\n感染筛查：激素治疗前筛查结核、乙肝、丙肝、HIV（激素可致潜伏感染再激活）\n患者宣教：强调任何新发症状（腹泻、皮疹、气促、乏力、多饮多尿）都必须及时报告，不可自行停药或用止泻药掩盖\n多学科随访：出现3级以上irAE时联合相关专科会诊处理\n\n【护理】\n症状监测与记录：每日评估皮疹部位与面积、腹泻次数与性状、咳嗽气促、乏力、体重，异常立即报告\n激素治疗护理：遵医嘱按时给药并观察不良反应（血糖升高、血压升高、失眠、情绪改变、感染征象）\n皮肤护理：温水清洁、避免搔抓与刺激性护肤品，按医嘱外用药物，观察有无继发感染\n腹泻护理：记录次数与性状，遵医嘱用药（2级以上禁用洛哌丁胺自行止泻），注意肛周皮肤保护与补液\n呼吸道护理：出现干咳气促者监测血氧、限制活动、必要时吸氧，配合胸部CT检查\n宣教与随访：告知免疫不良反应可能迟发，出院后出现任何新症状须立即联系医疗团队，不可自行停药\n\n【饮食】\n高蛋白、高热量、易消化饮食，少量多餐；骨髓抑制期食物需充分加热\n腹泻者：低渣低脂饮食，避免生冷、油腻、乳制品与高纤维食物，补充水分与电解质\n皮疹/黏膜炎者：避免辛辣、过烫、酸性食物，进食软烂食物并加强口腔护理\n激素治疗期间：低盐低糖饮食，控制碳水摄入（防血糖升高），注意补钾补钙\n免疫治疗期间避免服用免疫增强类保健品（如大剂量维生素、灵芝孢子粉等），可能干扰疗效（须先咨询医师）\n\n【注意事项】\n免疫治疗不良反应可在治疗期间或停药后数周至数月出现（迟发性），随访期仍需警惕\n免疫相关心肌炎、肺炎、中毒性表皮坏死松解症虽少见但可致命，出现相应症状须紧急处理\n激素减量过快是irAE复发的主要原因，减量过程一般不少于4～6周\n免疫治疗相关结肠炎禁用洛哌丁胺长期止泻（可致中毒性巨结肠），2级以上须激素治疗\nEGFR-TKI皮疹与疗效有一定相关性，但严重皮疹需积极处理并可能减量\n抗血管生成药物（贝伐珠单抗等）可致出血、血栓与胃肠穿孔，围手术期需停药（一般术前4～6周）\n\n【急诊/急救】\n呼吸困难、血氧下降伴双肺磨玻璃影（免疫相关肺炎3～4级）→ 立即停药、大剂量激素、吸氧，必要时机械通气\n胸闷心悸、肌钙蛋白升高、心律失常（免疫相关心肌炎）→ 立即停药、激素冲击、心内科急会诊\n剧烈腹痛、腹膜刺激征、血性腹泻（免疫相关结肠炎致穿孔）→ 急诊评估手术\n血压急剧升高伴头痛视力模糊（抗血管生成药致高血压危象）→ 立即降压处理\n严重皮疹伴发热、黏膜糜烂（Stevens-Johnson综合征/中毒性表皮坏死松解症）→ 立即停药、皮肤科急会诊、支持治疗","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"Y43.3","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2789,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e5e8942f1f65b78415689027a8ca75b6acd0f815d60f26752dee2cda9c84ffd0","pinyin":"baxiangyumianyizhiliaochangjianbuliangfanying","initials":"bxymyzlcjblfy","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","Y43.3",30]]},{"id":"templates-1a479ac2e7b6925f6c32","key":"v1-c9ccc21dfe2a3058|templates-1a479ac2e7b6925f6c32","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"颅内压增高/脑疝","category":"临床急症","raw":{"name":"颅内压增高/脑疝","category":"临床急症","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】头痛进行性加重、喷射性呕吐、视乳头水肿、意识障碍加深；脑疝征象：瞳孔不等大或一侧散大固定、去皮层/去大脑强直、Cushing反应（血压高脉缓呼吸慢）、呼吸节律异常。。\n【待人工确认·本机素材无此段原文】","现病史":"ICP>20mmHg持续>5min或出现脑疝征象即属危急，可迅速发展为天幕疝或枕骨大孔疝致脑干衰竭死亡；正常ICP 5-15mmHg，CPP=MAP-ICP正常60-80mmHg，<50mmHg脑缺血不可逆。\n常见表现：头痛进行性加重、喷射性呕吐、视乳头水肿、意识障碍加深；脑疝征象：瞳孔不等大或一侧散大固定、去皮层/去大脑强直、Cushing反应（血压高脉缓呼吸慢）、呼吸节律异常。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"GCS、瞳孔大小与对光反射、眼底视乳头水肿、肌张力与去脑强直、病理征、呼吸节律及生命体征。","辅助检查":"CT/MRI；血气（PaCO2）；电解质、渗透压、血钠；凝血与感染指标按病因；有创ICP监测。","初步诊断":"结合临床表现与CT/MRI（脑水肿、占位、中线移位、脑室受压）诊断；脑室内导管测压为ICP监测金标准，同时监测CPP与脑组织氧分压（PbtO2）。\n1. 颅内压增高/脑疝（ICD-10：G93.5）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n甘露醇0.5-1g/kg于15-30min输注、q4-6h按需，血浆渗透压<320mOsm/L，超则停药/减量；或3%高渗盐水250ml IV，血钠145-155mmol/L，>160停药。短时过度通气使PaCO2 30-35mmHg仅临时桥接（<1h），<25mmHg致脑缺血。\n\n【药物治疗·口服】\n急性期以静脉渗透与原发病处理为主；恢复期依病因（感染、肿瘤、癫痫等）口服维持。\n\n【治疗】\n一般措施：床头抬高30°、头颈中立位；镇静镇痛（丙泊酚/咪达唑仑+芬太尼）；防Valsalva（避免吸痰刺激、通便）；体温36-37°C；维持PaCO2 35-40mmHg防血管扩张。手术：恶性脑水肿/大面积梗死/脑出血ICP难控时去骨瓣减压，脑出血清血肿，脑积水行脑室外引流。目标ICP<20-22mmHg、CPP>60-70mmHg、PbtO2>20mmHg。\n\n【处理要点】\n持续监测ICP/CPP及GCS、瞳孔、生命体征；避免低血压低氧保CPP；防治应激性溃疡、感染与DVT；同步处理原发病。\n\n【护理】\n床头抬高30°、头颈中立；定时评估GCS瞳孔；躁动者镇静约束避免Valsalva；吸痰轻柔限时；甘露醇利尿者记录出入量；防压疮坠床。\n\n【饮食】\n急性期禁食或管饲，控液体入量、避免低渗输液；稳定后按吞咽过渡。\n\n【注意事项】\n监测渗透压与血钠，防肾损伤、高钠及甘露醇反跳；过度通气仅限临时；瞳孔不等大或GCS骤降提示脑疝，立即处理并呼叫神经外科。\n\n【急诊/急救】\n疑脑疝即刻快速静滴甘露醇/高渗盐水，必要时插管+过度通气过渡；急查CT明确病因，通知神经外科与ICU。","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"G93.5","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2790,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"920445a5e9a6da800796edb8c9609f0591b93f4440a69f0e8506f51901009539","pinyin":"luneiyazenggao/naoshan","initials":"lnyzg/ns","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","G93.5",30]]},{"id":"templates-cb38095ad68c029388dc","key":"v1-c9ccc21dfe2a3058|templates-cb38095ad68c029388dc","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"风湿病相关快速进展性间质性肺病","category":"临床急症","raw":{"name":"风湿病相关快速进展性间质性肺病","category":"临床急症","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】进行性呼吸困难、干咳、发热、乏力，重者静息低氧、发绀；皮肌炎伴皮疹肌无力，硬皮病伴皮肤硬化；咯血提示肺泡出血。。\n【待人工确认·本机素材无此段原文】","现病史":"识别要点：风湿病患者呼吸困难加重伴低氧（PaO₂<60mmHg或SpO₂<90%），HRCT示弥漫性间质性肺炎、机化性肺炎或弥漫性肺泡损伤。意义：CTD-ILD为风湿病主要死因之一，抗MDA5阳性皮肌炎RP-ILD病死率40%-60%，需紧急三联免疫抑制。\n常见表现：进行性呼吸困难、干咳、发热、乏力，重者静息低氧、发绀；皮肌炎伴皮疹肌无力，硬皮病伴皮肤硬化；咯血提示肺泡出血。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"呼吸急促、三凹征、双肺底爆裂音、发绀；皮肌炎见Gottron丘疹与近端肌无力；硬皮病皮肤硬化、雷诺现象。","辅助检查":"检查计划：患者为风湿病基础病，本次进行性呼吸困难、干咳、发热、乏力，重者静息低氧、发绀，疑抗MDA5阳性皮肌炎相关快速进展性间质性肺病，该病病死率40%-60%，需紧急启动免疫抑制，故检查从速、入院即刻完成。患者静息状态下即有气促、发绀，急查动脉血气分析明确低氧血症程度并判断有无Ⅱ型呼吸衰竭，为氧疗与呼吸支持决策提供依据；查HRCT（高分辨率胸部CT）判定弥漫性间质性肺炎、机化性肺炎或弥漫性肺泡损伤的病变模式与受累范围，明确影像学分型；患者咳嗽气促呈进行性加重，完善肺功能检查（含弥散功能）了解限制性通气障碍与弥散受损程度，评估病情严重度并作为后续疗效对比基线；患者皮肌炎伴皮疹、肌无力，查肌炎抗体谱（尤其抗MDA5、抗ARS等）明确肌炎亚型及RP-ILD高危属性，指导免疫抑制方案；查ANA/ENA谱确立基础风湿病诊断，鉴别系统性红斑狼疮、硬皮病等其他结缔组织病所致肺受累；患者存在肌无力，查肌酸激酶（CK）了解肌损伤程度，评估肌炎活动性以指导激素与免疫抑制剂用量；患者发热，查血常规、CRP、血沉等炎症指标评估炎症活动度并排除感染性因素；发热与弥漫性肺病变需与感染性肺炎鉴别，完善痰培养及支气管镜肺泡灌洗液病原学检查（含细菌、真菌、肺孢子菌及病毒核酸）排除机会性感染，用药前必须除外未控制的感染；患者呼吸困难明显，完善心超（心脏彩超）估测肺动脉压并了解右心结构与功能，评估继发肺动脉高压及右心负荷，必要时行右心导管检查进一步明确血流动力学状态。必要时复查上述指标动态观察病情演变。\n\n（检查清单）\n动脉血气、HRCT、肺功能、肌炎抗体谱（抗MDA5等）、ANA/ENA、CK、炎症指标；痰/灌洗病原学；心超估肺动脉压。","初步诊断":"血气分析明确低氧；HRCT判定病变模式；查肌炎抗体谱（尤其抗MDA5）与ANA/ENA谱确立基础病；肺功能、心超评估严重度；必要时支气管镜灌洗排除感染；与感染性肺炎、心衰鉴别。\n1. 风湿病相关快速进展性间质性肺病（ICD-10：J99.1）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n甲泼尼龙500-1000mg/d×3天冲击；环磷酰胺0.5-1g/m²每2-4周；难治/特定类型用利妥昔单抗或托珠单抗；输注监护生命体征与过敏。\n\n【药物治疗·口服】\n泼尼松（0.5-1mg/kg/d递减）；他克莫司0.05-0.15mg/kg/d；霉酚酸酯1.5-3g/d（SSc-ILD可联尼达尼布）；尼达尼布150mg bid或吡非尼酮；复方新诺明防PJP。\n\n【治疗】\n甲泼尼龙500-1000mg/d冲击3天，继以泼尼松0.5-1mg/kg/d递减；抗MDA5阳性RP-ILD立即联合他克莫司0.05-0.15mg/kg/d（谷浓度5-15ng/mL）与环磷酰胺0.5-1g/m²（每2-4周×6）；难治/非MDA5加利妥昔单抗或托珠单抗；SSc-ILD早期联尼达尼布150mg bid（FVC下降≥5%启用）或吡非尼酮。剂量按CTD-ILD共识/指南执行；冲击期监护血压血糖电解质与感染；他克莫司监测浓度与肾功能。\n\n【处理要点】\n呼吸科或监护室协作：动态血气与SpO₂监测、呼吸支持阶梯递进（HFNC/无创至气管插管）；警惕感染、气胸、肺栓塞；缓解后复查肺功能与HRCT。\n\n【护理】\n半卧位，监测SpO₂与血气趋势；氧疗/无创通气护理防滑脱；防感染、翻身拍背；记录出入量。\n\n【饮食】\n高蛋白易消化；呼吸窘迫者少量多餐；限钠水。\n\n【注意事项】\n抗MDA5阳性RP-ILD进展极快，激素单药不足应尽早三联；强化免疫抑制前排除感染；尼达尼布注意肝功与腹泻。\n\n【急诊/急救】\n即刻纠正低氧：鼻导管→HFNC/无创通气，必要时气管插管机械通气；先留病原学再强化免疫抑制；抗MDA5阳性RP-ILD立即启动激素+他克莫司+环磷酰胺三联方案。","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"J99.1","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2791,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"600df24fc7ff7af6d364ea8fbaed9ef4a37a0edc536c993ff03f9c0bcd62f558","pinyin":"fengshibingxiangguankuaisujinzhanxingjianzhixingfeibing","initials":"fsbxgksjzxjzxfb","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","J99.1",30]]},{"id":"templates-ecb2a05aad0221b9fd7e","key":"v1-c9ccc21dfe2a3058|templates-ecb2a05aad0221b9fd7e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"食管胃底静脉曲张破裂出血","category":"临床急症","raw":{"name":"食管胃底静脉曲张破裂出血","category":"临床急症","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】突发大量呕血(暗红或鲜血)、黑便，迅速出现心悸、头晕、大汗、血压下降等休克表现，常伴肝硬化体征。。\n【待人工确认·本机素材无此段原文】","现病史":"危急阈值：内镜见食管/胃底曲张静脉活动性出血(喷射或渗血)，或表面白色乳头征、血凝块附着；6周死亡率15%-25%，Child-Pugh C级可达50%。临床意义：门脉高压最致命并发症，约30%发生于无出血史者，疑似即按高危处理。\n常见表现：突发大量呕血(暗红或鲜血)、黑便，迅速出现心悸、头晕、大汗、血压下降等休克表现，常伴肝硬化体征。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"慢性肝病体征：黄疸、肝掌、蜘蛛痣、脾大、腹水、腹壁静脉曲张；低血压、心动过速等休克征象。","辅助检查":"检查计划：患者肝硬化、门脉高压基础，本次突发大量呕血、黑便，迅速出现心悸、头晕、大汗、血压下降等休克表现，高度疑诊食管胃底静脉曲张破裂出血，6周死亡率15%-25%、Child-Pugh C级可达50%，故检查须急诊完成。急查血常规（血红蛋白、血小板）评估失血量与贫血程度，并了解脾功能亢进所致血小板减少，判断输血指征；查肝功能了解肝脏合成与储备功能，为Child-Pugh分级、预后评估及用药选择提供依据；查凝血功能（PT、INR、APTT）明确凝血障碍程度，评估再出血与肝性脑病风险，指导凝血酶原复合物、新鲜冰冻血浆及维生素K补充；患者存在休克表现，查肾功能评估有效循环血量不足所致肾前性损伤，警惕肝肾综合征；查电解质了解呕吐、禁食及利尿治疗所致紊乱，尤其低钾低钠对肝性脑变的诱发作用；急查血型并交叉配血，为紧急输血、内镜下治疗及必要时三腔二囊管压迫止血做好准备；查肝炎病毒标志物（乙肝、丙肝等）明确肝硬化病因，指导抗病毒及长期病因治疗；补充查血氨排除肝性脑病，查腹部超声及门静脉彩色多普勒了解门静脉主干宽度、血流方向及有无血栓，评估门脉高压程度；病情稳定后限期完成胃镜检查确诊活动性出血并区分食管或胃底曲张静脉，必要时行内镜下套扎或组织胶注射治疗，同时鉴别消化性溃疡、贲门黏膜撕裂等非曲张性出血；必要时完善上腹部增强CT及门静脉成像评估侧支循环与门体分流情况，为TIPS等介入治疗提供依据。\n\n（检查清单）\n血常规(Hb、血小板)、肝功能、凝血(PT/INR)、肾功能、电解质、血型交叉配血；肝炎病毒标志物。","初步诊断":"肝硬化/门脉高压者上消化道出血即高度疑诊，不等内镜确认即启用血管活性药；急诊内镜确诊活动性出血并区分食管/胃底曲张；结合Child-Pugh分级评估预后。\n1. 食管胃底静脉曲张破裂出血（ICD-10：I85.0）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n血管活性药(3-5天)：特利加压素2mg静注后继2mg q4-6h，或生长抑素250μg静注后250μg/h泵入，或奥曲肽50μg静注后50μg/h泵入；预防性抗生素头孢曲松1g静注qd(5-7天)。限制性输血，Hb目标70-80g/L，避免容量过负荷升高门脉压。内镜治疗后予PPI静注(埃索美拉唑80mg→8mg/h泵入)降低套扎溃疡出血。\n\n【药物治疗·口服】\n替代抗感染可口服诺氟沙星400mg bid；防再出血用卡维地洛12.5-25mg qd或普萘洛尔(目标心率55-60次/分)；口服PPI。\n\n【治疗】\n收入ICU/监护病房、限制性输血复苏；疑似即血管活性药+抗生素；内镜治疗：食管曲张行套扎术EVL(用药后12h内)，胃底曲张注射组织粘合剂/氰基丙烯酸酯；顽固性出血：三腔二囊管填塞≤24h临时控制，或72h内TIPS，TIPS失败/禁忌时外科分流断流；防再出血用NSBB+EVL序贯。\n\n【处理要点】\n监测生命体征、Hb、出入量并记录出血量；警惕肝性脑病(行为改变、扑翼样震颤、血氨升高)；三腔二囊管护理：维持压力、定时放气，床旁备剪刀防窒息。\n\n【护理】\n绝对卧床、头偏一侧防误吸；禁食、胃肠减压观察；每1-2h测生命体征与神志；记录出血量与尿量；三腔二囊管护理，防压疮、坠积性肺炎。\n\n【饮食】\n出血期禁食；止血后流质→软食并限钠；肝性脑病倾向者限制蛋白；禁酒。\n\n【注意事项】\n止血后需NSBB+EVL序贯防再出血；避免过度输血致门脉压升高再出血；PPI可降低EVL术后溃疡出血风险。\n\n【急诊/急救】\n大呕血伴休克：立即复苏并静注特利加压素或生长抑素，急诊内镜套扎/粘合剂注射；内镜失败或高危(Child-Pugh C)考虑72h内TIPS。","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"I85.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2792,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"10b1653de752b5b476e1f28dc886dd3df624739992778aa9c6b29af6172974cf","pinyin":"shiguanweidijingmaiquzhangpoliechuxie","initials":"sgwdjmqzplcx","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","I85.0",30]]},{"id":"templates-3e9cd7548385389582ec","key":"v1-c9ccc21dfe2a3058|templates-3e9cd7548385389582ec","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"高钙危象","category":"临床急症","raw":{"name":"高钙危象","category":"临床急症","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】多饮多尿、恶心呕吐、便秘、食欲减退、肌无力、嗜睡、意识模糊、昏迷、心悸。。\n【待人工确认·本机素材无此段原文】","现病史":"危急阈值：校正后血钙≥3.5mmol/L（14mg/dL）。校正钙＝测定钙＋0.02×(40-白蛋白g/L)。临床意义：可致急性肾损伤（肾血管收缩、尿浓缩功能障碍、肾钙质沉积）、QT间期缩短与心律失常、意识改变至昏迷；最常见病因为恶性肿瘤（约70%）与原发性甲旁亢（约20%）。\n常见表现：多饮多尿、恶心呕吐、便秘、食欲减退、肌无力、嗜睡、意识模糊、昏迷、心悸。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"神志状态、脱水体征、心律心率、肌力与腱反射。","辅助检查":"检查计划：患者出现多饮多尿、恶心呕吐、便秘、食欲减退、肌无力、嗜睡、意识模糊甚至昏迷、心悸，临床考虑高钙危象（校正后血钙≥3.5mmol/L即为危象），可致急性肾损伤、QT间期缩短与心律失常、意识障碍，故检查须急诊完成。急查血钙并同步查白蛋白，按校正钙＝测定钙＋0.02×(40－白蛋白g/L)计算校正值，明确血钙真实水平并判断危象严重度；查血PTH明确病因，PTH升高提示原发性甲状旁腺功能亢进，PTH受抑制则多提示恶性肿瘤所致高钙血症；查血磷了解磷代谢状态，甲旁亢者血磷降低、恶性肿瘤相关者血磷可正常或升高，辅助病因鉴别；查血镁评估伴随的镁代谢紊乱，因低镁可加重症状并影响降钙治疗反应，需一并纠正；患者多饮多尿、呕吐，查肾功能评估脱水与肾血管收缩所致急性肾损伤及肾钙质沉积，指导扩容与利尿治疗；患者心悸，急查心电图了解有无QT间期缩短、心律失常及洋地黄敏感性增高，评估心脏受累情况；补充查25-(OH)D了解维生素D代谢状态，查血清蛋白电泳及免疫固定电泳、肿瘤标志物（如PTHrP）筛查多发性骨髓瘤等恶性肿瘤，明确高钙血症病因；必要时查血气分析与尿电解质评估容量状态及肾小管浓缩功能，动态复查血钙（每4-6小时）评估降钙疗效，与噻嗪类利尿剂、维生素D中毒等药物性高钙鉴别。\n\n（检查清单）\n血钙（校正值）、白蛋白、PTH、血磷、血镁、肾功能、心电图。","初步诊断":"按校正公式计算血钙；查血PTH（甲旁亢升高）、血磷、25-(OH)D、血清蛋白电泳及肿瘤相关检查以明确病因。\n1. 高钙危象（ICD-10：E83.5（钙代谢紊乱，高钙血症））","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n积极补液最关键：0.9%NaCl 200-500ml/h，首24h总量3-4L，根据心功能与容量状态调整，严密监测出入量与心肺体征防容量过负荷。\n\n【药物治疗·口服】\n泼尼松40-60mg/d口服（适用于血液系统恶性肿瘤、维生素D中毒、结节病相关）；甲旁亢相关难治病例可予西那卡塞（cinacalcet）。\n\n【治疗】\n①补液扩容促尿钙排泄。②降钙素4-8U/kg IM或SC q6-12h，4-6h快速起效，但24-48h后出现耐受。③双膦酸盐（一线持久降钙药）：唑来膦酸4mg IV（15-30min输注），2-4天达峰、维持2-4周；或帕米膦酸二钠60-90mg IV（2-4h输注）。④糖皮质激素（血液系统肿瘤、VitD中毒、结节病相关）。⑤严重/难治/肾衰竭：低钙透析液血液透析。⑥病因治疗：甲旁亢评估甲状旁腺切除术，恶性肿瘤行抗肿瘤治疗。\n\n【处理要点】\n心电监护QT间期与心律；每6-12h监测血钙；监测肾功能与出入量；心衰或老年人注意控制补液速度防肺水肿。\n\n【护理】\n监测出入量与心肺体征、防跌倒、双膦酸盐输注防外渗、记录神志变化。\n\n【饮食】\n鼓励饮水促进钙排泄；低钙饮食，视病因停用维生素D与噻嗪类利尿剂。\n\n【注意事项】\n双膦酸盐起效慢，急性期依靠补液＋降钙素控制，双膦酸盐负责中期维持；肾功能不全者需调整剂量。\n\n【急诊/急救】\n高钙危象伴意识改变、心律失常或急性肾损伤为急症，立即补液并联合降钙治疗。","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"E83.5（钙代谢紊乱，高钙血症）","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2793,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"867b2272bd74235e5713a939ec8387f555a5b930dca6684cc9bbbff214939c7d","pinyin":"gaogaiweixiang","initials":"ggwx","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","E83.5（钙代谢紊乱，高钙血症）",30]]},{"id":"templates-1e301bc571f76b8204cb","key":"v1-c9ccc21dfe2a3058|templates-1e301bc571f76b8204cb","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"高钙血症","category":"临床急症","raw":{"name":"高钙血症","category":"临床急症","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】恶心、呕吐、便秘、多尿、烦渴、神志改变、心律失常。\n【待人工确认·本机素材无此段原文】","现病史":"高钙血症的降钙方案：扩容+呋塞米利尿，中重度加双膦酸盐或降钙素，严重高钙（>3.5）需紧急处理。\n常见表现：恶心、呕吐、便秘、多尿、烦渴、神志改变、心律失常。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者出现恶心、呕吐、便秘、多尿、烦渴、神志改变、心律失常，结合初步诊断血钙>2.75mmol/L，临床考虑高钙血症，需评估脱水与肾功能状态并明确病因，故检查须入院即刻完成。急查血钙并同步查白蛋白，按校正钙＝测定钙＋0.02×(40－白蛋白g/L)计算校正值，明确血钙真实水平并区分轻、中、重度；查血PTH明确病因，PTH升高提示原发性甲状旁腺功能亢进，PTH受抑制则多提示恶性肿瘤、维生素D中毒等非甲状旁腺因素；查血磷、血镁了解伴随的磷镁代谢紊乱，辅助病因鉴别并指导补充治疗；患者多尿、烦渴、呕吐，查肾功能与电解质评估脱水程度、急性肾损伤及肾小管浓缩功能受损情况，指导扩容利尿；患者有心律失常表现，急查心电图了解有无QT间期缩短、传导阻滞及心律失常，评估心脏受累；补充查25-(OH)D、血清蛋白电泳与免疫固定电泳、肿瘤标志物（含PTHrP）筛查多发性骨髓瘤等恶性肿瘤病因，查尿钙/尿肌酐比值了解尿钙排泄情况，必要时查动脉血气分析评估酸碱状态；同时与噻嗪类利尿剂、维生素D制剂、锂剂等药物性高钙及制动性高钙鉴别。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 血钙>2.75mmol/L\n2. 评估有无脱水、肾衰\n1. 高钙血症（ICD-10：E83.5）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n扩容+利尿: 0.9% NS 1000~2000mlivgtt 扩容,配合呋塞米 20-40mgiv(肾功正常者)。\n抑制骨吸收(中重度高钙)：双膦酸盐(如帕米膦酸二钠)静滴，或降钙素肌注。\n注意：\n轻度高钙治疗以利尿结合补液扩容为主\n严重高钙(>3.5mmol/L)需紧急处理，警惕脱水、肾衰。","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"E83.5","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2794,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"322b269e8d5c9369ae7ee54f72094546efe2bbc8f8ca73215bf68d00336276aa","pinyin":"gaogaixuezheng","initials":"ggxz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","E83.5",30]]},{"id":"templates-9423ab71e388e5020987","key":"v1-c9ccc21dfe2a3058|templates-9423ab71e388e5020987","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"高钠血症","category":"临床急症","raw":{"name":"高钠血症","category":"临床急症","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】口渴、烦渴、意识障碍、昏迷。\n【待人工确认·本机素材无此段原文】","现病史":"高钠血症的处理：补水为主、限制钠摄入，严重/昏迷者静脉补糖（糖尿病用NS），警惕稀释性低钠。\n常见表现：口渴、烦渴、意识障碍、昏迷。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者出现口渴、烦渴、意识障碍甚至昏迷，结合初步诊断血钠>145mmol/L，临床考虑高钠血症，须评估脱水程度并判断是水丢失多于钠丢失还是钠摄入过多，故检查须入院即刻完成。急查血钠、血钾、血氯及二氧化碳结合力，明确高钠血症程度及有无伴随电解质紊乱与代谢性酸中毒；查血糖排除糖尿病高血糖所致渗透性利尿与高渗状态，避免误判为单纯高钠；查血渗透压并计算血浆有效渗透压，明确高渗程度与意识障碍的相关性，评估脑细胞脱水风险；查肾功能（尿素氮、肌酐）及尿常规、尿渗透压、尿钠，鉴别肾性失水（如尿崩症、渗透性利尿）与肾外失水（发热、出汗、摄入不足），计算尿钠排泄与自由水清除率评估补水方案；患者意识障碍、昏迷，查动脉血气分析评估酸碱平衡与通气状态，指导补液种类选择；补充查尿比重动态监测、24小时出入量记录，查甲状腺功能与头颅MRI（必要时）明确中枢性尿崩症等病因；同时警惕治疗过程中补液过快所致稀释性低钠与脑水肿，需定期复查血钠（每2-4小时）评估纠正速度。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 血钠>145mmol/L\n2. 评估脱水程度\n1. 高钠血症（ICD-10：E87.0）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n治疗原则：补水为主，限制钠摄入，严重/昏迷者静脉补糖，糖尿病者换用生理盐水。\n清醒者:口服白开水 1500-2000ml/日。\n严重/昏迷者: 5%GS500ml 静滴 qd (可连用 2-3 组,糖尿病患者用NS)。注意：严重脱水所致高钠，补水同时少量补钠，避免稀释性低钠。","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"E87.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2795,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c84289d48514c1044796be5d7ce5a7d1e6123b64ce5dcd7be8b3b3b3c2b50ce2","pinyin":"gaonaxuezheng","initials":"gnxz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","E87.0",30]]},{"id":"templates-b0c1f370bdc0bc7f70b3","key":"v1-c9ccc21dfe2a3058|templates-b0c1f370bdc0bc7f70b3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"高钾血症","category":"临床急症","raw":{"name":"高钾血症","category":"临床急症","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】可无症状（化验发现）或肌无力、肢端麻木、心率慢、心悸；ECG可示T波高尖、P波消失、QRS增宽、正弦波。。\n【待人工确认·本机素材无此段原文】","现病史":"血钾≥6.5mmol/L（或任意血钾伴心电图改变）为高钾危急值，可致传导阻滞、缓慢性心律失常甚至室颤/停搏；心电图可无典型改变（约半数），勿依赖ECG判断严重度。处理按\"降钾三步法\"：稳定心肌→促内移→促排出。\n常见表现：可无症状（化验发现）或肌无力、肢端麻木、心率慢、心悸；ECG可示T波高尖、P波消失、QRS增宽、正弦波。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者可无症状而由化验发现，或出现肌无力、肢端麻木、心率慢、心悸，心电图可示T波高尖、P波消失、QRS增宽甚至正弦波，结合血钾≥6.5mmol/L即为高钾危急值，可致传导阻滞、缓慢性心律失常甚至室颤与停搏，故检查须急诊完成。急查血钾复查确认，同时观察标本有无溶血以排除溶血所致假性高钾，避免过度治疗；急查心电图，明确有无T波高尖、P波消失、QRS增宽等表现并判断是否需要立即静脉钙剂稳定心肌，但约半数患者心电图可无典型改变，勿单凭心电图判断严重度；查肾功能（尿素氮、肌酐）明确有无急慢性肾衰竭所致排钾障碍，评估是否需要透析治疗；查动脉血气分析了解有无代谢性酸中毒，酸中毒时钾离子向细胞外转移可加重高钾；详细询问并核对用药史（ACEI/ARB、保钾利尿剂、螺内酯、非甾体抗炎药及补钾制剂），明确药物性高钾因素并及时停用；查血镁、血钠、血钙了解伴随电解质紊乱，低镁可加重心律失常并影响降钾效果；补充查血糖与血胰岛素水平评估胰岛素促钾内移治疗的安全性，查肌酸激酶与血常规排除横纹肌溶解、肿瘤溶解及严重感染所致钾释放；按血钾水平与心电图改变分级处理，并在降钾治疗中每2-4小时复查血钾动态评估疗效。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"复查血钾确认（排除溶血假性升高）；查肾功能、血气（酸中毒）、用药史（ACEI/ARB、保钾利尿剂、补钾）；按血钾与心电图分级。\n1. 高钾血症（ICD-10：E87.5）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n①膜稳定：10%葡萄糖酸钙10-30ml（或10%氯化钙5-10ml）缓慢静推2-5min，心电监护，必要时5-10min重复一次；②促内移：胰岛素10U+50%葡萄糖50ml静滴（监测血糖≥12h），可联合沙丁胺醇10-20mg雾化；合并代酸者5%碳酸氢钠100-250ml；③促排出：呋塞米20-40mg静推（有残余肾功能）、环硅酸锆钠10g口服/鼻饲（1h起效）。\n\n【药物治疗·口服】\n聚苯乙烯磺酸钠等树脂口服（起效慢）、环硅酸锆钠口服；慢性期管理用patiromer等。\n\n【治疗】\n1.立即停用钾制剂与保钾药并心电监护；2.三步降钾（钙剂→胰岛素+葡萄糖→排钾）；3.紧急透析指征：血钾≥7.0mmol/L、药物治疗无效、严重肾衰无尿；4.处理诱因（酸中毒、缺血、肾衰）；5.动态复查血钾与心电图（治疗后每1-2小时）。\n\n【处理要点】\n持续心电监护观察T波/QRS；记录出入量；透析协调。\n\n【注意事项】\n依据《内科常见危急值及详细处理》整理，实际以本院危急值制度与最新指南为准。钙剂只保护心肌不降血钾，必须继以内移与排钾；心脏骤停时钙剂不推荐常规给予（2025更新）；洋地黄中毒者钙剂慎用。\n\n【急诊/急救】\n血钾>6.5伴ECG改变、>7.0mmol/L、无尿或药物无效→立即钙剂+促内移并准备紧急透析；心脏停搏（高钾）按ACLS（钙剂选择性使用）。","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"E87.5","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2796,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"53f2f57d565c48962a23edf35fd7cfa3372917760f280dc5aba86e03d5c90c20","pinyin":"gaojiaxuezheng","initials":"gjxz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","E87.5",30]]},{"id":"templates-b0ccef6c191be713734f","key":"v1-c9ccc21dfe2a3058|templates-b0ccef6c191be713734f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"乏脂性湿疹（干性湿疹、皲裂性湿疹）","category":"湿疹皮炎类","raw":{"name":"乏脂性湿疹（干性湿疹、皲裂性湿疹）","category":"湿疹皮炎类","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】干燥、瘙痒，洗浴后加重。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：干燥、瘙痒，洗浴后加重。。\n自觉症状：干燥、瘙痒，洗浴后加重。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：皮肤干燥、脱屑、皲裂，呈细碎瓷裂纹样（裂纹状红斑），可伴红斑、抓痕。\n好发部位：好发于小腿前侧、四肢伸侧，冬季老年人多见。","辅助检查":"检查计划：患者以皮肤干燥、瘙痒为主要表现，洗浴后加重，秋冬好发，可见皲裂样皮损，临床考虑乏脂性湿疹（干性湿疹、皲裂性湿疹），需与淤积性皮炎及其他湿疹皮炎类疾病鉴别，故以临床检查为主、化验为辅。查血常规了解嗜酸性粒细胞及有无感染征象，排除感染性皮炎并评估过敏体质背景；查总IgE及过敏原特异性IgE（吸入与食入组）明确有无变态反应因素参与，指导避免接触与饮食管理；查肝肾功能与血糖，排除糖尿病、肝胆疾病及慢性肾病所致皮肤干燥瘙痒，因尿毒症性瘙痒、胆汁淤积性瘙痒可酷似本病；查甲状腺功能排除甲状腺功能减退所致皮肤干燥；查血清白蛋白与营养指标评估营养状态，因必需脂肪酸及锌缺乏可致皮肤干燥皲裂；必要时行皮肤真菌镜检与伍德灯检查排除体癣、手足癣等真菌感染性疾病，行皮肤病理活检与淤积性皮炎、银屑病、接触性皮炎鉴别；对老年患者必要时筛查肿瘤相关指标，因部分恶性肿瘤可伴发全身瘙痒；治疗中定期复查上述异常指标，观察皮肤屏障修复与瘙痒改善情况。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据皮肤干燥、皲裂样皮损及秋冬好发诊断，需与淤积性皮炎鉴别。\n1. 乏脂性湿疹（干性湿疹、皲裂性湿疹）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n减少洗浴、避免热水烫洗与皂类，充分保湿（润肤剂），外用中弱效糖皮质激素。\n\n【注意事项】\n注重保湿与生活方式调整，顽固者排查甲状腺功能减退等病因。","资料来源":"皮肤病库 derm.json（条目「乏脂性湿疹（干性湿疹、皲裂性湿疹）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2797,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8d28900d5cdddc87aaba0a5df7970760c9ee41c31147c057a876aa45aa5fd56d","pinyin":"fazhixingshizhen（ganxingshizhen、junliexingshizhen）","initials":"fzxsz（gxsz、jlxsz）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-3384b47f64278ff99be2","key":"v1-c9ccc21dfe2a3058|templates-3384b47f64278ff99be2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"传染性红斑","category":"病毒性","raw":{"name":"传染性红斑","category":"病毒性","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】一般无瘙痒或轻微瘙痒，可伴低热、乏力、关节痛（成人多见）。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：一般无瘙痒或轻微瘙痒，可伴低热、乏力、关节痛（成人多见）。。\n自觉症状：一般无瘙痒或轻微瘙痒，可伴低热、乏力、关节痛（成人多见）。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：面颊出现鲜红色水肿性红斑，呈“掌击样”（slapped cheek）外观，躯干四肢出现花边状、网状红斑，可时隐时现，消退后无脱屑。\n好发部位：好发于面颊部，随后累及四肢躯干。","辅助检查":"检查计划：患者面颊出现“掌击样”红斑、躯干花边状红斑，伴轻微瘙痒、低热、乏力，成人可有关节痛，临床考虑传染性红斑（细小病毒B19感染），需明确病原并与其他病毒性发疹性疾病鉴别。查血清细小病毒B19特异性IgM抗体，IgM阳性提示近期感染，为确诊本病的血清学依据；必要时查B19 DNA（PCR）提高病原检出率，适用于免疫功能低下或血清学结果不明确者；查血常规了解有无贫血、白细胞及血小板减少，因B19可抑制骨髓造血，纯红细胞再生障碍者需警惕；查CRP、血沉等炎症指标评估炎症活动度，判断是否合并细菌感染；患者低热、乏力，查肝功能了解有无转氨酶升高，因B19感染可累及肝脏；成人关节痛明显者查类风湿因子、抗CCP抗体及ANA谱，与类风湿关节炎、系统性红斑狼疮等风湿性疾病所致关节痛及皮疹鉴别；查EB病毒、巨细胞病毒、风疹病毒及麻疹病毒抗体，与EB病毒感染、风疹、麻疹等其他病毒性发疹性疾病鉴别；孕妇或育龄期女性需查B19 IgM/IgG及胎儿超声，评估宫内感染与胎儿水肿风险；必要时行皮肤病理活检辅助鉴别，病程中定期复查血常规观察血液系统变化。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据面颊“掌击样”红斑及躯干花边状红斑临床诊断，血清细小病毒B19 IgM抗体阳性可确诊。\n1. 传染性红斑","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n以对症支持为主，无需特殊抗病毒治疗。\n\n【注意事项】\n由细小病毒B19引起，儿童多见；孕妇感染可致胎儿水肿/流产，血液病患儿可致再生障碍危象，需警惕。","资料来源":"皮肤病库 derm.json（条目「传染性红斑」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2798,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"55a4aa59f7b6e6c056238a1ec5fc1ab7a5ac8d567f405c23accba404a888f6ba","pinyin":"chuanranxinghongban","initials":"crxhb","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-6ba25a846f06d1510b15","key":"v1-c9ccc21dfe2a3058|templates-6ba25a846f06d1510b15","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"咖啡牛奶斑","category":"色素性","raw":{"name":"咖啡牛奶斑","category":"色素性","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】一般无自觉症状。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：一般无自觉症状。。\n自觉症状：一般无自觉症状。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：淡棕色至深棕色、边缘清楚但不规则、大小不一的斑片，颜色均匀。\n好发部位：可发生于身体任何部位，常为散在。","辅助检查":"检查计划：患者出生后或幼年即出现褐色斑片，一般无自觉症状，本次就诊需明确色素斑性质并评估有无神经纤维瘤病等系统受累，入院后完善皮肤镜检查了解斑片色素分布层次与边缘特征，必要时行皮肤病理活检明确黑素细胞增生情况，以鉴别单纯性咖啡牛奶斑、雀斑样痣与色素痣；初步诊断提示斑片数目较多、直径偏大时须警惕神经纤维瘤病，故完善眼科裂隙灯及眼底检查明确有无Lisch结节，完善头颅MRI检查了解有无视神经胶质瘤及颅内异常信号，完善脊柱及四肢MRI检查评估有无神经纤维瘤或丛状神经瘤；患者斑片数量多、范围广，完善血常规、肝肾功能检查了解基础状况，为后续随访及可能的治疗提供依据；完善脑电图检查排除癫痫样放电，鉴别神经系统受累所致；完善神经内科专科查体配合听力及智力评估，了解有无听力下降、认知障碍等伴随表现；本病需长期随访，病情稳定后每6至12个月定期复查皮肤镜及头颅MRI，观察斑片数目、范围有无进展及有无新发系统损害，必要时复查眼科裂隙灯以评估Lisch结节变化。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据出生或幼年出现的均匀褐色斑片诊断；数量≥6个且直径达标（青春期前>5mm、青春期后>15mm）需警惕神经纤维瘤病。\n1. 咖啡牛奶斑","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n无症状者可不处理，美容需求可行激光治疗。\n\n【注意事项】\n多发咖啡牛奶斑需排查神经纤维瘤病及系统性疾病并转诊。","资料来源":"皮肤病库 derm.json（条目「咖啡牛奶斑」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2799,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"56052fb0aa740f0658e83a311c97d5962decc98ddd9e24e8a9e92d9b4d7ee696","pinyin":"kafeiniunaiban","initials":"kfnnb","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-ee17cda9c18c02c89719","key":"v1-c9ccc21dfe2a3058|templates-ee17cda9c18c02c89719","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"多形性日光疹","category":"物理性","raw":{"name":"多形性日光疹","category":"物理性","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】自觉瘙痒，日晒后数小时至数天发疹，避免日晒后可自行消退。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：自觉瘙痒，日晒后数小时至数天发疹，避免日晒后可自行消退。。\n自觉症状：自觉瘙痒，日晒后数小时至数天发疹，避免日晒后可自行消退。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：日晒后暴露部位出现多种形态的皮疹，如红斑、丘疹、丘疱疹、水疱、斑块或苔藓样变，同一患者皮损形态相对固定。\n好发部位：好发于面、颈、前胸V形区、前臂伸侧等暴露部位。","辅助检查":"检查计划：患者日晒后数小时至数天于暴露部位出现多形性皮疹，自觉瘙痒，避免日晒后可自行消退且反复发作，为明确光敏性疾病性质，入院后完善光试验（最小红斑量MED测定）明确作用光谱及光敏感程度，完善皮肤光斑贴试验查找可疑光敏物质，必要时行皮损组织病理检查了解真皮浅层血管周围淋巴细胞浸润情况，以鉴别多形性日光疹、光化性痒疹与慢性光化性皮炎；初步诊断需与红斑狼疮鉴别，故完善抗核抗体谱、抗Ro/SSA抗体及抗La/SSB抗体检查排除亚急性皮肤型红斑狼疮，完善尿卟啉及血卟啉检查排除卟啉病所致光敏；患者反复日晒后发疹，完善血常规、肝肾功能及红细胞沉降率检查了解全身炎症状态及重要脏器功能，为用药安全提供依据；完善甲状腺功能检查排除甲状腺疾病相关的光敏表现；皮疹泛发、瘙痒明显者完善总IgE及过敏原检测了解变态反应背景，鉴别接触性皮炎所致；病情稳定后定期复查光试验评估光耐受改善情况，并定期复查皮损变化，指导防晒及后续脱敏治疗方案调整。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据春季或初夏日晒后暴露部位出现多形性皮疹、避光后消退、反复发作，可结合光试验及皮肤光斑贴试验确诊。\n1. 多形性日光疹","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n防晒、避光，外用糖皮质激素及遮光剂，重症可预防性光疗（窄谱UVB、PUVA）或口服羟氯喹。\n\n【注意事项】\n需与光接触性皮炎、红斑狼疮、卟啉病等光敏性疾病鉴别。","资料来源":"皮肤病库 derm.json（条目「多形性日光疹」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2800,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7d4f9154e096b227dfdd08058411bb5afe432998ab0b9c955e458e9a50389aff","pinyin":"duoxingxingriguangzhen","initials":"dxxrgz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-9669eb7cbdd1ad065400","key":"v1-c9ccc21dfe2a3058|templates-9669eb7cbdd1ad065400","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"太田痣（眼上颌褐青色痣）","category":"色素性","raw":{"name":"太田痣（眼上颌褐青色痣）","category":"色素性","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】一般无自觉症状，影响外观。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：一般无自觉症状，影响外观。。\n自觉症状：一般无自觉症状，影响外观。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：蓝灰色、灰褐色或青褐色斑片，边界不清，常累及眼周皮肤与巩膜，单侧多见。\n好发部位：好发于三叉神经第一、二支分布区（眶周、颞部、额部、鼻部），常为单侧。","辅助检查":"检查计划：患者出生或幼年即出现单侧眶周褐青色斑片，一般无自觉症状但影响外观，为明确色素病变性质及深度，入院后完善Wood灯检查了解色素位于真皮浅层还是深层，完善皮肤镜检查观察色素网络及颜色均一性，必要时行皮肤组织病理检查明确真皮内黑素细胞分布，以鉴别太田痣、伊藤痣与蒙古斑；初步诊断提示需与伊藤痣、蒙古斑鉴别，故完善眼科裂隙灯及眼压检查明确有无巩膜及结膜色素沉着、是否合并青光眼，完善头颅及眼眶MRI检查了解有无颅内及眶内色素性病变，鉴别神经皮肤黑变病；患者意在接受激光治疗，完善血常规、凝血功能检查排除凝血异常所致出血风险，完善肝肾功能检查了解代谢状况，为麻醉及用药安全提供依据；完善心电图检查评估心脏情况，明确能否耐受治疗；治疗前完善皮损部位照片并定期随访拍照，客观评估面积与颜色变化；病情稳定后按疗程定期复查，观察有无色素沉着或色素减退等并发症，必要时复查眼压以评估眼部受累进展。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据出生或幼年出现的单侧眶周褐青色斑片及巩膜受累诊断，需与伊藤痣、蒙古斑鉴别。\n1. 太田痣（眼上颌褐青色痣）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n采用Q开关激光（694nm、755nm、1064nm）多次治疗，效果较好。\n\n【注意事项】\n需眼科评估巩膜受累情况，警惕罕见恶变可能。","资料来源":"皮肤病库 derm.json（条目「太田痣（眼上颌褐青色痣）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2801,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"97ad5a68ed23c35117d210b366ae5aed1557156c114e613883455053c9e57883","pinyin":"taitianzhi（yanshangheheqingsezhi）","initials":"ttz（yshhqsz）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-d118d5e217ff087ebe6c","key":"v1-c9ccc21dfe2a3058|templates-d118d5e217ff087ebe6c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"头癣（癞痢头）","category":"真菌性","raw":{"name":"头癣（癞痢头）","category":"真菌性","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】多有不同程度瘙痒，继发感染时可有疼痛。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：多有不同程度瘙痒，继发感染时可有疼痛。。\n自觉症状：多有不同程度瘙痒，继发感染时可有疼痛。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：头皮出现圆形或不规则形脱发斑，其上可见断发、鳞屑、脓疱或黄癣痂，头发在毛囊口处折断呈参差不齐状。\n好发部位：好发于头皮，儿童多见。","辅助检查":"检查计划：患者头皮出现鳞屑性斑片伴不同程度瘙痒，继发感染时可有疼痛，为明确致病真菌并指导用药，入院后即刻完善病发及鳞屑真菌直接镜检明确有无发内或发外孢子，同时完善真菌培养及菌种鉴定明确致病菌种，以鉴别白癣、黄癣与黑点癣；初步诊断提示需结合Wood灯结果判断，故完善Wood灯检查明确有无亮绿色或暗绿色荧光，注意黑点癣可无荧光，Wood灯阴性不能排除头癣；患者皮损范围较大需系统抗真菌治疗，完善血常规、肝肾功能检查了解基础状况，为伊曲康唑或特比萘芬用药安全提供依据，必要时完善心肌酶及心电图检查评估心脏情况；完善皮肤镜检查观察病发形态及断发特征，辅助明确诊断；患儿及密切接触者完善真菌学筛查了解有无交叉感染，指导隔离与消毒；治疗期间定期复查真菌镜检及培养评估疗效，病情稳定后每2至4周复查肝肾功能，观察药物不良反应并及时调整方案。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：真菌镜检/培养阳性；Wood灯检查：白癣呈亮绿色荧光、黄癣呈暗绿色荧光、黑点癣无荧光（故Wood灯阴性不能排除头癣）；病发镜检见发内或发外孢子。\n1. 头癣（癞痢头）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n口服抗真菌为主：儿童首选灰黄霉素10~20mg/kg·d分2次，疗程6~8周；特比萘芬按体重分层（<20kg 62.5mg/d、20~40kg 125mg/d、>40kg 250mg/d）；伊曲康唑亦可。须查肝功能与血常规。同时剪发、洗头、消毒枕巾帽子。\n\n【注意事项】\n具传染性，患儿帽子、梳子、枕巾需消毒，家庭成员应筛查；治疗需至真菌学检查转阴。","资料来源":"皮肤病库 derm.json（条目「头癣（癞痢头）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2802,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cad55b18977872525623a41c3928e67c1ee436943a5c10df631e4e648de4b016","pinyin":"touxuan（lailitou）","initials":"tx（llt）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-9236567403ab2e50f9de","key":"v1-c9ccc21dfe2a3058|templates-9236567403ab2e50f9de","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"婴儿血管瘤","category":"血管性","raw":{"name":"婴儿血管瘤","category":"血管性","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】多无症状；溃疡时疼痛出血。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：多无症状；溃疡时疼痛出血。\n自觉症状：多无症状；溃疡时疼痛出血。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：出生后数周出现，增殖期鲜红色隆起斑块（草莓状），消退期变软变灰\n好发部位：头颈、躯干；女性/早产儿多见","辅助检查":"检查计划：患儿出生后出现血管性皮损，多无症状，溃疡时可有疼痛出血，为明确病变性质、范围及有无系统受累，入院后完善皮损彩色多普勒超声检查了解瘤体大小、深度、血流丰富程度及有无动静脉分流，以鉴别婴儿血管瘤、血管畸形与卡波西样血管内皮瘤；初步诊断提示需评估增殖与消退过程，故完善皮肤镜检查观察血管形态特征，必要时行皮肤组织病理及免疫组化检查明确诊断；患者需口服普萘洛尔治疗，完善心脏彩超及心电图检查了解心功能及有无传导阻滞，排除心脏结构异常及心动过缓，完善血糖、甲状腺功能检查排除低血糖及甲状腺功能异常所致风险；完善血常规、肝肾功能检查了解基础状况，为用药安全提供依据；位于眼周、气道、肝脏等特殊部位者，完善头颅及腹部MRI检查了解有无颅内或肝内血管瘤，明确系统受累范围；病情稳定后定期复查彩超观察瘤体消退情况，定期复查心电图及血糖，评估用药安全性并指导剂量调整。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：典型出现时间+形态+增殖/消退过程；深部型肤色隆起\n1. 婴儿血管瘤","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n多数自行消退（5岁前）；需治疗者（眼周/气道/溃疡/快速生长）口服普萘洛尔\n\n【注意事项】\n眼周/气道血管瘤需尽早专科评估；勿盲目冷冻/激光","资料来源":"皮肤病库 derm.json（条目「婴儿血管瘤」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2803,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"15037805b1e649b70a05533c41470f1989fe7c1465e6df705b4c59ad3385a315","pinyin":"yingerxueguanliu","initials":"yexgl","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-0e1ef97a5994a265799b","key":"v1-c9ccc21dfe2a3058|templates-0e1ef97a5994a265799b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"寻常疣（瘊子）","category":"病毒性","raw":{"name":"寻常疣（瘊子）","category":"病毒性","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】多无症状；跖疣行走痛。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：多无症状；跖疣行走痛。\n自觉症状：多无症状；跖疣行走痛。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：黄豆大小角化性丘疹，表面粗糙呈乳头状，灰褐色，可见黑色点状出血\n好发部位：手背、手指、足底（跖疣）、甲周","辅助检查":"检查计划：患者皮肤出现角化性丘疹，多无症状，跖疣行走时疼痛，为明确诊断并指导治疗，入院后完善皮肤镜检查观察点状出血及血栓性毛细血管特征，必要时行皮肤组织病理检查明确有无空泡细胞及角化不全，以鉴别寻常疣、鸡眼与胼胝；初步诊断提示HPV感染，故完善HPV分型检测明确感染型别，了解有无高危型合并感染；患者疣体多发或反复发作，完善免疫球蛋白、淋巴细胞亚群及血糖检查了解免疫状态，排除免疫功能低下或糖尿病所致易感性增高，必要时完善HIV抗体筛查鉴别免疫缺陷相关疣；患者病程较长需多次物理或药物治疗，完善血常规、肝肾功能检查了解基础状况，为用药及手术安全提供依据；完善凝血功能检查排除凝血异常所致出血风险；病情稳定后定期复查皮肤镜及皮损变化，观察有无复发或新发，指导后续治疗及随访间隔。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：典型角化性丘疹+点状出血；HPV感染（1/2/4型等）\n1. 寻常疣（瘊子）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n冷冻、激光、外用5-氟尿嘧啶/水杨酸、局部免疫治疗\n\n【注意事项】\n有自愈倾向（儿童）；免疫功能低下者难治；避免搔抓传染","资料来源":"皮肤病库 derm.json（条目「寻常疣（瘊子）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2804,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5c0844db1bb542d725d1112bfc4bb60bc5602477ccf34b143f4931d22571f089","pinyin":"xunchangyou（houzi）","initials":"xcy（hz）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-7ebb79a8186fee84fb13","key":"v1-c9ccc21dfe2a3058|templates-7ebb79a8186fee84fb13","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"局限性硬皮病（硬斑病）","category":"结缔组织病","raw":{"name":"局限性硬皮病（硬斑病）","category":"结缔组织病","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】早期可有瘙痒或紧绷感，后期活动受限。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：早期可有瘙痒或紧绷感，后期活动受限。。\n自觉症状：早期可有瘙痒或紧绷感，后期活动受限。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：初期为淡红色水肿性斑，后中央硬化、蜡样光泽，呈象牙白或黄色，周围有紫红色晕（紫罗兰环），晚期萎缩、色素沉着。\n好发部位：好发于躯干、四肢，亦可累及面部（刀砍状硬皮病）或肢体带状分布。","辅助检查":"检查计划：患者皮肤出现硬化斑块，早期可有瘙痒或紧绷感，后期活动受限，为明确病变性质与累及范围，入院后完善皮肤组织病理活检了解真皮胶原增厚、炎症细胞浸润及附属器受累情况，完善皮肤镜检查观察紫罗兰环及毛细血管扩张特征，以鉴别硬斑病、系统性硬化症与硬化性苔藓；初步诊断提示需与系统性硬化症鉴别，故完善抗核抗体谱、抗Scl-70抗体、抗着丝点抗体及抗RNA聚合酶III抗体检查明确有无系统性疾病，完善甲襞微循环检查了解外周血管受累情况；患者后期活动受限，完善病变部位MRI检查了解皮下组织、筋膜及肌肉受累深度，必要时完善关节X线检查评估关节活动受限程度；完善血常规、肝肾功能、红细胞沉降率及C反应蛋白检查了解炎症活动度与重要脏器功能，为免疫抑制治疗提供依据；完善胸部CT及肺功能检查排除肺间质病变，完善心电图及心脏彩超排除心脏受累；病情稳定后定期复查皮肤病理及自身抗体，观察病情有无进展或转为系统性硬化症。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据典型硬化斑块及紫罗兰环诊断，行皮肤病理（真皮胶原增厚）确诊，需与系统性硬化症鉴别。\n1. 局限性硬皮病（硬斑病）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n早期外用或皮损内注射糖皮质激素、钙泊三醇，口服甲氨蝶呤或光疗（PUVA/UVA1）。\n\n【注意事项】\n带状或泛发型可致关节挛缩、肢体萎缩，需早期积极治疗并随访。","资料来源":"皮肤病库 derm.json（条目「局限性硬皮病（硬斑病）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2805,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bb2378e0a8c3b56fee6b61befc76663ad49018211e83c25a3e2817e57df32341","pinyin":"juxianxingyingpibing（yingbanbing）","initials":"jxxypb（ybb）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-a60fef7fac16611c14fd","key":"v1-c9ccc21dfe2a3058|templates-a60fef7fac16611c14fd","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"斑秃（圆形脱发）","category":"附属器疾病","raw":{"name":"斑秃（圆形脱发）","category":"附属器疾病","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】多无自觉症状，少数患者局部可有瘙痒、刺痛感。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：多无自觉症状，少数患者局部可有瘙痒、刺痛感。。\n自觉症状：多无自觉症状，少数患者局部可有瘙痒、刺痛感。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：突然出现的圆形或椭圆形边界清楚的脱发斑，头皮光滑无瘢痕，可见“感叹号”样发，可发展至全秃或普秃。\n好发部位：好发于头皮，可累及眉毛、胡须及其他部位毛发。","辅助检查":"检查计划：患者突然出现边界清楚的斑片状脱发，脱发区皮肤光滑无炎症，多无自觉症状，少数局部可有瘙痒或刺痛感，为明确脱发性质并寻找诱因，入院后完善拉发试验了解毛发活动期情况，完善皮肤镜检查观察感叹号发、黑点征及黄点征，必要时行头皮组织病理活检了解毛囊周围淋巴细胞浸润情况，以鉴别斑秃、头癣与拔毛癖；初步诊断提示需与头癣鉴别，故完善真菌镜检及Wood灯检查排除真菌感染所致脱发；患者脱发范围较广，完善甲状腺功能及甲状腺自身抗体检查排除甲状腺疾病所致脱发，完善抗核抗体谱检查排除红斑狼疮等自身免疫性疾病；完善血常规、铁代谢及维生素B12、叶酸检查排除缺铁性贫血及营养缺乏所致脱发，完善性激素及皮质醇检查了解内分泌状态，鉴别内分泌紊乱所致；完善肝肾功能及血糖检查，为糖皮质激素或免疫抑制治疗提供用药安全依据；病情稳定后定期复查皮肤镜及毛发计数，观察有无新发或复发，指导治疗周期与随访间隔。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据突然发生的边界清楚的斑片状脱发、皮肤光滑无炎症及感叹号发，拉发试验阳性；需与头癣、拔毛癖鉴别。\n1. 斑秃（圆形脱发）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n局部外用或皮损内注射糖皮质激素、外用米诺地尔；广泛或进行期可系统用药或局部免疫治疗。\n\n【注意事项】\n可合并甲改变及自身免疫性疾病（如甲状腺疾病），应注意随访。","资料来源":"皮肤病库 derm.json（条目「斑秃（圆形脱发）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2806,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a630c44daf7b22b7b372ea1fb9a1a250e593a9e2b44ea26ee2ea844911ef0a80","pinyin":"bantu（yuanxingtuofa）","initials":"bt（yxtf）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-e3cce733575e3ad82a98","key":"v1-c9ccc21dfe2a3058|templates-e3cce733575e3ad82a98","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"日光性皮炎（晒斑）","category":"物理性","raw":{"name":"日光性皮炎（晒斑）","category":"物理性","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】自觉灼热、刺痛，重者可有全身不适、发热、恶心等。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：自觉灼热、刺痛，重者可有全身不适、发热、恶心等。。\n自觉症状：自觉灼热、刺痛，重者可有全身不适、发热、恶心等。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：暴露部位出现境界清楚的红斑、水肿，重者出现水疱、大疱，后期脱屑、色素沉着。\n好发部位：好发于面、颈、前臂、手背等日晒暴露部位。","辅助检查":"检查计划：患者有强烈日光暴晒史，暴露部位出现境界清楚的红斑、水疱，需与接触性皮炎、药疹及其他光敏性皮肤病相鉴别。查血常规了解有无白细胞升高、中性粒细胞比例增高，明确是否合并细菌感染；因患者自觉灼热刺痛，重者可有全身不适、发热、恶心，完善 C 反应蛋白（CRP）检查评估全身炎症反应程度，必要时完善降钙素原检查以鉴别细菌感染与日光损伤所致吸收热；水疱破溃渗液者完善疱液细菌培养及药物敏感试验，明确有无继发感染并指导抗生素选择；查肝肾功能及电解质了解用药前基础状况，排除肝肾功能不全及电解质紊乱所致乏力、恶心，为口服抗组胺药及补液治疗提供依据；皮损广泛或疑有光敏性疾病者完善尿卟啉、粪卟啉检查，排除卟啉病所致光敏；完善皮肤镜检查观察皮损表面及血管结构，排除接触性皮炎、多形性日光疹等其他光敏性皮炎；反复发作或疑有光线性皮肤病者，病情稳定后行光激发试验（MED 测定）及光斑贴试验，明确致病光谱及致敏物质；皮损持续不愈、形态不典型或疑有恶变者，必要时行组织病理检查以进一步明确诊断。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据强烈日光暴晒史、暴露部位境界清楚的红斑水疱及与衣着遮盖部位分界明显，即可诊断。\n1. 日光性皮炎（晒斑）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n脱离日晒环境，冷敷；外用炉甘石洗剂、糖皮质激素软膏，重者系统患者糖皮质激素及对症处理。\n\n【注意事项】\n注意防晒（遮阳、防晒霜）；严重晒伤伴全身症状者需及时处理。","资料来源":"皮肤病库 derm.json（条目「日光性皮炎（晒斑）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2807,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5e1e28698d74411f4128f7b0e6ee4ab704c96b1d8a500a2fbc7556e68dee90f1","pinyin":"riguangxingpiyan（shaiban）","initials":"rgxpy（sb）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-6c24ced72d3ade22c8ee","key":"v1-c9ccc21dfe2a3058|templates-6c24ced72d3ade22c8ee","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"日光性角化（光线性角化病、老年性角化病）","category":"皮肤肿瘤","raw":{"name":"日光性角化（光线性角化病、老年性角化病）","category":"皮肤肿瘤","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】一般无自觉症状或轻度瘙痒、刺痛。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：一般无自觉症状或轻度瘙痒、刺痛。。\n自觉症状：一般无自觉症状或轻度瘙痒、刺痛。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：曝光部位干燥、粗糙的鳞屑性红斑或丘疹，表面黏着性鳞屑，可呈肤色、淡红或棕黄色，触之砂纸样。\n好发部位：好发于面部、头皮、耳廓、手背、前臂等日光暴露部位。","辅助检查":"检查计划：患者皮损位于曝光部位，呈持续性粗糙鳞屑性改变，需与脂溢性角化病、盘状红斑狼疮及早期鳞状细胞癌相鉴别。完善皮肤镜检查观察角化程度、毛囊开口及血管形态，评估有无鳞状细胞癌的皮肤镜特征，明确是否需要活检；因本病为癌前病变，可疑者行组织病理活检及免疫组化检查，明确有无细胞异型性及间变，必要时明确是否已进展为鳞状细胞癌；查血常规、C 反应蛋白及红细胞沉降率了解有无感染、贫血及全身炎症状态，为局部治疗或手术切除前评估提供依据；患者多为老年、长期日晒人群，查肝肾功能、血糖及电解质了解基础脏器功能，排除肝肾功能不全及糖尿病，评估外用 5-氟尿嘧啶、咪喹莫特或光动力治疗的耐受性；查凝血功能及术前免疫筛查（乙肝、丙肝、梅毒、HIV），明确有无凝血异常及传染性疾病，为手术切除或冷冻治疗做准备；皮损多发或疑有免疫抑制状态者查淋巴细胞亚群及 HIV 抗体，了解机体免疫状态，评估病变进展风险；长期随访者定期复查皮肤镜并每 3～6 个月专科复诊，观察有无新发皮损及恶变征象。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据曝光部位持续性粗糙鳞屑性皮损诊断，可疑者行皮肤镜或活检排除鳞状细胞癌。\n1. 日光性角化（光线性角化病、老年性角化病）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n属癌前病变，采用冷冻、光动力、外用5-氟尿嘧啶或咪喹莫特，或激光、手术切除。\n\n【注意事项】\n严格防晒，皮损迅速增大、破溃或结节化提示恶变需立即活检。","资料来源":"皮肤病库 derm.json（条目「日光性角化（光线性角化病、老年性角化病）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2808,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3f87241692835c258ae6778495e029d297302290eb0dec70829385e6135330c0","pinyin":"riguangxingjiaohua（guangxianxingjiaohuabing、laonianxingjiaohuabing）","initials":"rgxjh（gxxjhb、lnxjhb）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-d33f3036ec7fca323e06","key":"v1-c9ccc21dfe2a3058|templates-d33f3036ec7fca323e06","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"汗疱疹（出汗不良性湿疹）","category":"湿疹皮炎类","raw":{"name":"汗疱疹（出汗不良性湿疹）","category":"湿疹皮炎类","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】瘙痒或灼痛。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：瘙痒或灼痛。\n自觉症状：瘙痒或灼痛。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：掌跖部粟粒大小深在性水疱，疱液清亮，不易破，可融合成大疱\n好发部位：手掌、足底、指（趾）侧缘","辅助检查":"检查计划：患者掌跖部位出现深在水疱伴瘙痒或灼痛，呈季节性（春夏）发作，需与手癣、足癣、接触性皮炎及掌跖脓疱病相鉴别。完善真菌镜检及培养检查，取水疱疱壁或鳞屑行氢氧化钾涂片，明确有无真菌菌丝及孢子，排除手癣、足癣所致水疱；患者常与出汗、应激及接触因素相关，完善斑贴试验了解有无接触性致敏原，排除接触性皮炎及职业性皮炎；查血常规了解嗜酸性粒细胞及白细胞水平，评估过敏状态并排除感染；完善血清总 IgE 及特异性 IgE 检测，明确有无过敏体质及致敏物质，指导避免接触及抗过敏治疗；因湿疹类疾病与特应性体质相关，详细询问个人及家族过敏史，必要时完善过敏原筛查；查肝肾功能及电解质了解用药前基础状况，排除肝肾功能不全，为外用糖皮质激素、口服抗组胺药及必要时短期口服糖皮质激素提供依据；水疱继发感染、出现脓疱或渗出者完善疱液细菌培养及药物敏感试验，明确致病菌并指导抗生素选择；反复发作、顽固不愈者病情稳定后行组织病理检查，明确有无掌跖脓疱病等其他疾病。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：季节性（春夏）掌跖深在水疱+瘙痒；与出汗/应激/接触相关\n1. 汗疱疹（出汗不良性湿疹）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n外用糖皮质激素；渗出湿敷；瘙痒抗组胺药；顽固者光疗\n\n【注意事项】与手足癣鉴别（真菌镜检阴性）；避免过度洗涤","资料来源":"皮肤病库 derm.json（条目「汗疱疹（出汗不良性湿疹）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2809,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5908a57adb09856bece2d5c26585348c2aca6b89538a189490c15af3c6c1e841","pinyin":"hanpaozhen（chuhanbuliangxingshizhen）","initials":"hpz（chblxsz）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-027fe6735a58922cb881","key":"v1-c9ccc21dfe2a3058|templates-027fe6735a58922cb881","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"淤积性皮炎（淤积性湿疹、重力性湿疹）","category":"湿疹皮炎类","raw":{"name":"淤积性皮炎（淤积性湿疹、重力性湿疹）","category":"湿疹皮炎类","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】瘙痒，可伴胀痛、沉重感。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：瘙痒，可伴胀痛、沉重感。。\n自觉症状：瘙痒，可伴胀痛、沉重感。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：小腿下段红斑、丘疹、鳞屑、色素沉着，可伴水肿、硬化，严重时出现糜烂、溃疡。\n好发部位：好发于下肢，尤其小腿下1/3及踝部，伴静脉曲张者多见。","辅助检查":"检查计划：患者有下肢静脉功能不全表现，小腿下段出现皮炎及色素沉着，伴瘙痒、胀痛及沉重感，需与接触性皮炎、淤积性溃疡及深静脉血栓形成后综合征相鉴别。完善下肢静脉彩色多普勒超声检查，评估深浅静脉瓣膜功能、有无反流及血栓形成，明确静脉功能不全的部位与程度，为压力治疗及手术方案提供依据；因患者下肢肿胀、胀痛明显，查 D-二聚体及凝血功能，排除深静脉血栓形成及凝血异常所致肿胀；查血常规及 C 反应蛋白了解有无感染、贫血及炎症状态，评估皮炎是否继发细菌感染；皮损糜烂、渗液或溃疡者完善分泌物细菌培养及药物敏感试验，明确致病菌并指导抗感染治疗；查血糖及糖化血红蛋白，排除糖尿病所致下肢血管神经病变及创面愈合不良；查肝肾功能及电解质了解基础状况，排除低蛋白血症及肝肾功能不全所致下肢水肿；必要时完善下肢动脉超声及踝肱指数检查，评估动脉供血情况，明确有无动脉缺血性病变后再决定压力治疗方案；病情稳定后定期复查下肢静脉超声，观察静脉反流及血栓变化。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据下肢静脉功能不全表现、小腿下段皮炎及色素沉着诊断，必要时行下肢静脉超声。\n1. 淤积性皮炎（淤积性湿疹、重力性湿疹）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n治疗原发静脉疾病，抬高患肢、弹力袜加压，外用糖皮质激素，控制继发感染。\n\n【注意事项】\n警惕溃疡、感染及对局部用药过敏，久治不愈需血管外科评估。","资料来源":"皮肤病库 derm.json（条目「淤积性皮炎（淤积性湿疹、重力性湿疹）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2810,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d859cacfe84121109933830c01c9e50b2ccc985d0e06f3bd8ce9a22c519776c9","pinyin":"yujixingpiyan（yujixingshizhen、zhonglixingshizhen）","initials":"yjxpy（yjxsz、zlxsz）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-87a95016e27754c8528a","key":"v1-c9ccc21dfe2a3058|templates-87a95016e27754c8528a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"特应性皮炎（湿疹）","category":"湿疹皮炎类","raw":{"name":"特应性皮炎（湿疹）","category":"湿疹皮炎类","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】剧烈瘙痒，夜间加重。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：剧烈瘙痒，夜间加重。\n自觉症状：剧烈瘙痒，夜间加重。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：红斑、丘疹、丘疱疹，慢性期皮肤增厚、苔藓化，抓痕明显\n好发部位：婴儿头面部、肘窝腘窝、颈周；成人肘窝腘窝屈侧","辅助检查":"检查计划：患者有反复发作的湿疹样皮损伴剧烈瘙痒、夜间加重，皮损分布于屈侧，并有个人或家族过敏史（哮喘、过敏性鼻炎），符合特应性皮炎诊断，需与接触性皮炎、脂溢性皮炎及疥疮相鉴别。查血常规了解嗜酸性粒细胞及白细胞水平，评估过敏状态并排除感染；完善血清总 IgE 及特异性 IgE 检测，明确致敏原及过敏程度，指导环境规避与治疗；因患者皮损反复、瘙痒剧烈，完善过敏原筛查（吸入性及食入性）及斑贴试验，了解有无接触性致敏因素，排除接触性皮炎；查肝肾功能及电解质了解用药前基础状况，排除肝肾功能不全，为长期外用糖皮质激素、钙调神经磷酸酶抑制剂及必要时系统应用免疫抑制剂提供依据；皮损泛发、渗液或继发感染（出现脓疱、黄痂）者完善疱液或分泌物细菌培养及药物敏感试验，明确有无金黄色葡萄球菌感染并指导抗感染治疗；疑有疱疹病毒感染（出现簇集水疱、脐凹）者完善单纯疱疹病毒核酸或抗原检测，明确有无 Kaposi 水痘样疹；瘙痒严重影响睡眠、需系统治疗者完善血糖及骨密度检查，评估长期用药风险；病情稳定后定期复查，观察皮损变化并评估疗效。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：反复发作的湿疹样皮损+瘙痒+屈侧分布+个人/家族过敏史（哮喘/过敏性鼻炎）\n1. 特应性皮炎（湿疹）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n保湿（润肤剂）+外用糖皮质激素；瘙痒重加抗组胺药；避免诱因；严重者光疗/系统免疫抑制剂\n\n【注意事项】\n急性期勿用热水烫洗；继发感染时抗感染治疗","资料来源":"皮肤病库 derm.json（条目「特应性皮炎（湿疹）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2811,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"eb9df69394377655f1f0589c317c2476981208caa74a5955241c58fb1aaf884e","pinyin":"teyingxingpiyan（shizhen）","initials":"tyxpy（sz）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-c127c2a0aa47a37fe88d","key":"v1-c9ccc21dfe2a3058|templates-c127c2a0aa47a37fe88d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"玫瑰痤疮（酒渣鼻）","category":"附属器疾病","raw":{"name":"玫瑰痤疮（酒渣鼻）","category":"附属器疾病","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】自觉灼热、刺痛或干燥紧绷感，情绪激动、日晒、饮酒及辛辣饮食后加重。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：自觉灼热、刺痛或干燥紧绷感，情绪激动、日晒、饮酒及辛辣饮食后加重。。\n自觉症状：自觉灼热、刺痛或干燥紧绷感，情绪激动、日晒、饮酒及辛辣饮食后加重。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：面中部潮红、阵发性红斑、持久性毛细血管扩张及丘疹、脓疱，病程长者可出现鼻部结缔组织增生（鼻赘）。\n好发部位：好发于面中部，累及鼻、颊、额、颏部。","辅助检查":"检查计划：患者面中部出现持久性红斑、毛细血管扩张及丘疹脓疱而无粉刺，伴灼热、刺痛、干燥紧绷感，情绪激动、日晒、饮酒及辛辣饮食后加重，需与痤疮、脂溢性皮炎及红斑狼疮相鉴别。完善皮肤镜检查观察血管形态、毛囊开口及有无粉刺，明确是否支持玫瑰痤疮诊断；因本病需排除蠕形螨感染，完善蠕形螨检查（挤压法或透明胶带法）及真菌镜检，明确有无蠕形螨或马拉色菌感染，指导抗螨及抗真菌治疗；完善幽门螺杆菌检测（尿素呼气试验），了解有无幽门螺杆菌感染与本病加重的相关性；查血常规、C 反应蛋白及红细胞沉降率了解有无感染及全身炎症反应，排除系统性疾病；因长期外用激素可诱发玫瑰痤疮，详细询问用药史，必要时查皮质醇及促肾上腺皮质激素，排除激素依赖性皮炎；女性患者伴月经不规律、多毛者完善性激素六项及妇科超声，排除多囊卵巢综合征所致痤疮样皮损；查肝肾功能及电解质了解基础状况，排除肝肾功能不全，为口服四环素类、异维 A 酸及甲硝唑治疗提供依据；查血脂四项了解血脂水平，指导异维 A 酸用药期间的血脂监测；皮损不典型、疑有其他疾病者必要时行组织病理检查以进一步明确诊断。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据面中部持久性红斑、毛细血管扩张、丘疹脓疱而无粉刺，需与痤疮、脂溢性皮炎鉴别；应排除蠕形螨感染及长期外用激素诱因。\n1. 玫瑰痤疮（酒渣鼻）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n避免诱因、防晒及温和护肤；外用甲硝唑、壬二酸、伊维菌素或溴莫尼定，重症口服四环素类或异维A酸。\n\n【注意事项】\n需警惕长期外用糖皮质激素导致的激素依赖性皮炎，避免滥用。","资料来源":"皮肤病库 derm.json（条目「玫瑰痤疮（酒渣鼻）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2812,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"801d9332a58a5e5845394945bda167da2e35f95474b0fec8fc884e8027b9a1eb","pinyin":"meiguicuochuang（jiuzhabi）","initials":"mgcc（jzb）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-2553373edd9edeef4279","key":"v1-c9ccc21dfe2a3058|templates-2553373edd9edeef4279","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"白塞病（贝赫切特综合征）","category":"血管性","raw":{"name":"白塞病（贝赫切特综合征）","category":"血管性","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】溃疡疼痛明显，可伴发热、乏力、关节痛及视力下降等。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：溃疡疼痛明显，可伴发热、乏力、关节痛及视力下降等。。\n自觉症状：溃疡疼痛明显，可伴发热、乏力、关节痛及视力下降等。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：以复发性口腔阿弗他溃疡、生殖器溃疡、眼损害及皮肤损害为特征，皮肤可见结节性红斑样损害、毛囊炎样丘疹，针刺反应阳性。\n好发部位：累及口腔、生殖器黏膜及皮肤，可累及眼、关节、血管、消化道、神经系统等多系统。","辅助检查":"检查计划：患者有复发性口腔溃疡（1年内≥3次），伴溃疡疼痛、发热、乏力、关节痛及视力下降，需与其他血管炎、炎症性肠病及系统性红斑狼疮相鉴别。查血常规了解有无贫血、白细胞升高及血小板变化，评估炎症与感染状态；完善 C 反应蛋白及红细胞沉降率检查，评估全身炎症活动度，指导治疗方案制定；完善免疫球蛋白、补体 C3、C4 及抗核抗体谱检查，了解免疫状态，排除系统性红斑狼疮及其他自身免疫病；完善抗中性粒细胞胞质抗体（ANCA）检查，排除 ANCA 相关性血管炎；因患者有眼损害表现，完善眼科裂隙灯检查，明确有无葡萄膜炎及视网膜血管炎，评估眼部受累程度；完善针刺反应试验（同型反应），明确针刺反应是否阳性，作为诊断依据之一；查肝肾功能、电解质及血糖了解基础状况，排除肝肾功能不全及电解质紊乱所致乏力，为糖皮质激素及免疫抑制剂治疗提供依据；完善乙型肝炎、丙型肝炎、结核感染 T 细胞斑点试验及胸部影像学检查，排除潜伏感染，为免疫抑制治疗前的筛查提供依据；必要时完善 HLA-B51 检测了解遗传易感性；有血管及心脏受累表现者完善血管彩色多普勒超声及心脏彩超，明确血管、心脏受累情况；病情稳定后定期复查血常规、C 反应蛋白及红细胞沉降率。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据复发性口腔溃疡（1年内≥3次）加以下任2项：复发性生殖器溃疡、眼损害、皮肤损害、针刺反应阳性；需排除其他血管炎。\n1. 白塞病（贝赫切特综合征）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n对症及免疫调节治疗，患者秋水仙碱、糖皮质激素，重症累及眼或神经系统者用免疫抑制剂或生物制剂。\n\n【注意事项】\n眼、中枢神经及大血管受累者病情危重，应及时转专科治疗。","资料来源":"皮肤病库 derm.json（条目「白塞病（贝赫切特综合征）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2813,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bdffac8661cd702b834414d1f2f2efe5227a67a132bef902ed03cc4ee0b2ca25","pinyin":"baisaibing（beiheqietezonghezheng）","initials":"bsb（bhqtzhz）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-6e4f7fe49eff2ba3c7fe","key":"v1-c9ccc21dfe2a3058|templates-6e4f7fe49eff2ba3c7fe","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"皮肤淀粉样变（苔藓样淀粉样变）","category":"其他","raw":{"name":"皮肤淀粉样变（苔藓样淀粉样变）","category":"其他","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】剧烈瘙痒，长期搔抓致皮损增厚、色素沉着。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：剧烈瘙痒，长期搔抓致皮损增厚、色素沉着。。\n自觉症状：剧烈瘙痒，长期搔抓致皮损增厚、色素沉着。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：胫前、前臂伸侧对称分布的褐色、灰褐色坚实的半球形丘疹，密集排列呈苔藓样或串珠状，伴明显瘙痒及苔藓样变。\n好发部位：好发于双小腿胫前，其次为前臂伸侧、上背部。","辅助检查":"检查计划：患者胫前出现对称性褐色苔藓样丘疹，伴剧烈瘙痒，长期搔抓致皮损增厚及色素沉着，需与神经性皮炎、慢性湿疹及肥厚性扁平苔藓相鉴别。完善组织病理检查及刚果红染色、甲基紫染色，明确真皮乳头层有无淀粉样蛋白沉积，是确诊本病的关键依据；完善皮肤镜检查观察皮损表面及血管结构，评估皮损性质并指导活检取材部位；因瘙痒剧烈、长期搔抓，查血常规及 C 反应蛋白了解有无感染及炎症状态；查肝肾功能了解有无肝肾疾病，排除系统性淀粉样变所致脏器受累；查尿常规及尿蛋白定量，评估肾脏有无受累；查血糖及糖化血红蛋白，排除糖尿病所致皮肤瘙痒；完善血清蛋白电泳及免疫固定电泳检查，排除多发性骨髓瘤等浆细胞疾病所致系统性淀粉样变；完善甲状腺功能检查，排除甲状腺疾病所致皮肤改变及瘙痒；查电解质及凝血功能了解基础状况，为口服抗组胺药、外用糖皮质激素及必要时口服维 A 酸类药物提供依据；病情稳定后定期复查肝肾功能及尿蛋白，观察有无系统性受累。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据胫前对称性褐色苔藓样丘疹伴剧烈瘙痒，组织病理示真皮乳头层淀粉样蛋白沉积（刚果红染色、甲基紫染色阳性）。\n1. 皮肤淀粉样变（苔藓样淀粉样变）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n外用强效糖皮质激素、维A酸软膏，皮损内注射糖皮质激素，口服抗组胺药止痒，重者可光疗或激光。\n\n【注意事项】\n顽固性瘙痒需控制搔抓以防皮损加重；需与皮肤T细胞淋巴瘤等鉴别。","资料来源":"皮肤病库 derm.json（条目「皮肤淀粉样变（苔藓样淀粉样变）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2814,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"958fdaf1ffd27f1face8cba490a9e6f6cad6993d2401e199fd49399893817359","pinyin":"pifudianfenyangbian（taixianyangdianfenyangbian）","initials":"pfdfyb（txydfyb）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-33bf039b872ae189d6e5","key":"v1-c9ccc21dfe2a3058|templates-33bf039b872ae189d6e5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"皮肤纤维瘤（皮肤纤维组织细胞瘤）","category":"皮肤肿瘤","raw":{"name":"皮肤纤维瘤（皮肤纤维组织细胞瘤）","category":"皮肤肿瘤","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】一般无自觉症状，偶有瘙痒或压痛。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：一般无自觉症状，偶有瘙痒或压痛。。\n自觉症状：一般无自觉症状，偶有瘙痒或压痛。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：坚实丘疹或结节，直径多小于1cm，肤色、棕红或褐色，表面光滑，挤压时出现中央凹陷的酒窝征。\n好发部位：好发于四肢，尤其下肢。","辅助检查":"检查计划：患者皮损为坚实结节，一般无自觉症状，偶有瘙痒或压痛，需与恶性病变鉴别，入院后先行皮肤科专科查体与皮肤镜检查以了解结节边界、表面结构及有无色素网络、有无血管结构，判断是否具备良性皮肤纤维瘤的「酒窝征」特征；因本病需与黑色素瘤、隆突性皮肤纤维肉瘤鉴别，完善皮肤组织病理活检及免疫组化检查以明确诊断，免疫组化了解S-100、HMB-45、CD34、FXⅢa等表达情况以鉴别黑素细胞来源及隆突性皮肤纤维肉瘤；患者偶有瘙痒、压痛提示局部炎症反应，完善血常规及CRP检查以排除继发感染、了解炎症程度；考虑手术切除为主要治疗手段，术前完善凝血功能、肝肾功能、血糖及心电图检查以评估手术耐受性、排除凝血功能异常及重要脏器功能不全；若病理提示切除范围不足或细胞增生活跃，酌情完善局部影像学检查评估病变深度、明确有无深部组织受累；术后按病理结果制定随访方案，定期复查皮损及手术区域，观察有无复发。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据坚实结节及酒窝征诊断，可疑者需与黑色素瘤、隆突性皮肤纤维肉瘤鉴别，必要时活检。\n1. 皮肤纤维瘤（皮肤纤维组织细胞瘤）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n无需治疗，美容或诊断不明者行手术切除并病理检查。\n\n【注意事项】\n皮损迅速增大、出血或深部固定需警惕隆突性皮肤纤维肉瘤并转诊。","资料来源":"皮肤病库 derm.json（条目「皮肤纤维瘤（皮肤纤维组织细胞瘤）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2815,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c460dc5e622d060ab0596b2d8df08fd8dd63cb48cfe622005315b630c9a4a017","pinyin":"pifuxianweiliu（pifuxianweizuzhixibaoliu）","initials":"pfxwl（pfxwzzxbl）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-259b1a63a26ad292861c","key":"v1-c9ccc21dfe2a3058|templates-259b1a63a26ad292861c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"皮肤结核","category":"细菌性","raw":{"name":"皮肤结核","category":"细菌性","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】多无明显自觉症状，溃疡或继发感染时可疼痛。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：多无明显自觉症状，溃疡或继发感染时可疼痛。。\n自觉症状：多无明显自觉症状，溃疡或继发感染时可疼痛。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：皮损形态多样，常见寻常狼疮（红褐色结节/斑块、玻片压诊呈“苹果酱色”）、疣状皮肤结核、瘰疬性皮肤结核等，可破溃形成溃疡、瘢痕。\n好发部位：好发于面颈、四肢暴露部位及淋巴结引流区，因类型而异。","辅助检查":"检查计划：患者皮损慢性病程、多无明显自觉症状，溃疡或继发感染时疼痛，临床考虑皮肤结核，需先明确结核感染状态，入院后完善结核菌素试验（PPD）及γ干扰素释放试验（T-SPOT.TB）以明确有无结核感染；因皮肤结核多继发于体内其他脏器结核，完善胸部X线片或胸部CT检查以了解有无肺结核及纵隔淋巴结结核，明确原发灶；完善皮肤组织病理活检及抗酸染色检查以明确诊断，病理见结核样肉芽肿、抗酸染色阳性支持本病，必要时加做结核分枝杆菌PCR检测以提高病原学检出率；溃疡或继发感染者，完善分泌物细菌培养及药敏、真菌镜检以排除继发细菌或真菌感染，完善血常规及CRP检查以评估感染程度、排除其他感染性疾病所致皮损；抗结核治疗前完善肝肾功能、血常规、凝血功能及心电图检查以评估用药安全性、排除抗结核药物禁忌；病程中定期复查肝肾功能、血常规及尿酸以监测抗结核药物不良反应，定期复查胸部影像学及皮损变化以评估疗效。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据慢性病程、典型皮损、结核菌素试验（PPD）阳性及病理见结核样肉芽肿、抗酸染色或PCR检测确诊。\n1. 皮肤结核","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n采用标准抗结核联合化疗方案（异烟肼、利福平、吡嗪酰胺、乙胺丁醇等），疗程6~12个月。\n\n【注意事项】\n需排查内脏结核并规范全程抗结核治疗，注意药物肝损伤等副作用，具传染性者隔离。","资料来源":"皮肤病库 derm.json（条目「皮肤结核」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2816,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d4fd7fcab56f8b9416be02df76ab22350523bbdd3c3004bc53a5b7145f8de4cb","pinyin":"pifujiehe","initials":"pfjh","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-3b75c77ef683a70806d4","key":"v1-c9ccc21dfe2a3058|templates-3b75c77ef683a70806d4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"皮脂腺痣（先天性皮脂腺痣）","category":"皮肤肿瘤","raw":{"name":"皮脂腺痣（先天性皮脂腺痣）","category":"皮肤肿瘤","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】一般无自觉症状。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：一般无自觉症状。。\n自觉症状：一般无自觉症状。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：出生即有或幼年出现的境界清楚的淡黄色、蜡样或疣状斑块，表面无毛发，可呈带状、线状排列。\n好发部位：好发于头皮、面部、颈部。","辅助检查":"检查计划：患者皮损为出生即有的淡黄色疣状无发斑块，一般无自觉症状，青春期后需警惕继发肿瘤，入院后完善皮肤科专科查体与皮肤镜检查以了解斑块边界、表面结构及有无继发结节，评估有无基底细胞癌、毛母细胞瘤等继发肿瘤征象；必要时完善皮肤组织病理活检及免疫组化检查以明确诊断，了解有无毛囊皮脂腺结构异常及继发肿瘤成分；因本病属先天性发育异常，可合并神经系统及眼部异常，完善头颅MRI检查以明确有无脑部发育异常及颅内病变，完善眼科检查以排除眼睑、结膜及眼球结构异常；考虑手术切除为主要治疗方式，术前完善凝血功能、肝肾功能、血常规、血糖及心电图检查以评估手术耐受性、排除凝血功能障碍；病变范围较大或位于特殊部位者，完善局部超声或MRI检查以了解病变深度、明确有无深部组织受累，指导手术方案；术后定期复查，观察有无复发及瘢痕情况。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据出生即有的淡黄色疣状无发斑块诊断，必要时活检，青春期后需警惕继发肿瘤（如基底细胞癌、毛母细胞瘤）。\n1. 皮脂腺痣（先天性皮脂腺痣）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n可于青春期前（儿童期）手术完整切除以防恶变或美容。\n\n【注意事项】\n青春期后皮损出现结节、溃疡需警惕继发肿瘤并活检，建议择期手术切除。","资料来源":"皮肤病库 derm.json（条目「皮脂腺痣（先天性皮脂腺痣）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2817,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e62857fee8c04697c862a1ddc462c38203bda24ac11bd53f7e18495de00e5d94","pinyin":"pizhixianzhi（xiantianxingpizhixianzhi）","initials":"pzxz（xtxpzxz）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-aac2b960592a60efb900","key":"v1-c9ccc21dfe2a3058|templates-aac2b960592a60efb900","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"盘状红斑狼疮（慢性皮肤型红斑狼疮）","category":"结缔组织病","raw":{"name":"盘状红斑狼疮（慢性皮肤型红斑狼疮）","category":"结缔组织病","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】可有瘙痒、灼热感或无症状，日晒加重。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：可有瘙痒、灼热感或无症状，日晒加重。。\n自觉症状：可有瘙痒、灼热感或无症状，日晒加重。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：境界清楚的红色斑块，表面黏着性鳞屑及毛囊角栓，后期中央萎缩、色素减退，周边色素沉着，可留瘢痕。\n好发部位：好发于面颊、鼻背、耳廓、头皮等曝光部位。","辅助检查":"检查计划：患者皮损可有瘙痒、灼热感，日晒后加重，临床考虑盘状红斑狼疮，需明确诊断并评估有无系统受累，入院后完善皮肤组织病理活检及直接免疫荧光（狼疮带试验）检查以明确诊断，了解表皮基底细胞液化变性、毛囊角栓及真皮浅层免疫复合物沉积情况；完善抗核抗体（ANA）及抗核抗体谱、抗dsDNA抗体、抗Ro/SSA与抗La/SSB抗体检查以明确有无系统受累、鉴别系统性红斑狼疮；完善血常规、尿常规、肾功能及补体C3、C4检查以了解有无血液系统、肾脏受累及免疫复合物消耗；患者日晒加重提示光敏，完善光敏试验及皮肤镜检查以了解光敏程度、评估皮损活动性；完善血沉、CRP及免疫球蛋白检查以评估疾病活动度、指导治疗强度；长期氯喹或羟氯喹治疗者，定期复查眼科检查（视力、眼底及视野）以排除药物性视网膜病变，定期复查血常规、肝肾功能以监测药物不良反应；皮损广泛或伴系统症状时，完善胸部影像学及心脏超声检查以排除心肺受累。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据盘状红斑、毛囊角栓、萎缩瘢痕及好发部位诊断，行皮肤病理、直接免疫荧光（狼疮带试验）及抗核抗体等检查。\n1. 盘状红斑狼疮（慢性皮肤型红斑狼疮）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n严格防晒，外用强效糖皮质激素或钙调磷酸酶抑制剂，皮损内注射，口服羟氯喹。\n\n【注意事项】\n部分可转为系统性红斑狼疮，出现发热、关节痛、蛋白尿等系统症状需及时风湿免疫科评估。","资料来源":"皮肤病库 derm.json（条目「盘状红斑狼疮（慢性皮肤型红斑狼疮）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2818,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"009f22278bc449349f4fad5f93b75203378d197f25b7cb1c1f77b0ca60b1c258","pinyin":"panzhuanghongbanlangchuang（manxingpifuxinghongbanlangchuang）","initials":"pzhblc（mxpfxhblc）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-0ee59d09e411ed87aeae","key":"v1-c9ccc21dfe2a3058|templates-0ee59d09e411ed87aeae","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"神经性皮炎（慢性单纯性苔藓）","category":"湿疹皮炎类","raw":{"name":"神经性皮炎（慢性单纯性苔藓）","category":"湿疹皮炎类","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】阵发性剧烈瘙痒，搔抓后加重。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：阵发性剧烈瘙痒，搔抓后加重。。\n自觉症状：阵发性剧烈瘙痒，搔抓后加重。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：皮肤苔藓样变，皮纹加深、皮嵴隆起，多角形扁平丘疹融合成斑块，表面干燥、可有鳞屑。\n好发部位：好发于颈项、肘部、骶尾部、眼睑、踝部等易摩擦部位。","辅助检查":"检查计划：患者阵发性剧烈瘙痒、搔抓后加重，皮损呈苔藓样变，临床诊断神经性皮炎，但需排除系统性疾病及其他皮肤病所致瘙痒，入院后完善血常规、CRP检查以排除感染、了解有无嗜酸性粒细胞升高；因瘙痒可为多种内科疾病的首发表现，完善空腹血糖及糖化血红蛋白检查以排除糖尿病所致瘙痒，完善肝功能、肾功能、电解质及胆汁酸检查以排除肝胆疾病、尿毒症所致瘙痒，完善甲状腺功能检查以排除甲状腺功能异常所致瘙痒；完善皮肤镜检查以了解皮纹加深、皮嵴隆起等苔藓样变特征，评估搔抓所致继发改变；需与慢性湿疹、扁平苔藓鉴别，必要时完善皮肤组织病理活检以明确诊断、排除扁平苔藓；考虑过敏因素参与，必要时完善过敏原检测（血清特异性IgE）以明确可疑致敏原、指导回避；搔抓致皮损破溃或继发感染者，完善分泌物细菌培养及药敏检查以明确病原菌、指导抗感染治疗；病程中定期复查，观察皮损消退及复发情况。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据苔藓样变斑块、好发部位及搔抓史诊断，需与慢性湿疹、扁平苔藓鉴别。\n1. 神经性皮炎（慢性单纯性苔藓）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n打破瘙痒-搔抓循环。外用糖皮质激素按部位选择强度：眼睑、面部、颈前、皱褶部位须用弱效或中效激素，或钙调磷酸酶抑制剂（他克莫司/吡美莫司）；躯干四肢可用中强效。眼周禁用强效激素（可致皮肤萎缩、青光眼、白内障）。必要时封包或皮损内注射（封包禁用于感染部位）。\n\n【注意事项】\n避免搔抓、摩擦及精神紧张，顽固泛发者需转诊。","资料来源":"皮肤病库 derm.json（条目「神经性皮炎（慢性单纯性苔藓）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2819,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8e969d6eb60e88ce2870b321e9cf000599c3b754285956c45bceea32f8426838","pinyin":"shenjingxingpiyan（manxingdanchunxingtaixian）","initials":"sjxpy（mxdcxtx）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-e532562d45f6f01c4726","key":"v1-c9ccc21dfe2a3058|templates-e532562d45f6f01c4726","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"红癣","category":"细菌性","raw":{"name":"红癣","category":"细菌性","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】多无自觉症状或仅有轻微瘙痒。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：多无自觉症状或仅有轻微瘙痒。。\n自觉症状：多无自觉症状或仅有轻微瘙痒。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：境界清楚的红褐色或棕红色斑片，表面覆有细糠秕样鳞屑，边缘不规则，可缓慢扩展。\n好发部位：好发于腹股沟、腋窝、趾间、乳房下等潮湿皱褶部位。","辅助检查":"检查计划：患者皱褶部位出现红褐色斑片，多无自觉症状或仅有轻微瘙痒，临床考虑红癣，需与股癣等浅部真菌病鉴别，入院后完善Wood灯检查以明确诊断，Wood灯下呈珊瑚红色荧光支持微小棒状杆菌所致红癣；需与股癣鉴别，完善皮损边缘鳞屑真菌镜检及真菌培养检查以排除皮肤癣菌感染，真菌镜检阴性支持红癣诊断；必要时完善皮损分泌物细菌培养及革兰染色检查以明确病原菌、了解有无合并其他细菌感染；因红癣多见于糖尿病及肥胖人群，完善空腹血糖、餐后2小时血糖及糖化血红蛋白检查以排除糖尿病、明确易感因素，完善血脂及肝肾功能检查以评估代谢状况、指导治疗；患者皮损面积较大或反复发作者，完善血常规及CRP检查以排除继发细菌感染、了解炎症程度；合并糖尿病者，完善尿常规及尿微量白蛋白检查以了解有无肾脏受累；治疗期间定期复查皮损及Wood灯检查以评估疗效、判断病原学是否清除。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据皱褶部位红褐色斑片，Wood灯下呈珊瑚红色荧光可确诊，需与股癣鉴别（真菌镜检阴性）。\n1. 红癣","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n外用红霉素、克林霉素或夫西地酸等抗生素，也可口服红霉素、四环素。\n\n【注意事项】\n由微细棒状杆菌引起，易复发，注意局部清洁干燥；与真菌感染鉴别，避免误用抗真菌药。","资料来源":"皮肤病库 derm.json（条目「红癣」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2820,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b5068350352d6313a0c703d8d8091da95c9231aa5bab230cb8d4b9f1ec279460","pinyin":"hongxuan","initials":"hx","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-01a51279ae966af1a207","key":"v1-c9ccc21dfe2a3058|templates-01a51279ae966af1a207","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"红皮病（剥脱性皮炎）","category":"其他","raw":{"name":"红皮病（剥脱性皮炎）","category":"其他","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】自觉瘙痒、灼热、疼痛，可伴发热、畏寒、乏力等全身症状。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：自觉瘙痒、灼热、疼痛，可伴发热、畏寒、乏力等全身症状。。\n自觉症状：自觉瘙痒、灼热、疼痛，可伴发热、畏寒、乏力等全身症状。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：全身皮肤弥漫性潮红、肿胀、浸润及脱屑，皮损面积超过体表面积90%，可伴掌跖角化、甲改变及脱发。\n好发部位：全身弥漫分布，从头面至躯干四肢。","辅助检查":"检查计划：患者全身皮肤弥漫性潮红脱屑，面积超过90%体表面积，伴瘙痒、灼热、疼痛及发热、畏寒、乏力等全身症状，病情重、需尽快查找原发病，入院后急诊完善血常规、CRP及降钙素原检查以排除感染、药疹所致红皮病，了解有无嗜酸性粒细胞及白细胞异常；完善肝肾功能、电解质、血糖及白蛋白、前白蛋白检查以了解大面积脱屑所致水电解质紊乱、低蛋白血症及脏器功能受损情况，指导补液与营养支持；红皮病需查找原发病如银屑病、湿疹、药疹、淋巴瘤等，完善皮肤组织病理活检及免疫组化检查以明确诊断、鉴别皮肤T细胞淋巴瘤；考虑淋巴瘤所致者，完善淋巴结超声、胸腹部CT及骨髓穿刺+活检检查以明确有无血液系统受累、明确分期；完善心电图及心脏超声检查以评估有无高排血量心力衰竭，完善血培养及分泌物培养检查以排除败血症；治疗期间定期复查血常规、肝肾功能、电解质及白蛋白以监测病情变化及药物不良反应，定期复查皮损面积及体温，评估疗效。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据全身皮肤弥漫性潮红脱屑（超过90%体表面积），需查找原发病如银屑病、湿疹、药疹、淋巴瘤等。\n1. 红皮病（剥脱性皮炎）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n寻找并治疗原发病，加强支持治疗、补液、纠正电解质紊乱，外用温和润肤剂，系统用药根据病因选择。\n\n【注意事项】\n红皮病病情危重，可出现低体温、高排量心衰、感染等，应住院治疗。","资料来源":"皮肤病库 derm.json（条目「红皮病（剥脱性皮炎）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2821,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5ac3d64358dbc410f5cc09de936d8ec1b5013e8c7698d64fc66bbecf3636dab8","pinyin":"hongpibing（baotuoxingpiyan）","initials":"hpb（btxpy）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-da716b3dba2bd179aa8c","key":"v1-c9ccc21dfe2a3058|templates-da716b3dba2bd179aa8c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"结节性痒疹（结节性苔藓）","category":"湿疹皮炎类","raw":{"name":"结节性痒疹（结节性苔藓）","category":"湿疹皮炎类","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】剧烈瘙痒，顽固难忍。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：剧烈瘙痒，顽固难忍。。\n自觉症状：剧烈瘙痒，顽固难忍。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：坚实半球形或疣状结节，表面角化、粗糙，呈肤色、淡红或褐色，常对称散在。\n好发部位：好发于四肢伸侧、腰背，尤以下肢胫前多见。","辅助检查":"检查计划：患者剧烈瘙痒、顽固难忍，皮损为坚实结节，伴长期搔抓史，临床考虑结节性痒疹，但需排除系统性疾病及其他皮肤病所致瘙痒与结节，入院后完善血常规、CRP及嗜酸性粒细胞计数检查以排除感染、了解过敏性炎症程度；因顽固性瘙痒常与内科疾病相关，完善空腹血糖及糖化血红蛋白检查以排除糖尿病所致瘙痒，完善肝功能、肾功能、电解质及胆汁酸检查以排除肝胆疾病、尿毒症所致瘙痒，完善甲状腺功能检查以排除甲状腺功能异常；完善皮肤镜检查以了解结节表面结构、有无血管及角化改变，评估搔抓所致继发改变；需与扁平苔藓、结节型类天疱疮鉴别，完善皮肤组织病理活检及直接免疫荧光检查以明确诊断、排除类天疱疮，完善血清抗BP180及抗BP230抗体检查以进一步排除大疱性类天疱疮；结节破溃或继发感染者，完善分泌物细菌培养及药敏检查以明确病原菌、指导抗感染治疗；病程中定期复查皮损及瘙痒评分，评估疗效并观察复发。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据瘙痒性坚实结节、好发部位及长期搔抓史诊断，需与扁平苔藓、结节型类天疱疮鉴别。\n1. 结节性痒疹（结节性苔藓）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n外用超强效糖皮质激素、钙调磷酸酶抑制剂或皮损内注射，配合口服抗组胺药、加巴喷丁等止痒。\n\n【注意事项】\n顽固者需排除肝肾功能不全、血液病等系统性疾病并转诊。","资料来源":"皮肤病库 derm.json（条目「结节性痒疹（结节性苔藓）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2822,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6ba93f95c247574103a2a7f5ea080f242ee2b8aab7a68fc9953a5cf4108e306a","pinyin":"jiejiexingyangzhen（jiejiexingtaixian）","initials":"jjxyz（jjxtx）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-df973245e419d6c17b9c","key":"v1-c9ccc21dfe2a3058|templates-df973245e419d6c17b9c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胼胝（老茧）","category":"物理性","raw":{"name":"胼胝（老茧）","category":"物理性","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】多无自觉症状，重者可有压迫感或轻微疼痛。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：多无自觉症状，重者可有压迫感或轻微疼痛。。\n自觉症状：多无自觉症状，重者可有压迫感或轻微疼痛。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：境界不清的局限性角质增厚斑块，蜡黄色、扁平或稍隆起，质硬，表面光滑，无角质核。\n好发部位：好发于手掌、足跖等长期受压摩擦部位。","辅助检查":"检查计划：患者因长期摩擦受压，手足部出现境界不清的弥漫性角质增厚、无角质核及压痛，初步诊断胼胝，需先排除其他角化性皮肤病并评估反复受压的基础病因。查血常规了解有无继发感染所致白细胞及中性粒细胞升高；查空腹血糖及糖化血红蛋白，因糖尿病周围神经病变与足部畸形是胼胝反复发生、久治不愈的常见基础病，明确有无糖代谢异常以指导病因干预和足部护理；完善真菌直接镜检（必要时真菌培养）排除足癣等真菌感染导致的角化过度，因足癣与胼胝常并存而处理原则不同；对增厚明显、表面粗糙或见出血点者，完善皮肤镜检查以了解角质增厚方式及有无点状血管，鉴别跖疣等需鉴别的疾病；对皮损不对称、短期增大或诊断存疑者，完善皮肤组织病理活检明确有无其他角化性皮肤病或恶变；因需长期外用角质剥脱剂（如水杨酸软膏），查肝肾功能评估用药安全性；对合并足部畸形、疼痛明显者，查足部X线了解有无骨刺、跖骨异常，评估是否需要矫形治疗；对久治不愈者查下肢血管彩超了解下肢动脉供血情况，排除缺血因素影响愈合。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据长期摩擦受压史、境界不清的弥漫性角质增厚而无角质核及压痛，即可诊断。\n1. 胼胝（老茧）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n去除摩擦受压因素；外用角质软化剂（尿素、水杨酸），必要时削除增厚角质。\n\n【注意事项】与鸡眼鉴别：胼胝境界不清、无角质核、疼痛轻；注意职业防护。","资料来源":"皮肤病库 derm.json（条目「胼胝（老茧）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2823,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ff526beadd73b6709836d0b72403be91b9ab10beed6687ddca694b7f4a91df08","pinyin":"pianzhi（laojian）","initials":"pz（lj）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-3445dd0a61d04e31fc33","key":"v1-c9ccc21dfe2a3058|templates-3445dd0a61d04e31fc33","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脂溢性角化（老年疣、基底细胞乳头状瘤）","category":"皮肤肿瘤","raw":{"name":"脂溢性角化（老年疣、基底细胞乳头状瘤）","category":"皮肤肿瘤","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】一般无自觉症状，偶有瘙痒或刺激感。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：一般无自觉症状，偶有瘙痒或刺激感。。\n自觉症状：一般无自觉症状，偶有瘙痒或刺激感。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：圆形或椭圆形、境界清楚的疣状或乳头状斑块，表面呈粘着样油腻性鳞屑或角化，颜色淡黄至深褐甚至黑色。\n好发部位：好发于面、颈、躯干、手背等部位，中老年人多见。","辅助检查":"检查计划：患者为中老年，于面部、躯干出现粘着样表面及疣状外观的色素性皮损，初步诊断脂溢性角化，但需与黑色素瘤、色素性基底细胞癌等鉴别。完善皮肤镜检查以了解有无粉刺样开口、粟粒样囊肿及脑回样结构等特征性表现，明确诊断并鉴别色素性基底细胞癌及黑素瘤；对色素不均、边界不清、近期增大或出血者，完善皮肤组织病理活检明确有无恶变或黑色素瘤，此为确诊金标准；查血常规、肝肾功能及凝血功能评估一般状况与手术耐受性，为活检或激光、冷冻治疗做准备；因本病多为良性，若皮损多发且短期内显著增多，需警惕Leser-Trélat征，查肿瘤标志物（CEA、CA19-9等）并完善胸部CT、腹部超声排查有无合并内脏恶性肿瘤；患者老年，查心电图了解心脏基础情况，评估治疗耐受性；合并糖尿病等基础病者查空腹血糖、糖化血红蛋白，因糖代谢异常影响创面愈合；对拟行手术切除者，术前完善乙肝、丙肝、梅毒、HIV等感染性指标筛查。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据特征性粘着样表面及疣状外观诊断，可疑者需与黑色素瘤、色素性基底细胞癌鉴别，必要时皮肤镜或活检。\n1. 脂溢性角化（老年疣、基底细胞乳头状瘤）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n无需治疗，出于美容或反复刺激可行冷冻、激光、电灼或刮除。\n\n【注意事项】\n皮损短期内增多增大需警惕Leser-Trélat征及内脏肿瘤，突然恶变表现需活检。","资料来源":"皮肤病库 derm.json（条目「脂溢性角化（老年疣、基底细胞乳头状瘤）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2824,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2ee371cfd5e27d49e404dbdc83aa16367f6d8530f977b331d653c56067cdcaa4","pinyin":"zhiyixingjiaohua（laonianyou、jidixibaorutouzhuangliu）","initials":"zyxjh（lny、jdxbrtzl）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-c03ceaf4493ccb6ddc18","key":"v1-c9ccc21dfe2a3058|templates-c03ceaf4493ccb6ddc18","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脓疱疮（黄水疮）","category":"细菌性","raw":{"name":"脓疱疮（黄水疮）","category":"细菌性","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】轻度瘙痒；可伴低热。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：轻度瘙痒；可伴低热。\n自觉症状：轻度瘙痒；可伴低热。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：红斑上薄壁脓疱，破溃后结蜜黄色厚痂\n好发部位：口周、鼻周、四肢暴露部位（儿童多见）","辅助检查":"检查计划：患儿夏秋季节发病，面部及口周出现典型蜜黄色痂，伴轻度瘙痒及低热，初步诊断脓疱疮（金黄色葡萄球菌或链球菌感染）。查血常规、CRP及降钙素原了解感染严重程度及有无全身炎症反应，评估是否需要系统抗感染治疗；完善脓液或疱液细菌培养加药物敏感试验，明确致病菌并指导抗生素选择，尤其对反复发作或治疗反应不佳者；查尿常规及抗链球菌溶血素O、补体C3，因A组β溶血性链球菌感染后可继发急性肾小球肾炎，需定期复查尿常规明确有无血尿、蛋白尿；查肝肾功能及电解质评估系统用药安全性，因需口服或静脉抗生素治疗；伴低热不退者完善血培养排除菌血症；查空腹血糖排除糖尿病等易感因素，因糖代谢异常易致皮肤感染反复；对皮损泛发、脓疱融合或发热持续者，完善胸部X线或CT排除肺部感染等并发症；对疑似葡萄球菌性烫伤样皮肤综合征者，复查电解质及肾功能评估有无水电解质紊乱；病情稳定后定期复查尿常规，观察有无感染后肾小球肾炎的迟发表现。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：典型蜜黄色痂+儿童+夏秋季节；金葡菌/链球菌感染\n1. 脓疱疮（黄水疮）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n外用莫匹罗星/夫西地酸；广泛者口服抗生素\n\n【注意事项】\n传染性强，注意隔离；防止抓挠扩散；肾炎型链球菌感染需查尿","资料来源":"皮肤病库 derm.json（条目「脓疱疮（黄水疮）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2825,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a5b2b8ea3a208c493c39011e5a78a84ff217dd48089be6e1e3f2c3a8a716f4d6","pinyin":"nongpaochuang（huangshuichuang）","initials":"npc（hsc）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-1dc8639bb595cf360f0e","key":"v1-c9ccc21dfe2a3058|templates-1dc8639bb595cf360f0e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腋臭（狐臭）","category":"附属器疾病","raw":{"name":"腋臭（狐臭）","category":"附属器疾病","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】自觉腋下异味，夏季或出汗后加重，影响社交。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：自觉腋下异味，夏季或出汗后加重，影响社交。。\n自觉症状：自觉腋下异味，夏季或出汗后加重，影响社交。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：腋窝大汗腺分泌的汗液被细菌分解产生特殊臭味，皮肤外观多正常或伴多汗。\n好发部位：好发于腋窝，可伴外阴、肛周等部位。","辅助检查":"检查计划：患者青春期后出现腋下特殊异味，夏季或出汗后加重，影响社交，常有家族史，初步诊断腋臭，需与腋窝毛囊炎、真菌感染等继发性异味鉴别。完善腋窝皮肤专科检查及皮肤镜检查，了解毛囊及顶泌汗腺分布与病情分级，评估适合外用止汗剂、肉毒素注射还是手术治疗；查血常规、凝血功能及肝肾功能，评估手术或局部注射治疗的耐受性与安全性；完善腋窝真菌镜检及伍德灯检查，排除腋窝真菌感染、红癣所致继发性异味；因部分患者合并多汗症，查甲状腺功能排除甲状腺功能亢进等内分泌疾病引起的多汗与异味加重；查空腹血糖排除糖尿病，因糖代谢异常易合并皮肤感染并使异味加重；对拟行微创顶泌汗腺清除术者，术前完善心电图及乙肝、丙肝、梅毒、HIV感染性指标筛查；女性患者术前查妊娠试验排除妊娠后再安排治疗；对伴腋窝毛囊炎者查血常规及CRP，了解有无继发细菌感染并指导抗感染处理。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据腋窝特殊臭味、常有家族史、青春期后明显，需与腋窝毛囊炎、真菌感染等继发性异味鉴别。\n1. 腋臭（狐臭）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n注意清洁、外用抗菌止汗剂；轻中度可局部注射肉毒素，重者可选择激光、微波或手术切除大汗腺。\n\n【注意事项】\n手术需到正规医疗机构，注意术后血肿、感染及瘢痕等风险。","资料来源":"皮肤病库 derm.json（条目「腋臭（狐臭）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2826,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5107ee4b1d8e7ad8e8cff202b538d9b33d716bc7c82f7a4f86ba7381a1a851d1","pinyin":"yechou（huchou）","initials":"yc（hc）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-4ef26a20e668cd9c3dda","key":"v1-c9ccc21dfe2a3058|templates-4ef26a20e668cd9c3dda","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"色素痣（黑素细胞痣、痣细胞痣）","category":"皮肤肿瘤","raw":{"name":"色素痣（黑素细胞痣、痣细胞痣）","category":"皮肤肿瘤","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】一般无自觉症状。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：一般无自觉症状。。\n自觉症状：一般无自觉症状。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：斑疹、丘疹或结节，颜色从肤色、棕褐色到黑色，形态可平坦、隆起、乳头状，可有毛发生长，境界清楚。\n好发部位：可发生于全身任何部位皮肤及黏膜。","辅助检查":"检查计划：患者皮损为典型色素性皮损，初步诊断色素痣，需按ABCDE法则评估并重点鉴别恶性黑色素瘤。完善皮肤镜检查了解色素分布模式、有无非典型网络及蓝白幕等结构，明确诊断并评估恶变风险；对皮损不对称、边界不规则、颜色不均、直径大于6mm或近期增大、瘙痒、出血者，完善皮肤组织病理活检加免疫组化（S-100、HMB-45、Melan-A）明确有无恶变，此为确诊金标准；对多发性色素痣或伴非典型痣者，完善全身皮肤检查及皮肤镜随访，评估有无发育不良痣综合征；对疑似黑色素瘤者，查肿瘤标志物S-100、LDH并完善区域淋巴结超声、胸部CT及腹部超声，了解有无淋巴结及远处转移，明确分期以指导治疗；查血常规、肝肾功能及凝血功能评估手术耐受性；需手术切除者术前完善心电图及乙肝、丙肝、梅毒、HIV筛查；对无需手术者定期复查皮肤镜，观察皮损有无形态动态演变。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据典型色素性皮损诊断，可疑者用ABCDE法则、皮肤镜及活检鉴别恶性黑色素瘤。\n1. 色素痣（黑素细胞痣、痣细胞痣）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n多数无需治疗，出于美容、易摩擦部位或可疑恶变者行手术完整切除并病理检查。\n\n【注意事项】\n痣短期内增大、颜色不均、出血破溃或不对称需及时就医排除恶变。","资料来源":"皮肤病库 derm.json（条目「色素痣（黑素细胞痣、痣细胞痣）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2827,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a46be53a255c161a0ddec31e2057ed2823df4e82fc82e5beec3743cc00bc8d64","pinyin":"sesuzhi（heisuxibaozhi、zhixibaozhi）","initials":"ssz（hsxbz、zxbz）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-e10c2f999096d283a249","key":"v1-c9ccc21dfe2a3058|templates-e10c2f999096d283a249","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"花斑癣（汗斑）","category":"真菌性","raw":{"name":"花斑癣（汗斑）","category":"真菌性","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】一般无自觉症状或有轻微瘙痒，出汗时明显。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：一般无自觉症状或有轻微瘙痒，出汗时明显。。\n自觉症状：一般无自觉症状或有轻微瘙痒，出汗时明显。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：躯干上部出现圆形或不规则形淡白、淡褐或淡红色斑片，表面覆有细小糠秕状鳞屑，可融合成片。\n好发部位：好发于胸背、颈、肩、上臂等多汗、皮脂丰富部位。","辅助检查":"检查计划：患者多汗部位出现色素减退或加深斑伴细鳞屑，出汗时瘙痒明显，初步诊断花斑癣（马拉色菌感染）。完善真菌直接镜检（10%氢氧化钾涂片）了解有无短粗菌丝和成簇孢子，明确诊断；查伍德灯了解皮损有无淡黄色或黄褐色荧光，评估感染范围并用于疗效随访；对镜检阴性而临床高度可疑者，完善真菌培养或皮肤镜检查（见飞溅样色素及鳞屑），进一步明确诊断；对皮损广泛、反复发作或治疗反应不佳者，查空腹血糖、糖化血红蛋白及免疫相关指标（必要时HIV筛查），排除糖尿病、免疫抑制等易感因素；因本病易复发、可能需口服抗真菌药，查肝肾功能评估长期用药（如伊曲康唑）的安全性；查血常规了解有无继发感染；对伴多汗者查甲状腺功能，排除甲状腺功能亢进等内分泌疾病所致的多汗；对色素异常需与白色糠疹、白癜风鉴别者，完善伍德灯及皮肤镜检查鉴别，必要时行皮肤组织病理活检加PAS染色明确诊断。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据多汗部位色素减退或加深斑伴细鳞屑，Wood灯呈淡黄/黄褐色荧光，真菌镜检见短粗菌丝和成簇孢子确诊。\n1. 花斑癣（汗斑）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n外用酮康唑、咪康唑洗剂或联苯苄唑等抗真菌制剂，泛发者可口服伊曲康唑或氟康唑。\n\n【注意事项】\n易复发，注意保持皮肤干燥、勤换衣物；色素减退恢复较慢，需向患者说明。","资料来源":"皮肤病库 derm.json（条目「花斑癣（汗斑）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2828,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"16d6463762b1594b67c059944a6350c4d13f87c3f51be0021fc473600bba2acc","pinyin":"huabanxuan（hanban）","initials":"hbx（hb）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-bf87949755f54d6c4020","key":"v1-c9ccc21dfe2a3058|templates-bf87949755f54d6c4020","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"荨麻疹（风团）","category":"反应性","raw":{"name":"荨麻疹（风团）","category":"反应性","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】剧烈瘙痒。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：剧烈瘙痒。\n自觉症状：剧烈瘙痒。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：风团（暂时性隆起的红斑性皮损），大小形态不一，24小时内消退不留痕迹\n好发部位：全身均可发生；黏膜（唇、眼睑）水肿","辅助检查":"检查计划：患者反复出现风团伴剧烈瘙痒，皮疹24小时内消退，初步诊断荨麻疹，需明确诱因并排除系统性疾病所致的皮肤表现。查血常规及CRP排除感染所致，因急性荨麻疹常与病毒或细菌感染相关；查过敏原特异性IgE及总IgE了解有无食物、吸入物过敏，指导过敏原回避与饮食管理；对病程超过6周的慢性荨麻疹，完善甲状腺功能及甲状腺自身抗体、抗核抗体谱、幽门螺杆菌检测，排除甲状腺自身免疫病、结缔组织病及幽门螺杆菌感染等常见诱因；查肝肾功能及电解质，评估抗组胺药及其他系统用药的安全性；查凝血功能及D-二聚体了解有无凝血系统激活，因部分重症荨麻疹与补体、凝血系统激活相关；对伴血管性水肿、呼吸困难或血压下降者，急诊完善心电图、心肌酶及指脉氧监测，排除过敏性休克及心肌损伤，必要时查补体C3、C4及C1抑制物排除遗传性血管性水肿；对反复发作者查粪便寄生虫卵，排除寄生虫感染诱因。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：风团+24h内消退+反复发作（>6周为慢性）；过敏原/感染/物理诱因\n1. 荨麻疹（风团）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n抗组胺药（首选）；急性重症伴呼吸困难按过敏性休克处理；慢性者寻找病因\n\n【注意事项】\n喉头水肿/呼吸困难是急症（立即就医）；慢性荨麻疹多数无明确过敏原","资料来源":"皮肤病库 derm.json（条目「荨麻疹（风团）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2829,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ad541125df62ab540244d55062e16e805db242b8822a30048509b6687eacbd56","pinyin":"xunmazhen（fengtuan）","initials":"xmz（ft）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-30d5580b85cc05a13e60","key":"v1-c9ccc21dfe2a3058|templates-30d5580b85cc05a13e60","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"药疹（药物性皮炎）","category":"反应性","raw":{"name":"药疹（药物性皮炎）","category":"反应性","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】瘙痒；重症发热。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：瘙痒；重症发热。\n自觉症状：瘙痒；重症发热。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：形态多样：麻疹样红斑、荨麻疹、固定性药疹（紫红斑）、剥脱性皮炎、重症（SJS/TEN）\n好发部位：全身或固定部位（固定性药疹同一部位复发）","辅助检查":"检查计划：患者有明确用药史（抗生素、解热镇痛药或抗癫痫药等），用药后数天至2周出现皮疹伴瘙痒，重症可有发热，初步诊断药疹，需评估有无多脏器受累。查血常规了解有无嗜酸性粒细胞升高及白细胞变化，评估药物超敏反应程度；查肝功能、肾功能、电解质及心肌酶，排除药物性肝损伤、肾损伤及心肌损伤，因重症药疹常伴多脏器受累；查CRP、降钙素原及血培养，排除合并感染所致的发热；对皮疹广泛、出现水疱或表皮剥脱者，完善皮肤组织病理活检明确有无Stevens-Johnson综合征、中毒性表皮坏死松解症等重症药疹；查凝血功能及D-二聚体评估有无凝血异常；对伴发热、黏膜受累者完善胸部X线或CT，排除肺部感染及间质性肺炎；查心电图了解有无心律失常，因部分致敏药物可致心脏损害；对疑似药物超敏反应综合征者，查EBV、CMV、HHV-6等病毒学指标及甲状腺功能；病情稳定后完善致敏药物筛查（斑贴试验，药物激发试验需谨慎），明确致敏药物以指导今后安全用药。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：用药史+皮疹时间关系（用药后数天至2周）；常见致敏药（抗生素、解热镇痛、抗癫痫）\n1. 药疹（药物性皮炎）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n立即停用可疑药物；抗组胺药/糖皮质激素；重症（SJS/TEN/DRESS）住院\n\n【注意事项】\n记牢过敏药物，就医时主动告知；重症药疹死亡率高需尽早识别","资料来源":"皮肤病库 derm.json（条目「药疹（药物性皮炎）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2830,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0e12c938caadfc04b104f8cafc101b21011e0fb55886b40c6ebea959be2c1301","pinyin":"yaozhen（yaowuxingpiyan）","initials":"yz（ywxpy）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-100c7f3af5d51ba2ebfc","key":"v1-c9ccc21dfe2a3058|templates-100c7f3af5d51ba2ebfc","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"蕈样肉芽肿（蕈样霉菌病）","category":"皮肤肿瘤","raw":{"name":"蕈样肉芽肿（蕈样霉菌病）","category":"皮肤肿瘤","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】瘙痒，可较顽固。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：瘙痒，可较顽固。。\n自觉症状：瘙痒，可较顽固。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：早期为斑片、斑块（红斑期），可呈湿疹样、银屑病样，后发展为肿瘤期结节或肿块，可伴红皮病。\n好发部位：好发于非曝光部位，如躯干、臀部、大腿，呈泳裤区分布。","辅助检查":"检查计划：患者慢性顽固性瘙痒，病程迁延、反复发作，入院后完善血常规检查了解有无贫血、嗜酸性粒细胞增多及感染征象，完善肝肾功能、血糖及乳酸脱氢酶（LDH）检查评估全身状况与肿瘤负荷，为后续用药选择及剂量调整提供依据；本病确诊依赖组织病理，完善皮肤活检（选近新发浸润性斑块取材）行组织病理学检查明确真皮内有无亲表皮性异型淋巴细胞，并完善免疫组化（CD3、CD4、CD8、CD7、CD30等）检查明确肿瘤细胞免疫表型；患者外周血及皮损需进一步鉴别克隆性病变，完善T细胞受体（TCR）基因重排检查明确有无单克隆性T细胞增生，以提高早期诊断率；本病可累及淋巴结、骨髓及内脏，完善浅表淋巴结及腹部超声检查了解淋巴结、肝脾有无受累，完善胸部CT检查评估纵隔及肺门淋巴结情况；患者中年以上、皮疹泛发者需警惕系统受累，定期复查血常规与LDH评估病情活动度，必要时完善骨髓穿刺及流式细胞术检查进一步明确分期，指导分期与治疗方案制定。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据慢性顽固性斑片或斑块、好发部位及多次活检（真皮内亲表皮性异型淋巴细胞）诊断，必要时免疫组化、T细胞受体基因重排。\n1. 蕈样肉芽肿（蕈样霉菌病）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n早期外用糖皮质激素、氮芥、光疗（PUVA或窄谱UVB），进展期用系统治疗（维A酸、干扰素、放疗等）。\n\n【注意事项】\n早期易误诊为湿疹，久治不愈的湿疹样皮损需活检并转诊皮肤科或血液科。","资料来源":"皮肤病库 derm.json（条目「蕈样肉芽肿（蕈样霉菌病）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2831,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c31a4b4909e076cd2fd5f0f7897f0539bd1a0655915dacefc113c63b35a8fd82","pinyin":"xunyangrouyazhong（xunyangmeijunbing）","initials":"xyryz（xymjb）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-654bf2584eab884b3aee","key":"v1-c9ccc21dfe2a3058|templates-654bf2584eab884b3aee","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"表皮样囊肿（表皮囊肿、皮脂腺囊肿、粉瘤）","category":"皮肤肿瘤","raw":{"name":"表皮样囊肿（表皮囊肿、皮脂腺囊肿、粉瘤）","category":"皮肤肿瘤","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】一般无自觉症状，感染时红肿、疼痛、破溃流脓。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：一般无自觉症状，感染时红肿、疼痛、破溃流脓。。\n自觉症状：一般无自觉症状，感染时红肿、疼痛、破溃流脓。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：圆形、光滑、可移动的皮下结节，中央常有开口（可挤出豆腐渣样角化物），囊壁与表皮相连。\n好发部位：好发于面部、颈部、躯干及背部。","辅助检查":"检查计划：患者皮下圆形囊性结节，感染时出现红肿、疼痛、破溃流脓，入院后完善血常规检查明确有无继发细菌感染及感染程度，完善C反应蛋白、降钙素原检查评估炎症反应轻重，为是否需抗感染治疗提供依据；本病需与脂肪瘤、多发性脂囊瘤鉴别，完善浅表肿物彩超检查明确肿物为囊性、有无分隔及血流信号，鉴别实性肿瘤与囊肿；囊肿感染破溃者需明确致病菌，完善脓液或分泌物细菌培养加药物敏感试验检查指导抗生素选择；患者若拟行手术切除，术前需完善凝血功能、肝肾功能、血糖及心电图检查评估手术耐受性、排除凝血功能障碍与糖尿病等影响愈合的因素，完善乙型肝炎、丙型肝炎、梅毒及HIV等传染病筛查了解有无血源性传播疾病；多发囊肿或反复发作者需排除内分泌代谢因素，完善血脂、血糖检查了解代谢状况；术后定期复查彩超观察有无复发或残留，必要时将切除组织送病理检查明确诊断、排除其他皮肤肿瘤。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据皮下圆形囊性结节、中央开口及挤压出角化物诊断，需与脂肪瘤、多发性脂囊瘤鉴别。\n1. 表皮样囊肿（表皮囊肿、皮脂腺囊肿、粉瘤）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n无症状可不处理，反复感染或美容需求行手术完整切除（含囊壁）；感染期先抗炎，炎症消退后切除。\n\n【注意事项】\n切除不彻底易复发，勿自行挤压以免感染。","资料来源":"皮肤病库 derm.json（条目「表皮样囊肿（表皮囊肿、皮脂腺囊肿、粉瘤）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2832,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ac042cb441a5388d7741544db038167727bc0925bd9ad0dff691b274c3d65ed0","pinyin":"biaopiyangnangzhong（biaopinangzhong、pizhixiannangzhong、fenliu）","initials":"bpynz（bpnz、pzxnz、fl）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-f0b7a41bcd0793714472","key":"v1-c9ccc21dfe2a3058|templates-f0b7a41bcd0793714472","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"角化棘皮瘤","category":"皮肤肿瘤","raw":{"name":"角化棘皮瘤","category":"皮肤肿瘤","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】一般无自觉症状，数周至数月内快速生长。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：一般无自觉症状，数周至数月内快速生长。。\n自觉症状：一般无自觉症状，数周至数月内快速生长。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：生长迅速的坚实圆顶状结节，中央充满角质的火山口样凹陷，边缘光滑，直径1~2cm。\n好发部位：好发于面部、手背、前臂等日光暴露部位，中老年人多见。","辅助检查":"检查计划：患者皮损数周至数月内快速生长，呈中央角质栓的火山口样结节，需警惕恶性病变，入院后完善皮肤活检（沿皮损边缘连同中央角质栓完整取材）行组织病理学检查明确诊断，并与鳞状细胞癌鉴别，必要时完善免疫组化（CK、p53、Ki-67等）检查进一步明确肿瘤性质与良恶性；本病生长迅速且可有区域淋巴结转移风险，完善浅表淋巴结彩超检查了解引流区淋巴结有无肿大，完善浅表肿物彩超检查了解皮损深度、边界及与周围组织关系，为手术切除范围提供依据；患者拟行手术切除，术前完善血常规、凝血功能检查排除感染与凝血异常，完善肝肾功能、血糖及心电图检查评估手术耐受性，完善乙型肝炎、丙型肝炎、梅毒及HIV筛查了解有无血源性传播疾病；患者多为中老年、有长期日晒史，完善胸部CT检查排除肺部转移灶及其他原发肿瘤，完善腹部超声检查了解肝、胆、胰、脾及腹腔淋巴结有无转移；术后定期复查，观察有无局部复发，必要时再次活检明确。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据快速生长、中央角质栓的火山口样结节诊断，需与鳞状细胞癌鉴别，须活检确诊。\n1. 角化棘皮瘤","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n手术完整切除并病理检查是首选，亦可行刮除、冷冻或皮损内注射。\n\n【注意事项】与鳞状细胞癌鉴别困难，务必活检；快速增大或复发需警惕。","资料来源":"皮肤病库 derm.json（条目「角化棘皮瘤」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2833,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"73892254dd79d9ab9536de73f8478d543faf10f6932d4b9d8a4802fbb50028cf","pinyin":"jiaohuajipiliu","initials":"jhjpl","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-0b41e3d877f104753ba3","key":"v1-c9ccc21dfe2a3058|templates-0b41e3d877f104753ba3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"足癣（脚气）","category":"真菌性","raw":{"name":"足癣（脚气）","category":"真菌性","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】瘙痒、灼痛；继发感染时红肿疼痛。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：瘙痒、灼痛；继发感染时红肿疼痛。\n自觉症状：瘙痒、灼痛；继发感染时红肿疼痛。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：趾间浸渍发白、脱屑、糜烂（间擦型）；足底角化脱屑（鳞屑角化型）；小水疱（水疱型）\n好发部位：趾间、足底、足侧缘","辅助检查":"检查计划：患者足部瘙痒、灼痛，继发感染时红肿疼痛，诊断要点为鳞屑真菌镜检或培养阳性，故入院后完善皮屑真菌直接镜检检查明确有无菌丝及孢子，必要时完善真菌培养检查明确致病菌种，以指导抗真菌药物选择；本病需与湿疹、接触性皮炎鉴别，完善皮损真菌荧光染色检查提高检出率，必要时完善皮肤镜检查了解鳞屑、血管及毛发改变协助鉴别；患者局部红肿、疼痛、破溃流脓时提示继发细菌感染，完善血常规、C反应蛋白检查评估感染程度，完善分泌物细菌培养加药物敏感试验检查明确致病菌并指导抗生素应用；患者需长期口服抗真菌药物者，完善肝肾功能检查排除肝肾功能不全，为用药安全及剂量调整提供依据，完善血糖检查了解有无糖尿病等易感因素、评估复发风险；患者病程长、反复发作者，完善免疫功能相关检查评估机体免疫状态；治疗期间定期复查真菌镜检观察疗效，连续复查阴性方可判断治愈，避免过早停药导致复发。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：鳞屑真菌镜检/培养阳性；典型分布\n1. 足癣（脚气）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n外用抗真菌药（特比萘芬、联苯苄唑、咪康唑等），疗程需足（一般2~4周，角化型更长）。间擦糜烂型：先用生理盐水或0.1%依沙吖啶（雷佛奴尔）溶液湿敷收敛，干燥后再用抗真菌霜剂；避免使用硼酸溶液（婴幼儿禁用，破损皮肤大面积吸收可致中毒）。泛发、顽固或合并甲癣/糖尿病者口服特比萘芬或伊曲康唑。\n\n【注意事项】\n保持足部干燥；鞋袜消毒；糖尿病患者足癣需积极治疗防感染","资料来源":"皮肤病库 derm.json（条目「足癣（脚气）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2834,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bcf29f290edbab67db07e2345aa30cc59f6ad19f419174046e74d316c3be4d47","pinyin":"zuxuan（jiaoqi）","initials":"zx（jq）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-8b45a5d7066c8540d0ed","key":"v1-c9ccc21dfe2a3058|templates-8b45a5d7066c8540d0ed","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"过敏性紫癜（IgA血管炎）","category":"血管性","raw":{"name":"过敏性紫癜（IgA血管炎）","category":"血管性","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】可伴关节肿痛、腹痛、恶心呕吐及血尿等，自觉瘙痒或轻微疼痛。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：可伴关节肿痛、腹痛、恶心呕吐及血尿等，自觉瘙痒或轻微疼痛。。\n自觉症状：可伴关节肿痛、腹痛、恶心呕吐及血尿等，自觉瘙痒或轻微疼痛。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：双下肢对称分布的针尖至米粒大可触及性紫癜、瘀点瘀斑，压之不褪色，可融合成片，严重时出现血疱、坏死及溃疡。\n好发部位：好发于双下肢伸侧及臀部，尤以小腿为主，对称分布。","辅助检查":"检查计划：患者双下肢对称性可触及性紫癜，发病前1~3周常有上呼吸道感染史，入院后完善血常规检查明确血小板计数是否正常，与血小板减少性紫癜鉴别，同时了解有无贫血及白细胞升高提示感染；完善尿常规及尿沉渣检查明确有无蛋白尿、血尿，评估肾脏是否受累，完善24小时尿蛋白定量检查了解肾损害程度，完善肾功能及电解质检查排除肾功能不全与电解质紊乱；患者可伴关节肿痛，完善关节X线或彩超检查了解关节腔有无积液、排除其他关节病变；患者可伴腹痛、恶心呕吐，完善腹部超声检查了解肠壁有无水肿、肠套叠及腹腔积液，完善便常规加便隐血检查排除消化道出血，必要时完善胃镜检查明确有无紫癜性消化道黏膜病变；患者皮疹表现不典型或累及肾脏时，完善皮肤活检行直接免疫荧光检查明确血管壁有无IgA沉积，以明确诊断；完善凝血功能及D-二聚体检查排除凝血异常性疾病，完善C反应蛋白、红细胞沉降率检查评估炎症活动度；治疗期间定期复查尿常规及肾功能，动态监测肾脏受累情况，指导激素及免疫抑制方案调整。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据双下肢对称性可触及性紫癜及发病前1~3周常有上呼吸道感染史，可伴关节痛、腹痛或肾损害；血小板计数正常，尿常规可见蛋白尿、血尿。\n1. 过敏性紫癜（IgA血管炎）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n去除诱因、卧床休息；轻症对症处理，重症或伴腹型、肾型者系统患者糖皮质激素，必要时联合免疫抑制剂。\n\n【注意事项】\n合并严重腹痛、消化道出血或肾功能进行性损害者应转诊；应定期复查尿常规监测肾损害。","资料来源":"皮肤病库 derm.json（条目「过敏性紫癜（IgA血管炎）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2835,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"56d420de5fd6a98eb3a99e25f13fd62505ed2641cdfb9140c65d72f77547b0d9","pinyin":"guominxingzidian（IgAxueguanyan）","initials":"gmxzd（xgy）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-c61d4cd1d5ef74c5986f","key":"v1-c9ccc21dfe2a3058|templates-c61d4cd1d5ef74c5986f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"钱币状湿疹（钱币状皮炎）","category":"湿疹皮炎类","raw":{"name":"钱币状湿疹（钱币状皮炎）","category":"湿疹皮炎类","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】剧烈瘙痒，夜间常加重。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：剧烈瘙痒，夜间常加重。。\n自觉症状：剧烈瘙痒，夜间常加重。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：圆形或类圆形钱币状红斑、丘疹、丘疱疹，可融合成斑块，表面渗出、结痂，边界清楚。\n好发部位：好发于四肢伸侧、手背、躯干，尤以下肢多见。","辅助检查":"检查计划：患者钱币状、边界清楚的湿疹样斑块伴剧烈瘙痒、夜间加重，病程慢性复发，诊断需与体癣、银屑病鉴别，故入院后完善皮屑真菌直接镜检及真菌培养检查排除体癣等真菌感染，避免误用糖皮质激素导致皮损扩大；完善血常规检查了解有无嗜酸性粒细胞增多及感染征象，完善C反应蛋白、红细胞沉降率检查评估炎症活动程度；患者皮损渗出、结痂时提示可能继发细菌感染，完善分泌物细菌培养加药物敏感试验检查明确致病菌，指导抗感染治疗；患者瘙痒顽固，需寻找致病或加重因素，完善血清总IgE及过敏原特异性IgE检测检查了解有无过敏因素，完善斑贴试验检查明确有无接触性致敏物；本病需与银屑病鉴别，必要时完善皮肤镜检查观察背景、血管及鳞屑特征，必要时完善皮肤活检行组织病理学检查明确诊断；患者若需长期外用或系统应用糖皮质激素及免疫抑制剂治疗，完善肝肾功能、血糖、电解质检查排除用药禁忌；治疗期间定期复查评估疗效，指导药物减量方案。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据钱币状、边界清楚的湿疹样斑块及慢性复发病程诊断，需与体癣、银屑病鉴别，必要时真菌镜检。\n1. 钱币状湿疹（钱币状皮炎）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n外用糖皮质激素及保湿剂控制炎症与修复屏障，渗出明显时湿敷，瘙痒重者口服抗组胺药。\n\n【注意事项】\n避免过度洗涤与搔抓，反复不愈或继发感染时需就医。","资料来源":"皮肤病库 derm.json（条目「钱币状湿疹（钱币状皮炎）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2836,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"fdb87a530062ec0cf0142020a7290d4df3706036a5c9e1eb38bc9db810b45efb","pinyin":"qianbizhuangshizhen（qianbizhuangpiyan）","initials":"qbzsz（qbzpy）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-a1cef45fa5976da60713","key":"v1-c9ccc21dfe2a3058|templates-a1cef45fa5976da60713","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"间擦疹（褶烂）","category":"湿疹皮炎类","raw":{"name":"间擦疹（褶烂）","category":"湿疹皮炎类","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】瘙痒、烧灼、疼痛。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：瘙痒、烧灼、疼痛。\n自觉症状：瘙痒、烧灼、疼痛。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：皱褶部位红斑、浸渍、糜烂，可继发真菌/细菌感染\n好发部位：腹股沟、腋下、乳房下、臀沟","辅助检查":"检查计划：患者皱褶部位瘙痒、烧灼、疼痛，查体见对称性红斑浸渍，需与念珠菌所致真菌感染鉴别，故入院后完善皮屑真菌直接镜检及真菌培养检查明确有无念珠菌感染，如见卫星灶更支持真菌感染，以指导抗真菌治疗；皮损浸渍、糜烂渗液者易继发细菌感染，完善分泌物细菌培养加药物敏感试验检查明确致病菌并指导抗生素选择，完善血常规、C反应蛋白检查评估感染程度与炎症反应；本病多见于肥胖、糖尿病及免疫力低下人群，完善血糖及糖化血红蛋白检查排除糖尿病，完善肝肾功能检查了解全身状况、为用药安全提供依据；患者若长期卧床或局部潮湿多汗，完善电解质及血清白蛋白检查评估营养与代谢状况，指导支持治疗；本病需与湿疹、接触性皮炎、反向银屑病鉴别，必要时完善皮肤镜检查了解皮损细节，必要时完善皮肤活检行组织病理学检查进一步明确诊断；治疗期间定期复查真菌镜检观察疗效，同时保持局部干燥、减少摩擦以降低复发。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：皱褶部位对称性红斑浸渍；与真菌（念珠菌）鉴别（卫星灶）\n1. 间擦疹（褶烂）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n保持干燥（扑粉/氧化锌）；糜烂期收敛湿敷；念珠菌感染抗真菌\n\n【注意事项】\n肥胖、糖尿病者易反复；勿用刺激性强的药膏","资料来源":"皮肤病库 derm.json（条目「间擦疹（褶烂）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2837,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7389ea6dff63b9f2a32ce8eb9a23694fcfce55dfefe20e01489a06ec927c617e","pinyin":"jiancazhen（zhelan）","initials":"jcz（zl）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-aad2936bec023f95c60a","key":"v1-c9ccc21dfe2a3058|templates-aad2936bec023f95c60a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"雄激素性脱发（脂溢性脱发）","category":"附属器疾病","raw":{"name":"雄激素性脱发（脂溢性脱发）","category":"附属器疾病","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】多无自觉症状，可伴头皮油腻、瘙痒。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：多无自觉症状，可伴头皮油腻、瘙痒。。\n自觉症状：多无自觉症状，可伴头皮油腻、瘙痒。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：男性表现为额颞部发际线后移及头顶部毛发稀疏，女性多表现为头顶部弥漫性毛发稀疏而发际线保留。\n好发部位：男性以额颞部和头顶为主，女性以头顶部为主。","辅助检查":"检查计划：患者头皮油腻、瘙痒伴进行性脱发，依据典型脱发模式及家族史、毛囊微小化表现诊断，入院后完善毛发镜检查了解毛发直径差异、毛囊单位密度及有无黄点征，明确毛囊微小化程度并评估脱发分期；本病女性患者需排除多囊卵巢综合征等内分泌疾病，完善性激素六项检查了解睾酮、黄体生成素及促卵泡激素水平，完善妇科彩超检查了解卵巢有无多囊样改变，完善甲状腺功能检查排除甲状腺疾病所致脱发；患者需长期口服抗雄激素或外用药物治疗，完善肝肾功能检查排除肝肾功能不全，为用药安全及剂量调整提供依据；完善血常规、血清铁蛋白及叶酸、维生素B12检查排除缺铁性贫血及营养不良性脱发，完善甲状腺功能及空腹血糖、血脂检查了解代谢状况；本病需与斑秃、休止期脱发鉴别，必要时完善皮肤活检行组织病理学检查明确毛囊状态；治疗期间定期复查毛发镜及肝肾功能，动态评估疗效与药物安全性，指导长期维持治疗方案。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据典型脱发模式及家族史、毛囊微小化表现，可结合毛发镜检查；女性需排除多囊卵巢综合征等内分泌疾病。\n1. 雄激素性脱发（脂溢性脱发）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n外用米诺地尔，男性可口服非那雄胺、女性可口服螺内酯或抗雄激素药；可考虑毛发移植或低能量激光。\n\n【注意事项】\n需长期维持治疗，停药后可复发；女性患者应注意排除高雄激素血症。","资料来源":"皮肤病库 derm.json（条目「雄激素性脱发（脂溢性脱发）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2838,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8d1f2ba00ef687e009873d6168e37c24fcb6628d5a5e784d00d300e2f6c0e06e","pinyin":"xiongjisuxingtuofa（zhiyixingtuofa）","initials":"xjsxtf（zyxtf）","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-96c39ad40b247f2704a9","key":"v1-c9ccc21dfe2a3058|templates-96c39ad40b247f2704a9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"马拉色菌毛囊炎","category":"真菌性","raw":{"name":"马拉色菌毛囊炎","category":"真菌性","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】常有不同程度瘙痒，出汗后加重。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：常有不同程度瘙痒，出汗后加重。。\n自觉症状：常有不同程度瘙痒，出汗后加重。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：上胸、背、肩部出现密集分布的红色半球形丘疹、丘疱疹，约1~2mm，周边可有红晕，可伴少许脓疱，形态较一致。\n好发部位：好发于胸背、肩、上臂等皮脂腺丰富部位。","辅助检查":"检查计划：患者皮脂丰富部位出现密集小丘疹、脓疱，伴不同程度瘙痒且出汗后加重，临床高度疑诊马拉色菌毛囊炎，首先完善真菌直接镜检检查，取丘疹内容物或鳞屑加10%氢氧化钾制片，查找大量孢子及短菌丝以明确诊断，此为确诊该病的核心依据；同期完善伍德灯检查，观察皮损区有无黄绿色荧光，协助明确马拉色菌感染范围并了解皮损分布广度；患者皮损呈密集分布且需与细菌性毛囊炎、痤疮相鉴别，完善皮肤镜检查了解毛囊开口及血管形态，用于鉴别细菌性毛囊炎与寻常痤疮；若镜检结果不典型或反复治疗无效，完善真菌培养检查明确致病菌种，以指导抗真菌药物选择及疗程制定；对皮损形态特殊、诊断仍存疑者，必要时完善皮损组织病理检查排除其他肉芽肿性毛囊炎及深部真菌感染；患者瘙痒明显、长期反复发作，完善血常规及C反应蛋白检查排除细菌感染、排除贫血等全身因素；因需较长时间口服伊曲康唑等抗真菌药物，用药需经肝肾代谢，完善肝肾功能检查排除肝肾功能不全，以保证用药安全；本病易反复，嘱出院后定期复诊并复查真菌镜检，评估疗效并了解有无复发。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据皮脂丰富部位密集小丘疹脓疱，真菌镜检见大量孢子和短菌丝确诊，需与细菌性毛囊炎、痤疮鉴别。\n1. 马拉色菌毛囊炎","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n外用酮康唑洗剂及抗真菌乳膏，泛发或顽固者口服伊曲康唑或氟康唑。\n\n【注意事项】\n易复发，治疗同时注意控油、勤洗、更换透气衣物，避免长期使用糖皮质激素。","资料来源":"皮肤病库 derm.json（条目「马拉色菌毛囊炎」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2839,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"50b93235e67bbbd4effbb352654a8ee52122a7be964e1e0456325a12eca182e1","pinyin":"malasejunmaonangyan","initials":"mlsjmny","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-921d82107d1bf0765bb6","key":"v1-c9ccc21dfe2a3058|templates-921d82107d1bf0765bb6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"鸡眼","category":"物理性","raw":{"name":"鸡眼","category":"物理性","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】行走或受压时剧烈疼痛。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：行走或受压时剧烈疼痛。。\n自觉症状：行走或受压时剧烈疼痛。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：局限性角质增生的圆锥形角质栓，尖端嵌入真皮，中央有半透明角质核，周围绕以淡黄色角质环，境界清楚。\n好发部位：好发于足跖前中部、小趾外侧及趾间等摩擦受压部位。","辅助检查":"检查计划：患者足部长期摩擦受压部位出现境界清楚的圆锥形角质栓，行走或受压时剧烈疼痛，临床考虑鸡眼，首先完善皮肤镜检查了解角质栓结构及有无点状血管，用于与跖疣鉴别，鸡眼无黑色出血点而压痛明显；同期完善真菌直接镜检检查排除足癣、跖疣等真菌性皮肤病，避免误诊误治；对诊断仍不明确或经规范处理后不愈者，必要时完善皮损组织病理检查，明确角质层增厚及真皮内有无病毒性疣体改变，进一步鉴别跖疣及其他角化性皮肤病；患者足部长期受压、局部感觉减退，完善足部X线检查了解有无跖骨畸形、骨刺等骨性压迫因素，以明确疼痛原因；患者中老年多发、创面迁延，完善空腹血糖及糖化血红蛋白检查排除糖尿病及其所致足部病变，因糖尿病足早期可表现为局部角化性皮损；长期行走受限者完善下肢动脉血管彩超检查了解下肢动脉血供情况，排除下肢动脉硬化闭塞症所致缺血性疼痛；因需行局部物理治疗或手术切除，完善血常规、凝血功能检查排除凝血功能障碍，完善心电图检查评估心脏情况，以保障有创操作安全；治疗后嘱定期复查，观察角质栓有无残留及复发。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据长期摩擦受压史、境界清楚的圆锥形角质栓伴压痛，去除表面角质可见角质核；需与跖疣鉴别（鸡眼无黑色出血点，压痛明显）。\n1. 鸡眼","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n去除诱因，穿宽松软底鞋；外用角质剥脱剂（水杨酸、尿素软膏），或行冷冻、激光、手术切除。\n\n【注意事项】\n糖尿病患者足部鸡眼处理不当易致溃疡感染，应谨慎处理。","资料来源":"皮肤病库 derm.json（条目「鸡眼」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2840,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"336574a64976b6a10d1cf9fb4a17ae66d8a51506ad9620d99213b94f50a8d121","pinyin":"jiyan","initials":"jy","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-ef1dddb033f892b008e3","key":"v1-c9ccc21dfe2a3058|templates-ef1dddb033f892b008e3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"麻风","category":"细菌性","raw":{"name":"麻风","category":"细菌性","case":{"case_name":"门诊病历","templates":{"主诉":"【皮肤病库原文】皮损区感觉减退或麻木是特征，可无瘙痒疼痛。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：皮损区感觉减退或麻木是特征，可无瘙痒疼痛。。\n自觉症状：皮损区感觉减退或麻木是特征，可无瘙痒疼痛。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：皮损为边界清楚的色素减退斑或红斑，伴感觉减退/消失（麻木、不出汗），可形成结节、斑块，神经粗大，晚期出现“狮面”、爪形手、垂足等畸形。\n好发部位：好发于面部、四肢伸侧等温度较低部位，累及周围神经。","辅助检查":"检查计划：患者皮损区感觉减退或麻木，可无瘙痒疼痛，临床疑诊麻风，入院后完善皮肤涂片抗酸染色检查，取耳垂、眉弓及活动性皮损处组织液查找抗酸杆菌，以明确诊断并判定菌型，此为确诊麻风的关键依据；同期完善皮损组织病理检查，了解有无上皮样细胞肉芽肿、泡沫细胞及神经束内炎性细胞浸润，用于明确分型并鉴别结节病、皮肤结核等肉芽肿性疾病；患者存在感觉障碍、需评估神经受损节段与程度，完善神经传导速度及肌电图检查明确周围神经受损范围；完善血常规、肝肾功能检查排除贫血及肝肾功能不全，为氨苯砜、利福平等联合化疗方案的用药安全提供依据；因麻风需长期多药联合治疗，完善心电图检查排除心脏传导系统异常，避免氨苯砜、氯法齐明用药风险；患者长期慢性消耗，完善血糖、电解质检查了解营养及内环境状况；麻风可累及黏膜与眼部，完善眼科裂隙灯检查了解有无虹膜睫状体炎、角膜损害；本病为乙类传染病，完善乙肝、丙肝、梅毒及HIV等传染病筛查以明确合并感染；治疗期间定期复查皮肤涂片查菌及肝肾功能，了解细菌阴转情况并评估疗效。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"诊断要点：依据典型皮损伴感觉障碍、神经粗大，皮肤涂片或病理查抗酸杆菌确诊（多菌型）。\n1. 麻风","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【治疗】\n采用WHO多药联合化疗（MDT，利福平+氨苯砜+氯法齐明），疗程依型别而定。\n\n【注意事项】\n具一定传染性，需在专业机构规范治疗、随访，早期治疗可防畸残；现为国家重点防控传染病。","资料来源":"皮肤病库 derm.json（条目「麻风」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2841,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"becb009d9f017bb2283fadaff10e42b71d17fdfd243ad533db7d3832b6666b76","pinyin":"mafeng","initials":"mf","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-149b629d925b300555c6","key":"v1-c9ccc21dfe2a3058|templates-149b629d925b300555c6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"下肢动脉硬化闭塞症","category":"内科","raw":{"name":"下肢动脉硬化闭塞症","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者有下肢动脉硬化闭塞症，常见于长期吸烟、合并高血压糖尿病的中老年人群，多表现为间歇性跛行、下肢发凉及静息痛，入院后首先完善踝肱指数测定，了解下肢缺血程度并客观评估病情分级；完善下肢动脉血管彩超检查明确动脉狭窄或闭塞的部位与范围，必要时完善下肢动脉CTA检查进一步明确血管解剖、侧支循环及手术入路，为血运重建方案提供依据；患者动脉粥样硬化常为全身性病变，完善颈动脉彩超及心脏彩超检查了解有无颈动脉斑块及心脏结构功能异常，评估心脑血管合并风险；完善血脂四项及脂蛋白a检查了解血脂水平，指导他汀类降脂及抗动脉粥样硬化方案；患者多有糖代谢异常，完善空腹血糖、糖化血红蛋白检查排除糖尿病并评估血糖控制情况；完善血常规、凝血功能及D-二聚体检查排除贫血、排除凝血功能异常及血栓形成；因拟行抗血小板及可能的有创介入治疗，完善肝肾功能检查排除肝肾功能不全，完善心电图检查评估心脏情况，降低围手术期风险；患者肢体缺血易合并感染与组织坏死，完善C反应蛋白、降钙素原检查排除感染，完善下肢创面分泌物培养以指导抗感染治疗；病情稳定后定期复查踝肱指数及血管彩超，了解血流通畅情况及有无再狭窄。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 下肢动脉硬化闭塞症","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"下肢动脉硬化闭塞症是动脉粥样硬化累及下肢动脉导致动脉狭窄或闭塞而引起肢体缺血症状的\n慢性疾病， 是全身动脉硬化性疾病在下肢的表现。\n【病因和发病机制】 本病是冠心病的等危症， 引起冠状动脉粥样硬化的危险因素通常也会引发本\n病。发病机制参见本篇第四章动脉粥样硬化。吸烟使发病率增加 2～5 倍， 糖尿病使发病率增加 2～4 倍。\n【病理生理】 产生肢体缺血症状的主要病理生理机制是肢体的血供调节功能减退， 包括管腔斑\n块增厚、 侧支循环建立不足、 代偿性血管扩张不良、 一氧化氮产生减少、 对血管扩张剂反应减弱和循环\n中血栓素、 血管紧张素Ⅱ、 内皮素等血管收缩因子增多， 以及一些血液流变学异常， 由此导致血供调节\n失常和微血栓形成。\n【临床表现】 本病累及主、 髂动脉者占 30%， 累及股、 腘动脉者占 80%～90%， 而累及胫、 腓动脉\n者占 40%～50%。\n（一）   症 状  典型症状是间歇性跛行和静息痛； 肢体运动后引发局部疼痛、 紧束、 麻木或无力， 停\n止运动后即缓解为其特点。疼痛部位常与病变血管相关； 臀部、 髋部及大腿部疼痛导致的间歇跛行常\n提示主动脉和髂动脉部分阻塞。临床最多见的为小腿疼痛性间歇性跛行， 常为股、 腘动脉狭窄病变。\n踝、 趾间歇性跛行则多为胫、 腓动脉病变。病变进一步加重导致血管闭塞时， 可出现静息痛。目前临\n床常用的分期包括 Fontaine 分期和 Rutherford 分级 （ 表 3-12-2）。\n表3 -12-2   下肢动脉硬化闭塞症的临床分期\nFontaine 分期 Rutherford 分级\n分期 临床表现 分级 类别 临床表现\nⅠ期 无症状 0级 0 无症状\nⅡa 期 轻微间歇性跛行 Ⅰ级 1 轻微间歇性跛行\nⅡb 期 中度至重度间歇性跛行 Ⅰ级 2 中度间歇性跛行\nⅠ级 3 重度间歇性跛行\nⅢ期 缺血性静息痛 Ⅱ级 4 缺血性静息痛\nⅣ期 溃疡或坏疽 Ⅲ级 5 轻度组织丧失\nⅣ级 6 溃疡或坏疽\n（二）   体 征\n1. 狭窄远端的动脉搏动减弱或消失， 狭窄部位可闻及收缩期杂音。\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0014\u0014\u0019\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0014\u0014\u0019 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0014\u0014\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0014\u0014\n第十二章  主动脉和周围血管病\n339\n2. 患肢温度较低， 皮肤薄、 亮、 苍白， 毛发稀疏， 趾甲增厚， 严重时有水肿、 坏疽与溃疡。\n3. 肢体位置改变测试\n。肢体自高位下垂到肤色转红时间 ＞10 秒和表浅静脉充盈时间＞15 秒，\n提示动脉有狭窄及侧支形成不良。\n【辅助检查】 \n1.  踝肱指数（ankle brachial index， ABI） 临\n床上最简单和常用的检查方法， 为踝动脉收缩压与\n肱动脉收缩压的比值， 正常范围为 1.0～1.4， 0.91～0.99 被认为是 “临界值”，＜0.90 提示存在 PAD。\nABI＞1.40 常是血管钙化引起的。利用 ABI 诊断 PAD 的敏感性达 95%， 但严重狭窄伴侧支循环形成\n良好时可呈假阴性。\n2.  节段性血压测量\n 如发现节段间有压力阶差则提示其间有动脉狭窄存在。\n3. \n运动平板负荷试验\n 以缺血症状出现的运动负荷量和时间客观评价肢体的血供状态。\n4\n.  多普勒超声 随动脉狭窄程度的加重\n， 多普勒血流速度曲线会趋于平坦， 结合超声成像结果\n更可靠。\n5.  磁共振血管造影和 CT 血管造影\n 具有确诊价值。\n6. \n动脉造影\n 对手术或经皮介入的治疗决策提供直接依据。\n【\n诊断与鉴别诊断】 当病人有典型间歇性跛行或静息痛的症状与肢体动脉搏动不对称、 减弱或\n消失的体征， 再结合危险因素分析及辅助检查的结果， 诊断并不困难。但值得注意的是， 在确诊病人\n中有典型间歇性跛行症状者不足 20%。\n本病应与多发性大动脉炎累及髂动脉者、 血栓闭塞性脉管炎 （ 又称 Buerger 病） 相鉴别。多发性\n大动脉炎多见于年轻女性， 活动期有全身症状， 发热、 血沉增快及免疫指标异常， 病变部位多发， 常累\n及肾动脉而有肾性高血压。Buerger 病好发于青年男性重度吸烟者， 累及全身中、 小动脉， 上肢也常累\n及， 有反复发作浅静脉炎及雷诺现象。缺血性溃疡伴有剧痛应与神经病变、 下肢静脉曲张所致溃疡鉴\n别。此外， 跛行应与椎管狭窄、 关节炎、 骨筋膜隔室综合征等所致的假性跛行相鉴别。\n【治疗】 \n（ 一）  内科治疗  戒烟、 控制高血压、 糖尿病及血脂异常等； 清洁、 保湿、 预防外伤， 对有静息痛者\n可抬高床头， 以增加下肢血流， 减少疼痛。\n1.  运动和康复治疗 规律的有氧运动可改善最大步行距离\n， 患者专业指导下进行， 每次 30～45\n分钟， 每周至少 3 次， 至少持续 12 周。推荐的运动方式包括行走、 伸踝、 屈膝运动。Fontaine Ⅳ级病\n人不推荐进行常规运动治疗。\n2.  抗血小板和抗凝治疗 阿司匹林\n、 氯吡格雷等抗血小板药物可降低下肢动脉闭塞症病人发生\n心肌梗死、 脑卒中、 血管源性死亡的风险。西洛他唑具有抗血小板活性和舒张血管的特性， 作为治疗\n间歇性跛行的一线药物。传统抗凝药 （ 如华法林） 并不能减少心血管事件的发生， 反而可能增加大出\n血的风险。\n3.  前列腺素类药物\n 可扩张血管，\n改善间歇性跛行、 静息痛等症状。\n4.  止痛治疗 可遵循止痛治疗的阶梯原则进行\n， 从非甾体抗炎药开始， 如无效再尝试阿片类止\n痛药物。\n5.  抗感染治疗 对于缺血性溃疡或坏疽合并感染的病人\n， 需在病原学检查结果指导下， 针对性\n使用广谱、 足量、 足疗程的全身抗生素治疗。\n（ 二）  血运重建  经积极内科治疗后仍有静息痛、 组织坏疽或生活质量降低致残者可考虑进行血\n运重建。腔内介入治疗包括动脉内置管溶栓、 血栓抽吸、 球囊扩张及支架植入等， 围手术期并发症发\n生率低， 常作为首选。但对导丝无法通过病变等情况， 可选择外科手术治疗， 如斑块切除术或血管旁\n路移植术。\n（三）   截 肢  对于患有广泛坏死或感染性坏疽并伴有静息痛、 不能行走且不适合血运重建的病\n人， 需要进行截肢手术。\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0014\u0014\u001a\u0012\u000e\u0015௉\u000fJOE","资料来源":"人卫《内科学》第10版 · 循环.txt · 本节“下肢动脉硬化闭塞症”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2842,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"28caf3ee50bf75f0a2e99e47a55bbe23166607e97d5dd35ed8098be25212dd7a","pinyin":"xiazhidongmaiyinghuabisezheng","initials":"xzdmyhbsz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-7d5f9c6726c28d969d04","key":"v1-c9ccc21dfe2a3058|templates-7d5f9c6726c28d969d04","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"主动脉瓣反流","category":"内科","raw":{"name":"主动脉瓣反流","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者初步诊断主动脉瓣反流，常因瓣叶退行性变、主动脉根部扩张或感染性心内膜炎所致，可出现活动后气促、心悸及心绞痛样症状，入院后首先完善心脏彩超及左心功能测定检查，明确反流程度、瓣叶形态、主动脉根部内径及左心室射血分数，以评估病情严重度；必要时完善经食管超声心动图检查，进一步明确瓣膜病变性质、有无赘生物及主动脉夹层，用于鉴别感染性心内膜炎与主动脉夹层；患者长期反流致左心室容量负荷增加，完善NT-ProBNP检查明确有无心功能衰竭，完善心肌酶及肌钙蛋白检查排除急性心肌损伤；完善心电图检查了解有无左心室肥厚、心律失常及心肌缺血改变，必要时行动态心电图及运动负荷试验评估运动耐量与心律失常风险；患者发热或存在感染征象时，完善血培养检查排除感染性心内膜炎；完善血常规、C反应蛋白检查排除感染、排除贫血，完善肝肾功能及电解质检查排除肝肾功能不全及电解质紊乱，为利尿剂、血管扩张剂用药提供依据；患者多有动脉粥样硬化基础，完善血脂四项检查了解血脂水平，指导降脂方案；考虑外科瓣膜置换指征时，完善主动脉CTA检查明确主动脉根部及升主动脉形态，完善凝血功能、心电图、胸部X线片等术前必查项目，评估手术耐受性；病情稳定后定期复查心脏彩超及NT-ProBNP，观察反流程度及心功能动态变化。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 主动脉瓣反流","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"【病因】 主动脉瓣反流 （aortic regurgitation， AR） 主要由主动脉瓣膜本身病变、 主动脉根部疾病所\n致。根据发病情况又分为急性和慢性两种。\n（ 一）  急性主动脉瓣反流  病因主要包括： ①感染性心内膜炎； ②胸部创伤致升主动脉根部、 瓣\n叶支持结构和瓣叶破损或瓣叶脱垂； ③主动脉夹层血肿使主动脉瓣环扩大， 瓣叶或瓣环被夹层血肿撕\n裂； ④人工瓣膜撕裂等。\n（ 二）  慢性主动脉瓣反流\n1.  主动脉瓣本身病变 包括 ： ①风湿性心脏病： 在我国约 2/3 主动脉瓣反流由风湿性心脏病所\n致， 多合并主动脉瓣狭窄和二尖瓣病变； ②先天性畸形： 二叶瓣畸形占临床单纯性主动脉瓣反流的\n1/4， 儿童期出现反流多由于一叶边缘有缺口或大而冗长的一叶脱垂入左心室， 成人期多由于进行性\n瓣叶纤维化挛缩或继发于感染性心内膜炎而引起反流； ③感染性心内膜炎： 为单纯主动脉瓣反流的常\n见病因， 是由于瓣膜赘生物致瓣叶破损或穿孔， 瓣叶因支持结构受损而脱垂或赘生物介于瓣叶间妨碍\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0014\u0011\u0013\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0014\u0011\u0013 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0013\u0019\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0013\u0019\n第八章  心脏瓣膜病\n303\n其闭合而引起反流， 即使感染已控制， 瓣叶纤维化和挛缩可继续； ④退行性主动脉瓣病变： 75% 的老年\n退行性钙化性主动脉瓣狭窄合并反流； ⑤主动脉瓣脱垂： 系主动脉瓣黏液样变性致瓣叶舒张期脱垂入\n左心室， 偶尔合并主动脉根部中层囊性坏死， 可能为先天性原因。\n2.  主动脉根部扩张 引起瓣环扩大\n， 瓣叶舒张期不能对合， 为相对关闭不全。包括： ①Marfan 综\n合征： 遗传性结缔组织病， 通常累及骨、 关节、 眼、 心脏和血管， 典型者四肢细长， 韧带和关节过伸， 晶状\n体脱位和升主动脉呈梭形瘤样扩张； ②梅毒性主动脉炎： 炎症破坏主动脉中层， 致主动脉根部扩张，\n30% 发生主动脉瓣反流； ③其他病因： 高血压性主动脉环扩张、 特发性升主动脉扩张、 主动脉夹层形\n成、 强直性脊柱炎、 银屑病性关节炎等。\n【病理生理】 \n1.  急性舒张期 主动脉血流反流入左心室\n， 使左心室舒张末压迅速升高。收缩期， 左心室难以\n将左心房回血及主动脉反流血充分排空， 前向搏出量下降； 舒张期， 因舒张压迅速上升， 致使二尖瓣提\n前关闭， 有助于防止左心室压过度升高， 但左心房排空受限， 左心房压力增高， 引起肺淤血、 肺水肿。\n心率加快虽可代偿左心室前向排出量减少， 使左心室收缩压及主动脉收缩压不致发生明显变化， 但在\n急性主动脉瓣反流的病人， 血压常明显下降， 甚至发生心源性休克。\n2.  慢性舒张期 主动脉内血流大量反流入左心室\n， 使左心室舒张末容量增加。左心室对慢性容\n量负荷增加代偿反应为左心室扩张， 舒张末压可维持正常， 扩张在 Frank-Starling 曲线上升段， 可以增\n强心肌收缩力。另外， 由于血液反流， 主动脉内压力下降， 更有利于维持左心室泵血功能。由于左心\n室舒张末压不增加， 左心房和肺静脉压也保持正常， 故可多年不发生肺循环障碍。随病情进展， 反流\n量增多， 左心室进一步扩张， 左心室舒张末容积和压力显著增加， 最终导致心肌收缩力减弱， 心搏出量\n减少， 左心室功能降低， 最后可发展至左心功能不全。左心室心肌肥厚使心肌耗氧量增加， 同时主动\n脉反流致舒张压降低而使冠状动脉灌流减少， 引起心肌缺血， 也加速心功能恶化。\n【临床表现】 \n（一）   症 状  慢性主动脉瓣反流可在较长时间无症状， 轻症者一般可维持 20 年以上。随反流量\n增大， 出现与心搏出量增大有关的症状， 如心悸、 心前区不适、 头颈部强烈动脉搏动感等。心力衰竭的\n症状早期为劳力性呼吸困难， 随着病情进展， 可出现夜间阵发性呼吸困难和端坐呼吸。心绞痛发作较\n主动脉瓣狭窄时少见， 晕厥罕见， 改变体位时可出现头晕或眩晕。\n急性主动脉瓣反流轻者可无任何症状， 重者可出现突发呼吸困难， 不能平卧， 全身大汗， 频繁咳\n嗽， 咳白色或粉红色泡沫痰， 更重者可出现烦躁不安、 神志模糊， 甚至昏迷。\n（二）   体 征\n1.  慢性\n（1） 心尖搏动向左下移位\n， 范围较广， 心界向左下扩大。心底部、 胸骨柄切迹、 颈动脉可触及收缩\n期震颤。颈动脉搏动明显增强。\n（2） 心音\n： 第一心音减弱， 为舒张期左心室充盈过度、 二尖瓣位置高所致； 主动脉瓣区第二心音减\n弱或消失； 心尖区常可闻及第三心音，与舒张早期左心室快速充盈增加有关。\n（3） 心脏杂\n音： 主动脉瓣区舒张期杂音， 为一高调递减型叹气样杂音， 舒张早期出现， 坐位前倾位\n呼气末明显， 向心尖区传导。轻度反流者， 杂音柔和、 高调， 仅出现于舒张早期， 只有病人取坐位前倾、\n呼气末才能听到； 中重度反流者， 杂音为全舒张期， 性质较粗糙。当出现乐音性杂音时， 常提示瓣叶脱\n垂、 撕裂或穿孔。严重主动脉瓣反流， 在主动脉瓣区常有收缩中期杂音， 向颈部及胸骨上窝传导， 为极\n大量心搏出量通过畸形的主动脉瓣膜所致， 并非由器质性主动脉瓣狭窄所致。反流明显者， 常在心\n尖区闻及柔和低调的隆隆样舒张期杂音 （Austin-Flint 杂音）， 其产生机制是： ①由于主动脉瓣反流， 左\n心室血容量增多及舒张期压力增高， 将二尖瓣前侧叶推起处于较高位置， 引起相对二尖瓣狭窄所致。\n②主动脉瓣反流血液与由左心房流入的血液发生冲击、 混合， 产生涡流， 引起杂音。\n（4） 周围血管征\n： 动脉收缩压增高， 舒张压降低， 脉压增宽， 可出现周围血管征， 如点头征 （De \n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0014\u0011\u0014\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0014\u0011\u0014 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0013\u0019\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0013\u0019\n304\n第三篇  循环系统疾病\nMusset 征）、 水冲脉 （water-hammer pulse）、 股动脉枪击音 （Traube 征）和毛细血管搏动征， 听诊器压迫\n股动脉可闻及双期杂音 （Duroziez 双重音）。\n2.  急性\n 重\n者可出现面色灰暗、 唇甲发绀、 脉细数、 血压下降等休克表","资料来源":"人卫《内科学》第10版 · 循环.txt · 本节“主动脉瓣反流”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2843,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8d5a1bb013f5e9b2c0342d53d9567b0faef590ed1221744ea889fe0a9bb1bf51","pinyin":"zhudongmaibanfanliu","initials":"zdmbfl","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-9891aed6ae7bc78f8056","key":"v1-c9ccc21dfe2a3058|templates-9891aed6ae7bc78f8056","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"二尖瓣反流","category":"内科","raw":{"name":"二尖瓣反流","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者初步诊断二尖瓣反流，多见于瓣叶退行性变、风湿性心脏病、缺血性心肌病及左心室扩大者，常表现为活动后气促、乏力、心悸，入院后首先完善心脏彩超及左心功能测定检查，明确反流程度、瓣叶及瓣下结构改变、左心房左心室大小与射血分数，以评估病情严重度并明确病因；必要时完善经食管超声心动图检查，进一步明确瓣膜病变细节、有无赘生物及血栓，用于鉴别感染性心内膜炎，并为可能的瓣膜手术提供依据；患者长期反流致左心房压力升高、易并发心房颤动，完善心电图及动态心电图检查了解有无心房颤动、传导阻滞等心律失常；完善NT-ProBNP检查明确有无心功能衰竭，完善心肌酶及肌钙蛋白检查排除急性心肌损伤，完善胸部X线片了解心脏形态及肺淤血情况；患者发热时完善血培养、C反应蛋白检查排除感染性心内膜炎及风湿活动，完善抗链球菌溶血素O、红细胞沉降率检查明确有无风湿活动；完善血常规检查排除贫血、完善肝肾功能及电解质检查排除肝肾功能不全与电解质紊乱，为利尿剂、血管紧张素转换酶抑制剂等用药提供依据；患者多有动脉粥样硬化基础，完善血脂四项、空腹血糖及糖化血红蛋白检查了解血脂血糖水平，指导降脂降糖方案；拟行二尖瓣手术或介入治疗者，完善凝血功能及术前常规检查评估手术耐受性；病情稳定后定期复查心脏彩超与NT-ProBNP，动态评估反流程度及心功能变化。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 二尖瓣反流","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"【病因和病理】 二尖瓣结构包括瓣叶、 瓣环、 腱索、 乳头肌等四部分， 正常的二尖瓣功能有赖于\n此四部分及左心室的结构和功能完整性， 其中任何一个或多个部分发生结构异常或功能失调均可导\n致二尖瓣反流 （mitral regurgitation， MR）。常见二尖瓣反流病因如表 3-8-4 所示。根据病程， 可分为急\n性 MR和慢性 MR。慢性 MR 分为慢性原发性 （ 退化性） MR和慢性继发性 （ 功能性） MR。慢性原发性\nMR 由瓣叶、 瓣环、 腱索和乳头肌的一项及以上发生病理学改变引起； 慢性继发性 MR 继发于左室、 左\n房结构或功能异常， 二尖瓣膜通常是正常的。\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0014\u0011\u0019\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0014\u0011\u0019 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0013\u0019\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0013\u0019\n第八章  心脏瓣膜病\n309\n表3 -8-4   二尖瓣反流病因分类\n病变部位 慢性 急性或亚急性\n瓣叶 \n- 瓣 环 风湿性\n黏液样变性\n瓣环钙化\n结缔组织疾病\n先天性 （ 如二尖瓣裂）\n感染性心内膜炎\n外伤\n人工瓣瓣周漏\n腱索 \n- 乳头肌 瓣膜脱垂 （ 腱索或乳头肌过长）\n乳头肌功能不全\n原发性腱索断裂\n继发性腱索断裂\n感染性心内膜炎或慢性瓣膜病变所致\n心肌梗死并发乳头肌功能不全或断裂\n创伤所致腱索或乳头肌断裂\n心肌 （ 相对性） 扩张型心肌病\n肥厚型梗阻性心肌病\n冠心病\n1.  瓣叶 约 30% 的二尖瓣反流为风湿性损害。风湿性病变使瓣叶僵硬、 变性、 瓣叶边缘卷缩挛\n缩、 连接处融合以及腱索融合缩短。其他病因可见感染性心内膜炎引起的瓣叶穿孔、 赘生物附着， 影\n响瓣膜关闭。二尖瓣原发性黏液性变性使瓣叶宽松膨大或伴腱索过长致使二尖瓣脱垂， 当心脏收缩\n时瓣叶突入左房可致二尖瓣反流。二尖瓣脱垂亦可见于遗传性结缔组织病如 Marfan 综合征。肥厚\n型梗阻性心肌病收缩期二尖瓣前叶前向运动可导致二尖瓣反流。先天性心脏病心内膜垫缺损常合并\n二尖瓣前叶裂， 导致反流。\n2.  瓣环扩大 任何病因引起的左心室扩大\n、 左心房扩大、 二尖瓣环的退行性变和钙化， 都可造\n成二尖瓣环扩大而导致二尖瓣反流。二尖瓣环退行性变和瓣环钙化， 多见于老年女性。尸检发现 70\n岁以上女性， 二尖瓣环钙化的发生率为 12%。严重二尖瓣环钙化者， 50% 合并主动脉瓣环钙化， 大约\n50% 的二尖瓣环钙化累及传导系统， 引起不同程度的房室或室内传导阻滞。\n3.  腱索\n 这是引起二尖瓣反流的重要原因\n， 先天性异常、 自发性断裂或继发于感染性心内膜炎、\n风湿热的腱索断裂均可导致二尖瓣反流。\n4.  乳头肌\n 乳头肌功能失调可致其对腱索和瓣叶的牵制作用减弱而引起二尖瓣反流\n。乳头肌\n的血供来自冠状动脉终末分支， 对缺血很敏感， 冠状动脉灌注不足可引起乳头肌缺血、 损伤、 坏死和纤\n维化伴功能障碍。如乳头肌缺血短暂， 可出现短暂的二尖瓣反流； 如急性心肌梗死发生乳头肌坏死，\n则产生永久性二尖瓣反流， 乳头肌坏死是心肌梗死的常见并发症， 而乳头肌断裂在心肌梗死的发生\n率低于 1%， 乳头肌完全断裂可发生严重致命的急性二尖瓣反流。其他少见的疾病为先天性乳头\n肌畸形， 如一侧乳头肌缺如， 称降落伞二尖瓣综合征； 罕见的乳头肌脓肿、 肉芽肿、 淀粉样变和结节\n病等。\n【病理生理】 急性二尖瓣反流可致左心房及左心室压力骤然上升， 导致肺淤血甚至肺水肿。此\n外， 心搏出量及心排血量的减低会导致全身血管阻力的上升， 更加重了二尖瓣反流的严重程度。病人\n通常表现为突发的肺水肿及心源性休克。\n慢性二尖瓣反流时， 舒张期反流的血液再经二尖瓣充盈左心室， 导致左心室容量负荷增大， 早期\n通过左心室扩大和离心性肥厚代偿。根据 Frank-Starling 机制使左心室心搏出量增加以维持正常的\n前向心搏出量。慢性二尖瓣反流时左心房顺应性增加， 左心房扩大和左心室于较长时间内适应容量\n负荷的增加， 使左心房压和左心室舒张末压上升不明显， 故在相当长时期内不出现肺淤血且无临床症\n状。但持续、 严重的过度负荷， 终致左心室心肌功能衰竭， 左心室舒张末压和左心房压明显上升， 出现\n肺淤血， 最终出现肺动脉高压和右心衰。\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0014\u0011\u001a\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0014\u0011\u001a \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0013\u0019\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0013\u0019\n310\n第三篇  循环系统疾病\n【临床表现】 \n（一）   症 状\n1.  急性 轻度二尖瓣 反流仅有轻微劳力性呼吸困难； 严重反流时 （ 如腱索、 乳头肌断裂） 则很快\n发生急性左心衰， 甚至出现急性肺水肿或心源性休克。\n2.  慢性\n 慢性二尖瓣反流病人的临床症状轻重取决于二尖瓣反流的严重程度及进展速度\n、 左心\n房和肺静脉压的高低、 肺动脉压力水平及是否合并有其他瓣膜损害和冠状动脉疾病。如轻度二尖瓣\n反流者可以终身没有症状； 对于较重的二尖瓣反流， 从罹患风湿热至出现症状一般超过 20 年， 但一旦\n发生心力衰竭， 则进展常较迅速。\n程度较重的二尖瓣反流病人， 由于心排血量减少， 可表现为疲乏无力， 活动耐力下降； 同时， 肺静\n脉淤血导致程度不等的呼吸困难， 包括劳力性呼吸困难、 静息性呼吸困难、 夜间阵发性呼吸困难及端\n坐呼吸等。发展至晚期则出现右心衰竭的体循环淤血表现。在右心衰竭出现后， 左心衰竭的症状反\n而有所减轻。另外， 合并冠状动脉疾病的病人因心排血量减少可出现心绞痛的临床症状。\n（二）   体 征\n1.  急性 心尖搏动呈高动力型。肺动脉瓣第二心音亢进， 可见左心房强有力收缩所致的心尖区\n第四心音。心尖区收缩期杂音是二尖瓣反流的主要体征， 可在心尖区闻及＞3/6 级的收缩期粗糙的吹\n风样杂音， 累及腱索、 乳头肌时可出现乐音性杂音。由于左心房与左心室之间压力差减小， 心尖区反\n流性杂音持续时间变短， 于第二心音前终止。严重反流也可出现心尖区第三心音和短促的舒张期隆\n隆样杂音。\n2.  慢性\n 心尖搏动呈抬举样\n， 并向左下移位。重度反流时， 第一心音减弱或不能闻及。二尖瓣\n脱垂和冠心病所致反流时第一心音多正常。由于左心室射血时间缩短、 第二心音提前， 心音","资料来源":"人卫《内科学》第10版 · 循环.txt · 本节“二尖瓣反流”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2844,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9185d7b6b913bd8d75c5473662934d9d330c7c7dd5673b6cba6635de5b18f0ba","pinyin":"erjianbanfanliu","initials":"ejbfl","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-834dd2603dcd08c7006d","key":"v1-c9ccc21dfe2a3058|templates-834dd2603dcd08c7006d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"其他间质性肺疾病","category":"内科","raw":{"name":"其他间质性肺疾病","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者以进行性劳力性呼吸困难、干咳为主要表现，双下肺闻及爆裂音，初步诊断其他间质性肺疾病，入院后首先完善胸部高分辨率CT检查，了解病变分布、有无网格影、蜂窝影及磨玻璃影，以明确纤维化范围与程度并协助分型；完善肺功能检查及支气管舒张试验，了解限制性通气功能障碍与弥散功能下降程度，评估肺功能受损严重度；完善动脉血气分析检查明确有无低氧血症及换气功能障碍，必要时行六分钟步行试验评估运动耐量；因间质性肺疾病病因复杂，完善抗核抗体谱、类风湿因子、抗环瓜氨酸肽抗体及肌炎抗体谱等自身抗体检查排除结缔组织病相关间质性肺病，完善血清IgE、血嗜酸性粒细胞计数排除过敏性肺炎及嗜酸性粒细胞性肺疾病；患者需与感染性病变鉴别，完善血常规、C反应蛋白、降钙素原检查排除肺部感染、排除贫血；必要时完善支气管镜检查及支气管肺泡灌洗检查，行细胞学分类与病原学培养，鉴别外源性过敏性肺泡炎、肺泡蛋白沉积症等疾病；对诊断仍不明确者，必要时完善经支气管肺活检或外科肺活检行病理检查以明确病理类型；完善肝肾功能检查排除肝肾功能不全，为糖皮质激素及抗纤维化药物用药安全提供依据；定期复查胸部CT及肺功能，动态评估病情进展与治疗效果。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 其他间质性肺疾病","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"一、  过敏性肺炎\n过敏性肺炎 （HP） 也称外源性过敏性肺泡炎 （extrinsic allergic alveolitis， EAA）， 是指易感个体反复\n吸入有机或无机粉尘抗原后诱发的一种主要通过细胞免疫和体液免疫反应介导的肺部迟发性变态反\n应性疾病。病理表现为以淋巴细胞浸润为主的慢性肺泡炎症， 伴细胞性细支气管炎 （ 气道中心炎症）和散在分布的非干酪样肉芽肿为特征性病理改变。农民肺是 HP 的典型形式， 是农民吸入发霉干草\n中的嗜热放线菌或热吸水链霉菌孢子所致。吸入含动物蛋白的羽毛和排泄物尘埃引起饲鸟者肺 （ 如\n鸽子肺、 鹦鹉肺）， 生活在有嗜热放线菌污染的空调或湿化器的环境引起空调器肺等。各种病因所致\nHP 的临床表现相同， 可以是急性、 亚急性或慢性。\n目前根据 HP 的影像学和病理学表现分为非纤维化性 HP和纤维化性 HP。非纤维化性 HP 一般\n呈急性或亚急性起病， 急性起病者一般在职业或家居环境抗原接触后 4～8 小时出现畏寒、 发热、 全身\n不适伴胸闷、 呼吸困难和咳嗽。如果脱离抗原接触， 病情可于 24～48 小时内恢复。如果持续暴露， 反\n复急性发作导致几周或几个月内逐渐出现持续进行性发展的呼吸困难， 伴体重减轻， 表现为亚急性形\n式。纤维化性 HP 一般为慢性长期暴露于变应原， 肺脏炎症反复伴异常修复导致纤维化形成， 主要表\n现为进行性发展的呼吸困难伴咳嗽及体重减轻， 肺底部可以闻及吸气末 Velcro 啰音， 少数有杵状指。\n根据明确的抗原接触史， 典型的症状发作特点， 胸部 HRCT 具有小叶中心性微结节、 斑片磨玻璃\n影， 气体陷闭形成的马赛克征、 中上肺为著的肺纤维化等特征性表现， BALF 检查显示明显增加的淋\n巴细胞比例， 可以作出相对明确的诊断。TBLB、 TBLC 取得的病理资料能进一步支持诊断， 一些不典\n型病例也可能需要外科肺活检。\nHP 根本的治疗措施是脱离或避免抗原接触。对于伴有明显的肺部渗出和低氧血症者， 激素治疗\n有助于影像学和肺功能明显改善。\n二、  嗜酸性粒细胞性肺炎\n嗜酸性粒细胞性肺炎是一种以肺部嗜酸性粒细胞浸润伴有或不伴有外周血嗜酸性粒细胞增多为\n特征的临床综合征， 既可以是已知原因所致， 如单纯性肺嗜酸细胞浸润症 （Löffler 综合征）、 热带肺嗜\n酸性粒细胞增多症、 变应性支气管肺曲霉病、 药物或毒素诱发， 又可以是原因不明的疾病， 如急性嗜酸\n性粒细胞性肺炎、 慢性嗜酸性粒细胞性肺炎、 嗜酸性粒细胞性肉芽肿性多血管炎。\n慢性嗜酸性粒细胞性肺炎 （CEP） 的发病原因不明， 最常发生于中年女性， 通常于数周或数个月\n内出现呼吸困难、 咳嗽、 发热、 盗汗、 体重减轻和喘鸣， 呈现亚急性或慢性病程。X 线胸片的典型表\n现有肺外带的致密肺泡渗出影， 中心带清晰， 这种表现称作 “反肺水肿征” （photographic negative of \npulmonary edema）， 而且渗出性病变多位于上叶。80% 的病人有外周血嗜酸性粒细胞增多。血清 IgE\n增高也常见。如果病人有相应的临床和影像学特征， BALF 嗜酸性粒细胞大于 40%， 高度提示嗜酸性\n粒细胞性肺炎。治疗主要采用糖皮质激素。\n三、  肺朗格汉斯细胞组织细胞增生症\n肺朗格汉斯细胞组织细胞增生症 （PLCH） 是一种多数与吸烟相关的 ILD， 好发于成年人， 临床罕\n见。早期病变呈细支气管中心分布的朗格汉斯细胞 （CD1a 染色阳性） 浸润性结节， 多伴有嗜酸性粒\n细胞及慢性炎症细胞混合浸润， 可伴囊腔形成； 晚期病变朗格汉斯细胞可能较少， 多形成 “星形” 纤维\n化病灶。PLCH 起病隐匿， 表现为咳嗽和呼吸困难， 1/4 为胸部影像偶然发现， 也有部分病人因气胸就\n诊发现。X 线胸片显示结节或网格结节样渗出性病变， 常分布于上叶和中叶肺， 肋膈角清晰。HRCT\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0012\u0011\u0019\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0012\u0011\u0019 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u0019\u001b\u0015\u0018\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u0019\u001b\u0015\u0018\n第十章  间质性肺疾病\n109\n特征性地表现为多发的、 大小不一的、 囊壁厚薄不等的不规则囊腔， 早期多伴有细支气管周围结节 （ 直\n径1 ～4mm）， 主要分布于上、 中肺野。主要涉及上、 中肺野的多发性囊腔和结节或 BALF 朗格汉斯细\n胞超过 5% 高度提示 PLCH 的诊断。治疗为首先劝告病人戒烟。对于严重或已经戒烟但仍进行性加\n重的病人， 还可能需要患者糖皮质激素。\n四、  肺淋巴管平滑肌瘤病\n肺淋巴管平滑肌瘤病 （PLAM） 是一种临床罕见病， 可以散发， 也可以伴发于遗传疾病结节性硬化\n复合症 （tuberous sclerosis complex， TSC）。散发的 PLAM 几乎只发生于育龄期妇女。病理学为肺泡壁、\n细支气管壁和血管壁的类平滑肌细胞 （LAM 细胞， HMB-45\n+\n） 呈弥漫性或结节性增生， 导致局限性肺\n气肿或薄壁囊腔形成。\n临床上主要表现为进行性加重的呼吸困难、 反复出现的气胸和乳糜胸， 偶有咯血。肺功能呈现气\n流受限和气体交换障碍， 晚期伴有限制性通气功能障碍。胸部 HRCT 特征性地显示大小相对均一的\n薄壁囊腔 （ 直径 2～20mm） 弥漫性分布于两侧肺脏。LAM与 PLCH 在 CT 上的主要区别是 PLCH 一\n般不影响肋膈角， 囊壁更厚且囊形状不规则， 疾病早期有更多的结节。\n对于 PLAM 目前尚无可逆转病情的治疗方法。近来研究显示， 免疫抑制剂西罗莫司可以使一些\n病人的肺功能稳定或改善。终末期 PLAM 可以考虑肺移植。\n五、  肺泡蛋白沉着症\n肺泡蛋白沉着症 （pulmonary alveolar proteinosis， PAP） 以肺泡腔内积聚大量的表面活性物质形成\n的脂蛋白为特征， 主要是由于体内存在的抗粒细胞 \n- 巨噬细胞集落刺激因子\n（GM-CSF） 自身抗体导致\n肺泡巨噬细胞对表面活性物质的清除障碍所致。PAP 常隐匿起病， 10%～30% 诊断时无症状。常见\n症状是呼吸困难伴咳嗽， 偶有咳痰。 X 线胸片显示两侧弥漫性的渗出影， 分布于肺门周围， 形成 “蝴蝶”\n（","资料来源":"人卫《内科学》第10版 · 呼吸.txt · 本节“其他间质性肺疾病”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2845,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"33f822a635904d2b65ba5dffe01ad8a131c37ba54b5e4a4036267c80697cac84","pinyin":"qitajianzhixingfeijibing","initials":"qtjzxfjb","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-a5fd44135a406659bd30","key":"v1-c9ccc21dfe2a3058|templates-a5fd44135a406659bd30","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"农药中毒","category":"内科","raw":{"name":"农药中毒","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者有明确农药接触或口服史，伴恶心呕吐、多汗、流涎、瞳孔缩小及肌束颤动等表现，初步诊断农药中毒，属急危重症，入院即刻完善全血胆碱酯酶活性测定检查，明确中毒程度并指导阿托品及胆碱酯酶复能剂用量；急诊完善毒物筛查及血、尿标本有机磷类毒物检测，明确毒物种类，以指导特效解毒剂选择；急诊完成血常规、电解质、肝肾功能及血糖检查，排除电解质紊乱、排除肝肾功能不全，评估代谢紊乱与脏器损伤程度；完善动脉血气分析及胸部X线片检查，明确有无呼吸衰竭及吸入性肺炎，为呼吸支持提供依据；患者中毒易致心律失常与心肌损伤，完善心电图检查了解有无QT间期延长、传导阻滞，完善心肌酶及肌钙蛋白检查排除急性心肌损伤；完善凝血功能、D-二聚体及淀粉酶检查，了解有无凝血功能障碍及急性胰腺炎等并发症；因农药多经肝肾代谢，治疗期间需动态复查胆碱酯酶活性，评估疗效并了解有无反跳；必要时完善头颅CT检查排除脑血管意外所致意识障碍，完善腹部超声检查了解肝胰肾形态；病情稳定后定期复查肝肾功能、电解质及心电图，评估脏器功能恢复情况。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 农药中毒","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"农药 （pesticide） 是指用来杀灭害虫、 啮齿动物、 真菌和莠草等防治农业病虫害的药品。农药种类\n很多， 目前常用的包括杀虫药 （OPI、 氨基甲酸酯类、 拟除虫菊酯类和甲脒类等）、 灭鼠药 （rodenticide）和除草剂 （herbicide） 等。截至 2022 年 12 月 31 日， 我国登记的农药有效成分 751 种。农药在生产、\n运输、 分销、 贮存和使用过程中不注意防护， 以及摄入农药污染食物、 故意服毒或误服均可发生中毒。\n农药在使用过程中因效果不好或对人畜毒性太大而不断被淘汰或被新品种替代。在 20 世纪 50\n年代， 有机氯类杀虫药 （organochlorine insecticide， 如滴滴涕、 甲氧滴滴涕和六六六等） 被最早开发和\n广泛使用。该类药性质稳定， 对人畜毒性小， 但在土壤、 食品和生物体内残存时间持久， 可造成环境\n污染和生态环境破坏。动物实验发现， 该类药还能增加肝癌发病率， 故许多国家已禁用。20 世纪 60\n年代， 世界各地普遍生产和使用 OPI。据不完全统计， 世界上合成的有效 OPI 有数百种， 其中大量生\n产的有 40 余种。20 世纪 70 年代后， 相继生产氨基甲酸酯类、 拟除虫菊酯类和甲脒类等新型农业杀\n虫药。1982 年， 我国停止生产六六六， 并限制使用此类农药。目前， 我国不断淘汰对人畜毒性较大的\nOPI。2007 年起， 我国为保护粮食、 蔬菜和水果等农产品的质量安全， 停止使用对硫磷、 甲基对硫磷、\n甲胺磷、 磷胺和久效磷 5 种高毒 OPI。到 2009 年， 基本停止有机氯类杀虫药 （ 氯丹、 灭蚁灵和滴滴涕）\n生产、 使用和进出口。我国于 2022 年 9 月 1 日起禁止生产、 2024 年 9 月 1 日起禁止销售和使用甲拌\n磷、 甲基异柳磷、 水胺硫磷、 灭线磷原药及制剂。在农业生产中， 由于鼠类破坏庄稼， 灭鼠药患者广泛，\n也易引起人体中毒。本节重点介绍 OPI、 百草枯、 氨基甲酸酯类杀虫药和灭鼠药中毒。\n一、  急性有机磷杀虫药中毒\n急性有机磷杀虫药中毒 （acute organic phosphorus insecticide poisoning， AOPIP） 是指 OPI 进入体内\n抑制乙酰胆碱酯酶 （acetylcholinesterase， AChE） 活性， 引起体内生理效应部位 Ach 大量蓄积， 出现毒\n蕈碱样、 烟碱样和中枢神经系统等中毒症状和体征， 患者常死于呼吸衰竭。\nOPI 属于有机磷酸酯或硫化磷酸酯类化合物， 大都为油状液体， 呈淡黄\n色至棕色， 稍有挥发性， 有大蒜臭味， 除敌百虫， 难溶于水， 不易溶于多种有\n机溶剂， 在酸性环境中稳定， 在碱性环境中易分解失效。甲拌磷和三硫磷\n耐碱， 敌百虫遇碱能变成毒性更强的敌敌畏。常用剂型有乳剂、 油剂和粉\n剂等。其基本化学结构式如图 9-2-1。R和 R′ 为烷基、 芳基、 羟胺基或其他\n取代基团， X 为烷氧基、 丙基或其他取代基， Y 为氧或硫。\n【OPI 分类病因】 由于取代基不同， 各种 OPI 毒性相差很大。国内生产的 OPI 的毒性按大鼠急\n性经口进入体内的半数致死量 （LD50） 分为 4 类， 对 OPI 中毒有效抢救具有重要参考价值。\n1.\n  剧\n毒类\n LD50＜10mg/kg， 如甲拌磷 （thimet， 3911）、 内吸磷 （demeton， 1059）、 对硫磷 （parathion，\n1605）、 速灭磷 （mevinphos）和特普 （tetron， tetraethyl diphosphate， TEPP） 等。\n2.\n  高\n毒类\n LD50 10～100mg/kg， 如甲基对硫磷 （methylparathion）、 甲胺磷 （methamidophos）、 氧乐\n果 （omethoate）、 敌敌畏 （dichlorvos， dichlorphos， DDVP）、 磷胺 （phosphamidon）、 久效磷 （monocrotophos）、\n水胺硫磷 （isocarbophos）、 杀扑磷 （methidathion）和砜吸磷 （oxydemeton-methyl） 等。\n3 .  中度毒类 LD50 100 ～1 000mg/kg， 如 乐 果 （rogor， dimethoate）、 倍 硫 磷 （fenthion）、 除 线 磷\n（dichlofenthion）、 乙硫磷 （1240）、 敌百虫 （dipterex）、 乙酰甲胺磷 （acephate）、 二嗪磷 （diazinon）和亚胺\n硫磷 （phosmet） 等。\n4.\n  低\n毒类\n LD50 1 000 ～5 000mg/kg， 如马拉硫磷 （malathion， karbofos， 4049）、 辛硫磷 （phoxim）、 甲基\n乙酯磷 （methylacetophos）、 碘硫磷 （iodfenphos）、 氯硫磷 （phosphorus chloride）和溴硫磷 （bromophos） 等。\n【病因】\n1.  生产中毒 生产过程中引起中毒的主要是在杀虫药精制\n、 出料和包装过程中， 手套破损或衣\n图9 -2-1  OPI 结构通式\n8-9篇.indd 8898-9篇.indd 889 2024/7/28 11:14:502024/7/28 11:14:50\n890\n第九篇  理化因素所致疾病\n服和口罩污染； 也可因生产设备密闭不严， OPI 跑、 冒、 滴、 漏或污染手、 皮肤及吸入中毒。\n2.  使用中毒 在使用过程中\n， 施药人员喷洒时， 药液污染皮肤或湿透衣服由皮肤吸收， 以及吸入\n空气中 OPI； 配药时手被原液污染也可引起中毒。\n3.  生活中毒 故意吞服\n、 误服、 摄入 OPI 污染的水源或食品； 滥用 OPI 治疗皮肤病或驱虫也会发\n生中毒。\n【毒物代谢】 OPI 主要经胃肠、 呼吸道及皮肤黏膜吸收。吸收后迅速分布至全身各器官， 其中以\n肝内浓度最高， 其次为肾、 肺、 脾等， 肌肉和脑内含量最少。OPI 主要在肝内进行生","资料来源":"人卫《内科学》第10版 · 理化.txt · 本节“农药中毒”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2846,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4b6a61b7076b368dd1e348399e1e3fa19a4e60753c14a347b7f60149b545665d","pinyin":"nongyaozhongdu","initials":"nyzd","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-400c8d57a76a8965f391","key":"v1-c9ccc21dfe2a3058|templates-400c8d57a76a8965f391","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"动脉粥样硬化","category":"内科","raw":{"name":"动脉粥样硬化","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者初步诊断动脉粥样硬化，属全身性血管病变，入院后需系统评估危险因素与靶器官受累情况。完善血脂四项（总胆固醇、甘油三酯、低密度脂蛋白胆固醇、高密度脂蛋白胆固醇）检查了解血脂水平，明确低密度脂蛋白胆固醇是否达标，指导他汀类降脂方案；完善空腹血糖及糖化血红蛋白检查明确有无糖代谢异常，因糖尿病是动脉粥样硬化最重要的危险因素之一；完善超敏C反应蛋白检查了解血管炎症状态，评估斑块不稳定性；完善肝肾功能检查，因降脂药物及抗血小板药物需经肝肾代谢，排除肝肾功能不全以保障用药安全；完善血常规、凝血功能及D-二聚体检查排除贫血、感染及高凝状态。查心电图及心肌酶谱检查排除冠状动脉粥样硬化所致心肌缺血、心肌损伤；查心脏彩超加左心功能测定了解心室壁运动、射血分数及瓣膜情况，明确有无心功能受损；完善颈部血管彩超检查明确颈动脉内中膜厚度、斑块性质及狭窄程度，评估缺血性脑卒中风险；完善下肢动脉彩超及踝肱指数测定了解下肢动脉供血情况，明确有无下肢动脉硬化闭塞；必要时完善头颅CT或MRI检查明确有无脑缺血病灶；病情需要时行血管CTA或DSA检查明确血管狭窄程度，为血运重建治疗提供依据；住院期间定期复查心电图观察有无动态演变。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 动脉粥样硬化","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"动脉粥样硬化 （atherosclerosis）的特点是受累动脉的病变从内膜开始， 局部先后发生细胞内外的\n脂质积聚、 纤维组织增生和钙质沉着， 病变内可见单核巨噬细胞及其他炎症细胞， 并有平滑肌细胞的\n迁移和增生， 大量胶原纤维、 弹力纤维和蛋白多糖等结缔组织基质形成， 动脉中层也可发生逐渐退变和钙化， 在此基础上可发生斑块内出血、 糜烂或破裂及继发局部血栓形成。由于在动脉内膜积聚的脂\n质外观呈黄色粥样， 因此被称为动脉粥样硬化。动脉粥样硬化相关的心血管疾病被称为动脉粥样硬\n化性心血管疾病 （atherosclerotic cardiovascular disease， ASCVD）。\n【病因和危险因素】 病因尚未完全确定。流行病学研究表明不少因素与本病的发生率增加相\n关， 但并非直接因果关系， 而是多种因素作用于不同环节所致， 这些因素称为危险因素 （risk factor）。\n主要的危险因素如下：\n1.  年龄、 性别\n 动脉粥样硬化的发生率随年龄而增加。临床上多见于\n40 岁以上中老年， 49 岁以\n后进展较快， 近年来发病年龄有年轻化趋势。男性发生率高于女性， 发病年龄也较女性提前约 10 年，\n可能与雌激素的抗动脉粥样硬化作用有关， 但女性在绝经期后发病率迅速增加。年龄和性别属于不\n可改变的危险因素。\n2.  血脂异常 脂质代谢异常是动脉粥样硬化最重要的危险因素\n。动脉粥样硬化常见于高胆固\n醇血症， 且和累积的胆固醇暴露量有关。家族性高胆固醇血症病人在青少年期就可以发生动脉粥样\n硬化。实验动物给予高胆固醇饲料可引起动脉粥样硬化。总胆固醇 （total cholesterol， TC）、甘油三酯\n（triglyceride， TG）、 低密度脂蛋白胆固醇 （low density lipoprotein cholesterol， LDL-C）或极低密度脂蛋白\n胆固醇 （very low density lipoprotein cholesterol， VLDL-C）增高、 载脂蛋白 B （apo B） 增高和高密度脂蛋\n白胆固醇 （high density lipoprotein-cholesterol， HDL-C）减低、 载脂蛋白 A （apo A） 降低都被认为是危险\n因素， 目前最肯定的是 LDL-C 致动脉粥样硬化作用， 脂蛋白 （a） ［\nLp （a） ］ 增高和 TG 增高也可能是独\n立的危险因素。临床实践中， LDL-C 是防治 ASCVD 的首要干预靶点， 非 HDL-C 为次要干预靶点。\n3.  高血压病 高血压病病人动脉粥样硬化发病率明显增高\n， 可能由于高血压内皮细胞损伤，\nLDL-C 易于进入动脉壁， 并刺激平滑肌细胞增生， 进而引起动脉粥样硬化发生及发展。60%～70% 的\n冠状动脉粥样硬化病人有高血压， 高血压病病人患冠心病概率增高 3～4 倍。\n4.  糖尿病和糖耐量异常 2\n型糖尿病诊断成立时， 约 50% 的病人已存在动脉粥样硬化病变， 2\n型糖尿病也被视为 “冠心病等危症”。糖尿病病人动脉粥样硬化的发病率较非糖尿病者高出 2～4 倍，\n且病变发生更早、 更弥漫， 进展更迅速， 累及血管床更多。糖尿病病人多伴有高脂血症， 常见 TG 升\n高、 HDL-C 降低、 小而致密 LDL （sdLDL） 增加。如再伴有高血压， 则动脉粥样硬化的发病率明显增高。\n糖尿病病人还常有凝血因子Ⅷ增高及血小板功能增强， 加速动脉粥样硬化血栓形成和引起管腔闭塞。\n糖耐量异常阶段即可增加动脉粥样硬化发生风险， 近年研究认为这与胰岛素抵抗有密切关系。\n5.  吸烟与不吸烟者比较\n， 吸烟者动脉粥样硬化的发病率和病死率增高 2～6 倍， 且与每日吸烟\n支数成正比。被动吸烟也是危险因素。烟草中有害成分可导致血管内皮损伤， 前列环素释放减少， 血\n小板易在动脉壁黏附聚集而形成血栓。吸烟还可使 HDL-C 降低、 TC 增高。另外， 烟草所含尼古丁可\n直接作用于冠状动脉和心肌， 引起动脉痉挛和心肌受损。\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0013\u0013\u0018\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0013\u0013\u0018 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0012\u0018\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0012\u0018\n228\n第三篇  循环系统疾病\n6.  肥胖 体重指数 （BMI） = 体重 （kg）/ ［ 身 高（ m） ］\n2\n， BMI 在 24～27.9kg/m\n2\n为超重，≥28kg/m\n2\n为肥胖。肥胖可导致 TG 及胆固醇水平增高， 并常伴发高血压病、 糖尿病或胰岛素抵抗， 导致动脉粥\n样硬化发病率明显增高。\n7.  家族史\n 一级亲属男性 ＜\n55 岁、 女性＜65 岁发生临床 ASCVD 者， 考虑存在早发冠心病家族\n史。常染色体显性遗传所致的家族性高胆固醇血症是这些家族成员常见的患病因素。此外， 近年已\n报道与人类动脉粥样硬化危险因素相关的易感或突变基因有 200 种以上。\n其他的危险因素包括： ①A 型性格者： 精神过度紧张者也易患病， 可能与体内儿茶酚胺类物质浓\n度长期过高有关； ②口服避孕药： 长期口服避孕药可使血压升高、 血脂异常、 糖耐量异常， 同时改变凝\n血机制， 增加血栓形成机会； ③不良生活习惯： 高热量、 高动物脂肪、 高胆固醇、 高糖饮食， 缺乏体力活\n动等； ④睡眠障碍： 包括长期失眠， 睡眠时间不足 （ 每天＜6 小 时）。\n【发病机制】 曾有多种学说从不同角度阐述本病发病机制。近年来比较公认的学说认为， 动脉\n粥样硬化是内皮损伤 （ 形态或功能） 作为始动因素的一种炎症性疾病。\n1856 年德国病理学家 Virchow 即提出动脉粥样硬化是动脉内膜炎症的观点， 1999 年美国华盛顿\n大学医学院 Ross R. 教授在他的 “损伤反应学说” 的基础上明确提出 “动脉粥样硬化是一种炎症性疾\n病”， 其发生发展始终伴随炎症反应。\n正常动脉壁单层内皮细胞组成的内皮层是血液与组织之间的重要屏障。内皮细胞具有抗血栓作\n用， 协助维持血液的流动性； 合成和分泌多种血管活性物质， 如一氧化氮、 内皮素、 前列环素等， 协助\n调节血管平滑肌舒缩功能； 分泌多种细胞因子以调节各种细胞的增殖和游走， ","资料来源":"人卫《内科学》第10版 · 循环.txt · 本节“动脉粥样硬化”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2847,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3a189331875a7e41c21461230ebbb5fdc60c769b731501c3edb11c3e07c2fe05","pinyin":"dongmaizhouyangyinghua","initials":"dmzyyh","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-587a6e3d742456cf9dba","key":"v1-c9ccc21dfe2a3058|templates-587a6e3d742456cf9dba","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"原发免疫性血小板减少症","category":"内科","raw":{"name":"原发免疫性血小板减少症","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者初步诊断原发免疫性血小板减少症，属免疫介导的血小板破坏增多伴生成受抑，入院后需明确血小板减少程度并排除其他原因所致血小板减少。完善血常规加网织红细胞计数检查明确血小板计数水平及有无贫血、白细胞异常，评估出血风险；完善外周血涂片检查排除假性血小板减少，观察血小板形态并排除白血病、微血管病性溶血等；完善凝血功能（PT、APTT、纤维蛋白原）及D-二聚体检查排除凝血因子异常及弥散性血管内凝血；完善骨髓穿刺加骨髓活检及巨核细胞计数检查明确巨核细胞成熟障碍，排除再生障碍性贫血、骨髓增生异常综合征及急性白血病；完善血小板膜糖蛋白特异性抗体及血小板相关抗体检查了解免疫性破坏的依据；完善抗核抗体谱、抗磷脂抗体及狼疮抗凝物检查排除系统性红斑狼疮、抗磷脂综合征等继发性免疫性血小板减少；完善甲状腺功能及抗甲状腺抗体检查排除自身免疫性甲状腺疾病伴发；完善乙肝、丙肝、HIV、EB病毒、巨细胞病毒及幽门螺杆菌检测排除感染相关血小板减少；完善免疫球蛋白及补体检查了解免疫状态；完善腹部超声检查了解脾脏大小，排除脾功能亢进；完善肝肾功能、大便隐血及血型加交叉配血检查，为糖皮质激素、静脉丙种球蛋白或促血小板生成药物治疗及输注支持做准备。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 原发免疫性血小板减少症","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"原发免疫性血小板减少症 （primary immune thrombocytopenia， ITP） 既往也叫特发性血小板减少性\n紫癜， 是一种以血小板过度破坏和血小板生成减少为特点的自身免疫病， 也是临床上最为常见的出血\n性疾病。年发病率约为 （5～10） /10 万， 男女发病率相近， 育龄期女性发病率高于男性， 60 岁以上人\n群的发病率为 60 岁以下人群的 2 倍， 且出血风险随年龄增高而增加。本节主要讲述成人 ITP。\n【病因和发病机制】 病因迄今未明。发病机制如下。\n1.  血小板破坏增加 约\n50%～70% 的 ITP 患者血浆和血小板表面可检测到一种或多种抗血小\n板糖蛋白自身抗体。自身抗体致敏的血小板被单核巨噬细胞系统吞噬破坏。另外， ITP 患者的细胞\n毒性 T 细胞 （CTL） 可直接破坏血小板。\n2.  血小板生成不足 自身抗体可损伤巨核细胞或抑制巨核细胞释放血小板\n， 造成 ITP 患者血小\n板生成不足； 活化的 CTL 细胞可通过抑制巨核细胞凋亡使血小板生成障碍。另外， ITP 患者血浆血小\n板生成素 （thrombopoietin， TPO） 水平相对不足是血小板生成减少的另一重要机制。\n【临床表现】 \n1.  反复的皮肤黏膜出血 表现为皮肤黏膜瘀点\n、 瘀斑， 鼻出血， 牙龈出血， 月经过多及外伤后止\n血不易等， 严重者可发生内脏及颅内出血。部分患者仅有血小板减少而无出血症状。\n2.  乏力\n 部分患者有明显的乏力症状。\n3. \n其他\n 出血过多或长期月经过多可出现失血性贫血。\n【实验室检查】 \n1. \n血常规\n 血小板计数减少\n， 血小板平均体积偏大。部分患者可有正细胞或小细胞低色素性贫\n血。血细胞形态无异常。\n2.  出、 凝血及血小板功能检查 凝\n血功能正常， 出血时间延长， 束臂试验阳性。血小板功能一般\n正常。\n3.  骨髓象\n 骨髓巨核细胞数正常或增加\n； 巨核细胞成熟障碍， 幼稚巨核细胞增加， 产板型巨核细\n胞显著减少。\n4.  血清学检查 T\nPO 水平正常或轻度升高。约 70% 的患者抗血小板糖蛋白自身抗体阳性。伴\n自身免疫性溶血性贫血 （Evans 综合征） 的患者 Coombs 试验可阳性， 血清胆红素水平升高。\n【诊断与鉴别诊断】 \n（ 一）  诊断要点  ITP 目前仍是临床排除性诊断， 诊断要点有： ①至少 2 次检查血小板计数减少，\n血细胞形态无异常； ②体检脾一般不大； ③骨髓检查巨核细胞数正常或增多， 有成熟障碍； ④排除其他\n继发性血小板减少症。\n出血程度分级： 患者出血评分系统量化 ITP 患者出血情况， 以及进行风险评估。该系统分为年龄和出血症状两个部分。 ITP 患者的出血评分 = 年龄评分\n +\n出血症状评分 （ 所有出血症状中最高的分值）。\n（ 二）  鉴别诊断  须排除假性血小板减少； 遗传性或先天性血小板减少综合征； 继发性血小板减\n少症， 如再生障碍性贫血、 脾功能亢进、 骨髓增生异常性肿瘤、 白血病、 系统性红斑狼疮、 药物性免疫性\n血小板减少等。\n（ 三）  分型与分期\n1.  新诊断的 ITP 指确诊后 3 个月以内的 ITP 患者。\n5-6篇.indd 6225-6篇.indd 622 2024/7/28 10:28:132024/7/28 10:28:13\n第十五章  紫癜性疾病\n623\n2.  持续性 ITP 指确诊后 3～12 个月血小板持续减少的 ITP 患者。\n3.  慢性 ITP\n 指血小板减少持续超过\n12 个月的 ITP 患者。\n4.  重症 ITP\n 指血小板\n＜10 × 10\n9\n/L， 伴活动性出血， 或出血评分≥5 分。\n5.  难治性 ITP\n 指对一线治疗药物\n、 二线治疗中的促血小板生成药物及利妥昔单抗治疗均无\n效， 或脾切除无效\n /\n 术后复发，\n进行诊断再评估仍确诊为 ITP 的患者。\n【治疗】 ITP 目前尚无根治的方法， 治疗应以毒性最小为目标， 维持血小板在安全水平以上， 减\n少和预防出血， 提高患者生活质量， 治疗过程中应遵循个体化原则， 兼顾患者意愿， 实行个体化治疗。\n对于无明显出血倾向， 血小板计数高于 30 × 10\n9\n/L， 并且无手术、 创伤， 不从事增加出血风险的工作或活\n动的 ITP 患者， 发生出血的风险较小， 可予以观察随访。若患者有活动性出血 （ 出血症状评分≥2 分），\n不论血小板减少程度如何， 都应给予治疗。\n（ 一）  一般治疗  有明显出血倾向者， 应严格卧床， 避免使用任何引起或加重出血的药物， 禁用抗\n血小板药物， 有效地控制高血压及避免创伤等。\n（ 二）  急症处理  用于血小板低于 10 × 10\n9\n/L 伴广泛、 严重出血者； 疑有或已发生颅内出血者； 近\n期将实施手术或分娩者。\n1.  静脉输注免疫球蛋白（IVIG） 400mg/\n（kg · d） × 5 天； 或 1.0g/ （kg · d） × 2 天。\n2.  大剂量甲泼尼龙\n 1g/d，\n静脉滴注 3 天， 随后逐渐减量。\n3.  促血小板生成药物\n 如重组人血小板生成素\n（rhTPO）、 艾曲泊帕 （eltrombopag）、 海曲泊帕及罗\n普司亭 （romiplostim） 等。\n4.  血小板输注\n5.  其他\n 如长春碱类药物、\n急症脾切除等。\n病情危急者可联合患者以上治疗措施。\n（ 三）  新诊断患者的一线治疗\n1.  糖皮质激素 一般为首选治疗。\n（\n1） 大剂量地\n塞米松 （HD-DXM） ： 40mg/d × 4 天， 无效者 10 天后可重复一次。高龄、 糖尿病、 高血\n压、 青光眼等患者应慎用。\n（2） 泼\n尼松： 1mg/ （kg · d）， 最大剂量 80mg/d， 起效后应尽快减量， 6～8 周内停用。如需维持治疗，\n安全剂量不宜超过 5mg/d。2 周内泼尼松治疗无效者应尽快减停。\n2.  IVIG\n 用法同急症处理\n， 主要用于： ①ITP 的急症处理； ②不能耐受肾上腺糖皮质激素或者脾\n切除前准备； ③合并妊娠或分娩前。IgA 缺乏和肾功能不全者慎用。\n（ 四）  ITP 的二线治疗  ","资料来源":"人卫《内科学》第10版 · 血液.txt · 本节“原发免疫性血小板减少症”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2848,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"422202c09e0a1ca70b824173dbd566ac7fab88faf62b623aa957b55766017677","pinyin":"yuanfamianyixingxuexiaobanjianshaozheng","initials":"yfmyxxxbjsz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-db2ad393407a0206e95b","key":"v1-c9ccc21dfe2a3058|templates-db2ad393407a0206e95b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"原发性慢性肾上腺皮质功能减退症","category":"内科","raw":{"name":"原发性慢性肾上腺皮质功能减退症","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者初步诊断原发性慢性肾上腺皮质功能减退症，属肾上腺皮质破坏致皮质醇及醛固酮分泌不足，入院后需明确诊断、定位病因并评估肾上腺危象风险。入院即刻完善晨8时血皮质醇及促肾上腺皮质激素（ACTH）测定明确肾上腺皮质功能状态并判断病变位于肾上腺抑或垂体，原发性者表现为皮质醇降低而ACTH升高；完善快速ACTH兴奋试验了解肾上腺皮质储备功能，明确诊断；完善血电解质（钠、钾、氯）及血气分析检查了解有无低钠高钾及代谢性酸中毒，评估盐皮质激素缺乏程度；完善空腹血糖及糖化血红蛋白检查了解有无低血糖；完善24小时尿游离皮质醇及皮质醇节律检查进一步明确诊断；完善血浆肾素活性、血管紧张素及醛固酮测定评估盐皮质激素缺乏；完善肾上腺CT检查明确肾上腺形态，鉴别自身免疫性萎缩、结核、出血或转移性病变；完善胸部X线或CT检查排除肺结核；完善抗21羟化酶抗体检查明确自身免疫性病因；完善甲状腺功能及性激素检查排除多腺体自身免疫综合征；完善血常规、肝肾功能、红细胞沉降率及C反应蛋白检查评估全身状况；完善心电图检查了解有无高钾血症所致心律失常及低电压表现。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 原发性慢性肾上腺皮质功能减退症","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"原发性慢性肾上腺皮质功能减退症 （chronic adrenocortical  hypofunction）， 又称 Addison 病， 是由双\n侧肾上腺的绝大部分被毁所致， 主要表现为糖、 盐皮质激素分泌不足。继发性者由下丘脑 \n- 垂体病变\n引起，\n盐皮质激素分泌不受影响。\n\u0018௉\u000fJOEE\u0001\u0001\u0001\u0018\u0012\u0016\u0018௉\u000fJOEE\u0001\u0001\u0001\u0018\u0012\u0016 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u0019\u001b\u0016\u0015\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u0019\u001b\u0016\u0015\n716\n第七篇   内分泌和代谢性疾病\n【病因】\n1.  感染  肾上腺结核为常见病因， 常先有或同时有肺、 肾、 肠等其他部位结核病灶。肾上腺被上\n皮样肉芽肿及干酪样坏死病变所替代， 继而出现纤维化病变， 肾上腺钙化常见。肾上腺真菌感染的病\n理过程与肾上腺结核相近。艾滋病后期可伴有肾上腺皮质功能减退， 多为隐匿性， 一部分可有明显临\n床表现。坏死性肾上腺炎常由巨细胞病毒感染引起。严重脑膜炎奈瑟菌感染可引起急性肾上腺皮质\n功能减退症。严重败血症， 尤其于儿童可引起肾上腺内出血伴功能减退。\n2.  自身免疫性肾上腺炎  两侧肾上腺皮质被毁， 呈纤维化， 伴淋巴细胞、 浆细胞、 单核细胞浸润，\n髓质一般不受累。大多数患者血中可检出抗肾上腺的自身抗体。近半数患者伴其他器官特异性自\n身免疫病， 称为自身免疫性多内分泌腺体综合征 （autoimmune\n polyendocrine\n syndrome，\nAPS）， 多见于\n女性； 而不伴其他内分泌腺病变的单一性自身免疫性肾上腺炎多见于男性。APSⅠ型见于儿童， 主要\n表现为肾上腺功能减退、 甲状旁腺功能减退、 黏膜皮肤白念珠菌病、 卵巢早衰， 呈常染色体隐性遗传。\nAPSⅡ型见于成人， 主要表现为肾上腺功能减退、 自身免疫性甲状腺疾病、 1 型糖尿病， 呈显性遗传。\n3.  其他较少见病因  恶性肿瘤转移、 淋巴瘤、 白血病浸润、 淀粉样变性、 双侧肾上腺切除、 放射治\n疗破坏、 肾上腺酶系抑制药如美替拉酮、 氨鲁米特、 酮康唑或细胞毒性药物如米托坦 （o， p’-DDD） 的长\n期患者、 血管栓塞等。\n肾上腺脑白质营养不良症 （ adrenoleukodystrophy） 为先天性长链脂肪酸代谢异常疾病， 脂肪酸\nβ- 氧化受阻\n， 累及神经组织与分泌类固醇激素的细胞， 致肾上腺皮质及性腺功能低下， 同时出现神经\n损害。\n【临床表现】  最具特征者为全身皮肤色素加深， 暴露处、 摩擦处、 乳晕、 瘢痕等处尤为明显， 黏膜\n色素沉着见于齿龈、 舌部、 颊黏膜等处， 是垂体 ACTH、 黑素细胞刺激素分泌增多所致。\n其他症状包括： ①神经、 精神系统： 乏力， 淡漠， 易疲劳， 重者嗜睡、 意识模糊， 可出现精神失常。\n②胃肠道： 食欲减退， 嗜咸食， 胃酸过少， 消化不良； 有恶心、 呕吐、 腹泻者， 提示病情加重。③心血管系\n统： 血压降低， 心脏缩小， 心音低钝； 可有头昏、 眼花、 直立性昏厥。④代谢障碍： 糖异生作用减弱， 可出\n现低血糖症状。⑤肾： 排泄水负荷的能力减弱， 在大量饮水后可出现稀释性低钠血症； 糖皮质激素缺\n乏及血容量不足时， 抗利尿激素释放增多， 也是造成低血钠的原因。⑥生殖系统： 女性阴毛、 腋毛减少\n或脱落、 稀疏， 月经失调或闭经， 但病情轻者仍可生育； 男性常有性功能减退。⑦对感染、 外伤等各种\n应激的抵抗力减弱。⑧如病因为结核且病灶活跃， 或伴有其他脏器活动性结核者， 常有低热、 盗汗等\n症状， 体质虚弱， 消瘦更严重。\n肾上腺危象： 为本病急骤加重的表现。常发生于感染、 创伤、 手术、 分娩、 过劳、 大量出汗、 呕吐、 腹\n泻、 失水或突然中断糖皮质激素治疗等应激情况下。表现为恶心、 呕吐、 腹痛或腹泻、 严重脱水、 血压\n降低、 心率快、 脉细弱、 精神失常， 常有高热、 低血糖症、 低钠血症， 血钾可低可高。如不及时抢救， 可发\n展至休克、 昏迷、 死亡。\n【实验室检查】\n（ 一）  血液生化  可有低血钠、 高血钾。脱水严重时低血钠可不明显， 高血钾一般不重， 如十分明\n显须考虑肾功能不全或其他原因。少数患者可有轻度或中度高血钙 （ 糖皮质激素有促进肾、 肠排钙作\n用）， 如有低血钙和高血磷则提示同时合并有甲状旁腺功能减退症。脱水明显时有氮质血症， 可有空\n腹低血糖， 糖耐量试验示低平曲线。\n（ 二）  血常规检查  常有正细胞正色素性贫血， 少数患者合并有恶性贫血。白细胞分类示中性粒\n细胞减少， 淋巴细胞相对增多， 嗜酸性粒细胞明显增多。\n（ 三）  激素检查\n1.  基础血、 尿皮质醇， 尿 17- 羟皮质类固醇测定   常降低， 但也可接近正常。\n2.  血浆基础 ACTH 测定  明显增高， 超过 55pmol/L， 常介于 88～440pmol/L （ 正常人低于 18pmol/L），\n而继发性肾上腺皮质功能减退者 ACTH 浓度降低。\n\u0018௉\u000fJOEE\u0001\u0001\u0001\u0018\u0012\u0017\u0018௉\u000fJOEE\u0001\u0001\u0001\u0018\u0012\u0017 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u0019\u001b\u0016\u0015\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u0019\u001b\u0016\u0015\n第七章   肾上腺疾病\n717\n3.  血醛固酮、 肾素测定  原发性肾上腺皮质功能减退症患者血醛固酮可低于正常或在正常低\n限， 而血浆肾素活性升高； 继发性肾上腺皮质功能减退症者血肾素活性、 醛固酮水平正常。\n4.  ACTH 兴奋试验  在静脉注射人工合成 ACTH （1 -24） 250 μ g 前及后 30 分钟、 60 分钟测血皮\n质醇， ACTH 兴奋后血皮质醇峰值＜500nmol/L 提示为肾上腺皮质功能减退。对于病情较严重、 疑有\n肾上腺皮质功能不全者， 同时静脉注射 （ 或静脉滴注） 地塞米松及 ACTH， 在注入 ACTH 前、 后测血浆\n皮质醇， 如此既可进行诊断检查， 又可同时开始治疗。\n（ 四）  影像学检查  结核病患者 X 线片、 CT 或 MRI 可示肾上腺增大及钙化阴影。其他感染、 出\n血、 转移性病变在 CT 扫描时也显示肾上腺增大， 而自身免疫病所致者肾上腺不增大。\n【诊断与鉴别诊断】  本病需与一些慢性消耗性疾病相鉴别。最具诊断价值者为 ACTH 兴奋试\n验， 本病患","资料来源":"人卫《内科学》第10版 · 内分泌.txt · 本节“原发性慢性肾上腺皮质功能减退症”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2849,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4f66611d049dd4493ee726e07c51f2d65172b72dfb389f12c42db6245d7f35a0","pinyin":"yuanfaxingmanxingshenshangxianpizhigongnengjiantuizheng","initials":"yfxmxssxpzgnjtz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-2fbcbb6c669dc74aa100","key":"v1-c9ccc21dfe2a3058|templates-2fbcbb6c669dc74aa100","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"多发性内分泌腺瘤病","category":"内科","raw":{"name":"多发性内分泌腺瘤病","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者初步诊断多发性内分泌腺瘤病，属常染色体显性遗传的多腺体肿瘤综合征，入院后需系统筛查各内分泌腺体的功能与占位，并明确基因型。完善血钙、血磷及甲状旁腺激素测定明确有无甲状旁腺功能亢进，必要时行甲状旁腺超声及99mTc-MIBI核素显像明确病变位置；完善胃泌素测定及胃镜检查排除胃泌素瘤所致卓-艾综合征；完善空腹血糖、胰岛素及C肽测定，必要时行饥饿试验排除胰岛素瘤所致低血糖；完善血、尿甲氧基肾上腺素及去甲氧基肾上腺素测定排除嗜铬细胞瘤，因本病若合并嗜铬细胞瘤，术前必须先行排查以免术中发生血压危象；完善降钙素测定及甲状腺彩超检查排除甲状腺髓样癌；完善血皮质醇、ACTH及肾上腺CT检查排除肾上腺病变；完善垂体MRI及生长激素、胰岛素样生长因子1、泌乳素测定排除垂体腺瘤；完善腹部增强CT或MRI及超声内镜检查明确胰腺神经内分泌肿瘤的部位与数目；完善血醛固酮及肾素测定排除原发性醛固酮增多症；完善MEN1及RET原癌基因检测明确基因突变类型，为家系筛查与长期随访提供依据。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 多发性内分泌腺瘤病","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"多发性内分泌腺瘤病 （multiple endocrine  neoplasia， MEN） 为一组遗传性多种内分泌器官发生的\n肿瘤综合征的总称， 有 2 个或 2 个以上的内分泌腺体累及。肿瘤可为良性或恶性， 可为功能性 （ 分泌\n活性激素并造成特征性临床表现） 或无功能性， 可同时出现或先后发生， 间隔期长短不一， 病情轻重及\n病程缓急均存在较大异质性。MEN 可分为两种类型： 多发性内分泌腺瘤病 1 型 （MEN1） 及多发性内\n分泌腺瘤病 2 型 （MEN2）， 后者又分为 2 种亚型： MEN2A、 MEN2B。此外， 还有不能归属于 MEN1 或\nMEN2 的混合型 MEN。\n一、   多发性内分泌腺瘤病 1 型\nMEN1 为常染色体显性遗传疾病， 又称 Wermer 综合征， 在普通人群中患病率约为 （ 2～20） /10 万。\nMEN1 患者中约 10% 的基因突变属新出现的， 称为散发性。MEN1 可有多种临床表现， 其发生率在不\n同家系及同一家系不同患者中变化不一。\n【发病机制】  MEN1 基因位于第 11 号染色体， 11q13 带， 编码含 610 个氨基酸的蛋白质， 称为 “多\n发性内分泌腺瘤蛋白” （menin）。MEN1 为抑癌基因， 基因缺陷的性质多样化。除全身细胞的基因缺\n陷， 在 MEN1 肿瘤组织中发现MEN1 另一等位基因也发生缺失，MEN1 两个等位基因功能均丧失导致\n细胞增殖， 发生肿瘤， 这一现象符合两次打击致肿瘤抑制基因功能丧失致瘤的学说。约 20% 散发性\n甲状旁腺腺瘤及一部分散发性胰腺内分泌癌、 肺类癌亦可出现MEN1 基因突变， 但此种突变只发生于\n肿瘤组织而不见于患者的正常细胞， 故不形成疾病家族性集聚现象。\n【临床表现】\n1.  甲状旁腺功能亢进症  为 MEN1 中最常见且最早出现的病变，与腺瘤所致散发性甲旁亢病例\n相比较， 起病较早 （20 余岁）， 男女发病率相仿， 在病理上为多个甲状旁腺增生， 大小可不一致。诊断\n依据与一般散发病例相同。甲旁亢所致高钙血症可加重同时并存胃泌素瘤患者的症状， 血胃泌素水\n平更高。\n2.  肠胰内分泌瘤  可为功能性或无功能性， 包括以下肿瘤： 胃泌素瘤， 常伴 Zollinger-Ellison 综合\n征， 约占 MEN1 中肠胰瘤的 50%～60%。此种胃泌素瘤的特点为体积小、 多中心性， 且可为异位性， 位\n于十二指肠黏膜下。诊断依据为同时存在高胃泌素血症及高胃酸分泌， 据此可与常见的胃酸缺乏症\n伴高胃泌素血症相鉴别。必要时可做胰泌素 （secretin） 兴奋试验， 胃泌素瘤患者血浆胃泌素升高。由\n于 MEN 中胃泌素瘤体积小， 其定位诊断较困难， CT 及 MRI 可检出肝转移性病灶， 但对胃泌素瘤往往\n难以确诊， 进一步定位方法包括超声内镜、 选择性动脉注射胰泌素后肝静脉采血测胃泌素， 以及放射\n性核素标记奥曲肽扫描等。MEN1 中胰岛素瘤发生率约占起源于胰岛肿瘤的 20 %， 其余的为胰高血\n糖素瘤、 舒血管肠肽瘤及无功能瘤。MEN1 中胰岛素瘤亦常为多中心性， 定位亦较困难， 超声内镜检\n查、 选择性滴注钙剂后肝静脉采血测胰岛素等有助于定位。\n3.  垂体瘤  发生率约为 25 %， 大多为催乳素瘤， 可伴或不伴生长激素分泌增多， 其次为生长激素\n瘤、 无功能瘤及 ACTH 瘤伴库欣综合征。MEN1 中垂体瘤甚少为恶性， 其诊断、 治疗与散发病例相同。\n4.  肾上腺腺瘤及其他病变   分泌皮质醇的腺瘤可见于 MEN1， MEN1 中出现库欣综合征有 3 种\n\u0018௉\u000fJOEE\u0001\u0001\u0001\u0018\u001a\u0016\u0018௉\u000fJOEE\u0001\u0001\u0001\u0018\u001a\u0016 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u001a\u001b\u0011\u0017\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u001a\u001b\u0011\u0017\n796\n第七篇   内分泌和代谢性疾病\n可能性： ①肾上腺腺瘤； ②垂体 ACTH 瘤； ③类癌伴异位 ACTH 综合征， 以垂体瘤较多见。在 MEN1 中\n甲状腺腺瘤及其他甲状腺疾病亦较为多见。在 MEN1 的家族成员中， 出现皮下脂肪瘤、 皮肤胶原瘤及\n多发性面部血管纤维瘤者约占 30 %～90%， 此类表现有助于对这些个体进行筛查， 以明确携带 MEN1\n缺陷基因者。\n【治疗】  MEN1 中甲状旁腺功能亢进症的治疗为切除 3 个甲状旁腺， 余下的那 1 个切除一半， 留\n下半个甲状旁腺； 也有主张做 4 个甲状旁腺全切除的， 将外表上最接近正常的 1 个腺体的一半移植于\n一侧习惯上非主要使用的前臂肌肉中。手术治疗后甲旁亢持续存在或复发的频率均明显高于散发性\n甲旁亢患者。术后甲旁亢持续存在， 即血钙与血甲状旁腺激素均未恢复正常者占 36%； 复发者， 指血\n钙恢复正常 3 个月以上甲旁亢又复发者占 16 %； 而散发病例术后疾病持续存在及复发者分别占 4%\n及 16%。MEN1 中手术后甲旁亢持续存在发生率高的一个原因是甲状旁腺不止 4 个， 或有异位的甲\n状旁腺组织； 复发率高是由于剩余的甲状旁腺组织继续受到促进生长的刺激。\n【筛查】  对 MEN1 患者的家族成员应做全面的病史采集及体检。重要的实验室检查为血钙浓度\n测定， 或做血总钙测定加血浆蛋白测定作校正， 从 15 岁起开始定期检查。此外， 催乳素、 胃泌素及空\n腹血糖测定也有助于诊断， 有条件可进行MEN1 基因突变检测。\n二、   多发性内分泌腺瘤病 2 型\nMEN2 为一常染色体显性遗传病。其患病率约占普通人群的 （1～10） /10 万， 携带有 MEN2 缺陷\n基因者， 其疾病外显率高于 80%。MEN2 可分为两种独立的综合征： MEN2A （ 又称 Sipple 综合征） 及\nMEN2B。MEN2A 的临床表现包括甲状腺髓样癌、 嗜铬细胞瘤及甲状旁腺功能亢进症； MEN2B 则包括\n甲状腺髓样癌、 嗜铬细胞瘤等， 但甲状旁腺功能亢进症少见。\n【发病机制】  MEN2 的发病机制是原癌基因 RET 发生突变。RET 为一单链穿膜含酪氨酸激酶\n的蛋白， 在许多起源于神经嵴的细胞 （ 如甲状腺、 肾上腺、 肠内部神经系统等） 中表达， 在机体的发育\n上起重要作用。RET 结构上的特征是在其胞外区域近细胞膜处聚集有","资料来源":"人卫《内科学》第10版 · 内分泌.txt · 本节“多发性内分泌腺瘤病”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2850,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a298f5e58aae25d7ad60fbae8ec039822213182f49e7a1994b93674fa3d0e4ca","pinyin":"duofaxingneifenmixianliubing","initials":"dfxnfmxlb","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-c787077affc450be4404","key":"v1-c9ccc21dfe2a3058|templates-c787077affc450be4404","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"多瓣膜病","category":"内科","raw":{"name":"多瓣膜病","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者初步诊断多瓣膜病，需明确各瓣膜病变的性质、程度及心功能状态，为手术时机判断提供依据。完善心脏彩超加左心功能测定检查明确各瓣膜狭窄或关闭不全的程度、跨瓣压差、瓣口面积、心室壁运动、射血分数及肺动脉压力，评估瓣膜病变与心室重构情况；完善经食管超声心动图检查明确有无瓣周病变、附壁血栓及赘生物，为术前评估提供更精准的信息；完善NT-ProBNP检查明确有无心力衰竭及其严重程度；完善心电图及24小时动态心电图检查了解有无心房颤动、传导阻滞及心室肥厚；完善胸部X线检查了解心影形态及肺淤血情况；完善血常规检查排除贫血及感染，因贫血可加重心脏负荷；完善红细胞沉降率、C反应蛋白及多次血培养检查排除感染性心内膜炎及风湿活动；完善抗链球菌溶血素O、类风湿因子及免疫球蛋白、补体检查了解风湿性病因；完善肝肾功能、凝血功能、电解质及血气分析检查评估药物代谢、利尿剂所致电解质紊乱及手术耐受性；完善甲状腺功能检查排除甲状腺功能亢进所致高动力循环；必要时完善冠状动脉CTA或冠状动脉造影检查明确有无合并冠心病，为瓣膜手术前评估提供依据。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 多瓣膜病","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"多瓣膜病 （multivalvular heart disease） 又称联合瓣膜病， 是指两个或两个以上瓣膜病变同时存在。\n【病因】 引起多瓣膜病的病因， 多数为单一病因， 少数为多种病因引起。\n1.  一种疾病同时损害几个瓣膜 最常见为风湿性心脏病\n， 近一半病人有多瓣膜损害。其次为老\n年退行性改变、 黏液样变性， 可同时累及二尖瓣和三尖瓣， 两者可同时发生脱垂。感染性心内膜炎也\n可累及多瓣膜。\n2.  一个瓣膜病变致血流动力学异常引起邻近瓣膜相对性狭窄或关闭不全 如主动脉瓣膜反流\n使左心室容量负荷过度而扩大，\n产生相对性二尖瓣关闭不全。\n3.  不同疾病分别导致不同瓣膜损害\n 如先天性肺动脉瓣狭窄伴风湿性二尖瓣病变。\n【\n病理生理和临床表现】 取决于受损瓣膜的组合形式和各瓣膜受损的相对严重程度。虽然某一\n瓣膜的损害可能减轻或抵消另一瓣膜病变的血流动力学变化， 从而减轻临床症状， 但总的来说， 多瓣膜\n病变在病理生理上往往可使病情加重， 对心功能造成综合性不良影响。常见的多瓣膜病有以下几种。\n1.  二尖瓣狭窄伴主动脉瓣反流 常见于风湿性心脏病\n， 二尖瓣狭窄可使左心室扩张延缓， 周围\n血管征不明显， 听诊二尖瓣舒张期杂音可减弱， 甚至消失。\n2.  二尖瓣狭窄伴主动脉瓣狭窄 若二尖瓣狭窄重于主动脉瓣狭窄\n， 后者的一些表现常被掩盖，\n左心室充盈受限和左心室收缩压降低， 延缓左心室肥厚和减少心肌耗氧， 故心绞痛不明显； 由于心排\n血量明显减少， 跨主动脉瓣压差降低， 可能导致低估主动脉瓣狭窄的严重程度。\n3.  主动脉瓣狭窄伴二尖瓣反流 为危险的多瓣膜病\n， 相对较少见。前者加重二尖瓣反流， 后\n者减少了主动脉瓣狭窄维持左心室每搏容量必需的前负荷， 致使肺淤血早期发生， 短期内产生左心\n衰竭。\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0014\u0012\u0013\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0014\u0012\u0013 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0013\u001a\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0013\u001a\n第八章  心脏瓣膜病\n313\n4.  二尖瓣反流伴主动脉瓣反流 左心室承受双重容量过度负荷， 使左心室舒张期压力明显上\n升， 可进一步加重二尖瓣反流， 较早发生左心室衰竭。\n5.  二尖瓣狭窄伴三尖瓣和\n /\n 或肺动脉瓣反流\n 常见于晚期风湿性心脏病二尖瓣狭窄病人。\n【\n诊断及治疗】 诊断多瓣膜病必须仔细， 超声心动图对诊断及评价心功能具有重要价值， 必要时\n可行左心及右心导管术， 以仔细评估瓣膜功能。多瓣膜病内科治疗同单瓣膜损害者， 手术治疗为主要\n措施。双瓣膜置换术较单瓣膜置换术有更高的手术死亡率及远期死亡率， 手术治疗前应仔细分析各\n瓣膜治疗的利弊。外科手术禁忌而考虑经皮介入治疗时， 建议分期手术。","资料来源":"人卫《内科学》第10版 · 循环.txt · 本节“多瓣膜病”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2851,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6e66e08456e85fd4c80a99656cd1d6cb5b8232dcd33e6b2d355c83e9122f8904","pinyin":"duobanmobing","initials":"dbmb","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-3ca3dd7fcd6c01b5dc2e","key":"v1-c9ccc21dfe2a3058|templates-3ca3dd7fcd6c01b5dc2e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"室性心律失常","category":"内科","raw":{"name":"室性心律失常","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者初步诊断室性心律失常，需明确心律失常类型、负荷、起源及有无结构性心脏病，以决定治疗策略。入院即刻完善十二导联心电图检查明确室性早搏形态、数目及QT间期，判断起源部位与有无恶性预警征象；完善24小时动态心电图检查了解室性早搏负荷及有无成对、短阵或非持续性室性心动过速；完善心脏彩超加左心功能测定检查明确有无结构性心脏病、心室壁运动异常及射血分数，因射血分数是决定是否植入埋藏式心脏复律除颤器的关键依据；完善心肌酶及高敏肌钙蛋白检查排除急性心肌损伤、心肌炎所致心律失常；完善电解质（钾、钠、氯、镁、钙）及血气分析检查排除电解质紊乱所致心律失常；完善甲状腺功能检查排除甲状腺功能亢进；完善血常规、肝肾功能检查评估抗心律失常药物代谢及用药安全；完善冠状动脉CTA或冠状动脉造影检查明确有无缺血性病因；完善心脏磁共振检查明确有无心肌瘢痕、致心律失常性右室心肌病或其他心肌病；完善运动负荷试验了解运动诱发室性心律失常的情况；病情需要时完善心内电生理检查明确发病机制，为射频消融治疗提供依据。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 室性心律失常","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"一、  室性期前收缩\n室性期前收缩 （premature ventricular beat）也称室性早搏， 简称室早， 是一种最常见的心律失常，\n指希氏束以下部位心室兴奋灶提前除极而产生的过早搏动。\n【病因】 常见于各种器质性心脏病， 如高血压、 冠心病、 心肌病、 心肌炎及瓣膜性心脏病等。也可\n见于心脏结构与功能正常者， 在情绪紧张、 过度劳累、 过量烟酒或咖啡， 以及电解质紊乱等情况下可诱\n发室早。某些药物因素， 如洋地黄类药物、 奎尼丁、 三环类抗抑郁药物、 抗肿瘤药物也可引起。\n【临床表现】 室早症状的轻重程度与期前收缩的频发程度不直接相关。病人一般表现为心悸、\n胸闷、 类似失重感或代偿间歇后有力的心脏搏动， 可伴有头晕、 乏力等症状。严重器质性心脏病病人，\n长时间频发室早可产生心绞痛、 低血压或心力衰竭等。听诊时， 期前收缩后可出现较长的停歇， 第二\n心音强度减弱， 仅能听到第一心音， 桡动脉搏动减弱或消失。\n【心电图特征】 ①提前出现的宽大畸形 QRS 波群， 时限常超过 0.12 秒； ②T 波与 QRS 主波方向\n相反； ③室早与其前面的窦性搏动的间期 （ 称为配对间期） 恒定， 后可出现完全性代偿间歇 （ 图 3-3-2 0）。\n图3 -3-20   室性期前收缩\n第\n3、 8 个 QRS 波群提前发生， QRS 波增宽畸形， 其前无 P 波， 其后有完全性代偿间歇。\n室早的类型： 室早可孤立或规律出现。当每个窦性搏动后跟随一个室早称为二联律， 每两个窦性\n搏动后出现一个室早为三联律； 连续发生两个室早称成对室早， 连续三个或以上室早称室性心动过\n速； 如室早恰巧插入两个窦性搏动之间， 不产生期前收缩后停顿， 称为间位性室早； 同一导联内， 室早\n形态相同者， 为单形性室早， 形态不同者称多形性或多源性室早 （ 图 3-3-2 1）。\n【治疗】 首先应对病人室早的类型、 症状及其原有心脏病进行全面评估， 根据不同的临床状况决\n定是否给予治疗， 并制订出合理有效的治疗方案。\n1.  无器质性心脏病 室早不会增加此类病人发生心源性死亡的危险性\n， 如病人无明显症状或症\n状轻微， 不必使用药物治疗。若病人症状明显， 治疗以消除症状为目的， 应特别注意对病人作好耐心\n的解释及关怀， 说明这种情况的良性预后， 减轻病人焦虑与不安； 同时避免诱发因素， 如吸烟、 饮用咖\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0013\u0011\u0019\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0013\u0011\u0019 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0012\u0013\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0012\u0013\n第三章  心律失常\n209\n啡 / 茶、 焦虑及应激等。也可选择β受体拮抗剂、 非二氢吡啶类钙通道阻滞剂、 普罗帕酮等， 联合使用\n中成药如稳心颗粒、 参松养心胶囊等亦具有减少期前收缩和减轻症状的作用。\n2.  器质性心脏病 器质性心脏病合并心功能不全者\n， 原则上只处理心脏本身疾病， 不必患者治\n疗室早的药物。若症状明显， 可选用β受体拮抗剂以及胺碘酮治疗。\n急性心肌缺血合并室早的病人， 首选再灌注治疗， 不主张预防性患者抗心律失常药物。如果实施\n再灌注治疗前已出现频发室早、 多源性室早， 可患者β受体拮抗剂。同时注意纠正诱因， 尤其是电解\n质紊乱如低钾、 低镁血症。避免使用 Ⅰ a 类和 Ⅰ c 类抗心律失常药物， 因这类药物本身具有致心律失常\n作用， 可能导致病人总死亡率和猝死风险增加。\n3.  导管消融 起源于右心室流出道或左心室后间隔的频发室早\n， 若病人症状明显， 抗心律失常\n药物疗效不佳， 或不能耐受药物治疗， 且无明显器质性心脏病， 可考虑导管消融治疗， 成功率较高。起\n源于其他部位的单形性室早， 亦可选择导管消融治疗， 但成功率较低。\n二、  室性心动过速\n室性心动过速 （ventricular tachycardia， VT）简称室速， 是起源于希氏束以下的特殊传导系统或者\n心室肌的连续 3 个或 3 个以上的异位心搏。及时正确地判断和治疗室速具有非常重要的临床意义。\n【病因】 室速常发生于各种器质性心脏病病人。最常见为冠心病， 其次是心肌病、 心力衰竭、 瓣\n膜性心脏病等， 其他病因包括代谢障碍、 电解质紊乱、 洋地黄中毒等。室速偶可发生在无器质性心脏\n病者， 称为特发性室速， 其多起源于右心室流出道 （ 右室特发性室速）、 左心室间隔部 （ 左室特发性室\n速）和主动脉窦部。少部分室速与遗传因素有关， 又称为离子通道病， 如长 QT 间期综合征、 Brugada\n综合征等。\n【临床表现】 室速的临床症状视发作时心室率、 持续时间、 基础心脏病和心功能状况不同而异。\n非持续性室速 （ 发作时间短于 30 秒， 能自行终止） 的病人可无明显症状。持续性室速 （ 发作时间超过\n30 秒， 需药物或电复律终止） 常伴有明显血流动力学障碍与心肌缺血， 临床症状包括低血压、 头晕、 气\n图3 -3-21   室性期前收缩的类型\nA\n. 每个窦性搏动后跟随一个室早， 为二联律； B. 每两个窦性搏动后跟随一个室早， 为三联律； C. 第 3、\n4 个 QRS 波群连续出现， 为成对室早； D. 第 1、 2、 3 个 QRS 波群连续出现， 为短阵室速。E. 第 5、 10 个\nQRS 波群提前发生， 其后无代偿间歇， 为间位性室早； F. 第 2、 4 个 QRS 波群形态不一， 为多形性室早。\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0013\u0011\u001a\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0013\u0011\u001a \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0012\u0013\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0012\u0013\n210\n第三篇  循环系统疾病\n促、 心绞痛和晕厥等。部分多形性室速、 尖端扭转型室速发作后很快蜕变为心室颤动， 导致心源性晕\n厥、 心搏骤停和猝死。\n听诊心律可轻度不规则， 第一、 二心音分裂， 收缩期血压随心搏变化。\n【心电图特征】 ①3 个或以上的室早连续出现； ②心室率常为 100～250 次 / 分； ③节律规则或略\n不规则； ④心房独立活动与 QRS 波无固定关系， 形成房室分离； ⑤偶可见心室激动逆传夺获心房。\n心室夺获与室性融合波： 室速发作时少数室上性冲动可下传心室， 产生心室夺获， 表现为在 P 波\n之后","资料来源":"人卫《内科学》第10版 · 循环.txt · 本节“室性心律失常”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2852,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9e96bc36ab75566914b1e253f85e9b7d474cca4fcb1ba02777dee541dae60d68","pinyin":"shixingxinlvshichang","initials":"sxxlsc","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-4c2b5624a74ae154a7a5","key":"v1-c9ccc21dfe2a3058|templates-4c2b5624a74ae154a7a5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"小动脉性肾硬化症","category":"内科","raw":{"name":"小动脉性肾硬化症","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者初步诊断小动脉性肾硬化症，多为长期高血压所致肾小动脉病变，需评估肾损害程度、排除其他慢性肾脏病并明确血压控制情况。完善尿常规及尿沉渣检查了解有无蛋白尿、血尿及管型；完善尿白蛋白与肌酐比值及24小时尿蛋白定量检查评估肾损害程度及预后；完善血肌酐、尿素氮及估算肾小球滤过率检查明确肾功能分期；完善尿N-乙酰-β-D-氨基葡萄糖苷酶及β2微球蛋白检查了解肾小管损伤情况；完善血电解质及血气分析检查了解有无高钾血症及代谢性酸中毒；完善肾脏彩超检查了解双肾大小、皮质厚度及有无萎缩；完善血常规检查了解有无肾性贫血；完善24小时动态血压监测明确血压水平及昼夜节律，指导降压方案；完善血浆肾素活性、血管紧张素及醛固酮测定排除原发性醛固酮增多症等继发性高血压；完善肾动脉彩超检查排除肾动脉狭窄；完善血糖、糖化血红蛋白及血脂检查评估危险因素；完善眼底检查了解高血压视网膜病变程度；完善心电图及心脏彩超检查了解有无左心室肥厚等高血压心脏损害；必要时完善肾穿刺活检明确病理类型。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 小动脉性肾硬化症","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"小动脉性肾硬化症 （arteriolar nephrosclerosis） 又称高血压肾硬化症 （hypertensive nephrosclerosis），\n临床常见， 是导致终末期肾病的第二位病因 （ 约占 25%）。本病分为良性小动脉性肾硬化症 （benign \narteriolar nephrosclerosis）与恶性小动脉性肾硬化症 （malignant arteriolar nephrosclerosis）。\n一、  良性小动脉性肾硬化症\n【病因】 由长期未控制良好的高血压引起， 高血压持续 5～10 年即可出现良性小动脉性肾硬化\n症的病理改变和相关临床表现。\n【病理】 本病主要影响肾小球前小动脉， 引起入球小动脉玻璃样变， 小叶间动脉及弓状动脉肌内\n膜增厚， 造成动脉管腔狭窄， 供血减少。然后继发缺血性肾实质损害， 致肾小球硬化、 肾小管萎缩及肾\n间质纤维化。\n【临床表现】 肾小管对缺血敏感， 故首先出现肾小管浓缩功能障碍表现， 如夜尿多、 低比重及低\n渗透压尿。当肾小球缺血病变发生后， 尿检可出现轻度异常 （ 轻度蛋白尿， 少量红细胞及管型）， 肾小\n球功能渐进受损， 肾小球滤过率下降， 逐渐进展至终末期肾病。肾损害的同时， 常伴随高血压的眼底、\n心、 脑并发症。\n【防治】 本病应注重预防， 积极治疗高血压， 血压控制达标是防止肾脏损害的关键。合并糖尿病或\n5-6篇.indd 5115-6篇.indd 511 2024/7/28 10:27:582024/7/28 10:27:58\n512\n第五篇  泌尿系统疾病\n有肾损害时， 大多数指南建议的达标血压为＜130/80mmHg。在药物选择上， ACEI/ARB 显示出独立于降\n压之外的肾脏保护效应。良性小动脉性肾硬化症发生后， 控制高血压仍然是延缓肾损害进展的关键。\n二、  恶性小动脉性肾硬化症\n【病因】 恶性小动脉性肾硬化症是恶性高血压引起的肾损害， 属于高血压急症的肾脏表现， 病人\n常同时出现视网膜出血、 脑病等恶性高血压的其他靶器官损害。恶性高血压常发生在高血压病人不\n规律服用降压药， 以及滥用可卡因、 苯丙胺等引起高肾上腺素能状态的药物等情况。\n【病理】 本病主要累及肾小球前小动脉， 但是病变性质及程度与良性小动脉性肾硬化症不同， 表\n现为入球小动脉、 小叶间动脉及弓状动脉的纤维素样坏死， 肾小球塌陷。在小叶间动脉和弓状动脉，\n动脉壁细胞增生， 基质沉积， 出现内膜增厚、 分层， 血管切面呈 “洋葱皮” 样外观， 动脉管腔高度狭窄，\n乃至闭塞， 在受损血管周围有细胞浸润。肾实质病变进展十分迅速， 很快导致肾小球硬化、 肾小管萎\n缩及肾间质纤维化。\n【临床表现】 可出现肉眼或镜下血尿、 蛋白尿等肾炎综合征表现， 肾功能进行性恶化， 常于发病\n数周至数月后出现少尿， 进入终末期肾病。眼底检查可见视盘水肿。同时伴有中枢神经系统受损表现\n（ 如头痛、 惊厥发作甚至昏迷等）和心脏病变 （ 如充血性心力衰竭）， 甚至出现微血管病性溶血性贫血。\n【防治】 恶性高血压是内科急症， 应及时控制严重高血压， 防止威胁生命的心、 脑、 肾并发症发\n生。但血压也不能下降过快、 过低， 应尽可能降低靶器官低灌注的风险。推荐方案是通过静脉用降压\n药， 在治疗开始第 1 小时使血压的降幅不超过初始血压的 20%～25%； 随后的第 2～6 小时， 血压降幅\n维持在初始血压的 25% 左右， 或舒张压 100～110mmHg （ 两项标准参照高值）。收缩压通常在第 1 小\n时降到 160mmHg 左右， 在后面 24 小时缓慢降到 140mmHg 左右。根据病人对降压治疗的耐受度， 接\n下来的 24～48 小时， 将血压控制在 140/90mmHg 以下。\n若恶性小动脉性肾硬化症已发生并已出现肾衰竭， 应及时进行透析治疗。部分病人在血压控制\n后肾血管损害可以得到一定程度恢复， 从而避免维持性透析。","资料来源":"人卫《内科学》第10版 · 泌尿.txt · 本节“小动脉性肾硬化症”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2853,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2284ed203d579d6e24a271491ff2645559fb551595a7c4ba59e5e1b70a00e7ad","pinyin":"xiaodongmaixingshenyinghuazheng","initials":"xdmxsyhz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-2f5fd5c9c470c3cfe90b","key":"v1-c9ccc21dfe2a3058|templates-2f5fd5c9c470c3cfe90b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"常染色体显性遗传性多囊肾病","category":"内科","raw":{"name":"常染色体显性遗传性多囊肾病","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者初步诊断常染色体显性遗传性多囊肾病，属遗传性肾脏囊性疾病，需评估肾脏体积与功能、筛查肾外表现并指导治疗。完善肾脏彩超检查明确双肾囊肿数目、大小及肾脏体积，作为诊断与随访的基础；完善腹部或肾脏CT、MRI检查进一步明确囊肿分布及有无囊内出血、感染或结石，肾功能不全时避免使用增强对比剂；完善尿常规及尿培养检查排除泌尿系感染；完善尿白蛋白与肌酐比值及24小时尿蛋白定量检查评估肾损害程度；完善血肌酐、尿素氮及估算肾小球滤过率检查明确肾功能分期，为托伐普坦等药物治疗提供依据；完善血电解质检查了解有无低钠血症及高钾血症；完善血常规及凝血功能检查了解有无贫血及出凝血异常；完善24小时动态血压监测明确血压水平，指导血管紧张素转换酶抑制剂或血管紧张素受体拮抗剂的使用；完善肝脏彩超或CT检查明确有无多囊肝；完善头颅磁共振血管成像或CT血管成像检查排除颅内动脉瘤，尤其伴家族史者；完善心脏彩超检查明确有无二尖瓣脱垂等心脏瓣膜异常；完善PKD1、PKD2基因检测明确基因型，判断预后并指导家系筛查；必要时对一级亲属行肾脏超声筛查。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 常染色体显性遗传性多囊肾病","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"常染色体显性遗传性多囊肾病 （autosomal dominant polycystic kidney disease， ADPKD） 是最常见的\n单基因遗传性肾病， 患病率为 1/1 0\n00～1/400， 以双肾广泛囊肿形成并进行性增大为主要表现， 最终导\n致肾衰竭。ADPKD 是一种系统性疾病， 除肾脏表现外， 还可伴多种肾外表现， 包括肝囊肿、 颅内动脉\n瘤、 心脏瓣膜异常等。\n【病因和发病机制】 \n1.  分子遗传学机制 ADPKD\n多由位于染色体 16p13.3 的PKD1（ 占发病人数的 85%）和位于染\n色体 4q22-23 的PKD2 基因突变引起。 PKD1和 PKD2 分别编码多囊蛋白 \n-1 （ploycystin-1， PC1）和多\n囊蛋白 \n-2 （ploycystin-2， PC2）， 它们的基因突变可导致肾小管扩张和囊肿形成。\n2.  纤毛致病学说和 “二次打击” 学说 P\nC1和 PC2 蛋白均表达于肾小管上皮细胞初级纤毛， 它\n们的结构和功能异常引起小管上皮细胞异常增生、 囊腔内液体积聚及细胞外基质重建， 直至小管扩张和囊肿形成。在感染、 中毒等后天因素作用下，PKD 杂合子正常等位基因发生体细胞突变， 导致囊肿\n发生和进展， 被称为 “二次打击” 学说。\n【临床表现】 ADPKD 临床表现差异较大， 多为成年发病， 常累及多个器官。\n（ 一）  肾脏表现\n1.  肾囊肿 双肾广泛囊肿形成， 随病程进展不断增多、 增大。部分病人出现腹部肿块， 质硬， 表\n面呈结节状， 随呼吸移动。\n2.  结石\n 约\n20% 的病人合并肾结石， 大多为尿酸和\n /\n 或草酸钙结石。\n3. \n感染\n 是病人发热的首要原因，\n主要表现为膀胱炎、 肾盂肾炎、 囊肿感染以及肾周脓肿。\n4.  囊肿出血和肉眼血尿 由囊壁血管破裂\n、 结石、 感染或癌变引起。约 40% 的病人在病程中出\n现由囊壁血管破裂引起的肉眼血尿， 并反复发作。\n5.  疼痛\n 腰腹部疼痛见于约\n60% 的病人， 是最常见的早期症状之一。急性疼痛可由肾囊肿破\n裂出血、 尿路梗阻或合并感染引起， 慢性疼痛多由增大的肾脏或囊肿牵拉包膜、 肾蒂或压迫邻近组织\n所致。\n6.  高血压\n 是最常见的早期表现之一\n， 见于约 30% 的儿童病人、 约 60% 合并肾衰竭的病人， 在\n终末期肾病病人中高达 80%。\n7.  贫血与其他病因引起的肾衰竭病人相比，\nADPKD 病人的贫血出现晚且程度轻。\n8.  蛋白尿\n 一般为持续性蛋白尿，\n定量多＜1g/24h， 是促进肾功能恶化的重要危险因素。\n9.  慢性肾衰竭\n 60\n岁以上的病人约 50% 进入终末期肾病。\n（ 二）  肾外表现\n1.  囊性病变 可累及肝、 胰、 脾、 卵巢、 蛛网膜及松果体等。其中肝囊肿发生率最高， 但肝功能异\n常少见。\n2.  非囊性病变 包括心脏瓣膜异常\n、 结肠憩室、 颅内动脉瘤和腹壁疝等。颅内动脉瘤是最主要\n的早期死亡原因， 少数病人存在血管痉挛性头痛。约 30% 的病人可发生二尖瓣脱垂。\n【诊断】 ADPKD 诊断主要依据家族史、 临床表现、 影像学检查和基因检测。\n5-6篇.indd 5135-6篇.indd 513 2024/7/28 10:27:582024/7/28 10:27:58\n514\n第五篇  泌尿系统疾病\n（ 一）  临床诊断标准  ADPKD 诊断标准分为主要诊断标准和次要诊断标准， 见表 5-8-1， 只要同\n时符合主要诊断标准和任意一项次要诊断标准即可确诊。\n表5 -8-1   ADPKD 临床诊断标准\n主要诊断标准 次要诊断标准\n肾皮、 髓质布满多个液性囊肿\n明确的 ADPKD 家属遗传史\n多囊肝\n肾衰竭\n心脏瓣膜异常\n结肠憩室\n颅内动脉瘤\n腹壁疝\n胰腺囊肿\n（ 二）  诊断方法\n1.  家族史 病人常有明确的家族遗传史， 呈常染色体显性遗传特征， 子代发病率为约 50%，男 女\n均等。\n2.  影像学检查\n 超声、\nCT和 MRI 均可用于诊断。\n（1） 超声\n： 是首选的诊断方法， 经济且安全， 判断标准见表 5-8-2。彩超表现为肾内数个大小不等\n的囊肿， 囊壁间有花色血流。\n表5 -8-2   ADPKD 的超声诊断和排除标准\n标准\n年龄\n /\n 岁\n15\n～＜40 40～＜60 ≥60\n诊断标准 单 / 双侧肾囊肿≥3个 每侧肾囊肿≥2个 每侧肾囊肿≥4个\n排除标准 无 每侧肾囊肿＜2个 每侧肾囊肿＜2个\n（2） CT： 肾脏体积增大， 双肾广泛大小不等的囊肿， CT 值 8～20Hu 之间。\n（3） M\nRI： 精确度高， 判断标准见表 5-8-3。通过 MRI 方法计算囊肿与正常肾组织截面积比值， 能\n客观量化 ADPKD 的进展速度。\n表5 -8-3   ADPKD 的 MRI 诊断和排除标准\n标准 肾囊肿个数 标准 肾囊肿个数\n诊断标准 肾囊肿总数≥10 个 排除标准 肾囊肿总数＜5个\n（ 三）  基因检测  以下情况可考虑基因检测： ①无明确家族遗传史的散发病例； ②影像学不典型或与\n其他囊性肾病鉴别困难时； ③生殖咨询； ④儿童疑似病人的早期诊断； ⑤家族史阳性的活体肾脏捐献者。\n【鉴别诊断】 ADPKD 需要与以下囊肿性肾病进行鉴别诊断。\n1.  常染色体隐性遗传多囊肾病 （autosomal recessive polycystic kidney disease， ARPKD） 新\n生儿\n患病率约为 1/26\n 500，与单基因 PKHD1 基因突变有关。大多数病人出生时就患有肾衰竭或已进入到\n终末期肾病， 并伴有先天性肝纤维化和先天性肝内胆管囊状扩张症 （Caroli 病）。\n2.  多囊性肾发育不良 是婴儿最常见的囊肿性肾病\n， 存活者多为单侧病变， 发育不良的一侧肾\n脏广泛囊肿形成， 无泌尿功能。对侧肾脏可无囊肿， 常代偿性肥大或因输尿管梗阻而出现积水。\n3.  单纯性肾囊肿（simply renal cyst， SRC） 约\n50% 的病人 40 岁以后发病， 发病率随年龄增长而\n上升。一般无家族史， 肾脏体积正常， 典型肾囊肿为","资料来源":"人卫《内科学》第10版 · 泌尿.txt · 本节“常染色体显性遗传性多囊肾病”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2854,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ca9093695eb1ecd3e30b073929ecf47b1a20bc5fb7d255524f3393dce2e16aa4","pinyin":"changransetixianxingyichuanxingduonangshenbing","initials":"crstxxycxdnsb","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-6a80b772d64627f0eda3","key":"v1-c9ccc21dfe2a3058|templates-6a80b772d64627f0eda3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"心包积液及心脏压塞","category":"内科","raw":{"name":"心包积液及心脏压塞","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者以心包积液及心脏压塞收入院，首要任务是确认积液量并判断有无血流动力学障碍，入院即刻床旁完善超声心动图，明确心包积液量、有无右房右室塌陷及下腔静脉扩张等压塞征象，同时评估室壁运动与射血分数；同步完成12导联心电图并持续心电监护，了解有无窦性心动过速、低电压、电交替等表现并排除急性心肌损伤所致低血压；查胸片了解心脏轮廓形态、有无胸腔积液及肺部感染灶；血常规检查排除感染、结核或恶性疾病所致积液并了解有无贫血；完善心肌损伤标志物（肌钙蛋白、心肌酶）检查排除急性心肌梗死、心肌炎所致心包积液；查肝肾功能与凝血功能排除肝肾功能不全、凝血障碍，并为心包穿刺引流做术前准备；查C反应蛋白、红细胞沉降率评估炎症活动程度，鉴别结核性、化脓性及结缔组织病相关心包炎；查甲状腺功能排除甲状腺功能减退所致心包积液；检测结核感染T细胞斑点试验辅助鉴别结核性心包炎；完善肿瘤标志物检查明确有无恶性肿瘤所致心包转移，必要时行心包穿刺送积液常规、生化、细胞学及病原学检查进一步明确病因及性质；病情稳定后定期复查超声心动图与心电图，评估积液演变及有无缩窄性心包炎倾向。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 心包积液及心脏压塞","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"心包疾病或其他病因累及心包可造成心包渗出和心包积液 （pericardial effusion）， 当积液迅速或\n积液量达到一定程度时， 心包压增加， 可造成心排血量和回心血量明显下降而产生临床症状， 即心脏\n压塞 （cardiac tamponade）。\n【病因】 各种病因的心包炎均可能伴有心包积液。常见的原因是肿瘤、 特发性心包炎和感染性\n心包炎， 近年来结核性心包炎造成的心包积液也有回升趋势。严重的体循环淤血也可产生漏出性心\n包积液； 穿刺伤、 心肌梗死后心肌破裂、 心胸外科手术及介入操作造成的冠状动脉穿孔等可造成血性\n心包积液， 迅速或大量心包积液可引起心脏压塞。\n【病理生理】 正常时心包腔平均压力接近于零或低于大气压， 吸气时呈轻度负压， 呼气时近于正\n压。心包内少量积液一般不影响血流动力学。但如果液体迅速增多， 即使仅达 200ml， 也因为心包无\n法迅速伸展而使心包内压力急剧上升， 即可引起心脏受压， 导致心室舒张期充盈受阻， 周围静脉压升\n高， 最终使心排血量显著降低， 血压下降， 产生急性心脏压塞的临床表现。而慢性心包积液则由于心\n包逐渐伸展适应， 即使积液量达 2 000ml 也可无明显的血流动力学障碍。\n【临床表现】 心脏压塞的临床特征为 Beck 三联征： 低血压、 心音低弱、 颈静脉怒张。\n1.  症状\n 呼吸困难是心包积液最突出的症状\n， 可能与支气管、 肺、 大血管受压引起肺淤血有关。\n呼吸困难严重时， 病人可呈端坐呼吸， 身体前倾、 呼吸浅速、 面色苍白， 可有发绀。也可因压迫气管、 食\n管而产生干咳、 声音嘶哑及吞咽困难。还可出现上腹部疼痛、 肝大、 全身水肿、 胸腔积液或腹腔积液，\n重症病人可出现休克。\n2.  体征\n 心尖搏动减弱\n， 位于心浊音界左缘的内侧或不能扪及； 心脏叩诊浊音界向两侧增大， 均\n为绝对浊音区； 心音低弱而遥远。积液量大时可于左肩胛骨下出现叩诊浊音， 听诊闻及支气管呼吸\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0014\u0012\u0018\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0014\u0012\u0018 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0013\u001a\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0013\u001a\n318\n第三篇  循环系统疾病\n音， 称心包积液征 （Ewart 征）， 此为肺组织受压所致。少数病例可于胸骨左缘第 3～4 肋间闻及心包叩\n击音 （ 见缩窄性心包炎）。大量心包积液可使收缩压降低， 而舒张压变化不大， 故脉压变小。依心脏压\n塞程度， 脉搏可减弱或出现奇脉。大量心包积液影响静脉回流， 出现体循环淤血表现， 如颈静脉怒张、\n肝大、 肝颈静脉回流征阳性、 腹腔积液及下肢水肿等。\n3.  心脏压塞 短期内出现大量心包积液可引起急性心脏压塞\n， 表现为窦性心动过速、 血压下降、\n脉压变小和静脉压明显升高。如果心排血量显著下降， 可造成急性循环衰竭和休克。如果液体积聚\n较慢， 则出现亚急性或慢性心脏压塞， 产生体循环静脉淤血征象， 表现为颈静脉怒张， Kussmaul 征， 即\n吸气时颈静脉充盈更明显。还可出现奇脉， 表现为桡动脉搏动呈吸气性显著减弱或消失、 呼气时恢\n复。奇脉也可通过血压测量来诊断， 即吸气时动脉收缩压较吸气前下降 10mmHg 或更多。\n【辅助检查】 \n1.  X 线检查\n X\n线检查可见心影向两侧增大呈烧瓶状， 心脏搏动减弱或消失。特别是肺野清晰\n而心影显著增大常是心包积液的有力证据， 有助于鉴别心力衰竭。\n2.  心电图\n 心包积液时心电图检查可见肢体导联\nQRS 波低电压， 大量渗液时可见 P 波、 QRS 波、\nT 波电交替， 常伴窦性心动过速。\n3.  超声心动图 超声心动图对诊断心包积液简单易行\n， 迅速可靠。心脏压塞时的特征为： 整个\n心动周期可见脏层心包与壁层心包之间存在积液， 舒张末期右心房塌陷及舒张早期右心室游离壁塌\n陷， 主动脉瓣开放时间缩短， 心脏每搏输出量减低， 二尖瓣、 三尖瓣与肝静脉多普勒血流频谱亦有相应\n的改变。此外， 还可观察到吸气时右心室内径增大， 左心室内径减小， 室间隔左移等。超声心动图可\n用于心包积液定量、 定位， 并引导心包穿刺引流。\n4.  心脏磁共振成像 心脏磁共振成像能清晰显示心包积液的位置\n、 范围和容量， 并可根据心包\n积液的信号强度推测积液的性质。同时能显示其他病理表现， 如心包膜的增厚和心包腔内肿瘤。\n5.  心包穿刺 心包穿刺术后对穿刺液行常规\n、 生化、 细菌培养和查找抗酸杆菌及细胞学检查， 有\n助于了解心包积液的性质， 明确病因。\n【诊断与鉴别诊断】 \n1.  诊断标准 对于呼吸困难的病人\n， 如查体发现低血压、 颈静脉怒张、 奇脉、 心浊音界扩大、 心音\n遥远等典型体征， 应考虑此诊断， 超声心动图见心包积液可确诊。心包积液病因诊断可根据临床表\n现、 实验室检查、 心包穿刺液检查以及是否存在其他疾病进一步明确。\n2.  鉴别诊断 主要鉴别引起呼吸困难的临床情况\n， 尤其是与心力衰竭相鉴别。根据心脏原有的\n基础疾病如冠心病、 高血压、 瓣膜病、 先天性心脏病或心肌病等病史， 查体闻及肺部湿啰音， 并根据心\n音、 心脏杂音和有无心包摩擦音进行判断， 超声心动图有助于明确诊断。\n【预后】 不同病因导致的心包积液预后不同。恶性肿瘤预后差， 感染性心包炎若及时有效治疗\n可痊愈， 部分可留心肌损害或缩窄性心包炎。\n【治疗】 心包穿刺引流是解除心脏压塞最简单、 有效的手段， 对所有血流动力学不稳定的急性心\n脏压塞病人， 均应紧急行心包穿刺或外科心包开窗引流， 解除心脏压塞。对伴休克病人， 需紧急扩容、\n升压治疗。对于血流动力学稳定的心包积液病人， 应设法明确病因， 针对原发病进行治疗的同时应注\n意监测血流动力学情况， 必要时行心包减压并将引流液送实验室检查。\n【预防】 心包积液通常是作为其他疾病的一种并发症而存在， 故对本病的预防主要是积极地治\n疗原发性疾病。","资料来源":"人卫《内科学》第10版 · 循环.txt · 本节“心包积液及心脏压塞”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2855,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"379d1773a14de864ed034f52382ce22befeb1ae339c76a803d5dd4fd258bf753","pinyin":"xinbaojiyejixinzangyasai","initials":"xbjyjxzys","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-d7ebc44a0a59b0430ed4","key":"v1-c9ccc21dfe2a3058|templates-d7ebc44a0a59b0430ed4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"心脏传导阻滞","category":"内科","raw":{"name":"心脏传导阻滞","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】轻中度：头晕、疲乏、活动后气短、脉搏缓慢，可无症状。、重度：黑矇、晕厥（阿-斯综合征）、抽搐、心衰加重。、危险信号：心率<50 次/分伴头晕、黑矇或晕厥、长间歇、血压下降、意识淡漠、少尿。、特殊：老年人可仅表现为一次跌倒或食欲下降，患者脑血管病鉴别。。\n【待人工确认·本机素材无此段原文】","现病史":"定义：病变可位于窦房结、房室结或心脏传导束。心率过缓使心脑肾灌注不足，以病态窦房结综合征与二度、三度房室传导阻滞最突出，可致阿-斯综合征甚至猝死。\n夜班目标：先评估是否为症状性心动过缓，备体外临时起搏器、持续心电监护并建立静脉通路；二度 II 型与三度阻滞无论有无症状均按高危处理。\n常见表现：轻中度：头晕、疲乏、活动后气短、脉搏缓慢，可无症状。、重度：黑矇、晕厥（阿-斯综合征）、抽搐、心衰加重。、危险信号：心率<50 次/分伴头晕、黑矇或晕厥、长间歇、血压下降、意识淡漠、少尿。、特殊：老年人可仅表现为一次跌倒或食欲下降，患者脑血管病鉴别。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"循环：心率与节律、血压、颈静脉搏动（大炮波提示房室分离）、末梢温度与毛细血管再充盈。\n心肺：肺部湿啰音、心界与心音、奔马律与杂音、下肢水肿。\n神经：意识、晕厥表现与恢复时间、有无跌倒外伤。\n其他：起搏器置入侧锁骨下囊袋与瘢痕。","辅助检查":"检查计划：患者因心脏传导阻滞入院，常见头晕、疲乏、活动后气短乃至黑矇、晕厥，入院即刻完善12导联心电图并给予持续心电监护，明确阻滞分型并记录最长间歇，评估有无阿-斯综合征风险；二度Ⅱ型与三度阻滞属高危，需备体外临时起搏器并建立静脉通路。查血钾与其他电解质排除高钾血症、低钾低镁所致缓慢性心律失常，明确后2~4小时复查心电图与血钾；查肾功能排除肾功能不全所致电解质紊乱及药物蓄积；查血气分析了解缺氧与酸碱失衡程度，排除缺氧、酸中毒加重传导阻滞；查心肌损伤标志物排除急性心肌梗死、心肌炎所致传导系统损伤；血常规检查排除感染及贫血；患者有冠心病、心肌病、瓣膜病及减慢心率药物使用史，完善心脏超声了解心脏结构、瓣膜情况与射血分数，明确有无器质性心脏病基础；按需查甲状腺功能排除甲状腺功能减退所致传导阻滞；查地高辛血药浓度明确有无洋地黄中毒；查动态心电图明确间歇性阻滞与最长RR间期，一度或二度Ⅰ型者每3~6个月复查；患者脑血管病需鉴别，完善颈部血管彩超了解颈部血管情况，必要时查头颅CT进一步明确晕厥病因；纠正高钾或停用致缓药物后2~4小时复评心电图与血钾，评估传导恢复情况。\n\n（检查清单）\n必查：12 导联心电图与持续监护（记录最长间歇）、血钾与其他电解质、肾功能、血气、心肌损伤标志物、血常规。\n按需：甲状腺功能、地高辛血药浓度、心脏超声、动态心电图（一度或二度 I 型每 3~6 个月复查）。\n复评：纠正高钾或停致缓药后 2~4 小时复查心电图与血钾。","初步诊断":"病史：冠心病、心肌炎、心肌病、瓣膜病、心脏手术或导管操作，以及减慢心率药物使用史。\n诱因：甲减、高钾血症、药物毒性（β 受体阻滞剂、地高辛）、缺氧与迷走张力增高。\n分型：一度 PR>0.20 秒；二度 I 型 PR 渐延长至脱落；二度 II 型 PR 固定而突然脱落，无论症状均高危；三度为房室完全分离。\n鉴别：窦性心动过缓、交界性逸搏、起搏器功能异常、高钾所致缓慢性心律失常。\n1. 心脏传导阻滞（ICD-10：I45.9）","鉴别诊断":"1. 鉴别：窦性心动过缓、交界性逸搏、起搏器功能异常、高钾所致缓慢性心律失常\n2. 特殊：老年人可仅表现为一次跌倒或食欲下降，患者脑血管病鉴别","处理方案":"【药物治疗·输液】\n急性症状性心动过缓：阿托品 0.5mg 静推，每 3~5 分钟可重复，总量≤3mg；适用于窦缓与房室结水平阻滞（如急性下壁心梗），对结下水平三度阻滞无效。\n阿托品无效且无法立即起搏时：异丙肾上腺素 3mg 加 0.9% 氯化钠至 44mL 泵入，速度 1~4mL/h；须心电监护，可诱发室速室颤，急性冠脉缺血与 QT 延长者禁用。\n维持灌注：0.9% 氯化钠静滴，避免快速大量补液加重心衰。\n\n【药物治疗·口服】\n无症状的一度与二度 I 型夜班不新增口服药，重点停用或减量减慢心率药物。\n确需维持心率者由心内科按本院规范处方，夜班不自行启用。\n原有 β 受体阻滞剂、地高辛在心率<50 次/分或有症状时暂停并请示上级。\n限制：意识不清、反复晕厥或拟行临时起搏者禁止口服。\n\n【治疗】\n首要：立即分层。症状性心动过缓与二度 II 型、三度阻滞无论有无症状，均须备临时起搏、持续监护并建立静脉通路。\n其次：二度 I 型无症状者以观察与治疗原发病为主，仅有症状且心率<40 次/分时用药。\n随后：二度 II 型与三度阻滞首选临时起搏，尤其合并阿-斯综合征或晕厥者。\n最后：三支束支阻滞伴晕厥或不稳定者评估永久起搏；纠正甲减、高钾与药物毒性。\n\n【处理要点】\n复评：不稳定期每 15~30 分钟记录心率、血压与意识，稳定后每小时复评。\n观察：最长间歇与最低心率、晕厥是否复发、尿量与起搏阈值。\n随访：每日复查血钾、肾功能与血气；一度与二度 I 型者每 3~6 个月复查动态心电图。\n收治：二度 II 型以上、症状性心动过缓、需临时起搏或合并急性心梗者收入监护病房。\n\n【护理】\n体位：晕厥时立即平卧抬高下肢，清醒后缓慢改变体位。\n监测：持续心电并记录最长间歇与最低心率；除颤仪、阿托品与起搏设备置床旁。\n记录：晕厥时间、用药与反应、起搏参数。\n安全：床栏保护、呼叫器置手边，避免独自行走或如厕，防跌倒外伤。\n\n【注意事项】\n以本院规范为准：阿托品与异丙肾上腺素剂量、临时与永久起搏指征及操作流程按本院常规执行。\n禁用：禁用普罗帕酮、维拉帕米、地尔硫䓬等加重传导阻滞的药物；异丙肾上腺素禁用于急性冠脉缺血、QT 延长与室性心律失常高危者。\n提醒：无症状者观察，有症状者优先起搏，药物仅作过渡。\n\n【急诊/急救】\n立即升级：心率<40 次/分伴低血压、反复晕厥或抽搐、清醒时心室停搏>3 秒、意识改变、室性逸搏心律 → 立即准备临时起搏并呼叫上级。\n永久起搏绝对适应证：三度房室传导阻滞伴症状、交替性束支阻滞、清醒时停搏>3 秒。\n提示：阿托品仅对房室结水平阻滞有效，结下阻滞需直接起搏。","教材原文·内科学第10版":"心脏传导阻滞 （heart conduction block） 是由心脏传导系统的解剖或功能失常造成的永久性或暂\n时性冲动传导障碍， 可发生于心脏传导系统的任何水平。如发生在窦房结与心房之间， 称窦房传导阻\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0013\u0012\u0014\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0013\u0012\u0014 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0012\u0016\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0012\u0016\n214\n第三篇  循环系统疾病\n滞， 心房与心室之间称房室传导阻滞， 心室内称室内传导阻滞。\n窦房传导阻滞已在本章","资料来源":"人卫《内科学》第10版 · 循环.txt · 本节“心脏传导阻滞”正文逐字摘录；疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「心脏传导阻滞」原文）"},"icd10_diagnosis":"I45.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2856,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9cc930075cbf62026900c88225c468420e220fcd73c7e621d25d19b6ff088c61","pinyin":"xinzangchuandaozuzhi","initials":"xzcdzz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","I45.9",30]]},{"id":"templates-c664f069a841601d2742","key":"v1-c9ccc21dfe2a3058|templates-c664f069a841601d2742","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"急性乙醇中毒","category":"内科","raw":{"name":"急性乙醇中毒","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者因急性乙醇中毒急诊入院，首要明确中毒程度并排查合并损伤与代谢紊乱，急诊即刻查血乙醇浓度明确中毒程度与预后判断依据；查随机血糖排除酒精性低血糖所致意识障碍；查电解质排除呕吐、腹泻及酒精性酮症所致低钾、低镁、低磷血症；查血气分析明确有无代谢性酸中毒及呼吸抑制，评估通气功能；查肝功能与肾功能排除酒精性肝损伤及肾功能不全，并为补液用药提供依据；查血淀粉酶排除急性胰腺炎所致腹痛，必要时加查脂肪酶；血常规检查排除感染、应激性白细胞升高并了解有无贫血、血小板减少；查凝血功能与心肌损伤标志物排除凝血障碍及酒精性心肌损伤、急性冠脉事件；患者常有外伤史，完善头颅CT检查排除颅内出血、颅脑外伤所致意识障碍，必要时查胸部CT排除肋骨骨折、肺挫伤；对昏迷或呼吸抑制者急诊完善毒物筛查明确有无合并镇静催眠药、毒品等混合中毒，并查血氨排除肝性脑病；病情稳定后复查电解质、血气与心电图，评估心律失常风险及代谢紊乱纠正情况。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 急性乙醇中毒","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"乙醇 （ethanol） 别名酒精， 是无色、 易燃、 易挥发的液体， 具有醇香气味， 能与水和大多数有机溶\n剂混溶。一次饮入过量酒精或酒类饮料引起兴奋继而抑制的状态称为急性乙醇中毒 （acute ethanol \npoisoning） 或称急性酒精中毒 （acute alcohol poisoning）。\n【病因】 工业上乙醇是重要的溶剂。酒是含乙醇的饮品， 谷类或水果发酵制成的酒含乙醇浓度\n较低， 常以容量浓度 （L/L） 计， 啤酒为 3%～5%， 黄酒 12%～15%， 葡萄酒 10%～25%； 蒸馏形成烈性酒，\n如白酒、 白兰地、 威士忌等含乙醇 40%～60%。酒是人们经常食用的饮料， 大量饮用含乙醇浓度高的\n烈性酒易引起中毒。\n【发病机制】\n（ 一）  乙醇代谢  乙 醇（ C H3CH2OH） 是一种水溶性醇， 可快速通过细胞膜， 通过胃肠系统吸收， 主\n要是胃 （70%）和十二指肠 （25%）， 其余少量在小肠吸收。当胃中无内容物时， 血液乙醇水平在摄入后\n30～90 分钟达到峰值。由肾和肺排出的乙醇至多占总量的 10%，9 0% 在肝内代谢、 分解。乙醇先在\n肝内由醇脱氢酶氧化为乙醛， 乙醛经醛脱氢酶氧化为乙酸， 乙酸转化为乙酰辅酶 A 进入三羧酸循环，\n最后代谢为 CO2和H 2O。乙醇的代谢是限速反应。乙醇清除率为 2.2mmol / （kg · h） ［ 100mg/ （kg · h） ］，\n成人每小时可清除乙醇 7g （100% 乙醇 9ml）。血中乙醇浓度下降速度约 0.43mmol / h ［20mg/ （dl · h） ］。\n虽然对血中乙醇浓度升高程度的耐受性个体差异较大， 但血液乙醇致死浓度并无差异， 大多数成人致\n死量相当于一次饮纯酒精 250～500ml。\n（ 二）  中毒机制\n1.  急性毒害作用\n（\n1） 中枢神经系统抑制作用\n： 乙醇具有脂溶性， 可迅速透过大脑神经细胞膜， 并作用于膜上的某\n些酶而影响细胞功能。乙醇对中枢神经系统的抑制作用， 随着剂量的增加， 由大脑皮质向下， 通过边\n缘系统、 小脑、 网状结构到延髓。小剂量出现兴奋作用， 这是由于乙醇作用于大脑细胞突触后膜苯二\n氮䓬-GABA 受体， 从而抑制 GABA 对脑的抑制作用。血中乙醇浓度增高， 作用于小脑， 引起共济失调；\n作用于网状结构， 引起昏睡和昏迷。极高浓度乙醇抑制延髓中枢， 引起呼吸或循环衰竭。\n（2） 代谢异常\n： 乙醇在肝细胞内代谢生成大量还原型烟酰胺腺嘌呤二核苷酸 （NADH）， 使之与氧\n化型的比值 （NADH/NAD） 增高， 甚至可高达正常的 2～3 倍。相继发生乳酸增高、 酮体蓄积导致的代\n谢性酸中毒以及糖异生受阻所致的低血糖。\n8-9篇.indd 9058-9篇.indd 905 2024/7/28 11:14:512024/7/28 11:14:51\n906\n第九篇  理化因素所致疾病\n2.  耐受性、 依赖性和戒断综合征\n（1） 耐受性\n： 饮酒后产生轻松、 兴奋的欣快感。继续饮酒后， 产生耐受性， 需要增加饮酒量才能达\n到原有的效果。\n（2） 依赖性\n： 为了获得饮酒后特殊快感， 渴望饮酒， 这是精神依赖性。生理依赖性是指机体对乙\n醇产生的适应性改变， 一旦停用则产生难以忍受的不适感。\n（3） 戒断综合征\n： 长期饮酒后已形成身体依赖， 一旦停止饮酒或减少饮酒量， 可出现与酒精中毒\n相反的症状。机制可能是戒酒使酒精抑制 GABA 的作用明显减弱， 同时血浆中去甲肾上腺素浓度升\n高， 出现交感神经兴奋症状如多汗、 震颤等。\n3.\n  长期酗酒的危害\n（\n1） 营养缺乏\n： 酒饮料中每克乙醇供给 29.3kJ （7kcal） 热量， 但不含维生素、 矿物质和氨基酸等必\n需营养成分， 因而酒是高热量而无营养成分的饮料。长期大量饮酒时进食减少， 可造成明显的营养缺\n乏。缺乏维生素 B1 可引起 Wernicke-Korsakoff 综合征、 周围神经麻痹。叶酸缺乏可引起巨幼细胞贫\n血。长期饮酒饥饿时， 应补充糖和多种维生素。\n（2） 毒性作用\n： 乙醇对黏膜和腺体分泌有刺激作用， 可引起食管炎、 胃炎、 胰腺炎。乙醇在体内代\n谢过程中产生的自由基， 可引起细胞膜脂质过氧化， 造成肝细胞坏死， 肝功能异常。\n【临床表现】\n（ 一）  急性中毒  一次大量饮酒中毒可引起中枢神经系统抑制， 症状与饮酒量和血乙醇浓度以及\n个人耐受性有关， 临床上分为三期。\n1.\n  兴\n奋 期\n 血乙醇浓度达到\n11mmol/L （ 50mg/dl） 即感头痛、 欣快、 兴奋。血乙醇浓度超过\n16mmol/L （75mg/dl）， 健谈、 饶舌、 情绪不稳定、 自负、 易激怒， 可有粗鲁行为或攻击行动， 也可能沉默、\n孤僻。浓度达到 22mmol/L （100mg/dl） 时， 驾车易发生车祸。\n注： 根据国家标准 《车辆驾驶人员血液、 呼气酒精含量阈值与检验》 （\nGB 19522—2010）， 车辆驾驶\n人员血液中的酒精含量≥20mg/100ml，＜80mg/100ml 的驾驶行为即为饮酒后驾车； 车辆驾驶人员血液\n中的酒精含量≥80mg/100ml 的驾驶行为即为醉酒后驾车。\n2.  共济失调期 血乙醇浓度达到\n33mmol/L （150mg/dl）， 肌肉运动不协调， 行动笨拙， 言语含糊不\n清， 眼球震颤， 视力模糊， 复视， 步态不稳， 出现明显共济失调。浓度达到 43mmol/L （200mg/dl）， 出现恶\n心、 呕吐、 困倦。\n3.\n  昏\n迷期\n 血乙醇浓度升至\n54mmol/L （250mg/dl）， 患者进入昏迷期， 表现为昏睡、 瞳孔散大、 体\n温降低。血乙醇浓度超过 87mmol/L （400mg/dl）， 患者陷入深昏迷， 心率快、 血压下降， 呼吸慢而有鼾音，\n可出现呼吸、 循环麻痹而危及生命。\n此外， 重症患者可并发意外损伤， 酸碱失衡， 水、 电解质紊乱， 低血糖症， 肺炎， 急性肌病， 甚至出现\n急性肾衰竭。\n（ 二）  戒断综合征  长期酗酒者在突然停止饮酒或减少饮酒量后， 可发生下列 4 ","资料来源":"人卫《内科学》第10版 · 理化.txt · 本节“急性乙醇中毒”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2857,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"84e47fbf549afaa09718fd77a122f83f34b0eb1fc986f5a60f5d21861ffd1e7a","pinyin":"jixingyichunzhongdu","initials":"jxyczd","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-f336a22e475ac4eb1bd8","key":"v1-c9ccc21dfe2a3058|templates-f336a22e475ac4eb1bd8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"急性亚硝酸盐中毒","category":"内科","raw":{"name":"急性亚硝酸盐中毒","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者因急性亚硝酸盐中毒急诊入院，以口唇、甲床青紫而吸氧不易改善为特点，急诊即刻完善血高铁血红蛋白定量检查明确中毒程度并指导亚甲蓝用量；同步查动脉血气分析，了解血氧分压与实际氧饱和度分离情况及有无代谢性酸中毒，明确缺氧性质并鉴别缺氧性青紫；查葡萄糖-6-磷酸脱氢酶活性，评估亚甲蓝使用安全性，排除G6PD缺乏所致溶血风险；查血常规与网织红细胞计数排除溶血性贫血，了解有无红细胞破坏；血生化检查排除肝肾功能不全与电解质紊乱，并为补液、利尿等治疗提供依据；查心肌损伤标志物排除缺氧所致急性心肌损伤；完善12导联心电图并持续心电监护，了解有无心律失常与ST-T改变；患者多为进食含亚硝酸盐腌制食品或误服所致，完善毒物筛查明确毒物种类及有无合并其他中毒；对意识障碍者完善头颅CT检查排除脑血管意外等鉴别诊断；必要时查腹部超声了解肝脾大小及有无溶血相关改变，病情稳定后复查高铁血红蛋白、血气与血常规，评估疗效及有无反跳。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 急性亚硝酸盐中毒","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"急性亚硝酸盐中毒 （acute nitrite poisoning） 是指由于误食亚硝酸盐或含亚硝酸盐、 硝酸盐的食\n物或饮用亚硝酸盐含量高的井水、 蒸锅水而引起的以组织缺氧为主要表现的急性中毒。亚硝酸盐\n毒性很大， 成人摄入 0.2～0.5g 即可引起中毒， 1～3g 可致死， 小儿摄入 0.1g 即引起急性中毒， 甚至 \n死亡。\n亚硝酸盐为白色的粉末或结晶， 外观与食盐类似， 味稍苦或微咸涩， 主要以亚硝酸钠或亚硝酸钾\n形式存在， 易溶于水。因其可与肉制品中的肌红素结合而具有防腐、 成色、 护色的作用， 故食品加工业\n常将其作为防腐剂和发色剂； 亚硝酸盐可抑制肉毒梭状芽孢杆菌的产生， 可提高食用肉制品的安全\n性。亚硝酸盐是一种在肉制品生产加工中允许使用的食品添加剂， 但其添加量若超过国家卫生标准\n规定的剂量， 易引起中毒。亚硝酸盐与食品蛋白质中的胺类化合物结合生成亚硝胺和亚硝酸胺， 在胃\n肠道酸性条件下转化为亚硝胺， 亚硝胺有强烈的致癌作用， 长期大量食用含亚硝酸盐的食物存在远期\n致癌风险； 亚硝胺还能通过胎盘屏障进入胎儿体内， 对胎儿有致畸形的作用。\n我国多地区开展的流行病学调查表明： 亚硝酸盐急性中毒的发病率与性别、 年龄无关， 也无明显的\n季节性和地域性。中毒场所以集体食堂、 酒店餐饮业居多， 中毒食物以肉类及其制品 （ 如腌制咸菜） 居\n首位， 中毒原因主要是亚硝酸盐的误食误用。潜伏期及病情严重程度与摄入量有关， 最短 1.5 分钟， 一\n般1 ～3 小时， 偶有长达 20 小时。有研究认为， 中毒食物中的亚硝酸盐含量平均超过标准值的 212 倍。\n【病因】 常因误食亚硝酸盐而导致中毒， 误将亚硝酸盐当食盐、 白糖、 食用碱等使用。食用亚硝\n酸盐过量的食品 （ 超标使用亚硝酸盐作为食品添加剂）。有些新鲜蔬菜， 如白菜、 芹菜、 菠菜、 韭菜、 莴\n苣、 萝卜等， 含有较多的硝酸盐或亚硝酸盐， 这类蔬菜若糜烂变质、 腌制不透 （ 腌制的第 2～4 天亚硝酸\n盐含量增加， 1～2 周达高峰） 或烹调后放置过久， 易在硝酸盐还原菌作用下形成亚硝酸盐， 摄入过多\n易引起中毒。另外， 长期食用含亚硝酸盐的苦井水可发生中毒。\n8-9篇.indd 9138-9篇.indd 913 2024/7/28 11:14:512024/7/28 11:14:51\n914\n第九篇  理化因素所致疾病\n【发病机制】 亚硝酸盐具有强氧化性， 使正常的血红蛋白 （Fe\n2+\n） 氧化为失去携氧运输能力的高\n铁血红蛋白 （Fe\n3+\n）。一般高铁血红蛋白量超过血红蛋白总量的 1% 时称为高铁血红蛋白血症； 达总\n量的 10% 时， 皮肤、 黏膜出现发绀， 引起全身组织器官缺氧； 达总量的 20%～30% 时出现缺氧症状、\n头痛、 疲乏无力； 达总量的 50%～60% 时出现心动过速、 呼吸浅快、 轻度呼吸困难；＞60% 时可出现反\n应迟钝， 意识障碍， 呼吸、 循环衰竭， 甚至引起死亡。脑组织细胞对缺氧最敏感， 故中枢神经系统最先\n受累， 大脑皮质处于保护性抑制状态， 患者出现头痛、 头晕、 反应迟钝、 嗜睡甚至昏迷等表现。若缺氧\n时间较长， 可致循环、 呼吸衰竭和中枢神经系统的严重损害。亚硝酸盐还可松弛血管平滑肌致血压 \n降低。\n【临床表现】 食入富含硝酸盐的食物时， 胃肠道内硝酸盐还原菌 （ 以沙门菌和大肠埃希菌为\n主） 大量繁殖， 硝酸盐在其硝基还原作用下转化成亚硝酸盐， 机体不能及时将大量的亚硝酸盐分解\n为氨排出体外， 进入血液引起亚硝酸盐中毒， 称为肠源性发绀。儿童胃肠功能紊乱或免疫力低下\n时较易出现， 多为散发性。全身皮肤黏膜发绀表现最明显， 以口唇及四肢末梢为著。轻者表现为\n头痛、 心慌、 恶心、 呕吐、 腹痛、 腹胀等； 重者可有口唇青紫、 面色发绀、 呼吸困难、 心律不齐、 血压下\n降， 出现休克等表现； 极重者伴有抽搐、 心力衰竭、 呼吸衰竭、 肺水肿、 脑水肿、 昏迷等多器官衰竭的 \n表现。\n【实验室检查】 高铁血红蛋白含量显著高于正常； 尿亚硝酸盐定性检测阳性； 心电图可表现为窦\n性心动过速； 伴有心肌损害时心肌酶偏高。\n【诊断】 详细询问病史， 结合临床表现、 相关实验室检查， 尤其是出现不能用基础疾病或者\n缺氧解释的皮肤黏膜发绀时， 应高度怀疑亚硝酸盐中毒。高铁血红蛋白鉴定实验： 取 5ml 静脉血\n在空气中用力震荡 15 分钟， 若始终呈深棕色不变色 （ 正常情况下血红蛋白与氧结合变为猩红色），\n可排除由呼吸循环衰竭引起的缺氧性发绀， 考虑为高铁血红蛋白血症。剩余食物或呕吐物、 血液\n毒物分析、 血高铁血红蛋白鉴定试验和尿亚硝酸盐定性检查阳性， 并且除外泌尿系统感染后可 \n确诊。\n【鉴别诊断】 亚硝酸盐中毒除与急性胃肠炎、 肠梗阻、 冠状动脉粥样硬化性心脏病、 肺栓塞、 CO\n中毒相鉴别， 还患者以下疾病相鉴别。\n1.  杀虫脒中毒 杀虫脒是一种有机氮类农业杀虫剂\n， 中毒后引起高铁血红蛋白血症， 杀虫脒中\n毒伴有其他典型症状： 出血性膀胱炎 （ 尿频、 尿急、 血尿）， 瞳孔散大。病情急重， 病死率高， 患者有明确\n的杀虫脒服用史或接触史。\n2.  硫化血红蛋白血症 正常人血液中不含硫化血红蛋白\n， 当血液中硫化血红蛋白含量达到 4%\n以上或超过 5g/L 时可出现发绀。有些人服用非那西丁或磺胺类等药物后可出现硫化血红蛋白血症，\n可伴有溶血。硫化血红蛋白形成后在体内外都不能再恢复为血红蛋白， 缺乏有效的治疗措施。因此，\n当亚甲蓝治疗无效时， 要考虑到硫化血红蛋白血症的可能。\n【治疗】 治疗原则为高流量氧气吸入、 建立静脉通道、 洗胃、 催吐、 导泻、 使用解毒剂、 吸痰、 扩容、\n对症支持处理， 注意保暖， 密切监测生命体征变化。\n1.  氧气吸入 氧流量\n4～6L/min， 必要时行高压氧疗。高压氧疗尤为适用于严重缺氧伴急性肺\n水肿、 脑水肿、 昏迷等患者。高浓度氧可提高血氧张力、 提高血氧弥散速度、 增加缺血区的血流量、 改\n善微循环血流动力学功能， 进而改善脏器缺氧， 降低颅内压， 减轻肺脑水肿， 打破缺氧 \n- 水肿的恶性循\n环\n， 改善缺血缺氧状态","资料来源":"人卫《内科学》第10版 · 理化.txt · 本节“急性亚硝酸盐中毒”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2858,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8e2d02e5783a77ae1c48d2203e3cdff1776f151018c2289508c0e6a1536358d4","pinyin":"jixingyaxiaosuanyanzhongdu","initials":"jxyxsyzd","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-0f040e727c99a681cc07","key":"v1-c9ccc21dfe2a3058|templates-0f040e727c99a681cc07","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"急性毒品中毒","category":"内科","raw":{"name":"急性毒品中毒","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者因急性毒品中毒急诊入院，首要明确毒物种类与中毒程度并评估生命体征，急诊即刻完善血液、尿液毒物筛查明确毒品种类及其代谢产物，必要时加查苯丙胺类、阿片类及氯胺酮专项检测；查血气分析与血氧饱和度排除呼吸抑制所致缺氧及代谢性酸中毒；查电解质排除呕吐、出汗所致低钾、低钠血症，并了解有无横纹肌溶解相关高钾；血常规检查排除感染、贫血并评估应激状态；查心肌损伤标志物排除毒品所致急性心肌损伤、心肌缺血；完善12导联心电图并持续心电监护，了解有无QT间期延长、恶性心律失常，评估猝死风险；查肝肾功能与肌酸激酶排除肝肾功能不全及横纹肌溶解所致急性肾损伤；查血糖排除低血糖所致意识障碍；对意识障碍、抽搐或外伤者完善头颅CT检查排除颅内出血、脑水肿及颅脑外伤；疑有肺水肿者查胸片了解肺部情况；疑可卡因、冰毒中毒者完善心脏超声了解心功能与室壁运动；病情稳定后复查血气、电解质、心肌标志物与心电图，评估器官功能恢复情况。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 急性毒品中毒","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"毒品 （narcotics） 是指国家规定管制的能使人成瘾的麻醉 （ 镇痛） 药 （narcotic analgesic）和精神药\n（psychotropic drug）， 其具有药物依赖性、 危害性和非法性。毒品是一个相对概念， 用于治疗即为药品， 滥\n用 （abuse， misuse） 即为毒品。我国毒品不包括烟草和酒类中的成瘾物质。短时间内滥用、 误用或故意\n使用大量毒品， 超过耐受量， 产生相应临床表现时称为急性毒品中毒 （acute narcotics poisoning）。急性毒\n品中毒者常死于呼吸或循环衰竭， 有时发生意外死亡。急性毒品中毒多见于吸毒者。全球有 200 多个\n国家和地区存在毒品滥用。2020 年， 全球约 2.75 亿人使用毒品， 吸食的毒品主要有大麻、 苯丙胺类、 海\n洛因、 可卡因和氯胺酮等。我国在毒品滥用预防和管制方面取得显著成效， 现有吸毒人数已由 2017 年\n底的 234.5 万降至 2022 年底的 112.4 万。受传统毒品获取困难影响， 部分吸毒人员为缓解毒瘾， 转而\n寻求其他麻精药品、 新精神活性物质及未列管物质进行替代滥用， 或交叉滥用非惯用毒品以满足毒瘾。\n全年查处滥用曲马多、 氯硝西泮等麻精药品， 以及氟胺酮、 合成大麻素等新精神活性物质人数增多。\n吸毒除损害身体健康， 还给公共卫生、 社会、 经济和政治带来严重危害。第一次国际禁毒会议于\n续表\n8-9篇.indd 9008-9篇.indd 900 2024/7/28 11:14:512024/7/28 11:14:51\n第二章  中毒\n901\n1909 年在上海召开， 13 个国家的代表参加， 讨论阿片国际管制问题， 并通过了麻醉品管制的 “四项原\n则”， 该原则被吸收到国际禁毒公约中。目前毒品中毒已成为许多国家继心、 脑血管疾病和恶性肿瘤\n后的重要致死原因。为号召全球人民共同抵御毒品危害， 联合国把每年的 6 月 26 日确定为 “国际禁\n毒日 （International Day Against Drug Abuse and Illicit Trafficking） ”。为保证人民身体健康和社会安定，\n我国政府对制毒、 贩毒和吸毒行为加大了打击力度。\n【毒品分类】 我国将毒品分为麻醉 （ 镇痛） 药和精神药两类。本节重点介绍常见毒品。\n（一）   麻 醉（镇 痛）药\n1.  阿 片类 阿片 （opium， 鸦片） 是将未成熟的罂粟蒴果浆汁风干获取的干燥物， 具有强烈的镇\n痛、 止咳、 止泻、 麻醉、 镇静和催眠等作用。阿片含有 20 余种生物碱 （ 如吗啡、 可待因、 蒂巴因和罂粟\n碱等）， 其中蒂巴因与吗啡和可待因作用相反， 改变其化学结构后能形成具有强大镇痛作用的埃托啡。\n罂粟碱不作用于体内阿片受体。阿片类镇痛药 （opioid analgesic） 包括天然阿片制剂 （natural opiate）、\n半合成阿片制剂 （ 表 9-2-8）和人工合成阿片制剂 （ 表 9-2-9）， 能作用于体内阿片受体， 产生镇痛作用。\n表9 -2-8  天然、 半合成阿片制剂\n天然阿片制剂 半合成阿片制剂\n吗啡 （morphine） 海洛因 （heroin）\n可待因 （codeine） 羟考酮 （oxycodone）\n蒂巴因 （thebaine） 氢可酮 （hydrocodone）\n二氢可待因 （dihydrocodeine）\n氢吗啡酮 （hydromorphone）\n羟吗啡酮 （oxymorphone）\n丁丙诺啡 （buprenorphine）\n埃托啡 （etorphine）\n烟酰吗啡 （nicomorphine）\n表9 -2-9  人工合成阿片制剂\n美沙酮 （methadone） 非那佐辛 （phenazocine）\n哌替啶 （pethidine） 曲马多 （tramadol）\n芬太尼 （fentanyl） 洛哌丁胺 （loperamide）\n阿芬太尼 （alfentanil） 罗通定 （rotundine）\n舒芬太尼 （sufentanil） 布桂嗪 （bucinnazine）\n雷米芬太尼 （remifentanil） 二氢埃托啡 （dihydroetorphine）\n卡芬太尼 （carfentanil） 阿法罗定 （alphaprodine）\n喷他佐辛 （pentazocine）\n2.  可卡因类 包括可卡因、 古柯叶和古柯膏等。可卡因 （ 化学名苯甲酰甲基芽子碱， benzoyl \nmethyl ecgonine） 为古柯叶中提取的古柯碱。\n3.\n  大\n麻类（cannabis） 包括大麻叶\n、 大麻树脂和大麻油等， 主要含有的精神活性物质包括Δ\n9- 四\n氢大麻酚 （delta-9-tetrahydrocannabinol， Δ\n9-THC）、 大麻二酚、 大麻酚及其相应的酸。\n（二）   精 神 药\n1.  中枢抑制药 镇 静催眠药 （sedative hypnotic drug）和抗焦虑药 （antianxiety drug） 中毒详见本\n篇第二章第五节。\n2.\n  中\n枢兴奋药 （central\n stim\nulant） 滥\n用的有苯丙胺 （amphetamine， AA） 及其衍生物， 如甲基\n苯丙胺 （methamphetamine， MA， 俗称冰毒）、 3， 4- 亚甲二氧基苯丙胺\n（3， 4-methylene-dioxyamphetamine，\nMDA）和 3， 4- 亚甲二氧基甲基苯丙胺\n（3， 4-methylene-dioxymethamphetamine， MDMA， 俗称摇头丸）等。\n8-9篇.indd 9018-9篇.indd 901 2024/7/28 11:14:512024/7/28 11:14:51\n902\n第九篇  理化因素所致疾病\n3.  致幻药（ hallucinogen） 包括麦角二乙胺 （lysergide）、 苯环己哌啶 （phencyclidine， PCP）、 西洛西\n宾和麦司卡林等。氯胺酮 （ketamine） 俗称 K 粉， 是 PCP 衍生物， 属于第一","资料来源":"人卫《内科学》第10版 · 理化.txt · 本节“急性毒品中毒”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2859,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6f68970d7110eea017e6c3afaca3d80aee991550f8f0eb76a6bd8821f9305ca3","pinyin":"jixingdupinzhongdu","initials":"jxdpzd","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-065f0ff79d281a23dcf0","key":"v1-c9ccc21dfe2a3058|templates-065f0ff79d281a23dcf0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"性染色体异常疾病","category":"内科","raw":{"name":"性染色体异常疾病","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者因性染色体异常疾病就诊，常以身材异常、性腺发育不良、原发性闭经或第二性征发育迟缓为主要表现，完善外周血染色体核型分析明确染色体数目与结构异常，是确诊本病的核心依据；同步行荧光原位杂交（FISH）检测明确嵌合比例与具体异常片段，评估病情严重程度；查性激素六项（促卵泡激素、促黄体生成素、雌二醇、孕酮、睾酮、泌乳素）了解下丘脑-垂体-性腺轴功能，明确性腺功能减退程度并指导激素替代方案；查甲状腺功能排除合并甲状腺功能异常所致生长发育障碍；查生长激素与胰岛素样生长因子-1了解生长轴功能，评估身高干预指征；完善盆腔超声检查了解子宫、卵巢或睾丸发育情况及有无性腺母细胞瘤；查骨密度了解骨质疏松程度，评估雌激素缺乏所致骨量丢失；完善心脏超声与心脏大血管检查排除主动脉缩窄、二叶式主动脉瓣等合并畸形；查肝肾功能、血糖、血脂评估代谢综合征风险，指导长期随访与用药；必要时查泌尿系统超声排除肾畸形，对性腺发育不良者完善肿瘤标志物检查明确有无性腺肿瘤风险，青春期前患者按需定期复查骨龄与性激素。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 性染色体异常疾病","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"一、   Klinefelter 综合征\nKlinefelter 综合征 （ 克兰费尔特综合征）， 又称精曲小管发育不全症， 是一种非整倍型染色体疾病。\n该疾病是原发性睾丸功能减退症中最常见的疾病， 也是引起男性不育最常见的遗传性疾病。据报道\n克兰费尔特综合征在新生儿中的发病率约为 1/660， 不存在种族或地域的差异。\n【病因和发病机制】  克兰费尔特综合征的病因是性染色体异常， 即患者具有两条或两条以上\nX 染色体， 包括标准核型、 变异型等。47， XXY 核型约 40% 是精子减数分裂异常所致， 约 60% 是卵\n子减数分裂异常所致。嵌合体核型 （46， XY/47， XXY） 是由合子在有丝分裂时发生性染色体不分离\n所致， 在克兰费尔特综合征患者中所占比例约为 10 %。克兰费尔特综合征的其他染色体亚型可有  \n48， XXYY、 48， XXXY。导致性染色体异常的主要致病原因与父母生育时高龄、 遗传因素等有关。\n【临床表现】  临床特点为小而质韧的睾丸， 雄激素缺乏和不育的表现。\n1.  睾丸小  青春期前， 患者可能表现为睾丸容积较正常略小； 青春期中后期， 表现为小而质韧的\n睾丸， B 超监测双侧睾丸的平均容积为 4ml， 约 1/3 的患者存在睾丸下降不良。\n2.  第二性征男性化不全  青春期启动的时间正常或延迟， 大部分患者可在青春期出现无痛性双\n侧乳房发育、 阴茎小， 胡须、 腋毛及阴毛稀疏。成年后约 70% 患者出现性欲和性能力的进行性下降。\n\u0018௉\u000fJOEE\u0001\u0001\u0001\u0018\u001a\u0012\u0018௉\u000fJOEE\u0001\u0001\u0001\u0018\u001a\u0012 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u001a\u001b\u0011\u0017\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u001a\u001b\u0011\u0017\n792\n第七篇   内分泌和代谢性疾病\n3.  其他表现   出生时体重低， 头围小， 可有身体畸形， 如指趾弯曲。青春期， 开始特征性的骨骼\n发育， 一般能达到人群平均身高或更高， 四肢与躯干比例失调， 下部量大于上部量， 指距的 1/2 大于上\n部量。患者存在认知方面的异常， 但并非智力水平的整体下降， 而是某些方面的缺陷， 尤其是语言和\n执行能力。\n4.  伴发异常  雄激素缺乏可导致骨质疏松、 肌力下降。患者还可有肥胖、 糖耐量减低、 糖尿病的\n表现， 且糖尿病导致的死亡风险明显增高。克兰费尔特综合征的患者易发生生殖腺外的恶性生殖细\n胞肿瘤 （ 如纵隔恶性非精原细胞瘤和中枢神经系统生殖细胞瘤）， 另外白血病、 淋巴瘤等血液系统恶性\n疾病的发病率也增高。\n【实验室检查及其他检查】\n1.  激素测定  青春期前的黄体生成素 （LH）、 卵泡刺激素 （FSH）、 睾酮 （T） 的基础水平与同龄儿\n童相比无差异。患儿能够经历同正常男孩相似的青春期启动过程， 性激素水平表现为 LH、 FSH 升高，\n睾酮水平也升高达正常水平或正常值低限。直至青春期中期， 患儿的各种性激素异常才充分表现出\n来： LH、 FSH 水平逐渐升高， 达到高促性腺激素水平， 尤以 FSH 的上升更为明显和迅速。血清睾酮水\n平下降， 并在整个青春期都维持在较低水平。\n2.  染色体核型分析  外周血细胞的染色体核型分析可明确诊断。\n3.  睾丸 B 超  睾丸容积可通过触诊并与睾丸测量模具比较获得， 准确的容积可通过睾丸 B 超\n确定。\n4.  精液分析  精子计数通常为零。\n5.  睾丸活检  伴随着青春期的启动， 睾丸生精小管进行性萎缩和透明样变， 间质逐渐纤维化， 精\n原细胞丧失， 睾丸支持 （Sertoli） 细胞退化、 间质 （Leydig） 细胞增生。\n【诊断与鉴别诊断】\n1.  诊断  典型病例根据患者睾丸小而硬、 男性乳房发育、 呈类无睾体型、 第二性征发育不全等临\n床表现以及上述实验室检查可对本病作出诊断。进行染色体核型分析有特异性诊断意义， 有助于对\n典型与不典型 Klinefelter 综合征作出鉴别诊断。\n2.  鉴别诊断  本病应与低促性腺激素性腺功能减退症鉴别， 后者也具有睾丸小、 血清 T 明显减\n低的特点， 但低 LH、 FSH 及染色体核型分析可相鉴别。还需要与其他原因的高促性腺激素性腺功能\n减退症鉴别。\n【治疗】  当患者血清睾酮水平低于正常时， 即可开始雄激素替代治疗， 治疗目标为血睾酮达到正\n常中等水平， 并持续终身治疗， 替代治疗目的是改善患者雄激素不足的症状， 促进第二性征发育， 提\n高性功能和生活质量， 以避免出现雄激素缺乏的症状和后遗症。国内制剂包括肌内注射和口服制剂。\n庚酸睾酮、 十一酸睾酮肌内注射每次 200～250mg， 每 2～4 周注射一次。十一酸睾酮等口服制剂， 口\n服后经淋巴系统吸收， 适用于长期服用。起始剂量 120～160mg/d， 连续使用 2～3 周后， 改为维持剂\n量 40～120mg/d， 可分为早、 晚 2 次。雄激素替代治疗对患者生育能力无改变。\n二、   Turner 综合征\nTurner 综合征 （Turner s yndrome， 特纳综合征） 又称先天性卵巢发育不全症， 也是一种较为常见的\n非整倍型染色体疾病， 是由于 X 染色体部分或完全缺失以及结构异常所致的一种疾病。在存活的女\n婴中， 其发生率为 1/5\n 000\n～1/2\n 500。\n【\n病因和发病机制 】   经 典 的 Turner 综 合 征 （45， X） 核 型， 约 占 半 数； 嵌 合 体 Turner 综 合 征 \n（45， X/46， XX） 约占 1/4； 其余 1/4 为 X 染色体异常， 如长臂或短臂缺失、 等臂染色体或环状染色体等。\n【临床表现】  Turner 综合征患者的临床表现差异大， 典型者表现为身材矮小、 性腺发育不全、 淋\n巴水肿和躯体、 内脏畸形， 轻型者仅表现为最终身高略矮、 卵巢早衰等。典型的面容表现为多发黑痣、\n眼睑下垂、 鱼形嘴、 斜视。躯体畸形表现为身材矮小 （ 一般＜140cm）、 颈粗短、 颈蹼、 盾状胸、 肘外翻\n\u0018௉\u000fJOEE\u0001\u0001\u0001\u0018\u001a\u0013\u0018௉\u000fJOEE\u0001\u0001\u0001\u0018\u001a\u0013 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u001a\u001b\u0011\u0017\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u001a\u001b\u0011\u0017\n第十五章   性发育异常疾病\n793\n等， 后发际低至颈部。第二性征发育不","资料来源":"人卫《内科学》第10版 · 内分泌.txt · 本节“性染色体异常疾病”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2860,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e96f5fedcbaf5a1255e338f52d1218bc249730eb3754cac5f097853ef0a2d977","pinyin":"xingransetiyichangjibing","initials":"xrstycjb","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-c0189688518cf06c199d","key":"v1-c9ccc21dfe2a3058|templates-c0189688518cf06c199d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"慢性冠状动脉综合征","category":"内科","raw":{"name":"慢性冠状动脉综合征","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者因慢性冠状动脉综合征入院，多有劳力性胸闷、胸痛及冠心病危险因素，入院完善12导联心电图并动态对比，了解有无ST-T缺血性改变及动态演变；查心肌损伤标志物排除急性心肌损伤、急性冠脉综合征；完善超声心动图与左心功能测定，了解室壁运动异常、射血分数及瓣膜情况，评估心功能状态；查血常规排除贫血、感染等加重心肌缺血的诱因；查肝肾功能与电解质排除肝肾功能不全、电解质紊乱，并为抗血小板、他汀类药物安全使用提供依据；查血脂四项与空腹血糖、糖化血红蛋白了解血脂、血糖水平，明确危险分层并指导降脂、降糖方案；查NT-ProBNP明确有无心力衰竭及心功能不全程度；完善颈动脉血管彩超了解颈部血管粥样硬化情况，评估全身动脉硬化负荷；病情稳定后行运动负荷心电图或冠脉CTA，明确有无心肌缺血及冠状动脉狭窄程度，必要时行冠状动脉造影进一步明确解剖病变并指导血运重建；定期复查心电图、血脂与肝肾功能，评估疗效及药物不良反应。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 慢性冠状动脉综合征","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"慢性冠状动脉综合征 （CCS） 最常见为慢性稳定型劳力性心绞痛和以心功能不全为主要表现的缺\n血性心肌病， 部分处于渡过 ACS 后或行血运重建之后稳定期， 有些则为无症状隐匿型冠心病。发生\n心肌缺血的主要原因是存在稳定的心外膜冠脉粥样硬化造成的固定狭窄， 在某些因素导致心肌耗氧\n量增加的情况下诱发心肌急剧暂时性缺血缺氧； 但冠脉痉挛或微血管病变的病人没有心外膜血管固\n定狭窄临床上亦不少见。CCS 病人在治疗上有共同之处， 通过抗心肌缺血治疗改善症状， 稳定或逆转\n斑块并预防血栓形成， 延长病人生存期。\n一、  稳定型心绞痛\n稳定型心绞痛 （stable angina pectoris）也称劳力性心绞痛。其特点为阵发性的前胸部压榨性疼痛或憋\n闷感觉， 主要位于胸骨后部， 可放射至心前区和左上肢尺侧， 常发生于劳力负荷增加时， 持续数分钟， 休息或\n服用硝酸酯制剂后疼痛消失。疼痛发作的程度、 频度、 持续时间、 性质及诱发因素等在数月内无明显变化。\n【发病机制】 当冠脉狭窄或部分闭塞时， 其血流量减少， 心肌供血量相对比较固定。休息时尚能\n维持心肌血流的供需平衡， 病人可无症状。在劳力、 情绪激动、 饱食、 受寒等情况下， 心脏负荷突然增\n加， 使心率增快、 心肌张力和收缩力增加等导致心肌氧耗量增加， 而存在狭窄的冠脉供血却不能相应\n地增加以满足心肌需求时， 即可引起心绞痛。\n【病理解剖和病理生理】 稳定型心绞痛病人的冠脉造影显示： 有 1、 2 或 3 支冠脉狭窄减少＞\n70% 的病变者分别各占 25% 左右， 5%～10% 有左冠脉主干狭窄； 其余约 15% 的病人冠脉无显著狭窄，\n提示可能是冠脉痉挛、 微血管病变、 交感神经过度活动、 儿茶酚胺分泌过多或心肌代谢异常等导致心\n肌血供和氧供不足。\n病人心绞痛发作之前， 常有血压增高、 心率增快、 肺动脉压和肺毛细血管楔压增高， 反映心脏和肺\n的顺应性减低。发作时可有左心室收缩力和收缩速度降低、 射血速度减慢、 左心室收缩压下降、 心搏\n出量和心排血量降低、 左心室舒张末期压和血容量增加等左心室收缩和舒张功能障碍的病理生理变\n化。左心室壁可呈收缩不协调或部分有收缩减弱现象。\n【临床表现】 \n（一）   症 状  心绞痛以发作性胸痛为主要临床表现， 疼痛特点为：\n1.  诱因\n 常见诱因包括体力劳动或情绪激动\n（ 如愤怒、 焦急、 过度兴奋等）， 饱食、 寒冷、 吸烟、 心\n动过速、 休克等亦可诱发。疼痛多发生于劳力或激动的当时， 而不在劳累之后。典型稳定型心绞痛常\n在相似的条件下重复发生。\n2.  部位\n 主要在胸骨体后\n， 可波及心前区， 手掌大小范围， 也可横贯前胸， 界限不清。常放射至\n左肩、 左臂内侧达无名指和小指， 或至颈、 咽或下颌部。\n3.  性质\n 胸痛常为压迫\n、 发闷或紧缩性， 也可有烧灼感， 但不像针刺或刀扎样锐性痛， 偶伴濒死\n感。有些病人仅觉胸闷不适或呼吸困难， 而非胸痛。发作时病人往往被迫停止正在进行的活动， 直至\n症状缓解。\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0013\u0014\u0014\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0013\u0014\u0014 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0012\u001a\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0012\u001a\n234\n第三篇  循环系统疾病\n4.  持续时间 一般持续数分钟至十余分钟， 多为 3～5 分钟， 不超过半小时。\n5.  缓解方式 一般在停止原来诱发症状的活动后即可缓解\n； 硝酸甘油等快速起效的硝酸酯类药\n物舌下含服或喷吸也能在几分钟内使之缓解。\n（二）   体 征  平时一般无异常体征。心绞痛发作时常见心率增快、 血压升高、 表情焦虑、 皮肤冷或\n出汗， 有时出现第四或第三心音奔马律。可有暂时性心尖部收缩期杂音， 是因乳头肌缺血致功能失调\n引起二尖瓣关闭不全所致。\n【辅助检查】 \n（ 一）  实验室检查  血糖、 血脂检查可了解冠心病危险因素； 胸痛明显者需查血清心肌损伤标志\n物， 包括心肌肌钙蛋白 I 或 T、 肌酸激酶 （CK） 及同工酶 （CK-MB）， 据此与 ACS 相鉴别； 氨基末端脑钠\n肽前体 （NT-proBNP） 可了解病人心功能状态； 血常规可了解有无贫血； 必要时检查甲状腺功能。\n（二）   心 电 图（ECG）检查\n1.  静息时 ECG 约半数病人在正常范围， 也可能有陈旧性心肌梗死改变或非特异性 ST 段和 T\n波异常。有时出现房室或束支传导阻滞、 房性或室性期前收缩等心律失常， 但均非特异性。\n2.  发作时 ECG 绝大多数病人可出现暂时性心肌缺血引起的\nST 段移位。因心内膜下心肌更\n容易缺血， 故常见反映心内膜下心肌缺血的 ST 段压低 （≥0.1mV）， 发作缓解后恢复 （ 图 3-4-4）。有时\n也可以出现 T 波倒置。在平时有 T 波持续倒置的病人， 发作时可变为直立 （ “假性正常化”）。T 波改\n变虽然对反映心肌缺血的特异性不如 ST 段压低， 但如与平时 ECG 比较有明显差别， 也有助于诊断。\n图3 -4-4   心绞痛发作时的心电图\nⅠ\n、 Ⅱ、 Ⅲ、 aVF、 V4～6 导联 ST 段压低。\n3.  ECG 负荷试验 最常用的是运动负荷试验， 增加心脏负担以激发心肌缺血。运动方式主要\n为分级活动平板或踏车， 其运动强度可逐步升级。前者常用， 让受检查者迎着转动的平板就地踏步，\n以达到按年龄预计可达到的最大心率 （HRmax） 或亚极量心率 （85%～90% 的 HRmax） 为负荷目标， 前\n者为极量运动试验， 后者为亚极量运动试验。运动中应持续监测 ECG 改变。运动前、 运动中每当运\n动负荷量增加一次均应记录 ECG， 运动终止后即刻及此后每 2 分钟均应重复 ECG 记录， 直至心率恢\n复至运动前水平。ECG 记录时应同步测定血压。运动中出现典型心绞痛、 ECG 改变主要以 ST 段水\n平形或下斜形压低 ≥0.1mV （J 点后 60～80ms） 持续 2 分钟为运动试验阳性标准 （ 图 3-4-5）。运动中\n出现心绞痛、 步态不稳、 室性心动过速或血压下降时， 应立即停止运动。心肌梗死急性期、 不稳定型心\n绞痛、 明显心力衰竭、 严重心律失常或急性疾病者禁做运动试验。本试","资料来源":"人卫《内科学》第10版 · 循环.txt · 本节“慢性冠状动脉综合征”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2861,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bd393c8a49a1ac40c511ef3c9c9b814fc6b02f5ef871ba374d0d4273582d186a","pinyin":"manxingguanzhuangdongmaizonghezheng","initials":"mxgzdmzhz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-9c43dbdf9efeacdbd046","key":"v1-c9ccc21dfe2a3058|templates-9c43dbdf9efeacdbd046","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"慢性淋巴细胞白血病","category":"内科","raw":{"name":"慢性淋巴细胞白血病","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者因慢性淋巴细胞白血病入院，多以无痛性淋巴结肿大、乏力或体检发现持续淋巴细胞增多为主要表现，完善血常规加白细胞分类计数明确淋巴细胞绝对值及有无贫血、血小板减少，是诊断与分期的基础；同步行外周血涂片检查了解淋巴细胞形态、有无幼稚细胞及涂抹细胞，鉴别其他淋巴增殖性疾病；完善流式细胞术免疫分型检查明确CD5、CD19、CD23等特征性表型，是确诊慢性淋巴细胞白血病的关键依据；查血清免疫球蛋白定量了解有无低丙种球蛋白血症，评估感染风险并指导免疫支持治疗；查直接抗人球蛋白试验（Coombs试验）排除自身免疫性溶血性贫血所致贫血；查乳酸脱氢酶与β2微球蛋白了解肿瘤负荷，评估预后分层；查肝肾功能与电解质排除肝肾功能不全及肿瘤溶解所致代谢紊乱，并为化疗、靶向药物选择提供依据；完善骨髓穿刺及活检明确骨髓浸润程度，对诊断不明确或需鉴别者尤为必要；完善染色体核型与FISH检测（del(13q)、del(11q)、del(17p)、TP53）明确遗传学预后分层，指导治疗时机与方案选择；完善颈部、腹部及浅表淋巴结超声与胸腹部CT检查明确淋巴结、肝脾肿大范围，评估疾病分期；必要时查HBV、HCV及EBV等感染指标，为免疫化疗前的病毒再激活风险评估提供依据，治疗期间定期复查血常规与肝肾功能。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 慢性淋巴细胞白血病","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"慢性淋巴细胞白血病 （chronic lymphocytic leukemia， CLL） 是一种进展缓慢的成熟 B 淋巴细胞增\n殖性肿瘤， 以外周血， 骨髓、 脾和淋巴结等淋巴组织中出现大量克隆性 B 淋巴细胞为特征。CLL 细胞\n形态上类似成熟淋巴细胞， 但免疫学表型和功能异常。CLL 均起源于成熟 B 细胞， 病因及发病机制尚\n未完全明确。本病在西方国家是较常见的成人白血病， 但在亚洲发病率显著下降。\n【临床表现】 本病好发于老年人群， 男性患者多见。起病缓慢， 诊断时多无自觉症状， 超过半数\n患者在常规体检或因其他疾病就诊时才被发现。有症状者早期可表现为乏力、 疲倦、 消瘦、 低热、 盗汗\n等。约 60%～80% 的患者存在淋巴结肿大， 多见于头颈部、 锁骨上、 腋窝、 腹股沟等部位。肿大淋巴\n结一般为无痛性， 质韧、 无粘连， 随病程进展可逐渐增大或融合。CT 扫描可发现纵隔、 腹膜后、 肠系膜\n淋巴结肿大。肿大的淋巴结可压迫气管、 上腔静脉、 胆道或输尿管而出现相应症状。半数以上患者有\n轻至中度的脾大， 肝大多为轻度， 胸骨压痛少见。晚期患者可出现贫血、 血小板减少和粒细胞减少， 常\n并发感染。由于免疫功能失调， 约 10%～15% 的 CLL 患者可并发自身免疫病， 如自身免疫性溶血性\n贫血 （AIHA）、 原发免疫性血小板减少症 （ITP） 等。部分患者可转化为 Richter 综合征 （CLL 转化为弥\n漫大 B 细胞淋巴瘤或霍奇金淋巴瘤等）。\n【实验室检查】 \n1.  血象\n 以淋巴细胞持续性增多为主要特征\n， 外周血单克隆 B 淋巴细胞绝对值通常≥5×1 0\n9\n/L。\n大多数患者的白血病细胞形态与成熟小淋巴细胞类同， 胞质少， 胞核染色质呈凝块状。多数患者外周\n血涂片可见破碎细胞 （ 涂抹细胞）， 少数患者细胞形态异常， 胞体较大， 不成熟， 胞核有深切迹 （Reider\n细胞）。偶可见原始淋巴细胞。中性粒细胞比值降低。随病情进展， 可出现血小板减少和贫血。\n2.  骨髓象\n 有核细胞增生明显活跃或极度活跃\n， 淋巴细胞≥40%， 以成熟淋巴细胞为主。红系、\n粒系及巨核系细胞增生受抑， 至晚期可明显减少。伴有溶血时， 幼红细胞可代偿性增生。\n3.  免疫学检查\n 免疫表型检查是目前\nCLL 疾病诊断和疗效监测的重要手段， 目前大多使用流式\n细胞仪进行检测。 CLL 细胞具有单克隆性， 呈现 B 细胞免疫表型特征。细胞膜表面免疫球蛋白 （SmIg）\n为弱阳性表达， 多为 IgM 或 IgM和 IgD 型， 呈κ或λ单克隆轻链型； CD5、 CD19、 CD23 阳性； CD200 强\n阳性； CD20、 CD22、 CD11c 弱阳性； FMC7、 CD79b 阴性或弱阳性； CD10、 Cyclin D1 阴性。可患者 RMH\n免疫标志积分进行鉴别， CLL 积分为 4～5 分， 其他 B 细胞慢性淋巴增殖性疾病为 0～2 分。积分≤3\n分时建议患者荧光原位杂交 （FISH） 技术检测， 除外套细胞淋巴瘤 （MCL） 等， 并参考 CD200、 CD43 的\n表达情况。另外， LEF1 在 CLL 阳性、 MCL 阴性也有助于鉴别。\n4.  细胞遗传学检查 由于\nCLL 细胞有丝分裂较少， 染色体异常检出率较低。间期 FISH 技术可\n检测到＞80% 的患者存在染色体异常。如 13q14 缺失 （50%）、 12 号染色体三体 （20%）、 11q22-23 缺失、\n17p13 缺失和 6q 缺失等。接受免疫治疗及化疗的患者， 单纯 13q14 缺失提示预后良好， 12 号染色体\n三体和正常核型预后中等， 17p13 及 11q22-23 缺失预后差。\n5.  分子生物学检查 约\n50%～60% 的 CLL 发生免疫球蛋白重链可变区 （IGHV） 基因体细胞突\n变，IGHV 突变的 CLL 患者生存期长，IGHV 无突变的 CLL 患者预后较差。约 5%～8% 的初诊 CLL 存\n在 TP53 基因突变 （ 该基因位于 17p13），与疾病进展有关， 对治疗有抵抗， 生存期短。此外近年来发现\nCLL 中存在SF3B1、NOTCH1、MYD88 等基因突变， 可能与 CLL 发病和耐药相关。\n【 诊断与鉴别诊断 】 CLL 的诊断标准如下： ①外周血单克隆 B 淋巴细胞 （ CD19\n+\n细胞） 计数\n≥5×1 0\n9\n/L， 且持续≥3 个月 （ 如具有典型的 CLL 免疫表型、 形态学等特征， 则时间长短对 CLL 的诊断\n5-6篇.indd 5885-6篇.indd 588 2024/7/28 10:28:102024/7/28 10:28:10\n第九章  白血病\n589\n意义不大）； B 淋巴细胞＜5×1 0\n9\n/L， 如存在 CLL 细胞骨髓浸润所致的血细胞减少， 也可诊断 CLL。②外\n周血涂片中特征性表现为小的、 形态成熟的淋巴细胞显著增多， 外周血淋巴细胞中不典型淋巴细胞及\n幼稚淋巴细胞 ≤55%。③典型的免疫表型特征： CD5、 CD19、 CD23、 CD200、 CD43 阳性， CD10、 FMC7、\nCCDN 阴性， SmIg、 CD20、 CD79b 弱表达。\n但患者下列疾病相鉴别。\n1.  病毒感染引起的反应性淋巴细胞增多症 淋巴细胞增多呈多克隆性和暂时性\n， 淋巴细胞计数\n随感染控制可逐步恢复正常。\n2.  其他 B 细胞慢性淋巴增殖性疾病 侵犯\n骨髓的其他 B 细胞慢性淋巴增殖性疾病 （ 如滤泡性\n淋巴瘤、 套细胞淋巴瘤、 脾边缘区淋巴瘤等）与 CLL 易混淆， 前者除具有原发病病史外， 细胞形态学、\n淋巴结及骨髓病理、 免疫表型特征及细胞遗传学与 CLL 不同。\n3.  毛细胞白血病（HCL） 多数为全血细胞减少伴脾大\n， 淋巴结肿大不常见， 易于鉴别。但少数\n患者白细胞升高达 （10～30） × 10\n9\n/L。外周血及骨髓中可见 “毛细胞”， 即有纤毛状胞质突出物的 HCL\n细胞， 抗酒石酸酸性磷酸酶染色反应阳性， CD5 阴性， 高表达 CD25、 CD11c、 CD103和 CD","资料来源":"人卫《内科学》第10版 · 血液.txt · 本节“慢性淋巴细胞白血病”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2862,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0690a4195108d1782f7075339fbd7cc9e93e5513c1e5a5ff52baefcab32b4719","pinyin":"manxinglinbaxibaobaixuebing","initials":"mxlbxbbxb","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-63e14aa7af9bddd65832","key":"v1-c9ccc21dfe2a3058|templates-63e14aa7af9bddd65832","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"慢性髓系白血病","category":"内科","raw":{"name":"慢性髓系白血病","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者初步诊断慢性髓系白血病，需先明确血象异常程度及有无幼稚细胞，入院即刻完善血常规+白细胞手工分类检查了解白细胞升高幅度及细胞形态，同时查外周血涂片了解有无幼稚粒细胞、嗜碱性粒细胞增多及血小板异常；为明确诊断并获取治疗前基线，完善骨髓穿刺涂片+骨髓活检了解骨髓增生程度、粒红比例及有无骨髓纤维化，完善染色体核型分析明确有无 Ph 染色体 t(9;22)，完善 BCR-ABL 融合基因定量检查明确转录本类型及国际标准化比值基线，指导后续 TKI 靶向治疗及疗效监测；为评估肿瘤负荷与用药安全，完善乳酸脱氢酶及血尿酸检查了解肿瘤溶解风险，完善肝肾功能、电解质检查排除肝肾功能不全及电解质紊乱，肝肾功能为 TKI 药物经肝肾代谢的必查项目；为排查合并感染与血液制品输注准备，查乙肝五项、丙肝抗体、HIV 抗体及梅毒筛查排除合并病毒感染，查凝血功能与血型鉴定了解凝血状态、为必要时成分输血及造血干细胞移植作准备；查腹部超声了解肝脾肿大及有无髓外浸润，查心电图、心脏彩超评估心脏结构与功能，为 TKI 治疗前心脏毒性基线及定期复查提供依据。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 慢性髓系白血病","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"慢性髓系白血病 （chronic myelogenous leukemia， CML）， 又称慢性粒细胞白血病， 俗称慢粒， 是一种\n发生在多能造血干细胞的恶性骨髓增殖性肿瘤 （ 为获得性造血干细胞恶性克隆性疾病）， 主要涉及髓\n系。外周血粒细胞显著增多， 在受累的细胞系中， 可找到 Ph 染色体和\n /\n 或 BCR::ABL1 融合基因。病程\n发展缓慢\n， 多数脾大。CML 自然病程分为慢性期 （chronic phase， CP）、 加速期 （accelerated phase， AP）和急变期 （blastic phase or blast crisis， BP/BC）。\n【临床表现和实验室检查】 CML 在我国年发病率为 （0.39～0.55） /10 万。在各年龄组均可发病，\n国内中位发病年龄 45～50 岁， 男性多于女性。起病缓慢， 早期常无自觉症状。患者可因健康检查或\n因其他疾病就医时发现血象异常或脾大而被确诊。\n（ 一）  慢 性 期 （ C P）  CP 一般持续 1～4 年。患者有乏力、 低热、 多汗或盗汗、 体重减轻等代谢亢\n进的症状， 由于脾大而自觉有左上腹坠胀感。常以脾大为最显著体征， 往往就医时已达脐或脐以下，\n质地坚实， 平滑， 无压痛。如果发生脾梗死， 则脾区压痛明显， 并有摩擦音。明显肝大者较少见。部分\n患者胸骨中下段压痛。当白细胞显著增高时， 可有眼底充血及出血。白细胞极度增高时， 可发生白细\n胞淤滞症。\n1.  血象\n 白细胞数明显增高，\n常超过 20 × 10\n9\n/L， 可达 100 × 10\n9\n/L 以上， 血涂片中粒细胞显著增多，\n可见各阶段粒细胞， 以中性中幼、 晚幼和杆状核粒细胞居多； 原始 （ Ⅰ+Ⅱ）细 胞＜10%； 嗜酸、 嗜碱性粒\n细胞增多， 后者有助于诊断。血小板可在正常水平， 近半数患者增多； 晚期血小板逐渐减少， 并出现\n贫血。\n2.  中性粒细胞碱性磷酸酶（NAP） 活性减低或呈\n阴性反应。治疗有效时 NAP 活性可以恢复，\n疾病复发时又下降， 合并细菌性感染时可略升高。\n3.  骨髓象\n 骨髓增生明显至极度活跃\n， 以粒细胞为主， 粒红比例明显增高， 其中中性中幼、 晚幼\n及杆状核粒细胞明显增多， 原始细胞＜10%。嗜酸、 嗜碱性粒细胞增多。红细胞相对减少。巨核细胞\n正常或增多， 晚期减少。偶见戈谢 （Gaucher） 细胞。\n4.  细胞遗传学及分子生物学检查\n 95% 以上的\nCML 细胞中出现 Ph 染色体 （ 小的 22 号染色体），\n显带分析为 t （9； 22） （\nq34； q11）。9 号染色体长臂上ABL1 原癌基因易位至 22 号染色体长臂的断裂\n5-6篇.indd 5855-6篇.indd 585 2024/7/28 10:28:102024/7/28 10:28:10\n586\n第六篇  血液系统疾病\n点簇集区 （BCR），形 成BCR::ABL1 融合基因。其编码的蛋白主要为 P210，P210 具有酪氨酸激酶活性。\nPh 染色体可见于粒、 红、 单核、 巨核及淋巴细胞中。不足 5% 的 CML 有BCR::ABL1 融合基因阳性而\nPh 染色体阴性。\n5.  血液生化检查\n 血清及尿中尿酸浓度增高。血清\nLDH 增高。\n（二）   加 速 期（AP）  AP 可维持几个月到数年。常有发热、 虚弱、 进行性体重下降、 骨骼疼痛，\n逐渐出现贫血和出血； 脾持续或进行性肿大； 原来治疗有效的药物包括酪氨酸激酶抑制剂 （tyrosine \nkinase inhibitor， TKI） 无效； 外周血或骨髓原始细胞≥10%； 外周血嗜碱性粒细胞＞20%； 不明原因的血\n小板进行性减少或增加； Ph 染色体阳性细胞中又出现其他染色体异常， 如： +8、 双 Ph 染色体、 17 号染\n色体长臂的等臂 ［i （17q） ］ 等。\n（三）   急 变 期（BC）  为 CML 的终末期， 临床与 AL 类似。多数发展为急性髓系白血病， 少数发展\n为急性淋巴细胞白血病或急性单核细胞白血病， 偶有巨核细胞及红细胞等类型的急性变。急性变预\n后极差， 往往在数月内死亡。外周血或骨髓中原始细胞＞20% 或出现髓外原始细胞浸润。\n【诊断与鉴别诊断】 凡有不明原因的持续性白细胞数增高， 根据典型的血象、 骨髓象改变， 脾大，\nPh 染色体阳性和 / 或BCR::ABL1 融合基因阳性即可作出诊断。Ph 染色体尚可见于 1%AML、 5% 儿\n童 ALL 及 25% 成人 ALL， 应注意鉴别。不具有 Ph 染色体和BCR::ABL1 融合基因而临床特征类似于\nCML 的疾病， 归入骨髓增生异常性肿瘤 / 骨髓增殖性肿瘤。其他需要鉴别的疾病如下。\n1.  其他原因引起的脾大 血吸虫病\n、 慢性疟疾、 黑热病、 肝硬化、 脾功能亢进等均有脾大， 但均有\n各自原发病的临床特点， 并且血象及骨髓象无 CML 的典型改变。Ph 染色体及BCR::ABL1 融合基因\n均阴性。\n2.  类白血病反应 常并发于严重感染\n、 恶性肿瘤等基础疾病， 并有相应原发病的临床表现。粒\n细胞胞质中常有中毒颗粒和空泡。嗜酸性粒细胞和嗜碱性粒细胞不增多。NAP 反应强阳性。Ph 染\n色体及 BCR::ABL1 融合基因阴性。血小板和血红蛋白大多正常。原发病控制后， 白细胞恢复正常。\n3.  骨髓纤维化\n 原发性骨髓纤维化脾大显著，\n血象中白细胞增多， 并出现幼粒细胞等， 易与 CML\n混淆。但骨髓纤维化外周血白细胞数一般比 CML 少， 多不超过 30 × 10\n9\n/L。NAP 阳性。此外幼红细\n胞持续出现于外周血中， 红细胞形态异常， 特别是泪滴状红细胞易见。Ph 染色体及BCR::ABL1 融合\n基因阴性。患者可存在 JAK2\n V617F、CALR、MPL 基因突变\n。多次多部位骨髓穿刺干抽。骨髓活检网\n状纤维染色阳性。\n【治疗】 CML 治疗应着重于慢性期早期， 避免疾病转化， 力争细胞遗传学和分子生物学水平的\n缓解， 一旦进入加速期或急变期 （ 统称进展期） 则预后不良。\n（ 一）  CML CP 的治疗\n","资料来源":"人卫《内科学》第10版 · 血液.txt · 本节“慢性髓系白血病”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2863,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"dab7051609cc591e1d967c04c5e1d07e5219e68d8e6be8ef418a712b9d73d26f","pinyin":"manxingsuixibaixuebing","initials":"mxsxbxb","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-962d8593c6183f077cf0","key":"v1-c9ccc21dfe2a3058|templates-962d8593c6183f077cf0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"成人常见先天性心血管病","category":"内科","raw":{"name":"成人常见先天性心血管病","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者初步诊断成人常见先天性心血管病，因长期左向右分流或右向左分流可致心腔扩大、肺动脉高压及心律失常，入院后完善心电图检查了解有无心室肥厚、束支传导阻滞及心律失常，查胸部 X 线检查了解肺血增多或减少、心影形态及主动脉结情况；经胸超声心动图为本病首选无创检查，完善心脏彩超+左心功能测定明确缺损部位、大小、分流方向、瓣膜情况与射血分数，评估肺动脉压力及心内合并畸形；对超声不能明确解剖关系或合并复杂畸形者，必要时完善心脏 CT 血管成像或心脏 MRI 检查进一步明确心内结构异常及大血管连接关系；为明确肺血管阻力及手术、介入封堵指征，必要时完善心导管检查及造影评估血流动力学；为评估手术耐受性，完善血常规、凝血功能检查了解有无贫血、血小板减少及凝血障碍，完善肝肾功能、电解质检查排除肝肾功能不全及电解质紊乱，查动脉血气分析了解氧合及有无酸中毒；患者心内结构异常易并发感染性心内膜炎，必要时完善血培养检查明确有无菌血症，并行经食管超声心动图鉴别心内赘生物；查甲状腺功能排除甲状腺功能异常所致心脏改变。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 成人常见先天性心血管病","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"先天性心血管病 （congenital cardiovascular diseases） 是指心脏及大血管在胎儿期发育异常引起\n的、 在出生时病变即已存在的疾病， 简称先心病。在我国， 先心病的发病率为 0.7%～0.8%。成人常见\n先天性心血管病见表 3-7-1。\n表3 -7-1   成人常见先天性心血管病\n部位 畸形 血流动力学\n心房 房间隔缺损 左向右分流\n卵圆孔未闭 房水平分流较小\n心室 室间隔缺损 左向右分流\n瓣膜 二叶主动脉瓣 无分流\n肺动脉瓣狭窄 无分流\n三尖瓣下移 无分流\n血管 动脉导管未闭 左向右分流\n主动脉缩窄 无分流\n主动脉窦瘤 窦瘤破裂多发生左向右分流\n冠状动脉瘘 多发生左向右分流\n复杂 法洛四联症 右向左分流\n一、  房间隔缺损\n房间隔缺损 （atrial septal defect， ASD） 是最常见的成人先天性心脏病， 占成人先天性心脏病的\n20%～30%， 男女发病率之比为 1∶ （1.5～3）， 且有家族遗传倾向。\n【 病理解剖 】 房 间 隔 缺 损 一 般 分 为 原 发 孔 缺 损 （primum atrial septal defect）和 继 发 孔 缺 损\n（secundum atrial septal defect）。后者又分为中央型缺损、 下腔型缺损、 上腔型缺损和混合型缺损， 以中\n央型缺损最多见， 也可有多个缺损同时存在。\n【病理生理】 房间隔缺损对血流动力学的影响主要取决于分流量的多少。持续的肺血流量增加\n导致肺淤血， 使右心容量负荷增加， 肺血管顺应性下降， 从功能性肺动脉高压发展为器质性肺动脉高\n压， 晚期可形成 Eisenmenger 综合征。\n【临床表现】 一般无症状， 随病情发展可出现劳力性呼吸困难、 心律失常、 右心衰竭等， 晚期约有\n15% 的病人因重度肺动脉高压出现右向左分流而有青紫， 形成 Eisenmenger 综合征。\n体格检查最典型的体征为肺动脉瓣区第二心音亢进伴固定分裂， 部分病人并可闻及Ⅱ～Ⅲ级收\n缩期吹风样杂音。\n【辅助检查】 \n1.  心电图\n 可有电轴右偏、\n右室肥大、 右束支传导阻滞等表现。\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0013\u0019\u0019\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0013\u0019\u0019 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0013\u0017\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0013\u0017\n第七章  先天性心血管病\n289\n2.  X 线检查 可见右房、 右室增大， 肺动脉段突出及肺血管影增加。\n3.  超声心动图\n 可见房间隔处连续性中断。\n【\n诊断与鉴别诊断】 典型的心脏听诊、 心电图、 X 线表现可提示房间隔缺损的存在， 超声心动图\n可以确诊。应与肺静脉畸形引流、 肺动脉瓣狭窄及小型室间隔缺损等鉴别。\n【治疗】 对于成人房间隔缺损病人， 只要超声检查有右室容量负荷增加的证据， 就应尽早关闭缺\n损。房间隔缺损的治疗方法包括介入治疗和外科开胸手术两种。\n1.  介入治疗\n 参见本章第二节。\n2\n.  手术治疗 在未开展介入手术治疗以前\n， 对所有单纯房间隔缺损已引起血流动力学改变者均\n应手术治疗。\n【预后】 死亡原因常为心力衰竭， 其次为肺部感染、 肺动脉血栓形成或栓塞。\n二、  室间隔缺损\n室间隔缺损 （ventricular septal defect， VSD）， 也是一种常见的先天性心脏畸形， 约占成人先天性心\n血管疾病的 10%～20%。可单独存在， 亦可与其他畸形合并发生。\n【病理解剖】 室间隔由膜部、 漏斗部和肌部三部分组成。根据缺损的部位， 室间隔缺损可分为：\n膜部缺损， 最常见； 漏斗部缺损， 又可分为干下型和嵴内型； 肌部缺损。\n【病理生理】 室间隔缺损必然导致心室水平的左向右分流， 其血流动力学效应为： ①肺循环血量\n增多； ②左室容量负荷增大； ③体循环血量下降； ④晚期可形成 Eisenmenger 综合征。\n【临床表现】 一般根据血流动力学受影响的程度、 症状轻重等， 临床上分为大、 中、 小型室间隔\n缺损。\n1.  小型室间隔缺损 此类病人通常无症状\n， 沿胸骨左缘第 3～4 肋间可闻及Ⅳ～Ⅵ级全收缩期\n杂音伴震颤， P2 心音可有轻度分裂， 无明显亢进。\n2.  中型室间隔缺损 部分病人有劳力性呼吸困难\n。听诊除在胸骨左缘可闻及全收缩期杂音伴\n震颤外， 并可在心尖区闻及舒张中期反流性杂音， P2 心音可轻度亢进。\n3.  大型室间隔缺损 因血流动力学影响严重\n， 存活至成人期者较少见， 且常因出现右向左分流\n而呈现青紫； 并有呼吸困难及负荷能力下降。胸骨左缘收缩期杂音常减弱至Ⅲ级左右， P2 心音亢进；\n有时可闻及因继发性肺动脉瓣关闭不全而致的舒张期杂音。\n【辅助检查】 \n1.  心电图\n 可正常或电轴左偏，\n较大缺损时可有左室或双室肥大。\n2.  X 线检查\n 可见肺血增加\n， 心影略向左增大； 大型缺损主要表现为肺动脉及其主要分支明显\n扩张， 肺野外 1/3 血管影突然减少， 心影大小不一。\n3.  超声心动图\n 可见室间隔处连续性中断。\n【\n诊断与鉴别诊断】 典型室间隔缺损根据临床表现及超声心动图即可确诊。需与肺动脉瓣狭\n窄、 肥厚型心肌病鉴别， 合并肺动脉高压者应与原发性肺动脉高压及法洛四联症鉴别。\n【治疗】 \n1.  介入治疗\n 参见本章第二节。\n2\n.  手术治疗 室间隔缺损修补术\n。伴明显肺动脉压增高， 肺血管阻力＞7Wood 单位者不宜\n手术。\n【预后】 缺损面积较小者预后良好， 较大缺损伴有严重肺动脉高压者预后极差。\n三、  动脉导管未闭\n动脉导管未闭 （patent ductus arteriosus， PDA） 是常见的先天性心脏病之一， 占先天性心脏病总数\n的 12%～15%， 女性约两倍于男性。约 10% 的病例并存其他心血管畸形。\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0013\u0019\u001a\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0013\u0019\u001a \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0013\u0017\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0013\u0017\n290\n第三篇  循环系统疾病\n【病理解剖】 动脉导管连接肺动脉总干与降主动脉， 是胎儿期血液循环的主要渠道。出生后一\n般在数月内因废用而闭合， 如 1 岁后仍未闭合， 即为动脉导管未闭。\n【病理生理】 由于存在左向右分流","资料来源":"人卫《内科学》第10版 · 循环.txt · 本节“成人常见先天性心血管病”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2864,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d854a585967c8f1dd90f10447399958902e574fee022e8e8ace350af18e6bdc3","pinyin":"chengrenchangjianxiantianxingxinxueguanbing","initials":"crcjxtxxxgb","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-447f143355600b796bde","key":"v1-c9ccc21dfe2a3058|templates-447f143355600b796bde","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"房室交界性心律失常","category":"内科","raw":{"name":"房室交界性心律失常","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者初步诊断房室交界性心律失常，该病常见于洋地黄中毒、心肌炎、急性下壁心肌梗死及心脏手术后，入院即刻完善十二导联心电图检查明确心律失常类型及有无房室传导阻滞，查动态心电图了解心律失常发作频率、持续时间及与症状的关系；为排查常见可逆诱因，急诊完善电解质检查排除低钾、低镁所致心律失常，完善心肌酶及肌钙蛋白检查排除急性心肌损伤及心肌炎，查肾功能及地高辛血药浓度排除洋地黄中毒及药物蓄积；完善心脏彩超+左心功能测定了解心脏结构、室壁运动及射血分数，明确有无器质性心脏病基础；查甲状腺功能检查排除甲状腺功能亢进或减退所致心律失常，查血常规排除贫血及感染；为后续抗心律失常药物及射频消融治疗作准备，完善肝肾功能检查排除肝肾功能不全，查凝血功能了解凝血状态，必要时完善心内电生理检查明确折返机制及阻滞部位；病情稳定后定期复查心电图观察有无动态演变。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 房室交界性心律失常","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"一、  房室交界性期前收缩\n房室交界性期前收缩 （premature atrioventricular junctional beats） 简称交界性期前收缩。其冲动起\n源于房室交界区， 可前向和逆向传导， 分别产生提前发生的 QRS 波与逆行 P 波； 逆行 P 波可位于 QRS\n波之前 （PR 间期＜0.12 秒）、 之中或之后 （RP 间期＜0.20 秒）； QRS 波形态正常 （ 图 3-3-13）， 当发生室\n内差异性传导时， QRS 波形态可有变化。\n房室交界性期前收缩通常无需治疗。\n图3 -3-13   房室交界性期前收缩\n箭头指示为房室交界性期前收缩。\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0013\u0011\u0014\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0013\u0011\u0014 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0012\u0011\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0012\u0011\n204\n第三篇  循环系统疾病\n二、  房室交界性逸搏与心律\n【住址】， 称为潜在起搏点。下列情况时， 潜在起搏点可成\n为主导起搏点： ①由于窦房结发放冲动频率减慢， 低于潜在起搏点的固有频率； ②由于传导障碍， 窦\n房结冲动不能抵达潜在起搏点部位， 潜在起搏点自动除极产生逸搏。房室交界性逸搏 （AV junctional \nescape beats） 的心电图表现为在长于正常 PP 间期的间歇后出现一个正常的 QRS 波， P 波缺失， 或逆\n行 P 波位于 QRS 波之前或之后， 此外， 亦可见到未下传至心室的窦性 P 波。\n房室交界性心律 （AV junctional rhythm） 指房室交界性逸搏连续发生而形成的节律。心电图显示\n正常下传的 QRS 波， 频率为 40～60 次 / 分\n， 可有逆行 P 波或存在独立、 缓慢的心房电活动， 从而形成\n房室分离， 此时， 心室率超过心房率 （ 图 3-3-1 4）。\n图3 -3-14   房室交界性心律\nRR\n间期 1.24 秒， 频率为 48 次\n /\n 分，\nQRS 波群后出现逆行 P 波， RP=0.15 秒。\n房室交界性逸搏或心律的出现，与迷走神经张力增高、 显著的窦性心动过缓或房室传导阻滞有\n关， 并作为防止心室停搏的生理保护机制。一般无需治疗， 必要时可起搏治疗。\n三、  非阵发性房室交界性心动过速\n非阵发性房室交界性心动过速 （nonparoxysmal atrioventricular junctional tachycardia） 的发生机制\n【住址】。最常见的病因为洋地黄中毒， 其次为下壁心肌梗\n死、 心肌炎、 急性风湿热或心脏瓣膜手术后等， 亦偶见于正常人。\n心动过速发作起始与终止时， 心率逐渐变化， 有别于突发突止的阵发性折返性心动过速， 故称为\n“非阵发性”。心率 70～150 次\n /\n 分或更快，\n心律通常规则， QRS 波群正常， 自主神经系统张力变化可影\n响心率快慢。如心房的电活动由窦房结或异位心房起搏点控制， 可发生房室分离。洋地黄过量引起\n者， 经常合并房室交界区文氏型传导阻滞， 使心室律变得不规则。\n治疗主要针对基本病因。本型心律失常通常能自行消失， 如病人耐受性良好， 仅需密切观察和治\n疗原发疾病。已用洋地黄或疑洋地黄中毒者应立即停用洋地黄， 补充钾盐， 不宜施行电复律； 如与洋\n地黄无关， 可患者β受体拮抗剂、 非二氢吡啶类钙通道阻滞剂或洋地黄治疗。其他药物可选用 Ⅰ a、 Ⅰ c与Ⅲ类 （ 胺碘酮） 抗心律失常药物。\n四、  房室交界区相关的折返性心动过速\n房室交界区相关的折返性心动过速主要包括房室结折返性心动过速 （ atrioventricular nodal \nreentrant tachycardia， AVNRT）和房室折返性心动过速 （atrioventricular reentrant tachycardia， AVRT） 两大\n类， 临床特征表现为规律而快速的心动过速， 呈突然发作与终止， 心电图多表现为 QRS 波群形态正常、\nRR 间期规则的快速心律， 故在临床上又统称为阵发性室上性心动过速 （paroxysmal supraventricular \ntachycardia， PSVT）， 简称室上速。其共同的发生机制是折返， 前者的折返环路位于房室结内； 后者由\n房室交界区、 旁道与心房、 心室共同组成折返环路，与预激综合征密切相关。\n房室结折返性心动过速\n【病因】 病人多无器质性心脏病， 常见于年轻人， 相当部分病人有长期反复发作病史。\n【临床表现】 心动过速呈阵发性， 突发突止； 持续时间长短不一， 可数分钟或数小时， 甚者可达\n数天。症状包括突发的心悸、 胸闷、 焦虑不安、 头晕、 疲劳， 少见有晕厥、 心绞痛、 心力衰竭与休克。症\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0013\u0011\u0015\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0013\u0011\u0015 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0012\u0011\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0012\u0011\n第三章  心律失常\n205\n状轻重取决于发作时心室率加快的程度以及持续时间， 亦与是否合并器质性心脏病及其严重程度相\n关。若发作时心室率过快， 使心排血量与脑血流量锐减， 或心动过速猝然终止， 窦房结未能及时恢\n复自律性导致心搏停顿， 则可发生晕厥。心动过速发作时听诊心尖区第一心音强度恒定， 心律绝对\n规则。\n【心电图特征】 心电图表现为： ①心率常为 150～200 次 / 分， 节律规则， 偶尔超过 250 次 / 分， 尤\n其是儿童； ②QRS 波群形态与时限均正常， 但发生室内差异性传导或束支传导阻滞时， QRS 波群形态\n异常； ③P 波为逆行性 （Ⅱ、 Ⅲ、 aVF 导联倒置）， 常埋藏于 QRS 波群内或位于其终末部分， P 波与 QRS\n波保持固定关系； ④起始突然， 通常由一个房性期前收缩触发， 其下传的 PR 间期显著延长， 随之引起\n心动过速发作 （ 图 3-3-1 5）。\n图3 -3-15   房室结折返性心动过速\n连续快速、\n规则的 QRS 波群， 其形态和时限均正常， 频率 154 次\n /\n 分，\nQRS 波群终末部分可见逆行 P 波。\n【心电生理检查】 心电生理检查是 ","资料来源":"人卫《内科学》第10版 · 循环.txt · 本节“房室交界性心律失常”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2865,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7c192b9b46614fea75ef1ce1da091a34d00428d8363ff836aadceb6508ef70fb","pinyin":"fangshijiaojiexingxinlvshichang","initials":"fsjjxxlsc","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-de9e806df931155b6947","key":"v1-c9ccc21dfe2a3058|templates-de9e806df931155b6947","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"房性心律失常","category":"内科","raw":{"name":"房性心律失常","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者初步诊断房性心律失常，房性早搏、房速及心房颤动多与心房结构重构、甲状腺功能异常及电解质紊乱相关，入院即刻完善十二导联心电图检查明确心律失常类型，查动态心电图了解房性心律失常负荷及有无长间歇；完善心脏彩超+左心功能测定了解心房大小、有无瓣膜病变及左房血栓、评估射血分数，查经食管超声心动图明确有无左心耳血栓，为复律及射频消融治疗提供依据；为排查可逆诱因，完善甲状腺功能检查排除甲状腺功能亢进所致房性心律失常，完善电解质检查排除电解质紊乱，查心肌酶及肌钙蛋白检查排除急性心肌损伤；为评估血栓栓塞风险与抗凝方案，完善凝血功能、D-二聚体检查了解凝血状态，完善肝肾功能检查排除肝肾功能不全并指导抗凝药物剂量；查血常规了解有无贫血及血小板减少，查血脂、血糖检查了解有无动脉粥样硬化危险因素；必要时完善心内电生理检查明确异位起源部位，病情稳定后定期复查心电图及动态心电图观察心律控制情况。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 房性心律失常","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"一、  房性期前收缩\n房性期前收缩 （premature atrial beats），也称房性早搏， 简称房早，是指起源于窦房结以外心房的\n任何部位的心房激动， 是临床上常见的心律失常。\n【临床表现】 主要表现为心悸， 自觉有停跳感， 部分伴有胸闷、 乏力等； 有些病人可能无任何症\n状。房早多为功能性， 正常成人进行 24 小时动态心电图监测， 大约 60% 有房早发生。在各种器质性\n心脏病如冠心病、 肺心病、 心肌病等病人中， 房早发生率明显增加， 并常可引起其他快速型房性心律\n失常。\n【 心电图特征 】 心电图表现为： ①P 波提前发生，与窦性 P 波形态不同； ②PR 间期＞120ms；\n③QRS 波群呈室上性， 部分可有室内差异性传导； ④多为不完全代偿间歇。如发生在舒张早期， 适逢\n房室结尚未脱离前次搏动的不应期， 可产生传导中断， 无 QRS 波发生 （ 被称为阻滞的或未下传的房早）\n或缓慢传导 （ 下传的 PR 间期延长） 现象 （ 图 3-3-8）。\n图3 -3-8   房性期前收缩\nⅡ\n导联箭头处为房早； V1 导联箭头处为房早伴室内差异性传导； aVL和Ⅲ导联箭头处均为未下传的\n房早， aVL 导联提前出现的房性 P 波与前面的 T 波部分融合， Ⅲ导联提前出现的房性 P 波与前面的\nT 波完全融合， 导致 T 波高耸。\n【治疗】 房早通常无需治疗。吸烟、 饮酒和咖啡均可诱发房早， 应劝导病人戒除或减量。有症状\n或当房早诱发心动过速发生时， 可用β受体拮抗剂或非二氢吡啶类钙通道阻滞剂治疗。\n二、  房性心动过速\n房性心动过速 （atrial tachycardia） 简称房速， 指起源于心房且无需房室结参与维持的心动过速。\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0012\u001a\u0019\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0012\u001a\u0019 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0011\u001a\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0011\u001a\n第三章  心律失常\n199\n发生机制包括自律性增加、 折返与触发活动。根据起源点不同， 分为局灶性房性心动过速 （focal atrial \ntachycardia）和多源性房性心动过速 （multifocal atrial tachycardia）， 后者也称为紊乱性房性心动过速\n（chaotic atrial tachycardia）， 是严重肺部疾病常见的心律失常， 最终可能发展为心房颤动。\n【病因】 冠心病、 慢性肺部疾病、 洋地黄中毒、 大量饮酒以及各种代谢障碍均可成为致病原因。\n心脏外科手术或导管消融术后所致的手术瘢痕也可引起房性心动过速， 亦可见于部分心脏结构正常\n的病人。\n【临床表现】 常表现为心悸、 头晕、 胸痛、 憋气和乏力等， 部分病人可能无任何症状。合并器质性\n心脏病的病人甚至可表现为晕厥、 心肌缺血或肺水肿等。症状发作可呈短暂、 间歇或持续发生。当房\n室传导比例发生变动时， 听诊心律不恒定， 第一心音强度发生变化。\n【心电图特征】 局灶性房速心电图特征包括： ①心房率通常为 150～200 次 / 分； ②P 波形态与窦\n性 P 波不同； ③当心房率加快时可出现二度Ⅰ型或Ⅱ型房室传导阻滞， 呈现 2∶1 房室传导亦属常见，\n但心动过速不受影响； ④P 波之间的等电线仍存在 （与心房扑动时等电线消失不同）； ⑤刺激迷走神经\n不能终止心动过速， 仅加重房室传导阻滞； ⑥发作开始时心率逐渐加速 （ 图 3-3-9）。\n图3 -3-9   局灶性房性心动过速\nⅡ\n导联心房率 187 次\n /\n 分，\n房室间呈 1∶1 传导； Ⅲ导联心房率 167 次\n /\n 分，\n房室间呈 2∶1 传导。\n图3 -3-10   多源性房性心动过速\nⅡ\n、 aVF、 V1 导联 P 波呈多种形态， 部分房室间呈 2∶1～1∶1 传导。\n多源性房速心电图特征包括： ①通常有 3 种或以上形态各异的 P 波， PR 间期各不相同； ②心房率\n100～130 次\n /\n 分；\n③大多数 P 波能下传心室， 但部分 P 波因过早发生而受阻， 心室率不规则 （ 图 3-3-1 0）。\n【治疗】 房速的处理主要取决于心室率的快慢及病人的血流动力学情况。如心室率不太快且无\n严重的血流动力学障碍， 可选择口服β受体拮抗剂， 不伴器质性心脏病， 可选择非二氢吡啶类钙通道\n阻滞剂和Ⅰc 类 （ 普罗帕酮） 抗心律失常药。如心室率达 140 次 / 分以上， 由洋地黄中毒所致或临床上\n有严重充血性心力衰竭或休克征象， 应进行紧急治疗。其处理方法如下： ①病因与诱因治疗： 主要是\n针对基础疾病治疗。肺部疾病病人应纠正低氧血症、 控制感染； 如洋地黄中毒引起者， 需立即停用并\n纠正可能伴随的电解质紊乱， 特别要警惕低钾血症。②控制心室率： 急性期血流动力学稳定且无失代\n偿性心力衰竭可静脉使用β受体拮抗剂或非二氢吡啶类钙通道阻滞剂， 当药物治疗不能控制心室率\n时， 可考虑同步直流电复律。对于药物治疗无效反复发作的多源性房性心动过速伴左心室功能不全\n病人， 可考虑房室结消融联合永久起搏器治疗。③转复窦性心律： 优先使用腺苷转复治疗， 若无效， 可\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0012\u001a\u001a\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0012\u001a\u001a \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0011\u001a\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0011\u001a\n200\n第三篇  循环系统疾病\n选择Ⅰc （ 普罗帕酮） 或Ⅲ类 （ 胺碘酮、 伊布利特等） 抗心律失常药。血流动力学不稳定者立即行同步直\n流电复律。对于反复发作或引起心动过速性心肌病的局灶性房性心动过速， 首选导管消融治疗。\n三、  心房扑动\n心房扑动 （atrial flutter） 简称房扑， 是介于房速和房颤之间的快速型心律失常。健康者很少见， 病\n人多伴有器质性心脏病。\n【病因】 \n多见于冠心病、 瓣膜病、 高血压心脏病和心肌病等器质性心脏病。此外， 肺栓塞、 甲状腺功能亢\n进、 酒精中毒和心包炎等， 亦可出现房扑。部分病人也可无明显病因。\n【临床表现】 病人的症状主要与房扑的心室率相关， 心室率不快时， 病人可无症状； 房扑伴有极\n快的心室率时， 可诱发心绞痛与心力衰竭。房扑往往有不稳定的倾向， 可恢复窦性心律或进展为心房","资料来源":"人卫《内科学》第10版 · 循环.txt · 本节“房性心律失常”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2866,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b958632c07e17799745fdac0dac6020ca0ee1de1b421a3bf1ab44f72146badb1","pinyin":"fangxingxinlvshichang","initials":"fxxlsc","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-5c679a9c58aac5066eb1","key":"v1-c9ccc21dfe2a3058|templates-5c679a9c58aac5066eb1","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"抗利尿不适当综合征","category":"内科","raw":{"name":"抗利尿不适当综合征","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者初步诊断抗利尿不适当综合征，诊断须先排除其他原因所致低钠血症，入院即刻完善血电解质检查明确低钠程度，同步查血浆渗透压及尿渗透压、尿钠定量检查了解尿液浓缩程度及钠排泄情况，符合尿渗透压>100 mOsm/kg、尿钠>30 mmol/L 方能支持诊断；为鉴别有效循环血容量不足所致低钠，完善血常规、肝肾功能、白蛋白及血尿酸检查了解容量状态，查甲状腺功能排除甲状腺功能减退所致低钠血症，完善血皮质醇及促肾上腺皮质激素检查排除肾上腺皮质功能减退；胸部 CT 检查为病因筛查所必需，明确有无肺部肿瘤、肺结核及肺部感染（尤其小细胞肺癌异位分泌抗利尿激素），完善头颅 MRI 检查排除脑部肿瘤、脑出血、脑梗死及中枢神经系统感染所致抗利尿激素分泌异常；查心电图了解有无低钠所致心律失常，必要时完善血、尿渗透压动态监测及限水试验评估病情变化，指导补钠与限水治疗。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 抗利尿不适当综合征","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"抗 利 尿 不 适 当 综 合 征 （syndrome of  inappropriate  antidiuresis， SIAD） 是 指 抗 利 尿 激 素 （ADH， 即\n精氨酸加压素） 分泌异常增多或其效应增强， 导致水潴留、 低钠血症、 低血浆渗透压等临床表现的一\n组综合征。其中， 由抗利尿激素分泌异常增多引起， 称为抗利尿激素分泌失调综合征 （ syndrome o\nf \ninappropriate\n secretion\n of\n antidiu\nretic\n hormone，\nSIADH）， 较常见， 是低钠血症的最常见原因； ADH 效应增\n\u0018௉\u000fJOEE\u0001\u0001\u0001\u0017\u0019\u0013\u0018௉\u000fJOEE\u0001\u0001\u0001\u0017\u0019\u0013 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u0019\u001b\u0016\u0011\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u0019\u001b\u0016\u0011\n第四章   垂体后叶疾病\n683\n强 者，为肾性抗利尿不适当综合征 （nephrogenic  syndrome  of inappropriate  antidiuresis， NSIAD）， 罕见。\n本节着重介绍 SIADH。\n【病因和病理生理】  SIADH 常见病因为恶性肿瘤、 呼吸系统及神经系统疾病等。部分病因不明\n者称为特发性 SIADH， 多见于老年患者。\n（ 一）  异源性 AVP 分泌\n1.  恶性肿瘤  小细胞肺癌、 胰腺癌、 淋巴肉瘤、 十二指肠癌、 霍奇金淋巴瘤等可合成及释放 AVP\n引起 SIADH。其中以小细胞肺癌最多见。\n2.  肺部感染性疾病   肺炎、 肺结核、 肺脓肿、 肺曲霉病等可引起 SIADH， 可能是由病变的肺组织\n合成与释放 AVP 所致。\n（ 二）  中枢神经系统疾病  脑外伤、 脑脓肿、 脑肿瘤、 蛛网膜下腔出血、 脑血栓形成、 脑部急性感\n染、 结核性或其他脑膜炎、 卟啉病等都可影响下丘脑 \n- 神经垂体功能，\n使 AVP 分泌过多。\n（三）   药 物  某些药物如抗抑郁药 （ 如选择性 5- 羟色胺再摄取抑制剂）、 全身麻醉药、 巴比妥类、 卡\n马西平、 氯磺丙脲等可使 AVP 分泌过多， 引起 SIADH。\n由于 AVP 释放过多， 且不受正常调节机制所控制， 肾远曲小管与集合管对水的重吸收增加， 尿液\n不能稀释， 游离水不能排出体外， 细胞外液容量扩张， 血液稀释， 血清钠浓度与渗透压下降。同时， 细\n胞内液也处于低渗状态， 细胞肿胀， 当影响脑细胞功能时， 可出现神经系统症状。本综合征血容量正\n常， 一般不出现水肿， 因为当细胞外液容量扩张到一定程度， 可抑制近曲小管对钠的重吸收， 使尿钠排\n出增加， 水分不致在体内潴留过多。加之容量扩张导致心房钠尿肽释放增加， 使尿钠排出进一步增\n加， 因此， 钠代谢处于负平衡状态， 加重低钠血症与低血浆渗透压。此外， 醛固酮分泌受到抑制， 也增\n加尿钠的排出。\n【临床表现和实验室检查】  主要临床特征是水潴留 （ 稀释性低血钠）、 低血浆渗透压， 机体血容量\n正常， 一般无水肿。临床症状的轻重与 AVP 分泌量有关， 同时取决于水负荷的程度。多数患者在限\n制水分时， 可不表现典型症状。但若水摄入过多， 则可出现水潴留及低钠血症表现。患者血清钠一般\n低于 130mmol/L， 但尿钠排出相对较多 （ 一般超过 20mmol/L）。当血清钠浓度低于 120mmol/L 时， 可出\n现食欲减退、 恶心、 呕吐、 肢体软弱无力、 嗜睡， 甚至精神错乱； 当血清钠低于 110mmol/L 时， 出现肌力\n减退， 腱反射减弱或消失、 惊厥、 昏迷， 如不及时处理， 可导致死亡。本病血浆渗透压常低于 275mOsm/\n（ k g·H2O）， 而尿渗透压可高于血浆渗透压。由于血容量充分， 肾小球滤过率增加， 血尿素氮、 肌酐、 尿\n酸等浓度常降低。血浆 AVP 相对于血浆渗透压呈不适当的高水平。\n【诊断与鉴别诊断】\n（ 一）  诊断依据  主要诊断依据： ①血钠降低 （ 常低于 130mmol/L）； ②尿钠增高 （ 常超过 20mmol/L \n或尿钠排泄率每日 ＞25mmol）； ③ 血 浆 渗 透 压 降 低 ［常 低 于 275mOsm/ （kg · H2O） ］； ④尿渗透压＞\n100mOsm/ （kg · H2O）； ⑤血尿素氮、 肌酐、 尿酸常下降； ⑥除外肾上腺皮质功能减低、 甲状腺功能减退、\n利尿药使用等原因。\n（ 二）  病因诊断  恶性肿瘤是常见原因， 特别是小细胞肺癌。有时可先出现 SIADH， 以后再出现\n肺癌的影像学改变。其次应除外中枢神经系统疾病、 肺部感染、 药物等因素。\n（ 三）  鉴别诊断\n1.  肾性抗利尿不适当综合征 （NSIAD）   肾小管 AVP 受体 （V2R） 基因突变 （ 如 R137C、 R137L），\n激活受体 G 蛋白的α亚单位， 致抗利尿效应增强， 是 X 连锁隐性遗传性疾病， 其血 AVP 降低。若儿\n童或多个家庭成员发生低钠血症， 或托伐普坦疗效不佳者， 应警惕 NSIAD， 必要时行血 AVP和 V2R\n基因检测。此外， 环磷酰胺、 舍曲林等药物也可激活肾小管 AVP 受体导致低钠血症， 必要时停药后\n观察。\n2.  其他正常血容量性低钠血症   肾上腺皮质功能减退症、 恶心呕吐、 甲状腺功能减退等也是导\n致低钠血症的常见原因， 应仔细询问病史及完善相关检查进行鉴别。\n\u0018௉\u000fJOEE\u0001\u0001\u0001\u0017\u0019\u0014\u0018௉\u000fJOEE\u0001\u0001\u0001\u0017\u0019\u0014 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u0019\u001b\u0016\u0011\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u0019\u001b\u0016\u0011\n684\n第七篇   内分泌和代谢性疾病\n3.  低血容量性低钠血症   胃肠消化液丧失 （ 如腹泻）， 胃肠、 胆道、 胰腺造瘘或胃肠减压等， 体内\n钠丢失超过水丢失， 致低钠血症， 有相关疾病史及失水表现。血尿素氮、 肌酐、 尿酸常增高。脑盐耗综\n合征 （cerebral\n salt\n wasting\n syndrome，\nCSWS） 是在颅内疾病的过程中肾不能保存钠而导致进行性钠自\n尿中大量流失， 并带走水分， 从而导致低钠血症和细胞外液容量下降。CSWS 的主要临床表现为低钠\n血症、 尿钠增高和低血容量； 而 SIADH","资料来源":"人卫《内科学》第10版 · 内分泌.txt · 本节“抗利尿不适当综合征”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2867,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"22e50a949dbb54027b8181c2959fa2b52a6648c15b24b8f2fbaeea16f2989f13","pinyin":"kangliniaobushidangzonghezheng","initials":"klnbsdzhz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-e5daee7e4ec2ed68b62d","key":"v1-c9ccc21dfe2a3058|templates-e5daee7e4ec2ed68b62d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"无症状性血尿和/或蛋白尿","category":"内科","raw":{"name":"无症状性血尿和/或蛋白尿","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者初步诊断无症状性血尿和/或蛋白尿，首要任务是明确出血与蛋白来源、区分肾小球性与非肾小球性，入院后完善尿常规+尿沉渣镜检检查了解红细胞计数及管型，完善尿红细胞形态及棘形红细胞检查鉴别肾小球性血尿，查尿蛋白定量及尿蛋白电泳了解蛋白尿程度及有无选择性；查肾功能、胱抑素 C 及肾小球滤过率检查评估肾功能受损程度，查泌尿系统彩超检查了解双肾大小、形态、有无结石、囊肿及占位；为排除继发性肾小球疾病，完善免疫球蛋白、补体 C3/C4、抗核抗体、抗中性粒细胞胞浆抗体及乙肝、丙肝病毒标志物检查排除狼疮性肾炎、紫癜性肾炎及病毒相关性肾炎，查血糖、糖化血红蛋白检查排除糖尿病肾病；中老年患者需完善尿脱落细胞学检查及泌尿系 CT 或膀胱镜检查排除泌尿系肿瘤；为评估血压与肾脏关系，完善动态血压监测；经上述检查仍不能明确病因者，必要时完善肾穿刺活检检查明确病理诊断，指导治疗方案。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 无症状性血尿和/或蛋白尿","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"无症状性血尿和 / 或蛋 白尿 （asymptomatic hematuria and/or proteinuria） 指仅表现为肾小球源性血\n尿和 / 或轻至\n中度蛋白尿， 不伴水肿、 高血压及肾功能损害的一组肾小球疾病， 通常通过实验室检查发\n现。在没有肾穿刺活检获取病理时， 用本病来描述这组疾病。\n【病理】 本组疾病可由多种病理类型的原发性肾小球疾病所致， 但病理改变多较轻， 如轻微病变\n性肾小球肾炎 （ 肾小球中仅有节段性系膜细胞及基质增生）、 轻度系膜增生性肾小球肾炎及局灶节段\n性肾小球肾炎 （ 局灶性肾小球病， 病变肾小球内节段性内皮及系膜细胞增生） 等。\n【临床表现】 多无症状， 常因体检提示镜下血尿或蛋白尿而发现， 无水肿、 高血压和肾功能损害；\n部分病人高热或剧烈运动后出现一过性血尿， 短期内消失。反复发作的单纯性血尿， 尤其是和上呼吸\n道感染密切相关者应注意 IgA 肾病的可能。有家族史的持续单纯性血尿者需注意薄基底膜肾病。\n【实验室检查】 尿液分析可有镜下血尿和 / 或蛋白尿 （ 尿蛋白＞0.5g/24h， 但通常＜2.0g/24h， 以白\n蛋白为主）； 相差显微镜尿红细胞形态检查和 / 或尿红细胞容积分布曲线测定可判定血尿性质为肾小\n球源性血尿。免疫学检查抗核抗体、 抗双链 DNA 抗体、 免疫球蛋白、 补体等均正常。部分 IgA 肾病病\n人可有血 IgA 水平的升高； 肾功能及影像学检查如 B 超、 静脉肾盂造影、 CT 或 MRI 等常无异常发现。\n对于单纯血尿者不一定行肾活检， 因为这类病例预后通常良好， 且有 5%～15% 的病人肾活检后\n仍不能确诊。血尿伴蛋白尿病人的病情及预后一般较单纯性血尿病人稍重。在临床上无法鉴别为\nIgA 肾病或其他肾病， 建议行肾穿刺活检评估病情和协助治疗。如病人随访中出现血尿、 蛋白尿加重和\n /\n 或肾功能恶化，\n应尽快做肾活检明确诊断。\n【诊断与鉴别诊断】 无症状血尿和 / 或蛋白尿临床上无特殊症状， 易被忽略， 故应加强临床随访。\n此外， 尚需排除其他原因所致的可能。\n相差显微镜检查尿红细胞位相和 / 或尿红细胞容积分布曲线测定有助于鉴别血尿来源\n。肾小球\n5-6篇.indd 4865-6篇.indd 486 2024/7/28 10:27:562024/7/28 10:27:56\n第二章  原发性肾小球疾病\n487\n来源的红细胞以畸形为主， 典型者呈 “芽孢样”。非肾小球源性血尿者需注意胡桃夹综合征 （ 左肾静\n脉压迫综合征）和外科性血尿的可能， 如尿路结石、 肿瘤或炎症。泌尿系统超声或 CT 可协助鉴别。\n如确定为肾小球源性血尿， 又无水肿、 高血压及肾功能减退时， 即应考虑诊断此病。需注意的是， 诊断\n本病前必须小心除外其他肾小球疾病的可能， 如全身性疾病 （ANCA 相关性血管炎、 狼疮性肾炎、 过敏\n性紫癜肾炎等）、 Alport 综合征、 薄基底膜肾病及非典型的急性肾炎恢复期等。依据临床表现、 家族史和实验室检查予以鉴别， 必要时需依赖肾活检方能确诊。\n对无症状单纯蛋白尿者， 需做尿蛋白定量和尿蛋白成分分析、 尿蛋白电泳以区分蛋白尿性质， 必\n要时应做尿本周蛋白检查及血清蛋白免疫电泳。尤其是病人尿常规中蛋白定性试验时提示蛋白量不\n多， 但 24 小时尿蛋白定量出现大量蛋白尿时， 需高度注意单克隆免疫球蛋白增多症的可能。在作出\n诊断前还必须排除假性蛋白尿 （ 如肿瘤引起大量血尿时）、 溢出性蛋白尿、 功能性蛋白尿 （ 仅发生于剧\n烈运动、 发热或寒冷时）、 体位性蛋白尿 （ 见于青少年， 直立时脊柱前凸所致， 卧床后蛋白尿消失） 等性\n质蛋白尿， 需注意排除左肾静脉压迫综合征， 以及其他继发性肾小球疾病 （ 如糖尿病肾脏病、 肾淀粉样\n变、 多发性骨髓瘤等）。必要时行肾活检确诊。\n相较于单纯性的无症状血尿或蛋白尿， 血尿合并蛋白尿 （≥0.5g/d） 者为慢性肾小球肾炎的可能\n性显著增大。这类肾小球疾病进展的风险高， 是肾穿刺活检确认病理类型的指征。\n如进行了肾穿刺活检， 获得病理学结果后， 以病理诊断替代本病。\n【治疗】 尿蛋白定量 ＜1.0g/d， 以白蛋白为主， 而无血尿者， 称为单纯性蛋白尿， 一般预后良好， 很\n少发生肾功能损害。但近年的研究显示， 有小部分尿蛋白在 0.5～1.0g/d 的病人， 肾活检病理改变并\n不轻， 应引起重视。\n发现进展趋势和避免肾毒性因素暴露是本病的管理重点。诊疗原则包括： ①定期检查和追踪 （ 每\n3～6 个月 1 次）， 监测尿常规、 肾功能和血压的变化。女性病人在妊娠前及怀孕期间更需加强监测。\n②保护肾功能、 避免肾损伤的因素 （ 参见本章","资料来源":"人卫《内科学》第10版 · 泌尿.txt · 本节“无症状性血尿和/或蛋白尿”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2868,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cafa61b0e1d7964152807d22f3e18fad709f22fa47949f2e1cdb821bb95b9cb6","pinyin":"wuzhengzhuangxingxueniaohe/huodanbainiao","initials":"wzzxxnh/hdbn","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-09ed29981dc1f564824b","key":"v1-c9ccc21dfe2a3058|templates-09ed29981dc1f564824b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"有机溶剂中毒","category":"内科","raw":{"name":"有机溶剂中毒","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者初步诊断有机溶剂中毒，有机溶剂多经呼吸道及皮肤吸收并损害肝脏、肾脏、造血及中枢神经系统，入院即刻完善血常规检查了解有无白细胞减少、血小板下降等骨髓抑制表现，完善肝肾功能、电解质及血糖检查排除肝肾功能不全及电解质紊乱、低血糖；查血气分析检查了解有无代谢性酸中毒及缺氧，必要时完善血渗透压及阴离子间隙计算鉴别甲醇、乙二醇中毒；查心电图检查了解有无中毒性心肌损害及心律失常，完善肌钙蛋白、心肌酶检查排除急性心肌损伤，查胸部 X 线或胸部 CT 检查了解有无化学性肺炎及肺水肿；为评估中枢神经系统受累，完善头颅 CT 或头颅 MRI 检查明确有无脑水肿、白质脱髓鞘及基底节损害（一氧化碳、甲苯中毒常见），必要时查脑电图了解脑功能状态；对苯及苯系物接触者，必要时完善骨髓穿刺涂片检查明确有无骨髓增生异常或白血病；必要时完善血、尿中毒物浓度测定明确毒物种类及中毒程度，指导解毒剂应用与血液净化时机。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 有机溶剂中毒","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"有机溶剂常用作工业原料、 实验的反应介质、 稀释剂、 清洗剂、 去脂剂、 黏胶溶剂、 萃取剂、 防腐剂、\n内燃机燃料等， 品种繁多， 达 500 种以上。有机溶剂通常具有以下共同特征： ①常温下为液体， 挥发\n性强； ②大多易燃、 易爆； ③脂溶性强， 不溶于水或微溶于水； ④毒性方面， 一般都有刺激和麻醉作用；\n⑤某些有机溶剂具有特殊毒性， 如神经毒、 肝肾毒及骨髓抑制作用等。\n按化学组成， 有机溶剂可分九类。\n1.\n  脂肪开链烃类\n 正乙烷、\n汽油、 煤油。\n2.\n  脂肪族环烃类\n 环乙烷、\n环乙烯、 萘烷。\n3.\n  芳香烃类\n 苯、\n甲苯、 二甲苯、 乙苯。\n4.\n  卤代烃类\n 氯甲烷、\n溴甲烷、 三氯甲烷、 四氯化碳、 二氯乙烷、 三氯乙烯。\n5.\n  醇类\n 甲醇、\n乙醇、 氯乙醇、 三氯丙醇。\n6.\n  醚类\n 乙醚、\n异丙醚、 二氯乙醚。\n7.\n  酯类\n 甲酸甲酯、\n乙酸甲苯酯。\n8.\n  酮类\n 丙酮、\n丁酮、 庚酮、 环己酮、 甲基正丁基酮。\n9.\n  其他\n 二硫化碳、\n二甲基甲酰胺、 二甲基乙酰胺。\n【中毒机制】 不同有机溶剂中毒机制有所差异， 本节仅简述最常见的苯与苯胺中毒机制。\n1.  苯中毒机制 苯的亲脂性很强\n， 且多聚集于细胞膜内， 使细胞膜的脂质双层结构肿胀， 影\n响细胞膜蛋白功能， 干扰细胞膜的脂质和磷脂代谢， 抑制细胞膜的氧化还原功能， 导致中枢神经 \n麻醉。\n苯代谢产物 （ 邻苯二酚、 氢醌和苯醌） 通过抑制骨髓基质生成造血干细胞， 干扰细胞增殖和分化的\n调节因子， 阻断造血干细胞分化过程而诱发白血病。同时苯的酚类代谢产物， 可直接毒害造血细胞，\n并通过巯基作用导致维生素 C和谷胱甘肽代谢障碍。\n2.  苯胺中毒机制 苯胺被吸收后\n， 产生大量的高铁血红蛋白， 其本身不仅不能携氧， 还会阻碍血\n红蛋白释放氧， 血红蛋白分子含有 4 个二价铁离子， 如果有一个被氧化为三价铁离子， 就会影响其他\n二价铁离子对氧的释放， 导致组织缺氧， 出现高铁血红蛋白血症。同时还原型谷胱甘肽减少， 导致红\n细胞破裂， 产生溶血性贫血。另外， 苯胺中毒的代谢产物直接毒害珠蛋白分子中的巯基， 使珠蛋白转\n8-9篇.indd 9158-9篇.indd 915 2024/7/28 11:14:512024/7/28 11:14:51\n916\n第九篇  理化因素所致疾病\n变为不可逆性的变性沉淀物， 形成红细胞内海因茨小体， 导致红细胞的结构与功能出现缺陷， 易遭受\n单核巨噬细胞破坏， 而加重溶血性贫血。\n苯胺中毒后， 对肝、 肾和皮肤均有严重损害， 导致肝硬化和肾衰竭， 还可导致化学性膀胱炎， 出现\n一过性肉眼血尿。\n【中毒表现】 常温、 常压下的有机溶剂呈液体状态， 易挥发。中毒途径以呼吸道吸入为主， 亦可\n经皮肤接触或消化道吸收中毒， 不同有机溶剂有其不同的中毒表现， 按各系统的主要症状分类如下。\n（ 一）  神经精神损害  包括苯及苯胺在内的大多数有机溶剂中毒， 均可出现不同程度的神经精神\n损害。\n1.  急性中毒 轻者头痛\n、 头昏、 眩晕。重者恶心、 呕吐、 心率慢、 血压增高、 躁动、 谵妄、 幻觉、 妄\n想、 精神异常、 抽搐、 昏迷甚至死亡。\n2.\n  慢性中毒\n（\n1） 神经衰弱综合征：\n头痛、 头晕、 失眠、 多梦、 厌食、 倦怠和乏力等。\n（2） 中毒性脑病：\n反应迟钝、 意识障碍、 震颤、 活动困难、 生活不能自理和中毒性精神病表现。\n（3） 脑神经损害\n： ①甲醇毒害视神经可导致双目失明； ②三氯乙烯可毒害三叉神经， 也可导致前\n庭神经麻痹和听力障碍。\n（4） 小脑功能障碍综合征：\n酒精中毒损害小脑功能， 导致步态不稳， 意向性震颤。\n（5） 周围神经病\n： ①二硫化碳、 正乙烷及甲基正丁基酮中毒损伤周围神经系统导致手足麻木、 感\n觉过敏， 手不能持物， 肌肉无力， 肌肉萎缩以至运动神经传导速度减慢； ②三氯乙烯中毒出现周围神经\n病时伴有毛发粗硬和水肿。\n（ 二）  呼吸道损害  吸入有机溶剂蒸气中毒的患者均有呼吸道损害， 有害气体刺激呼吸道黏膜，\n导致呛咳。\n1.\n 吸入酮类或卤代烷类及酯类蒸气后，\n导致化学性肺炎、 肺水肿。\n2.\n 误吸入汽油及煤油后可致化学性肺炎，\n甚至肺水肿及渗出性胸膜炎。\n（ 三）  消化道损害  经口服有机溶剂中毒者均有明显的恶心、 呕吐等胃肠症状。\n乙醇、 卤代烃类及二甲基甲酰胺中毒主要影响肝， 导致肝细胞变性、 坏死， 中毒性肝炎、 脂肪肝及\n肝硬化。\n（ 四）  肾脏损害\n1. 酚、 醇、 卤代烃类中毒后皆可导致急性肾小管坏死、 肾小球损害， 发生急性肾衰竭， 以非少尿型\n肾衰竭多见。\n2.\n 四氯化碳、\n二硫化碳及甲苯中毒后可致慢性中毒性肾病。\n3.\n 烃类化合物\n（ 汽油） 吸入中毒后可导致肺出血肾炎综合征 （Goodpasture 综合征）。\n（ 五）  造血功能损害\n1. 亚急性或慢性苯中毒致白细胞减少、 再生障碍性贫血， 慢性苯中毒可致白血病。\n2.\n 三硝基甲苯可引起高铁血红蛋白血症、\n溶血和再生障碍性贫血。\n（ 六）  皮肤损害\n1. 有机溶剂急性皮肤损害， 如皮肤丘疹、 红斑、 水肿、 水疱、 糜烂及溃疡。\n2.\n 有机溶剂慢性皮肤损害，\n如皮肤角化、 脱屑及皲裂。\n3.\n 长期接触石油易导致皮肤色素沉着。\n（ 七）  生殖功能损害  苯、 二硫化碳和汽油中毒对女性的损害表现为月经紊乱、 性欲减退， 受孕率\n降低， 甚至会导致胎儿畸形。对男性损害表现为性欲降低、 阳痿和精子异常。\n（ 八）  心血管损害\n1. 苯、 汽油、 酒精、 三氯乙烯、 二氯乙烷、 四氯化碳和二硫化碳中毒后不仅引起急性或慢性心肌损\n害， 出现各种类型心律失常， 还会使心脏对肾上腺素敏感性增强， 易致恶性心律失常。\n2.\n 长期接触二硫化碳及慢性乙醇中毒可致动脉粥样硬化。\n8-9篇.indd 9168-9篇.indd 916 2024/7/28 11:14:512024/7/28 11:14:51\n第二章  中毒\n917\n（ 九）  有机溶剂复合损害  当机体受到两种以上","资料来源":"人卫《内科学》第10版 · 理化.txt · 本节“有机溶剂中毒”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2869,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f4f18bd237f0b97561a52ad4393cfdf6d6ff802fc2304cf022fc9056c40589c8","pinyin":"youjirongjizhongdu","initials":"yjrjzd","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-1fb92ed38d68cea71b68","key":"v1-c9ccc21dfe2a3058|templates-1fb92ed38d68cea71b68","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"毒蛇咬伤中毒","category":"内科","raw":{"name":"毒蛇咬伤中毒","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者初步诊断毒蛇咬伤中毒，蛇毒可致凝血功能障碍、溶血、急性肾损伤及神经肌肉麻痹，入院即刻完善血常规检查了解有无贫血、血小板减少及感染征象，完善凝血功能（凝血酶原时间、活化部分凝血活酶时间、纤维蛋白原、D-二聚体）检查明确有无凝血障碍，急诊完成 20 分钟全血凝固试验检查鉴别血循毒类蛇咬伤；完善肝肾功能、电解质及心肌酶检查了解有无急性肝损伤、急性肾损伤、电解质紊乱及心肌损害，查肌酸激酶了解有无横纹肌溶解及局部肌肉坏死；查尿常规检查了解有无血尿、血红蛋白尿及肌红蛋白尿，指导碱化尿液与补液；为评估神经毒类蛇伤所致呼吸肌麻痹，监测血氧饱和度并完善动脉血气分析检查了解有无呼吸衰竭，必要时行动脉血氧监测；查心电图检查了解有无中毒性心律失常及高钾血症所致心电图改变；咬伤部位必要时行 X 线检查排除异物残留，疑骨筋膜室综合征者监测患肢周径及筋膜室压力，必要时完善破伤风抗毒素皮试及预防接种评估，动态复查凝血功能与肾功能观察病情演变。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 毒蛇咬伤中毒","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"世界上有 3 0 00 多种蛇， 其中约 15% 被认为会对人类构成危险， 3 0 00 多种蛇中， 毒蛇有 650 种，\n我国已知的毒蛇约 50 种， 其中剧毒蛇 10 余种， 主要有： ①眼镜蛇科 （ 眼镜蛇、 眼镜王蛇、 金环蛇、 银\n环蛇）； ②蝰蛇科， 分为蝰亚科 （ 蝰蛇）、 蝮亚科 （ 尖吻蝮、 竹叶青、 蝮蛇、 烙铁头）； ③海蛇科 （ 海蛇）。常\n见且危害较大的毒蛇主要有金环蛇、 银环蛇、 眼镜蛇和眼镜王蛇， 主要分布在长江以南； 青环海蛇和\n长吻海蛇分布在我国东南沿海； 蝰蛇、 五步蛇、 烙铁头、 竹叶青和蝮蛇 （ 其中各类蝮蛇数量多且分布\n范围广泛）， 主要分布在长江流域和东南、 西南各省。全世界每年被毒蛇咬伤 （venomous snake bite）\n者达 42 万以上， 致死者约有 20 0\n00～25 0\n00 人， 其中多数发生在南亚、 东南亚和撒哈拉沙漠以南非\n洲。国内报道每年毒蛇咬伤者达 10 万余人次， 被毒蛇咬伤机会较多的人群为农民、 渔民、 野外工作\n者、 从事毒蛇研究和蛇产业的人员。咬伤部位以手、 臂、 足和下肢为常见。毒蛇咬伤以夏、 秋两季为 \n多见。\n【发病机制】\n（ 一）  毒液释放机制  毒蛇口内有毒腺， 经排毒导\n管与毒牙相连 （ 图 9-2-4）。当毒蛇咬人时， 毒腺收缩，\n蛇毒通过排毒导管， 经有管道或沟的毒牙， 注入人体组\n织。眼镜蛇科的一些蛇种甚至可以向短距离目标喷射\n毒液， 目标通过黏膜吸收毒液， 导致中毒。毒腺内贮有\n蛇毒液约 0.1～0.5ml，与蛇种、 蛇体大小、 近期捕食情\n况等有关， 大的蛇可有 5ml， 咬时约射出毒腺内贮量的\n一半。毒蛇液呈淡黄色、 琥珀色或无色。蛇毒成分复\n杂， 干蛇毒约 90% 为蛋白质， 主要为酶或非酶多肽毒\n素以及非毒蛋白质。\n（ 二）  毒液对伤口局部作用  蛇毒中的神经毒可麻痹感觉神经末梢， 引起肢体麻木； 阻断运动神\n经与横纹肌之间的神经冲动， 引起瘫痪。所含磷脂酶 A2 可促使组胺、 5- 羟色胺和缓动素释放， 引起伤\n口局部组织水肿、 炎症反应和疼痛； 透明质酸酶使局部炎症进一步扩展。蛋白质溶解酶破坏血管壁，\n引起出血、 损伤组织或局部坏死。\n（ 三）  毒液全身作用机制  蛇毒成分比较复杂， 一般分神经毒、 血循毒和肌肉毒等。金环蛇、\n银环蛇、 海蛇毒液以神经毒为主； 蝰蛇、 五步蛇、 竹叶青、 烙铁头等毒蛇毒液以血循毒为主； 眼镜\n蛇、 眼镜王蛇及蝮蛇毒液兼有神经毒和血循毒 （ 混合毒）。此外， 海蛇和眼镜蛇还有非常强烈的肌 \n肉毒。\n1.\n  神\n经毒\n 具有阻断神经肌肉接头传导的作用\n， 引起横纹肌弛缓性瘫痪， 可导致呼吸肌麻痹、\n严重呼吸衰竭， 为临床上主要致死原因。根据作用部位不同， 神经毒包括突触前神经毒和突触后神\n经 毒。β- 银环蛇毒或蝮蛇毒是突触前神经毒\n， 能抑制运动神经末梢释放神经递质乙酰胆碱； α- \n银\n环蛇毒、 眼镜蛇毒、 眼镜王蛇毒、 海蛇毒为突触后神经毒， 可与运动终板乙酰胆碱受体结合， 使乙酰\n胆碱失去作用， 骨骼肌不能兴奋收缩。银环蛇毒含有两种神经毒， 对神经肌肉接头的传导有双重阻\n图9 -2-4  毒蛇的毒腺、 排毒导管和毒牙模式图\n8-9篇.indd 9178-9篇.indd 917 2024/7/28 11:14:512024/7/28 11:14:51\n918\n第九篇  理化因素所致疾病\n断作用， 可迅速引起呼吸肌麻痹。此外， 神经毒可作用于自主神经系统， 抑制颈动脉体化学感受器，\n加重呼吸衰竭； 兴奋肾上腺髓质中的神经受体， 释放肾上腺素， 使血压升高； 胃肠道平滑肌兴奋性先\n增高， 后抑制， 出现肠麻痹； 毒素还可影响延髓血管运动中枢和呼吸中枢， 导致休克和中枢性呼吸 \n衰竭。\n2.\n  血循毒\n（\n1） 凝血毒和抗凝血毒：\n蝰蛇和澳大利亚眼镜蛇蛇毒可激活Ⅹ因子， 在Ⅴ因子、 磷脂、 Ca\n2+\n参与下，\n使凝血酶原变成凝血酶。响尾蛇蛇毒可直接作用于纤维蛋白原， 引起凝血。蝰蛇科大部分毒蛇的蛇\n毒中含有凝血酶样物质， 使纤维蛋白原直接转变为纤维蛋白， 有研究认为其在体外水解纤维蛋白原为\n纤维蛋白单体， 后者凝聚为纤维蛋白， 从而促进血液凝固， 而在体内则由于水解纤维蛋白原， 导致血纤\n维蛋白原水平下降， 但不形成血凝块， 表现为双重作用； 另外， 还可抑制血小板的黏附、 聚集， 表现为抗\n凝作用。还有些蛇毒可溶解纤维蛋白原或抑制纤维蛋白活性； 促使纤溶酶原转化成纤溶酶； 阻抑Ⅴ因\n子， 阻抑凝血酶形成， 最终导致出血。\n（2） 出血毒和溶血毒： 蛇毒中的蛋白水解酶能溶解组织蛋白， 破坏肌肉组织， 损伤血管壁， 引起出\n血和组织坏死。蛇毒中的磷脂酶 A2 可使毛细血管内皮细胞肿胀、 溶解， 基底膜中糖蛋白、 纤维连接蛋\n白、 Ⅳ型和Ⅴ型胶原及其他基质成分分解， 导致毛细血管壁的通透性改变， 组织水肿、 出血和坏死； 蛇\n毒还可使红细胞膜上卵磷脂变成溶血卵磷脂， 从而溶解红细胞膜， 引起溶血。有些毒蛇的毒液还含有\n直接溶血因子， 可溶解红细胞膜， 如蝰蛇、 五步蛇毒液。\n（3） 心脏血管毒\n： 蛇毒中的蛋白水解酶能释放组胺和血管活性物质； 磷脂酶 A2 也能促释放组胺、\n5- 羟色胺\n、 肾上腺素、 缓动素等， 使血管扩张、 血压下降， 甚至休克。蛇毒中的心脏毒能损害心肌细胞\n结构和功能， 使心肌变性、 坏死， 出现心律失常甚至心搏骤停。眼镜蛇、 蝰蛇等含有心脏毒。\n3.\n  肌\n肉毒\n 主要包括肌肉毒素\n（ 膜毒素）、 响尾蛇胺及其类似物、 蛋白水解酶和磷脂酶 A2。作用\n靶点一般为骨骼肌而非平滑肌， 通过使肌细胞溶解、 蛋白水解， 引起组织坏死。中华眼镜蛇的肌肉毒\n主要引起局部组织坏死； 海蛇的肌肉毒则能破坏全身骨骼肌细胞， 引起肌肉疼痛、 无力、 肌红蛋白尿、\n高钾血症和急性肾损伤。\n【临床表现】 眼镜蛇科和海蛇科的蛇毒分子小， 咬后迅速进入受害者血液循环， 因而发病很快；\n蝰蛇的蛇毒分子较大， 由淋巴系统缓慢吸收后才出现症状。眼镜蛇和烙铁头的蛇毒接触黏膜被吸收\n后可引起全身中毒。根","资料来源":"人卫《内科学》第10版 · 理化.txt · 本节“毒蛇咬伤中毒”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2870,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"83ca799f5e4eeb91f63e05a94bffe1826cc7a8a868d396d67ce32040fccb5824","pinyin":"dusheyaoshangzhongdu","initials":"dsyszd","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-dae3a1b829dcc502ba5c","key":"v1-c9ccc21dfe2a3058|templates-dae3a1b829dcc502ba5c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"水、钠代谢失常","category":"内科","raw":{"name":"水、钠代谢失常","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者因原始病史资料待补录，本次按初步诊断「水、钠代谢失常」制定检查方案，入院即刻完善血清电解质（钾、钠、氯、钙、镁）检查，明确低钠或高钠血症的程度与类型，为补钠或限钠速度提供依据；同步查血糖、血脂、尿素氮与血肌酐，排除高血糖、高脂血症所致假性低钠及肾功能不全引起的水钠潴留；查血浆渗透压与尿渗透压、尿钠浓度，鉴别抗利尿激素分泌不当综合征、脑性耗盐综合征与肾性失钠；完善肝功能、血清白蛋白检查，排除肝病与低蛋白血症导致的稀释性低钠；查甲状腺功能与晨起血浆皮质醇、促肾上腺皮质激素，排除甲状腺功能减退及肾上腺皮质功能减退所致电解质紊乱；查 NT-ProBNP 与心脏彩超＋左心功能测定，评估心功能状态，明确有无心力衰竭引起的水钠潴留；查血气分析了解酸碱平衡状态及有无合并低氯性碱中毒；记录 24 小时出入量并每日称体重、监测血压与心率。头颅 CT 或 MRI 在存在意识障碍、抽搐等神经系统症状时急诊完成，排除颅内病变所致中枢性低钠；胸部 CT 在怀疑肺部感染或肿瘤时安排，排除其引起的抗利尿激素异常分泌。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 水、钠代谢失常","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"水、 钠代谢失常相伴发生。临床上多分为失 水 （water loss）、 水 过 多 （water  excess）、低钠血症\n（hyponatremia）和高钠血症 （hypernatremia） 等， 单纯性水 （ 或钠） 增多或减少较少见。\n\u0018௉\u000fJOEE\u0001\u0001\u0001\u0018\u0017\u0019\u0018௉\u000fJOEE\u0001\u0001\u0001\u0018\u0017\u0019 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u001a\u001b\u0011\u0014\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u001a\u001b\u0011\u0014\n第十二章   水、电解质代谢和酸碱平衡失常\n769\n一、   失水\n失水是指体液丢失所造成的体液容量不足。根据水和电解质 （ 主要是 Na\n+\n） 丢失的比例和性质，\n临床上将失水分为高渗性失水、 等渗性失水和低渗性失水。\n【病因】\n（ 一）  高渗性失水\n1.  摄水不足   ①昏迷、 创伤、 拒食、 吞咽困难、 淡水供应断绝； ②脑外伤、 脑卒中等致渴感中枢迟\n钝或渗透压感受器不敏感。\n2.  失水过多\n（1）  经肾丢失\n： ①中枢性或肾性尿崩症； ②糖尿病酮症酸中毒、 高渗性昏迷、 高钙血症等； ③长期\n鼻饲高蛋白流质等所致的溶质性利尿 （ 鼻饲综合征）； ④使用高渗葡萄糖溶液、 甘露醇、 山梨醇、 尿素等\n脱水药物或非溶质性利尿药。\n（2）  肾外丢失\n： ①大量出汗； ②烧伤开放性治疗丢失大量低渗液； ③哮喘持续状态、 过度换气、 气\n管切开等使肺呼出的水分增多 2～3 倍。\n（3）  水向细胞内转移：\n剧烈运动或惊厥等使细胞内小分子物质增多， 渗透压增高， 水转入细胞内。\n（ 二）  等渗性失水\n1.  消化道丢失  呕吐、 腹泻、 胃肠引流或肠梗阻等致消化液丢失。\n2.  皮肤丢失  大面积烧伤、 剥脱性皮炎等渗出性皮肤病变。\n3.  组织间液贮积  胸、 腹腔炎性渗出液的引流， 反复大量放胸、 腹水等。\n（ 三）  低渗性失水\n1.  补充水分过多  高渗性或等渗性失水时补充水分过多。\n2.  肾丢失  ①过量使用噻嗪类、 呋塞米等排钠性利尿药； ②肾小管中存在大量不被吸收的溶质\n（ 如尿素）， 抑制钠和水的重吸收； ③失盐性肾炎、 急性肾衰竭多尿期、 肾小管性酸中毒、 糖尿病酮症酸\n中毒； ④肾上腺皮质功能减退症。\n【临床表现】\n（ 一）  高渗性失水\n1.  轻度失水  失水多于失钠， 细胞外液量减少， 渗透压升高。当失水量达体重的 2%～3% 时，渴\n感中枢兴奋， 刺激抗利尿激素释放， 水重吸收增加， 尿量减少， 尿比重增高。如伴有多饮， 一般不造成\n细胞外液容量不足和渗透压异常； 如伴渴感减退， 可发生高渗性失水。\n2.  中度失水  当失水量达体重的 4 %～6% 时， 醛固酮分泌增加和血浆渗透压升高， 此时口渴严\n重， 咽下困难， 声音嘶哑； 有效循环容量不足， 心率加快； 皮肤干燥、 弹性下降； 进而因细胞内失水出现\n乏力、 头晕、 烦躁。\n3.  重度失水  当失水量达 7 %～14% 时， 脑细胞失水严重， 出现神经系统症状如躁狂、 谵妄、 定向\n力失常、 幻觉、 晕厥和脱水热。当失水量超过 15% 时， 可出现高渗性昏迷、 低血容量性休克、 尿闭及急\n性肾衰竭， 死亡率高。\n（ 二）  等渗性失水及低渗性失水  等渗性失水时， 有效循环血容量和肾血流量减少， 出现少尿、\n口渴， 重者血压下降， 但渗透压基本正常。低渗性脱水早期即发生有效循环血容量不足和尿量减少，\n但无口渴； 重者导致细胞内低渗和细胞水肿。临床上， 依据缺钠的程度大致分轻、 中、 重三度。\n1.  轻度失水  当每千克体重缺钠 8.5mmol （ 血浆钠 130mmol/L 左右） 时， 血压可在 100mmHg 以上，\n患者有疲乏、 无力、 尿少、 口渴、 头晕等。尿钠极低或测不出。\n2.  中度失水   当每千克体重丢失钠在 8.5 ～12.0mmol （ 血浆钠 120mmol/L 左右） 时， 血压降至\n100mmHg 以下， 表现为恶心、 呕吐、 肌肉挛痛、 手足麻木、 静脉下陷及直立性低血压。尿钠测不出。\n3.  重度失水   当每千克体重丢失钠在 12.8 ～21.0mmol （ 血浆钠 110mmol/L 左右） 时， 血压降至\n80mmHg 以下， 出现四肢发凉、 体温低、 脉细数等休克表现， 并伴木僵等神经症状， 严重者昏迷。\n\u0018௉\u000fJOEE\u0001\u0001\u0001\u0018\u0017\u001a\u0018௉\u000fJOEE\u0001\u0001\u0001\u0018\u0017\u001a \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u001a\u001b\u0011\u0014\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u001a\u001b\u0011\u0014\n770\n第七篇   内分泌和代谢性疾病\n【诊断与鉴别诊断】  根据病史 （ 钠摄入不足、 呕吐、 腹泻、 多尿、 大量出汗等） 可推测失水的类型和\n程度， 再结合必要的实验室检查确诊。如高热、 尿崩症多考虑高渗性失水； 呕吐、 腹泻多考虑低渗性或\n等渗性失水。三种失水的比较见表 7-12-2。\n表7 -12-2   三种失水的比较\n临床表现 高渗性失水 等渗性失水 低渗性失水\n脱水外貌 不明显 较明显 很明显\n口渴 明显 有 无\n肌肉挛痛 无 有 有\n精神状态 烦躁、 谵妄 烦躁或淡漠 淡漠、 嗜睡\n体温 升高 正常或稍低 正常或稍低\n血压 正常， 严重者下降 降低 降低， 严重者休克\n尿量 很少 减少 正常， 严重者减少\n尿钠 正常 减少 明显减少\n血钠 ＞145mmol/L 130～145mmol/L ＜130mmol/L\n血液浓缩 + +～++ ++～+++\n血浆渗透压 ＞310mOsm/ （kg · H2O） 正常 ＜280mOsm/ （kg · H2O）\n失水、 失钠与血浆浓度 失水＞失钠 平衡 失水＜失钠\n注： 通常指中度以上失水。\n【防治】  积极治疗原发病， 避免不适当的脱水、 利尿、 鼻饲高蛋白饮食等， 依据失水的类型、 程度和机体情况， 决定补液方案。\n（ 一）  补液总量  应包括已丢失液体量及继续丢失的液体量两部分。\n1.  已丢失量  有 4 种计算方法。\n（1）  依据失水程度估算\n： 轻度失水相当于体重的 2%～3%； 中度失水相当于体重的 4%～6%，即\n2\n 400\n～3\n 600ml；\n重度失水相当于体重的 7%～14%， 更重者可达 15% 以上。\n（2）  依据","资料来源":"人卫《内科学》第10版 · 内分泌.txt · 本节“水、钠代谢失常”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2871,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4fbc63e6f1cd349e992e4577dfb954ff5cc7d817286f3e8721b72637907a456c","pinyin":"shui、nadaixieshichang","initials":"s、ndxsc","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-83c035e17e9d06b22dcc","key":"v1-c9ccc21dfe2a3058|templates-83c035e17e9d06b22dcc","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"特发性肺动脉高压","category":"内科","raw":{"name":"特发性肺动脉高压","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者因原始病史资料待补录，本次按初步诊断「特发性肺动脉高压」制定检查方案，完善 NT-ProBNP 检查评估右心负荷与心功能不全程度，并作为疗效随访的基线指标；查动脉血气分析与血氧饱和度，明确有无低氧血症及二氧化碳潴留，指导氧疗；查血常规排除慢性缺氧所致红细胞增多及贫血；查肝肾功能、电解质与凝血功能，为后续靶向药物及抗凝治疗的安全性提供依据；查甲状腺功能与自身抗体谱（抗核抗体、抗中性粒细胞胞浆抗体等），排除甲状腺疾病与结缔组织病相关肺动脉高压；查 HIV 抗体与肝炎病毒标志物，排除感染相关肺动脉高压；完善心电图与 24 小时动态心电图，了解有无右心室肥厚、右束支传导阻滞及心律失常；查心脏彩超＋左心功能测定评估右心大小、三尖瓣反流速度与估测肺动脉收缩压，排除左心疾病与先天性心脏病；查胸部 CT 及 CT 肺动脉造影，排除肺栓塞、肺静脉闭塞病及肺部实质性病变。病情稳定后行肺功能＋弥散功能检查与右心导管检查，明确血流动力学分级并指导靶向治疗；必要时行腹部及下肢静脉超声排除慢性血栓栓塞性肺动脉高压。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 特发性肺动脉高压","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"特发性肺动脉高压 （idiopathic pulmonary arterial hypertension， IPAH） 是一种不明原因的肺动脉高\n压， 过去被称为原发性肺动脉高压。病理上主要表现为 “致丛性肺动脉病”， 即由动脉中层肥厚、 向心\n或偏心性内膜增生及丛状损害和坏死性动脉炎等构成的疾病。\n【流行病学】 欧洲资料显示成年人肺动脉高压的患病率最低估计为 15/100 万人， 发病率最低估\n计为 2.4/ （100 万人 ·年）， IPAH 的患病率最低估计为 5.9/100 万人。1981 年美国国立卫生院第一次注\n册研究数据显示 IPAH 的平均患病年龄为 36 岁， 近年来老年人更多地被诊断为 IPAH， 最近的研究统\n计其平均年龄为 50～65 岁。目前我国尚无发病率的确切统计资料， 一些研究资料表明， IPAH与家族\n性肺动脉高压病人 1 年、 3 年、 5 年的生存率分别为 68%、 38.9%、 20.8%， 接受肺动脉高压靶向药物， 病\n人 1 年、 3 年、 5 年的生存率分别为 84.1%、 73.7%、 70.6%。\n【病因和发病机制】 特发性肺动脉高压迄今病因不明， 目前认为其发病与遗传因素、 自身免疫及\n肺血管内皮、 平滑肌功能障碍等因素有关。\n1.  遗传因素 11%～\n40% 的散发 IPAH 存在骨形成蛋白受体 2 （BMPR2） 基因变异。有些病例\n存在激活素受体样激酶 1 （ACVRL1） 基因、endoglin、SMAD9 变异。\n2.  免疫与炎症反应 免疫调节作用可能参与\nIPAH 的病理过程。有 29% 的 IPAH 病人抗核抗\n体水平明显升高， 但却缺乏结缔组织疾病的特异性抗体。IPAH 病人丛状病变内可见巨噬细胞、 T 淋\n巴细胞和 B 淋巴细胞浸润， 提示炎症细胞参与了 IPAH 的发生与发展。\n3.  肺血管内皮功能障碍 肺血管收缩和舒张由肺血管内皮分泌的收缩和舒张因子共同调控\n， 前\n者主要为血栓素 A2（TXA2）和内皮素 -1（ E T-1）， 后者主要是前列环素和一氧化氮 （NO）。由于上述因\n子表达的不平衡， 导致肺血管平滑肌收缩， 从而引起肺动脉高压。\n4.  血管壁平滑肌细胞钾通道缺陷 可见血管平滑肌增生肥大\n， 电压依赖性钾 （K\n+\n）通 道（ K v）功\n能缺陷， K\n+\n外流减少， 细胞膜处于除极状态， 使 Ca\n2+\n进入细胞内， 从而导致血管收缩。\n【临床表现】 \n（一）   症 状  IPAH 的症状缺乏特异性， 早期通常无症状， 仅在剧烈活动时感到不适； 随着肺动脉\n压力的升高， 可逐渐出现全身症状。\n续表　　\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0012\u0012\u001a\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0012\u0012\u001a \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u0019\u001b\u0015\u0019\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u0019\u001b\u0015\u0019\n120\n第二篇  呼吸系统疾病\n1.  呼吸困难 是最常见的症状， 多为首发症状， 主要表现为活动后呼吸困难， 进行性加重， 以至\n在静息状态下即感呼吸困难，与心排血量减少、 肺通气血流比例失调等因素有关。\n2.  胸痛\n 由于右心后负荷增加\n、 耗氧量增多及冠状动脉供血减少等引起心肌缺血所致， 常于活\n动或情绪激动时发生。\n3.  头晕或晕厥 由于心排血量减少\n， 脑组织供血突然减少所致。常在活动时出现， 有时休息时\n也可以发生。\n4.  咯血\n 通常为小量咯血，\n有时也可出现大咯血而致死亡。\n其他症状包括疲乏、 无力， 往往容易被忽视。10% 的病人出现雷诺现象， 增粗的肺动脉压迫喉返\n神经可引起声音嘶哑 （Ortner 综合征）。\n（二）   体 征  IPAH 的体征均与肺动脉高压和右心室负荷增加有关。\n【辅助检查】 \n1.  血液检查 血红蛋白可增高\n，与长期缺氧代偿有\n关； 脑钠肽可有不同程度升高，与疾病严重程度及病人预后\n具有一定相关性。\n2.  心电图\n 心电图不能直接反映肺动脉压升高\n， 但能\n提示右心增大或肥厚， 参见肺源性心脏病部分。\n3.  胸部 X 线检查 提示肺动脉高压的\nX 线征象 （ 图\n2-12-1） ： ①右下肺动脉干扩张， 其横径≥15mm 或右下肺动\n脉横径与气管横径比值 ≥1.07， 或动态观察右下肺动脉干\n增宽＞2mm； ②肺动脉段明显突出或其高度≥3mm； ③中心\n肺动脉扩张和外周分支纤细， 形成 “残根” 征； ④圆锥部显\n著凸出 （ 右前斜位 45°） 或其高度≥7mm； ⑤右心室增大。\n4.  超声心动图和多普勒超声检查 是筛查肺动脉高\n压最重要的无创性检查方法\n， 多普勒超声心动图估测三尖\n瓣峰值流速＞3.4m/s 或肺动脉收缩压＞50mmHg 将被诊断\n为肺动脉高压 （ 表 2-12-2）。\n表2 -12-2   超声心动图和多普勒超声在肺动脉高压中的评估及临床建议\n肺动脉高\n压可能性\n三尖瓣反流峰值 \n流速\n /\n（m/s）\n其他 “PH \n征象”\n无 PAH 或 CTEPH 危险\n因素或相关状况\n有 PAH 或 CTEPH 危险\n因素或相关状况\n低 ≤2.8 或测量不出 无 诊断存疑 随诊复查 Echo\n中 ≤2.8 或测量不出 有 诊断存疑、 随诊 进一步 PH 相关检查 （ 包\n括 RHC）2.9～3.4 无 或复查 Echo\n高 2.9～3.4 有 进一步 PH 相关检查 （ 包括\nRHC）\n进一步 PH 相关检查 （ 包\n括 RHC）＞3.4 不必要\n注： 其他 PH 征象包括右心室、 肺动脉、 下腔静脉和右心房的超声心动图征象。\n5.  肺功能测定 可有轻到中度限制性通气障碍与弥散功能障碍。\n6\n.  血气分析 多数病人有轻\n、 中度低氧血症， 系由通气血流比例失调所致。肺泡高通气导致二\n氧化碳分压降低。重度低氧血症可能与心排血量下降、 合并肺动脉血栓或卵圆孔开放有关。\n7.  放射性核素肺通气 / 灌注显像 I\nPAH 病人可呈弥漫性稀疏或基本正常， 也是排除慢性栓塞性\n肺动脉高压的重要手段。\n8.  右心漂浮导管检查及急性血管反应试验 右心漂浮导管检查是确定肺动脉高压的\n“金标准”\n检查， 可直接测量肺动脉压力， 并测定心排血量， 计算肺血管阻力， 确","资料来源":"人卫《内科学》第10版 · 呼吸.txt · 本节“特发性肺动脉高压”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2872,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a786655905c10dcd30a3d7586e202f127ed96df246eb434abe9bff609760086a","pinyin":"tefaxingfeidongmaigaoya","initials":"tfxfdmgy","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-4f346021320bca1753c2","key":"v1-c9ccc21dfe2a3058|templates-4f346021320bca1753c2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"特殊类型的胃炎或胃病","category":"内科","raw":{"name":"特殊类型的胃炎或胃病","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者因原始病史资料待补录，本次按初步诊断「特殊类型的胃炎或胃病」制定检查方案，完善胃镜检查并多点活检行病理组织学检查，明确胃炎的特殊类型（如嗜酸性粒细胞性胃炎、淋巴细胞性胃炎、肉芽肿性胃炎、Menetrier 病等）并排除胃恶性肿瘤；活检组织同步行幽门螺杆菌检测（快速尿素酶试验或病理染色），明确有无幽门螺杆菌感染以指导根除方案；查血常规与血清铁、铁蛋白、叶酸及维生素 B12，评估有无因胃黏膜病变导致的缺铁性贫血与巨幼细胞性贫血；查血清胃蛋白酶原Ⅰ、Ⅱ及胃泌素-17，了解胃黏膜萎缩范围与胃酸分泌状态，鉴别自身免疫性胃炎；查抗壁细胞抗体与内因子抗体，明确自身免疫性胃炎诊断；完善肝功能、肾功能、电解质及凝血功能，为后续用药及内镜治疗安全性提供依据；查粪便常规＋隐血试验，排除消化道出血；查腹部超声排除肝胆胰疾病所致上腹不适。病情稳定后复查胃镜评估黏膜愈合情况；对 Menetrier 病等怀疑恶性倾向者，加做超声内镜与增强 CT 评估病变范围。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 特殊类型的胃炎或胃病","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"【腐蚀性胃炎】 吞服强酸、 强碱、 砷、 磷、 氯化汞等所致。强酸常在口唇、 咽部黏膜留下不同颜色\n的烧灼痂； 强碱所致的严重组织坏死多呈黏膜透明肿胀。严重者可发生消化道出血、 上消化道穿孔、\n腹膜炎。幸存者常遗留食管和 / 或胃流出道狭窄。\n对腐蚀性胃炎， 应暂时禁食， 给予肠外营养， 密切监护。内镜检查有助于指导治疗， 但须小心谨\n慎。可放置鼻胃管， 清洗或稀释腐蚀剂， 引流胃液， 防止食管完全狭窄及梗阻。若不清楚腐蚀剂， 可饮\n用牛奶或蛋清进行稀释。对有喉头水肿、 呼吸困难者， 可考虑气管切开。对胃穿孔、 急性腹膜炎应手\n术修补。对后期出现瘢痕狭窄、 吞咽梗阻， 则需手术或胃镜下扩张或安置支架治疗。\n【感染性胃炎】 大多数非 Hp 感染的感染性胃炎病人机体存在免疫缺陷， 如获得性免疫缺陷病\n毒感染、 大剂量患者糖皮质激素和免疫抑制剂、 化疗期间或之后及垂危状态。\n1.  细菌感染 化脓性炎症多由葡萄球菌\n、 α- 溶血链球菌或大肠埃希菌引起\n， 胃手术及化疗常为\n其诱因。临床表现为突发上腹痛， 恶心呕吐， 呕吐物呈脓样、 含有坏死黏膜， 胃扩张， 有明显压痛和局\n部肌紧张、 发热。胃黏膜大片坏死脱落或扩展至胃壁， 常伴有败血症。严重坏死、 穿孔可导致化脓性\n腹膜炎， 由于基础疾病多致全身性衰竭、 营养不良， 死亡率高。其他可有结核及梅毒等细菌感染。\n2.  病毒感染 巨细胞病毒可发生于胃或十二指肠\n， 胃镜下可见局部或弥漫性胃黏膜皱襞粗\n大。组织切片中可见受染细胞体积增大 3～4 倍， 细胞核内可见嗜酸性包涵体， 酷似猫头鹰眼， 颇具特\n征性。\n【克罗恩病】 克罗恩病可累及整个消化道， 但主要见于小肠、 回盲部、 结肠， 也可发生于胃。胃克\n罗恩病多见于胃窦， 常与近端十二指肠克罗恩病共存。其组织病理特点详见本篇第八章第二节。\n【嗜酸细胞性胃炎】 是一种病因未明的少见疾病， 胃壁炎症以嗜酸性粒细胞浸润和外周血嗜酸\n性粒细胞增多为特征， 不伴有肉芽肿或血管炎性病变， 虽然胃壁各层均可受累， 多数病变以其中一层\n为主。胃黏膜活检在诊断中至关重要， 除明显嗜酸性粒细胞浸润外甚至形成嗜酸性小凹脓肿、 坏死伴\n中性粒细胞浸润和上皮再生。但当病变仅累及肌层或浆膜下层时， 靠胃黏膜活检难以作出诊断。病\n变范围可累及胃和小肠或仅局限于胃。本病可能因变应原与胃肠组织接触后在胃肠壁内发生抗原抗\n体反应， 释放出组胺类血管活性物质。\n临床表现有上腹疼痛、 恶心、 呕吐， 抑酸剂难以缓解腹痛， 常伴有腹泻， 外周血嗜酸性粒细胞增高。\n表4 -4-1   具有杀灭和抑制 Hp 作用的药物\n抗生素 克拉霉素、 阿莫西林、 甲硝唑、 替硝唑、 喹诺酮类抗生素、 呋喃唑酮、 四环素等\nPPI 埃索美拉唑、 奥美拉唑、 兰索拉唑、 泮托拉唑、 雷贝拉唑、 艾普拉唑等\n铋剂 枸橼酸铋钾、 果胶铋等\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0014\u0018\u0013\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0014\u0018\u0013 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0014\u0017\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0014\u0017\n第四章  胃炎\n373\n本病常为自限性， 但部分患者症状可持续存在或复发。治疗可用糖皮质激素。\n【淋巴细胞性胃炎】 其特征为胃黏膜表面及小凹内淋巴细胞密集浸润。其与内镜下疣状胃炎相\n关， 后者以结节、 皱襞增厚和糜烂为特征。根除 Hp 可显著改善胃上皮内淋巴细胞浸润、 胃体炎症和\n消化不良症状。故淋巴细胞性胃炎可能为伴发 Hp 感染的胃黏膜相关淋巴样组织 （mucosa-associated \nlymphoid tissue， MALT） 淋巴瘤的癌前疾病。\n内镜下， 淋巴细胞性胃炎表现为胃黏膜皱襞粗大， 结节样和口疮样糜烂 （ 疣状胃炎）。活检显示固\n有层扩大， 伴浆细胞、 淋巴细胞浸润， 偶见中性粒细胞浸润。\n【M é n é trier 病】 属增生性胃病， 即巨大肥厚性胃炎。胃镜下见胃体皱襞粗大、 肥厚、 扭曲呈脑\n回状， 胃窦黏膜多正常。因胃黏液分泌增多， 较多蛋白质从胃液中丢失， 常引起低蛋白血症。此症多\n见于男性， 病因不明。诊断本病时， 应注意除外胃黏膜的癌性浸润和淋巴瘤。本病无特效治疗且具有\n一定的癌变率。\n（房 静 远） 本章思维导图\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0014\u0018\u0014\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0014\u0018\u0014 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0014\u0017\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0014\u0017\n本章数字资源\n374\n第五章  消化性溃疡\n消化性溃疡 （peptic ulcer， PU） 指胃、 十二指肠黏膜发生的炎性缺损，与胃液的胃蛋白酶消化和胃\n酸作用有关， 病变穿透黏膜肌层或达更深层次。消化性溃疡也可发生于食管 \n- 胃吻合口及胃 \n- 空肠吻\n合口或附近，\n还可发生于含有胃黏膜的 Meckel 憩室等。\n【流行病学】 PU 是一种全球性常见病， 男性多于女性， 可发生于任何年龄段； 不同年龄时期患病\n率存在差异， 约有 10% 的人其一生中患过本病。十二指肠溃疡 （duodenal ulcer， DU） 多于胃溃疡 （gastric \nulcer， GU）。DU 多见于青壮年， GU 多见于中老年。过去 30 年随着 H2RA、 PPI 等抑酸药物的患者， PU 及\n其并发症发生率明显下降。近年阿司匹林等 NSAIDs 药物患者增多， 老年消化性溃疡发病率有所增高。\n【病因和发病机制】 PU 病因和发病机制是多因素的， 损伤与防御修复不足是发病机制的两个\n方面。\n1.  胃酸与胃蛋白酶 胃蛋白酶是\nPU 发病的重要因素， 其活性依赖于胃液的 pH， pH 为 2～3 时，\n胃蛋白酶原易被激活； pH 大于 4 时， 胃蛋白酶失活。因此， 抑制胃酸可同时降低胃蛋白酶的活性。\nPU 发生的机制是致病因素引起胃酸、 胃蛋白酶对胃黏膜的侵袭作用与黏膜屏障的防御能力间失\n去平衡。侵袭作用增强或\n /和防御能力减弱均可导致\nPU 的产生。GU和 DU 同属于 PU。\n2.  Hp\n H\np 感染是 PU 的另一个重要致病因素。DU 病人的 Hp 感染率可高达 90% 以上， GU 的\nHp 阳性率为 60%～90%。另外， Hp 阳性率高的人群， PU 的患病率也较高。根除 Hp 有助","资料来源":"人卫《内科学》第10版 · 消化.txt · 本节“特殊类型的胃炎或胃病”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2873,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8564c90f99316c4aa76d6ec737d0302487eb45b9e2a65c70c6f4c0fb2d8bbe0a","pinyin":"teshuleixingdeweiyanhuoweibing","initials":"tslxdwyhwb","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-dfe69c77e762b9c931d2","key":"v1-c9ccc21dfe2a3058|templates-dfe69c77e762b9c931d2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"生长激素缺乏性矮小症","category":"内科","raw":{"name":"生长激素缺乏性矮小症","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者因原始病史资料待补录，本次按初步诊断「生长激素缺乏性矮小症」制定检查方案，完善左手腕掌指骨 X 线片测定骨龄，评估骨骼成熟度与生长潜能，明确骨龄落后程度；查血清胰岛素样生长因子-1（IGF-1）与胰岛素样生长因子结合蛋白-3（IGFBP-3）作为生长激素分泌状态的筛查指标；行生长激素激发试验（胰岛素低血糖试验或左旋多巴、精氨酸激发试验）两项以上，明确生长激素缺乏的诊断并判断缺乏程度；查甲状腺功能五项，排除甲状腺功能减退所致矮小；查血皮质醇与促肾上腺皮质激素，排除肾上腺皮质功能异常；查肝肾功能、血糖、电解质与血常规，作为重组人生长激素治疗前的安全基线；查染色体核型（女性患儿）排除 Turner 综合征；完善垂体 MRI 检查，明确有无垂体发育不良、垂体柄中断综合征或颅内占位；查 IGF-1 及甲状腺功能定期复查，用于治疗期间剂量调整与安全性监测，同时监测血糖与甲状腺功能以防治疗相关并发症。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 生长激素缺乏性矮小症","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"生长激素缺乏性矮小症又称儿童生长激素缺乏症 （growth hormone  deficiency， GHD）， 指儿童期因\n垂体前叶分泌的生长激素缺乏或生长激素生物效应不足所致的躯体生长障碍， 可为单一性生长激素\n缺乏， 也可伴有腺垂体其他激素缺乏。按病因可为特发性、 获得性和遗传性； 按病变部位可分为下丘\n脑性和垂体性。\n【病因和发病机制】\n1.  特发性  病因不明。可能由于下丘脑 \n- 垂体功能或结构的异常\n， 导致生长激素 （GH） 分泌不\n足。部分患者在接受生长激素释放激素 （GHRH） 治疗后， GH 水平升高， 生长加速， 提示有些患者的\n病因在下丘脑。部分患儿有围生期异常， 如臀位产、 横位产、 生后窒息等， 可能是 GHD 导致的胎儿宫\n内转位障碍。\n2.  获得性  本病可继发于下丘脑 \n- 垂体病变\n， 如先天性垂体异常， 或来自中枢神经系统的肿瘤\n（ 颅咽管瘤、 生殖细胞肿瘤、 垂体瘤、 脑膜瘤、 胶质瘤、 Rathke 囊肿、 蛛网膜囊肿等）； 颅内感染 （ 脑炎、 脑\n膜炎） 及肉芽肿病变； 手术、 创伤、 放射损伤等， 病变可影响下丘脑 \n- 腺垂体的结构和功能\n， 引起获得性\n生长激素缺乏症。\n3.  遗传性  至少有三分之一的 GHD 患者有家族史， 可表现为常染色体显性、 隐性遗传或 X 连锁\n遗传。分子生物学研究已明确部分患者存在下丘脑 \n- 垂体发育的转录因子\n（ 如POU1F1和 PROP1）的\n基因突变， 或生长激素基因 （GH1） 缺失 / 突变\n， 或生长激素受体及下游信号转导过程的基因突变等。\n其中， 转录因子突变多表现为复合性垂体激素缺乏， 如 GH、 PRL、 TSH、 促性腺激素缺乏。\n生长激素不敏感综合征： 本综合征是由于靶细胞对 GH 不敏感而引起的一种矮小症。本病多呈\n常染色体隐性遗传。其病因复杂多样， 多数为 GH 受体基因突变 （Laron 综合征）， 少数因 GH 受体后\n信号转导障碍、 胰岛素样生长因子 \n-1 （IGF-1） 基因突变或 IGF-1 受体异常等因素引起。\n【临床表现】\n1.  生长迟缓   本病患者出生时身长、 体重往往正常， 数月后躯体生长迟缓， 但常不被发觉。多\n在2 ～3 岁后与同龄儿童的身高差别愈见显著， 但生长并不完全停止， 只是生长速度缓慢， 生长速度低\n于正常速度 1SD （ 一般指 2～4 岁每年低于 5.5cm、 4 岁至青春\n期每年低于 4 ～5cm）。体态一般尚匀称， 成年后多仍保持童年\n体形和外貌， 营养状态一般良好。成年身高一般不超过 130cm \n（图 7-3-3）， 但最终身高与生长激素缺乏的程度、 时间都有关系。\n2.  性腺发育障碍   患者至青春期， 性器官常不发育， 第二\n性征缺如， 声音尖锐， 体型偏胖。男性呈小阴茎，与幼儿相似，\n睾丸细小， 可伴隐睾症， 无阴毛和腋毛； 女性可表现为原发性闭\n经， 乳房发育差， 子宫和附件均小。单一性 GH 缺乏者可出现性\n器官发育与第二性征， 但往往明显延迟。\n3.  智力与年龄相称   智力发育一般正常， 但在精神方面\n可因身材矮小而有自卑感、 心情忧郁。\n4.  骨发育延迟和骨代谢异常   临床上通常选用左手腕部\n进行 X 线摄片来观察骨骺骨化中心的成熟程度， 即骨龄。未治\n疗过的 GHD 患儿的骨龄较正常同龄儿童显著落后 2 年或 2 年\n以上。除骨骼成熟缓慢， 骨转换水平也较低， 骨量减少甚至出\n现骨质疏松。X 线摄片可见长骨短小， 骨龄幼稚， 骨化中心发育\n迟缓， 骨骺久不融合。\n图7 -3-3   生长激素缺乏性矮小症\n患者与同龄正常人对比。\n\u0018௉\u000fJOEE\u0001\u0001\u0001\u0017\u0018\u0019\u0018௉\u000fJOEE\u0001\u0001\u0001\u0017\u0018\u0019 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u0019\u001b\u0015\u0019\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u0019\u001b\u0015\u0019\n第三章   垂体前叶疾病\n679\n5.  Laron 综合征 （ 侏儒综合征）  罕见。呈常染色体隐性遗传， 是 GH 受体基因突变所致， 患者\n有严重 GH 缺乏的临床表现， 如身材矮小， 蓝巩膜， 肘关节活动受限， 头相对较大， 鞍鼻， 前额凸出， 外\n生殖器和睾丸细小， 性发育延迟等。但血浆 GH 水平正常或升高， IGF-1、 胰岛素样生长因子结合蛋\n白 \n-3 （IGFBP-3） 降低。本病患者对外源性 GH 治疗无反应， 目前唯一有效的治疗措施是使用重组人\nIGF-1 替代治疗。\n【诊断与鉴别诊断】\n（ 一）  主要诊断依据  ①身材矮小 （ 身高为同年龄同性别正常人均值 -2SD 以下）， 生长速度缓慢，\n可伴性发育障碍等临床特征。②骨龄检查较实际年龄落后 2 年以上。③血 IGF -1和 IGFBP-3 水平测\n定： GH 刺激肝脏分泌 IGF-1， GH 的促进生长作用大部分是由循环中的 IGF-1 介导， 因此测定 IGF-1水\n平可反映 GH 的分泌状态。已发现 6 种 IGFBP， 分别称为 IGFBP-1～IGFBP-6， 其中 IGFBP-3占9 2 %，\n可反映 GH 的分泌状态。④GH 激发试验： 因生长激素呈脉冲式分泌， 测定随机血 GH 浓度对诊断价\n值不大。临床上常需要进行至少两个 GH 激发试验协助诊断， 包括胰岛素低血糖、 左旋多巴、 精氨酸、\n可乐定等激发手段 （ 见本章","资料来源":"人卫《内科学》第10版 · 内分泌.txt · 本节“生长激素缺乏性矮小症”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2874,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"37cee01988a0b637f74b55288488925682e3fcdf53fd29746fbdd3d1e8a67962","pinyin":"shengzhangjisuquefaxingaixiaozheng","initials":"szjsqfxaxz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-1f388c3ddf41335a7e7d","key":"v1-c9ccc21dfe2a3058|templates-1f388c3ddf41335a7e7d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"甲状腺结节和甲状腺癌","category":"内科","raw":{"name":"甲状腺结节和甲状腺癌","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者因原始病史资料待补录，本次按初步诊断「甲状腺结节和甲状腺癌」制定检查方案，完善甲状腺功能检查（促甲状腺激素、游离三碘甲状腺原氨酸、游离甲状腺素）了解甲状腺功能状态并指导后续处理；查甲状腺球蛋白与甲状腺球蛋白抗体、甲状腺过氧化物酶抗体，作为甲状腺癌术后随访与自身免疫性甲状腺疾病鉴别的基线；完善甲状腺及颈部淋巴结彩超，明确结节大小、形态、边界、回声、血流及钙化情况，并按 TI-RADS 分类评估恶性风险、了解颈部淋巴结有无转移；对超声提示中高危结节行超声引导下细针穿刺细胞学检查，明确结节性质以指导手术决策；查血清降钙素，排除甲状腺髓样癌；查血常规、肝肾功能、电解质、凝血功能与心电图，作为手术前必查项目评估手术耐受性；查血钙与甲状旁腺激素，作为甲状腺全切术后低钙血症风险评估的基线。必要时行颈部增强 CT 或 MRI 评估胸骨后甲状腺肿及气道受压情况；术后定期复查甲状腺功能与甲状腺球蛋白，指导左甲状腺素抑制治疗剂量调整。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 甲状腺结节和甲状腺癌","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"一、   甲状腺结节\n甲状腺结节 （thyroid n odule） 临床常见。在女性和男性触及率分别为 6 %和2 %， 人群中高分辨\n率超声对甲状腺结节检出率可高达 76 %。大部分结节为良性结节或囊肿， 约 5%～10% 为恶性肿瘤。\n少数甲状腺结节具有自主分泌甲状腺激素功能。\n【病因】  病因和发病机制仍不明。良性甲状腺结节包括多结节性甲状腺肿、 甲状腺囊肿、 甲状腺\n滤泡性腺瘤、 嗜酸细胞腺瘤以及桥本甲状腺炎和亚急性甲状腺炎等形成的结节。恶性结节绝大多数\n为甲状腺癌， 少数为原发性甲状腺淋巴瘤或转移癌。\n\u0018௉\u000fJOEE\u0001\u0001\u0001\u0017\u001a\u001a\u0018௉\u000fJOEE\u0001\u0001\u0001\u0017\u001a\u001a \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u0019\u001b\u0016\u0013\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u0019\u001b\u0016\u0013\n700\n第七篇   内分泌和代谢性疾病\n【临床表现】  大部分甲状腺结节无任何临床症状， 常在体检或影像学检查时发现。如伴有甲状\n腺功能异常可出现相应症状。结节可导致压迫症状， 气管受压时会出现咳嗽、 气促， 食管受压时会有\n吞咽困难， 胸骨后甲状腺结节可引起 Pemberton 征。当周围组织受侵犯时提示恶性结节可能， 喉返神\n经受累时会出现声嘶， 气管被侵犯时可出现咯血。如甲状腺癌发生远处转移， 可出现相应症状， 如胸\n痛、 呼吸困难、 骨痛和神经系统受累症状。\n提示结节为甲状腺癌的危险因素包括： ①儿童时期头颈部放射线暴露史； ②有甲状腺髓样癌、 多\n发性内分泌腺瘤病 2 型 （MEN2） 或甲状腺乳头状癌家族史； ③年龄＜14 岁或＞70 岁； ④男性； ⑤结节\n迅速增大； ⑥结节形状不规则、 坚硬、 固定； ⑦异常颈部淋巴结； ⑧伴持续性声嘶、 发音困难、 吞咽困难\n或呼吸困难。\n【实验室检查】  首先行甲状腺功能检查。如 TSH 下降须行甲状腺核素扫描 （\n99m\nTcO4\n-\n、\n123\nI或\n131\nI）\n以明确是否为自主高功能结节。具有自主分泌功能的 “热” 结节的恶性风险极小， 一般不须细针穿刺\n活检 （FNA）。如 TSH 正常或升高， 超声检查显示有恶性征象 （ 见影像学检查）， 须行 FNA。TPOAb和\nTgAb 有助于排查自身免疫性甲状腺炎。有甲状腺髓样癌或多发性内分泌腺瘤病 2 型家族史的患者\n应检测血清降钙素及癌胚抗原。血清 Tg 检测无法鉴别甲状腺结节的良恶性。\n【影像学检查】  超声是评估甲状腺结节最重要的影像学检查， 对结节良恶性鉴别价值优于 CT\n或 MRI。超声检查可明确结节的位置、 大小、 数目、 囊实性、 回声水平、 形态、 有无钙化、 边缘、 血供、与\n周边解剖结构关系以及颈部淋巴结情况。通过超声征象对结节的良恶性进行危险分层可以指导是否\n进行 FNA 及下一步处理。提示结节恶性的征象包括： 实性、 低回声、 结节纵横比＞1、 微小钙化、 边缘\n不规则、 甲状腺外浸润、 异常颈部淋巴结等。中、 高危结节 （ 实性低回声结节不伴或伴上述恶性征象）\n直径≥1cm 时须行 FNA； 低危结节 （ 实性等回声或高回声结节不伴上述恶性征象） 直径≥1.5cm 时行\nFNA； 极低危结节 （ 海绵状或部分囊性结节不伴上述恶性征象） 则直径≥2cm 时才建议做 FNA。随着\n人工智能技术的发展， 目前正研究开发用于鉴别甲状腺良恶结节的超声影像人工智能系统。\n颈部 CT 或 MRI 主要用于判断甲状腺结节与周围解剖结构的关系， 并协助寻找异常颈部淋巴结。\n核素扫描主要用于判断是否为甲状腺自主高功能结节。\n18\nF-FDG P ET 显像阳性的甲状腺结节恶性风\n险仅为 30%～40%， 不能准确判断良恶性。\n【细针穿刺活检】  超声引导下 FNA 细胞学检查是目前术前鉴别甲状腺结节良恶性的国际标\n准， 其诊断的灵敏度和特异度均达 90% 以上。根据甲状腺细胞学 Bethesda 报告系统， FNA 细胞学\n检查结果可分 6 类： Ⅰ 类， 非诊断性； Ⅱ类， 良性； Ⅲ类， 意义不明的不典型病变； Ⅳ类， 滤泡性肿瘤； Ⅴ\n类， 可疑恶性； Ⅵ类， 恶性。Bethesda Ⅲ\n类、 Ⅳ类、 Ⅴ类属于细胞学不确定的结节， 可行分子检测进一\n步明确诊断。目前分子检测主要基于基因突变  / 重排和\nmRNA 表达。基因突变  / 重排组合\n（BRAF，\nRAS，RET/PTC，PAX8/PPARG）等 具 有 较 高 阳 性 预 测 值； 基 因 组 测 序 分 类 器 （genomic\n sequencing\n \nc\nlassifier， GSC） 等具有高诊断灵敏度和高阴性预测值， 可减少细胞学不确定结节行诊断性手术的 \n比例。\n【诊断与鉴别诊断】  甲状腺结节的诊断须结合病史、 临床表现、 实验室检查和甲状腺超声检查\n综合判断， 超声引导下 FNA 可对结节的良恶性进行准确的评估， 也可以进行有效的鉴别诊断。对于\nFNA 细胞学检查为不确定的结节， 分子诊断有助于进一步明确诊断。\n【治疗】  对临床高度疑似恶性或 FNA 确定为恶性的结节， 须进行外科手术治疗。\n甲状腺良性结节须长期随访， 且须保持适量碘摄入， 不建议进行 TSH 抑制治疗。\n如果临床或超声出现可疑恶性征象或结节体积增大超过 50 %（ 或至少 2 条径线增加超过 20% 且\n超过 2mm）， 应重复行超声引导下 FNA 明确诊断。\n良性结节出现压迫症状或位于胸骨后首选手术治疗， 术后给予左甲状腺素 （L-T4） 替代治疗。甲\n状腺自主高功能结节可采用手术治疗或放射性碘治疗。超声引导下热消融治疗可作为有压迫症状\n或影响外观且最大直径≥2cm 的实性结节的治疗选择之一， 热消融前须行穿刺活检明确结节为良性。\n\u0018௉\u000fJOEE\u0001\u0001\u0001\u0018\u0011\u0011\u0018௉\u000fJOEE\u0001\u0001\u0001\u0018\u0011\u0011 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u0019\u001b\u0016\u0013\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0016\u001b\u0011\u0019\u001b\u0016\u0013\n第五章   甲状腺疾病\n701\n甲状腺囊肿或囊性为主的结节 （ 囊性体积＞90%） 可选择超声引导下经皮无水酒精或聚桂醇注射治疗\n（PEI/PLI）。\n二、   甲状腺癌\n甲状腺癌 （thyroid c arcinoma， TC） 是内分泌系统最常见的恶性肿瘤。根据组织学特征， 源于甲状\n腺滤泡上皮的恶","资料来源":"人卫《内科学》第10版 · 内分泌.txt · 本节“甲状腺结节和甲状腺癌”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2875,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"060adda79512441997ba30c551d0f892d68b227bfae8ba9d532d72c43460ac07","pinyin":"jiazhuangxianjiejiehejiazhuangxianai","initials":"jzxjjhjzxa","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-ad2263e3fbcdf9f31fff","key":"v1-c9ccc21dfe2a3058|templates-ad2263e3fbcdf9f31fff","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"病毒性肺炎","category":"内科","raw":{"name":"病毒性肺炎","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者因原始病史资料待补录，本次按初步诊断「病毒性肺炎」制定检查方案，入院即刻完善血常规＋C 反应蛋白检查，了解白细胞与淋巴细胞计数变化，评估感染程度并初步鉴别病毒与细菌感染；查降钙素原有助于鉴别是否合并细菌感染，指导抗菌药物使用；完善胸部 CT 检查，明确肺部病变部位、范围、形态（磨玻璃影、间质改变）并排除肺结核、肺部肿瘤及其他非感染性病变；查动脉血气分析，评估氧合状态与呼吸衰竭程度，指导氧疗与呼吸支持；行呼吸道病原体核酸检测（流感病毒、呼吸道合胞病毒、腺病毒、鼻病毒及新型冠状病毒等），明确病原学诊断以指导抗病毒治疗；查肝肾功能、电解质与心肌酶谱，评估有无病毒所致肝损伤、心肌损伤及电解质紊乱；查凝血功能与 D-二聚体，排除病毒性肺炎继发的高凝状态与肺栓塞；查 NT-ProBNP 与心脏彩超＋左心功能测定，排除病毒性心肌炎及心力衰竭所致呼吸困难。病情加重或疗效不佳时复查胸部 CT 与炎症指标，必要时行支气管镜检查及肺泡灌洗液病原学检测以进一步明确诊断。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 病毒性肺炎","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"病毒性肺炎 （viral pneumonia） 是由病毒侵入呼吸道上皮及肺泡上皮细胞引起的肺间质及实质性\n炎症。免疫功能正常或抑制的个体均可罹患。大多发生于冬春季节， 暴发或散发流行。病毒是成人\n社区获得性肺炎除细菌外第二大常见病原体， 大多可自愈。近年来， 新的变异病毒 （ 如 SARS 冠状病\n毒， H5N1、 H1N1、 H7N9 病毒等） 不断出现， 产生暴发流行， 死亡率较高， 成为公共卫生防御的重要疾病\n之一。\n【病因和发病机制】 常见病毒为甲、 乙型流感病毒， 腺病毒， 副流感病毒， 呼吸道合胞病毒和冠状\n病毒等。免疫抑制宿主为疱疹病毒和麻疹病毒的易感者； 骨髓移植和器官移植受者易患疱疹病毒和\n巨细胞病毒性肺炎。病人可同时受一种以上病毒感染， 并常继发细菌感染如金葡菌感染， 免疫抑制宿\n主还常继发真菌感染。病毒性肺炎主要为吸入性感染， 通过人与人的飞沫传染， 主要是由上呼吸道病\n毒感染向下蔓延所致， 常伴气管支气管炎。偶见黏膜接触传染， 呼吸道合胞病毒通过尘埃传染。器官\n移植的病例可以通过多次输血， 甚至供者的器官引起病毒血行播散感染， 通常不伴气管支气管炎。\n【病理】 病毒侵入细支气管上皮引起细支气管炎。感染可波及肺间质与肺泡而致肺炎。气道上\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0016\u0014\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0016\u0014 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u0019\u001b\u0015\u0011\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u0019\u001b\u0015\u0011\n54\n第二篇  呼吸系统疾病\n皮广泛受损， 黏膜发生溃疡， 其上覆盖纤维蛋白被膜。单纯病毒性肺炎多为间质性肺炎， 肺泡间隔有\n大量单核细胞浸润。肺泡水肿， 被覆含蛋白及纤维蛋白的透明膜， 使肺泡弥散距离增加。肺炎可为局\n灶性或弥漫性， 也可呈实变。部分肺泡细胞及巨噬细胞内可见病毒包涵体。炎性介质释出， 直接作用\n于支气管平滑肌， 致使支气管痉挛。病变吸收后可留有肺纤维化。\n【临床表现】 好发于病毒疾病流行季节， 症状通常较轻，与支原体肺炎的症状相似。但起病较\n急， 发热、 头痛、 全身酸痛、 倦怠等全身症状较突出， 常在急性流感症状尚未消退时即出现咳嗽、 少痰或\n白色黏液痰、 咽痛等呼吸道症状。小儿或老年人易发生重症肺炎， 表现为呼吸困难、 发绀、 嗜睡、 精神\n萎靡， 甚至发生休克、 心力衰竭和呼吸衰竭或 ARDS 等并发症。本病常无显著的胸部体征， 病情严重\n者有呼吸浅速、 心率增快、 发绀、 肺部干湿啰音。\n【实验室和其他检查】 白细胞计数正常、 稍高或偏低， 血沉通常在正常范围， 痰涂片所见的白细\n胞以单核细胞居多， 痰培养常无致病细菌生长。\n病毒培养较困难， 不宜常规开展， 肺炎病人的痰涂片仅发现散在细菌及大量有核细胞， 或找不到\n致病菌， 应怀疑病毒性肺炎的可能。用血清检测病毒的特异性 IgM 抗体， 有助于早期诊断。急性期和\n恢复期的双份血清抗体滴度增高 4 倍或以上有确诊意义。PCR 检测病毒核酸对新发变异病毒或少见\n病毒有确诊价值。\n胸部 X 线检查可见肺纹理增多， 磨玻璃状阴影， 小片状浸润或广泛浸润、 实变， 病情严重者显示\n双肺弥漫性结节性浸润， 但大叶实变及胸腔积液者均不多见。病毒性肺炎的致病原不同， 其 X 线征\n象亦有不同的特征。病毒性肺炎胸部 CT 表现多样， 常见小叶分布的磨玻璃影、 小结节病灶， 也可表\n现为网织索条影， 支气管、 血管束增粗， 叶、 段实变影， 可伴有纵隔淋巴结肿大， 单侧或双侧少量胸腔积\n液。病毒性肺炎吸收慢， 病程长。\n【诊断】 诊断依据为临床症状及 X 线或 CT 影像改变， 并排除由其他病原体引起的肺炎。确诊\n则有赖于病原学检查， 包括病毒分离、 病毒核酸以及病毒抗体的检测。呼吸道分泌物中细胞核内的包\n涵体可提示病毒感染， 但并非一定来自肺部， 需进一步收集下呼吸道分泌物或肺活检标本作培养分离\n病毒。血清学检查常用的方法是检测特异性 IgG 抗体， 如补体结合试验、 血凝抑制试验、 中和试验， 作\n为回顾性诊断。\n【治疗】 以对症为主， 必要时氧疗。注意隔离消毒， 预防交叉感染。\n目前已经证实较为有效的病毒抑制药物有： ①利巴韦林， 具有广谱抗病毒活性， 包括呼吸道合胞\n病毒、 腺病毒、 副流感病毒和流感病毒。0.8～1.0g/d， 分 3～4 次服用； 静脉滴注或肌内注射每日 10～\n15mg/kg， 分 2 次。亦可用雾化吸入， 每次 10～30mg， 加蒸馏水 30ml， 每日 2 次， 连续 5～7 天。②阿昔\n洛韦， 具有广谱、 强效和起效快的特点， 用于疱疹病毒、 水痘病毒感染， 尤其对免疫缺陷或患者免疫抑\n制者应尽早患者。每次 5mg/kg， 静脉滴注， 一日 3 次， 连续给药 7 天。③更昔洛韦， 可抑制 DNA 合成，\n用于巨细胞病毒感染， 7.5～15mg/ （kg · d）， 连用 10～15 天。④奥司他韦， 为神经氨酸酶抑制剂， 对甲、\n乙型流感病毒均有很好的抑制作用， 耐药发生率低， 150mg/d， 分 2 次， 连用 5 天。⑤阿糖腺苷， 具有广\n泛的抗病毒作用， 多用于治疗免疫缺陷病人的疱疹病毒与水痘病毒感染， 5～15mg/ （kg · d）， 静脉滴注，\n每 10～14 天为 1 个疗程。原则上不宜患者抗生素预防继发性细菌感染， 一旦明确已合并细菌感染，\n应及时选用敏感的抗生素。\n糖皮质激素对病毒性肺炎疗效仍有争论， 例如对传染性非典型肺炎国内报道有效， 而欧洲和亚洲\n有报道对 H1N1 肺炎的观察证明无效， 还导致病死率升高、 机械通气和住院时间延长、 二重感染发生\n率升高。因此， 不同的病毒性肺炎对激素的反应可能存在差异， 应酌情使用。\n［附 1］   严重急性呼吸综合征\n严重急性呼吸综合征 （severe acute respiratory syndrome， SARS） 是由 SARS 冠状病毒 （SARS-associated \ncoronavirus， SARS-CoV） 引起的一种具有明显传染性、 可累及多个器官系统的病毒性肺炎。2002 年首\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0016\u0015\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0016\u0015 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u0019\u001b\u0015\u0011\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u0019\u001b\u0015\u0011\n第六章","资料来源":"人卫《内科学》第10版 · 呼吸.txt · 本节“病毒性肺炎”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2876,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d71d0e0e2c1dbbe4abddd103f6f5a707e82dc7d84ec624f9337b5840cebb31fd","pinyin":"bingduxingfeiyan","initials":"bdxfy","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-1151438f663615fc80da","key":"v1-c9ccc21dfe2a3058|templates-1151438f663615fc80da","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"窦性心律失常","category":"内科","raw":{"name":"窦性心律失常","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者因原始病史资料待补录，本次按初步诊断「窦性心律失常」制定检查方案，入院即刻完善 12 导联心电图检查，明确窦性心动过速、窦性心动过缓、窦性停搏或窦房传导阻滞的类型；查 24 小时动态心电图，了解心率变异性、最快最慢心率及有无伴随的其他心律失常，评估有无病态窦房结综合征；查甲状腺功能五项，排除甲状腺功能亢进或减退所致窦性心律失常；查血常规排除贫血所致代偿性心动过速；查血清电解质（钾、钠、氯、钙、镁），排除电解质紊乱所致心律失常；查心肌酶与肌钙蛋白，排除急性心肌损伤与心肌梗死；查肝肾功能、血糖与血脂，了解基础代谢状况并为抗心律失常药物选择提供依据；查 NT-ProBNP 与心脏彩超＋左心功能测定，评估心脏结构与射血分数，排除器质性心脏病、心肌病及心力衰竭；对疑有睡眠呼吸暂停者行多导睡眠监测，排除夜间低氧所致窦性心律失常。头晕、黑矇或晕厥发作时急诊完成心电图并持续心电监护；病情稳定后行阿托品试验或食管心房调搏检查，评估窦房结功能，明确是否需要起搏器治疗。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 窦性心律失常","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"正常窦性心律的冲动起源于窦房结， 频率为 60～100 次 / 分。心电图显示窦性心律的 P 波在 Ⅰ、\nⅡ、 aVF 导联直立， aVR 导联倒置； PR 间期为 0.12～0.20 秒。窦性心律失常是由于窦房结冲动发放频\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0012\u001a\u0016\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0012\u001a\u0016 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0011\u0019\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0011\u0019\n196\n第三篇  循环系统疾病\n率的异常或窦性冲动向心房的传导受阻所导致的心律失常。根据心电图及临床表现分为窦性心动过\n速、 窦性心动过缓、 窦性停搏、 窦房传导阻滞以及病态窦房结综合征。\n一、  窦性心动过速\n成人窦性心律的频率超过 100 次 / 分为 窦性心动过速 （sinus tachycardia） （ 图 3-3-4）。目前临床上\n分为生理性窦性心动过速和不适当窦性心动过速。生理性窦性心动过速通常见于健康人、 吸烟、 饮茶\n或咖啡、 饮酒、 体力活动及情绪激动时； 也可见于某些病理状态， 如发热、 甲亢、 贫血、 休克、 心肌缺血、\n心力衰竭以及患者肾上腺素、 阿托品等药物时。不适当窦性心动过速是指在静息状态下心率的持续\n性增快， 或心率的增快与生理、 情绪激动、 病理状态或药物作用无关或不相一致， 其发生机制不明， 可\n能与窦房结本身的自律性增强， 或自主神经对窦房结的调节异常有关。窦性心动过速通常逐渐开始和终止， 频率大多在 100～150 次 / 分\n。窦性心动过速的治疗应针对病因和去除诱发因素， 如治疗心力\n衰竭、 纠正贫血、 控制甲亢等。必要时单用或联合患者β受体拮抗剂、 非二氢吡啶类钙通道阻滞剂 （ 如\n地尔硫䓬）； 如上述药物无效或不能耐受， 可选用窦房结内向电流 If 抑制剂伊伐布雷定。\n图3 -3-4   窦性心动过速\nⅡ\n导联的 P 波正向， PR 间期 0.13 秒， 心率 115 次\n /\n 分。\n二、  窦性心动过缓\n成人窦性心律的频率低于 60 次 / 分 称为窦性心动过缓 （sinus bradycardia） （ 图 3-3-5）。窦性心动\n过缓常同时伴有窦性心律不齐 （ 不同 PP 间期的差异＞0.12 秒）。窦性心动过缓常见于健康的青年人、\n运动员及睡眠状态； 其他原因包括颅内疾病、 严重缺氧、 低温、 甲状腺功能减退和血管迷走性晕厥等，\n以及患者拟胆碱药物、 胺碘酮、 β受体拮抗剂、 非二氢吡啶类钙通道阻滞剂或洋地黄类等药物； 窦房结\n病变和急性下壁心肌梗死亦常发生窦性心动过缓。无症状的窦性心动过缓通常无需治疗。如因心率\n过慢， 出现心排血量不足症状如头晕、 黑矇、 乏力， 可患者阿托品或异丙肾上腺素等药物， 但长期患者\n往往效果不确定， 易发生严重副作用， 故应考虑心脏起搏治疗。\n图3 -3-5   窦性心动过缓\nⅡ\n导联的 P 波正向， PR 间期 0.18 秒， 心率 48 次\n /\n 分。\n三、  窦性停搏\n窦性停搏或窦性静止 （sinus pause or sinus arrest） 是指窦房结不能产生冲动。心电图表现为在较\n正常 PP 间期显著长的间期内无 P 波发生， 或 P 波与 QRS 波均不出现， 长的 PP 间期与基本窦性 PP\n间期无倍数关系 （ 图 3-3-6）。长时间的窦性停搏后， 下位的潜在起搏点， 如房室交界处或心室， 可发出\n单个逸搏或逸搏性心律控制心室。窦性停搏多见于窦房结变性与纤维化、 急性下壁心肌梗死、 脑血管\n意外等病变以及迷走神经张力增高或颈动脉窦过敏； 此外， 患者洋地黄类药物、 乙酰胆碱等亦可引起\n窦性停搏。过长时间的窦性停搏 （＞3 秒） 且无逸搏发生时， 病人可出现黑矇、 短暂意识障碍或晕厥，\n严重者可发生阿 \n- 斯\n（Adams-Stokes） 综合征， 甚至死亡。治疗可参照病态窦房结综合征。\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0012\u001a\u0017\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0012\u001a\u0017 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0011\u0019\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0011\u0019\n第三章  心律失常\n197\n四、  窦房传导阻滞\n窦房传导阻滞 （sinoatrial block， SAB） 指窦房结冲动传导至心房时发生延缓或阻滞。理论上 SAB\n可分为三度， 由于体表心电图不能显示窦房结电活动， 因而通过体表心电图无法确定一度和三度窦房\n传导阻滞的诊断。二度窦房传导阻滞分为两型： 莫氏 （Mobitz） Ⅰ 型即文氏 （Wenckebach） 阻滞， 表现\n为 PP 间期进行性缩短， 直至出现一次长 PP 间期， 该长 PP 间期短于基本 PP 间期的两倍 （ 图 3-3-7）；\n莫氏Ⅱ型阻滞时， 长 PP 间期为基本 PP 间期的整倍数。窦房传导阻滞后可出现逸搏心律。窦房传导\n阻滞的病因及治疗参见病态窦房结综合征。\n图3 -3-6   窦性停搏伴室性逸搏\nⅡ\n导联无窦性 P 波， 最长 RR 间期 4.9 秒， QRS 波群宽大畸形， 时间 0.12 秒。\n图3 -3-7   二度Ⅰ型窦房传导阻滞\nⅡ\n导联可见窦性 PP 间期逐渐缩短， 直至出现一次长 PP 间期， 长的 PP 间期 （1.47 秒） 短于基本 PP\n间期 （0.95 秒） 的两倍。\n五、  病态窦房结综合征\n病态窦房结综合征 （sick sinus syndrome， SSS） 简称病窦综合征， 是由窦房结病变导致功能减退，\n产生多种心律失常的综合表现。病人可在不同时间出现一种以上的心律失常， 常同时合并心房自律\n性异常， 部分病人同时有房室传导功能障碍。\n【病因】 众多病变过程， 如窦房结纤维化与脂肪浸润、 硬化与退行性变、 淀粉样变性、 甲状腺功能\n减退、 某些感染 （ 布鲁氏菌病、 伤寒） 等均可损害窦房结， 导致窦房结起搏与窦房传导功能障碍； 窦房\n结动脉供血减少、 窦房结周围神经和心房肌的病变亦是 SSS 的病因； 颈动脉窦过敏、 脑血管意外、 高血\n钾、 迷走神经张力增高、 某些抗心律失常药物如洋地黄类药物、 乙酰胆碱等抑制窦房结功能亦可导致\n窦房结功能障碍， 应注意鉴别。\n【临床表现】 病人出现与心动过缓有关的心、 脑等脏器供血不足的症状， 如发作性头晕、 黑","资料来源":"人卫《内科学》第10版 · 循环.txt · 本节“窦性心律失常”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2877,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"05412f80ff952d434735a4c5d2da78120687c694bd899cfb5a7648a25d05f0f1","pinyin":"douxingxinlvshichang","initials":"dxxlsc","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-1adae187993d6464fabb","key":"v1-c9ccc21dfe2a3058|templates-1adae187993d6464fabb","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"糖尿病与冠心病","category":"内科","raw":{"name":"糖尿病与冠心病","category":"内科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者因原始病史资料待补录，本次按初步诊断「糖尿病与冠心病」制定检查方案，完善空腹血糖、餐后 2 小时血糖与糖化血红蛋白检查，评估血糖控制水平并指导降糖方案；查肝肾功能与尿微量白蛋白/肌酐比值，明确有无糖尿病肾病，并为他汀及降糖药物安全性提供依据；查血脂四项了解血脂水平，指导降脂目标设定与他汀剂量调整；查血清电解质与心肌酶、肌钙蛋白，排除急性心肌损伤及电解质紊乱所致心律失常；入院即刻与定期复查心电图，观察 ST-T 有无动态演变，明确心肌缺血变化；完善 NT-ProBNP 与心脏彩超＋左心功能测定，评估心功能状态及有无室壁节段性运动异常；查动态心电图了解有无无症状性心肌缺血与心律失常；完善颈动脉及下肢血管彩超，评估动脉粥样硬化斑块与管腔狭窄程度；查眼底检查与肌电图，了解糖尿病视网膜病变及周围神经病变；查胸部 CT 排除肺部感染、肺部肿瘤等合并症。患者胸闷、胸痛症状加重时急诊完善心电图与心肌损伤标志物，必要时行冠状动脉 CTA 或冠状动脉造影，明确冠状动脉狭窄部位与程度，指导血运重建决策。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 糖尿病与冠心病","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","教材原文·内科学第10版":"动脉粥样硬化性心血管疾病 （ASCVD） 是糖尿病病人最主要的大血管并发症， 超过 40% 的糖尿\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0014\u0016\u0011\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0014\u0016\u0011 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0014\u0016\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0014\u0016\n第十五章  其他心血管疾病\n351\n病病人死于心血管疾病， 尤其是 ASCVD； 在住院的冠心病病人中， 合并已诊断和新诊断糖尿病的病人\n比例超过 40%。血糖水平与冠心病发生风险呈正相关性。\n【发病机制】 糖尿病导致冠心病的发病机制非常复杂， 目前认为与高血糖和胰岛素抵抗引起的\n内皮功能紊乱、 炎症水平上升、 脂代谢异常、 氧化应激、 高凝状态等因素密切相关。\n1.  内皮功能紊乱 高血糖可直接抑制内皮细胞依赖的血管舒张\n。高胰岛素血症通过促进内\n皮素 \n-1和血管紧张素Ⅱ产生、活性氧 （ROS）激活， 加重内皮功能不良， 导致动脉粥样硬化和血栓\n形成。\n2.  炎症水平上升 糖基化代谢产物的堆积增加了病变部位炎症细胞浸润\n、 炎症因子和组织因子\n表达增多， 导致全身炎症水平上升， 加速了动脉粥样硬化斑块的形成。\n3.  脂代谢异常 约\n60%～70% 的糖尿病病人合并脂代谢异常， 多表现为高甘油三酯、 低水平\nHDL-C和高水平富含 apo B 微粒的脂蛋白。LDL-C 在糖尿病病人中更具促动脉粥样硬化性， LDL-C\n水平不高的糖尿病病人也易发生动脉粥样硬化。高水平游离脂肪酸通过损害胰岛素信号， 促进炎症\n反应、 加重促栓状态， 加速动脉粥样硬化的进展。\n4.  氧化应激 糖基化终末产物\n（AGE） 可激活其受体 （RAGE）， 刺激还原型烟酰胺腺嘌呤二核苷\n酸磷酸 （NADPH） 氧化酶 1， 增加 ROS 产生。糖尿病病人线粒体功能障碍会进一步增加 ROS 的水平。\nROS 的异常升高导致了细胞增殖、 迁徙、 内质网应激、 自噬、 衰老和死亡的发生， 在动脉粥样硬化形成和发展中起重要作用。\n5.  高凝状态 高胰岛素血症和高血糖均可升高循环组织因子的促凝活性以及促栓塞蛋白\n（\nPAI-1 抗原， vWF 抗原， 纤维蛋白原， 凝血因子Ⅱ、 Ⅴ、 Ⅶ、 Ⅷ、 Ⅹ等） 的表达， 导致糖尿病病人动脉粥样\n斑块栓塞的发生率较高。此外， 糖尿病病人可溶性 P 选择素和 CD40 配体的水平较高， 导致血小板的\n过度激活， 促进血栓形成， 加速了血管狭窄及堵塞。\n【临床表现】 糖尿病合并冠心病的病人常常具有以下临床特点。\n1.  无症状性心肌缺血 指有心肌缺血的客观证据\n， 但是没有胸闷、 胸痛等临床症状。其在糖尿\n病病人中的发生率明显高于非糖尿病病人， 易导致冠心病的漏诊。其原因可能与糖尿病病人痛觉敏\n感性阈值升高、 自主神经功能受损等有关。\n2.  弥漫性血管病变及钙化 糖尿病合并冠心病病人常表现为弥漫的动脉粥样硬化病变\n、 显著的\n血管钙化、 较少的侧支循环， 以及较高的左主干病变发生率。\n3.  微血管病变 一部分糖尿病病人可以出现胸闷\n、 胸痛等症状和心肌缺血客观依据， 但是冠状\n动脉造影仅提示轻度的动脉粥样硬化表现，与临床表现严重程度不符。其原因多为微血管病变， 心肌\n灌注显像可以帮助诊断。\n【诊断与鉴别诊断】 参照 “冠心病” “糖尿病” 相关章节。\n【治疗】 \n1.  生活方式干预 生活方式干预是基础\n， 应贯穿于治疗的全过程， 包括： ①低盐低脂及糖尿病膳\n食； ②有规律的运动 （ 一般建议每周 150 分钟中等强度锻炼或者 75 分钟患者度体育锻炼）； ③避免抽\n烟、 喝酒等不良嗜好； ④保持心情舒畅等。对于超重和肥胖人群， 通过严格的热量摄入限制和规律锻\n炼以减轻体重， 有益于减少心血管事件的发生。\n2.  降糖治疗\n（1） 降\n糖目标： 血糖控制目标应当遵循个体化原则。对于大多数病人， 糖化血红蛋白应控制在\n＜7.0%。对于病程较长、 预期寿命有限以及年老或体弱者， 血糖控制目标可适当放宽。\n（2） 降糖药物的选择\n： 建议优先使用经证实有心血管获益的 GLP-1R 激动剂和\n /\n 或\nSGLT2i， 若同\n时合并心力衰竭或慢性肾脏病， 建议优先使用 SGLT2i。若血糖控制不达标， 可加用二甲双胍、 DPP-4\n抑制剂等其他类型具有心血管系统安全性的降糖药。\n3.  冠心病的治疗\n 参见\n“冠心病” 相关章节。\n\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0014\u0016\u0012\u0012\u000e\u0015௉\u000fJOEE\u0001\u0001\u0001\u0014\u0016\u0012 \u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0014\u0016\u0013\u0011\u0013\u0015\u0010\u0018\u0010\u0013\u0019\u0001\u0001\u0001\u0012\u0011\u001b\u0013\u001a\u001b\u0014\u0016\n352\n第三篇  循环系统疾病","资料来源":"人卫《内科学》第10版 · 循环.txt · 本节“糖尿病与冠心病”正文逐字摘录"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2878,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"642730955ab025e58fafd5fa75f0f497156b0a0975ef21bbee1da602bda0f9cb","pinyin":"tangniaobingyuguanxinbing","initials":"tnbygxb","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","教材原文·内科学第10版","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 教材原文·内科学第10版 资料来源",30],["主要诊断编码","",30]]}]);